def meaningful_table_rows(text: str) -> list[str]:
    rows: list[str] = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped.startswith("|"):
            continue
        if set(stripped.replace("|", "").strip()) <= {"-", ":"}:
            continue
        cells = table_cells(stripped)
        if cells and cells[0].lower() in {"date", "tool name", "project", "action id", "goal id"}:
            continue
        if "Date" in stripped and ("Project" in stripped or "Risk" in stripped or "Decision" in stripped or "Lesson" in stripped):
            continue
        rows.append(stripped)
    return rows


def table_cells(row: str) -> list[str]:
    stripped = row.strip()
    if stripped.startswith("|"):
        stripped = stripped[1:]
    if stripped.endswith("|"):
        stripped = stripped[:-1]
    cells: list[str] = []
    current: list[str] = []
    link_depth = 0
    index = 0
    while index < len(stripped):
        char = stripped[index]
        pair = stripped[index : index + 2]
        if pair == "[[":
            link_depth += 1
            current.append(pair)
            index += 2
            continue
        if pair == "]]" and link_depth:
            link_depth -= 1
            current.append(pair)
            index += 2
            continue
        if char == "|" and link_depth == 0:
            cells.append("".join(current).strip())
            current = []
        else:
            current.append(char)
        index += 1
    cells.append("".join(current).strip())
    return cells


def format_risk_row(row: str) -> str:
    cells = table_cells(row)
    if len(cells) >= 4:
        return f"{cells[1]} - mitigation: {cells[2]} ({cells[3]})"
    return row


def format_memory_row(row: str) -> str:
    cells = table_cells(row)
    if len(cells) >= 4:
        return " - ".join(cells[:4])
    return row


def count_open_tasks_in_file(path: Path, config: RaphaelConfig) -> int:
    text = read_text_if_exists(path, config)
    return sum(1 for line in text.splitlines() if line.strip().startswith("- [ ]"))


def project_health_snapshot(config: RaphaelConfig, project_name: str) -> dict:
    clean_project = slugify(project_name)
    folder = require_project_folder(config, clean_project)
    required_docs = [
        "Overview.md",
        "Tasks.md",
        "Decisions.md",
        "Lessons Learned.md",
        "Next Actions.md",
        "Technical Debt.md",
        "Risks.md",
    ]
    missing = [name for name in required_docs if not (folder / name).exists()]
    risk_rows = meaningful_table_rows(read_text_if_exists(folder / "Risks.md", config))
    decision_rows = meaningful_table_rows(read_text_if_exists(folder / "Decisions.md", config))
    lesson_rows = meaningful_table_rows(read_text_if_exists(folder / "Lessons Learned.md", config))
    open_tasks = count_open_tasks_in_file(folder / "Tasks.md", config)
    next_actions = count_open_tasks_in_file(folder / "Next Actions.md", config)
    debt_text = read_text_if_exists(folder / "Technical Debt.md", config)
    debt_findings = [
        line.strip("- ").strip()
        for line in debt_text.splitlines()
        if line.strip().startswith("- ") and "Generated:" not in line
    ][:8]
    score = 100 - (len(missing) * 10) - (len(risk_rows) * 5)
    if open_tasks == 0 and next_actions == 0:
        score -= 10
    score = max(0, min(100, score))
    if score < 55:
        status = "At Risk"
    elif missing or risk_rows or score < 80:
        status = "Needs Attention"
    else:
        status = "Healthy"
    recommendations: list[str] = []
    if missing:
        recommendations.append(f"Create missing docs: {', '.join(missing)}.")
    if risk_rows:
        recommendations.append("Review open risks and confirm mitigations.")
    if open_tasks == 0 and next_actions == 0:
        recommendations.append("Add concrete next actions to `Tasks.md` or `Next Actions.md`.")
    if not decision_rows:
        recommendations.append("Capture at least one key decision if the project has meaningful direction set.")
    if not lesson_rows:
        recommendations.append("Capture one lesson learned after the next work session.")
    if not recommendations:
        recommendations.append("Review current next actions and pick the next deliverable.")
    return {
        "folder": folder,
        "name": clean_project,
        "status": status,
        "score": score,
        "missing": missing,
        "risks": risk_rows,
        "decisions": decision_rows,
        "lessons": lesson_rows,
        "open_tasks": open_tasks,
        "next_actions": next_actions,
        "debt_findings": debt_findings,
        "recommendations": recommendations,
    }


