def knowledge_root(config: RaphaelConfig) -> Path:
    return config.vault / "09_Knowledge"


def ensure_knowledge_dirs(config: RaphaelConfig) -> Path:
    root = ensure_safe_path(knowledge_root(config), config)
    for name in ["Academic", "Programming", "Research", "Portfolio", "Business", "Lessons Learned", "Inventories", "Curation", "Relationships"]:
        (root / name).mkdir(parents=True, exist_ok=True)
    return root


def knowledge_source_path(folder: Path, config: RaphaelConfig) -> Path:
    source = ensure_safe_read_path(folder, config)
    if not source.exists() or not source.is_dir():
        raise FileNotFoundError(f"Knowledge source folder not found: {source}")
    vault = config.vault.resolve()
    if source == vault or vault in source.parents:
        raise PermissionError("Refusing to ingest the Raphael vault as an external knowledge source.")
    return source


def knowledge_skip_reason(path: Path) -> str | None:
    lowered_parts = {part.lower() for part in path.parts}
    if lowered_parts & {item.lower() for item in JUNK_DIRS}:
        return "junk folder"
    if path.is_symlink():
        return "symlink"
    if is_sensitive_path(path):
        return "sensitive path"
    if path.suffix.lower() not in KNOWLEDGE_EXTENSIONS:
        return "unsupported or binary"
    return None


def scan_knowledge_files(folder: Path, config: RaphaelConfig) -> tuple[list[dict], Counter]:
    source = knowledge_source_path(folder, config)
    max_files = int(config.safety.get("max_import_files", 5000))
    rows: list[dict] = []
    skipped: Counter = Counter()
    for current, dirs, files in os.walk(source, topdown=True, followlinks=False):
        current_path = Path(current)
        kept_dirs = []
        for dirname in dirs:
            candidate = current_path / dirname
            reason = knowledge_skip_reason(candidate)
            if reason in {"junk folder", "symlink", "sensitive path"}:
                skipped[reason] += 1
            else:
                kept_dirs.append(dirname)
        dirs[:] = kept_dirs
        for filename in sorted(files):
            candidate = current_path / filename
            reason = knowledge_skip_reason(candidate)
            if reason:
                skipped[reason] += 1
                continue
            try:
                safe = ensure_safe_read_path(candidate, config)
                stat = safe.stat()
            except (OSError, PermissionError):
                skipped["unreadable"] += 1
                continue
            rows.append(
                {
                    "path": safe,
                    "relative": str(safe.relative_to(source)),
                    "extension": safe.suffix.lower(),
                    "size": stat.st_size,
                    "modified": dt.datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds"),
                }
            )
            if len(rows) >= max_files:
                skipped["file limit reached"] += 1
                return rows, skipped
    return rows, skipped


def xml_archive_text(path: Path, prefixes: tuple[str, ...]) -> str:
    parts: list[str] = []
    with zipfile.ZipFile(path) as archive:
        for name in sorted(archive.namelist()):
            if not any(name.startswith(prefix) for prefix in prefixes) or not name.endswith(".xml"):
                continue
            raw = archive.read(name).decode("utf-8", errors="ignore")
            text = html.unescape(re.sub(r"<[^>]+>", " ", raw))
            text = re.sub(r"\s+", " ", text).strip()
            if text:
                parts.append(text)
    return "\n".join(parts)


def extract_knowledge_text(path: Path, config: RaphaelConfig, max_chars: int = 18000) -> str:
    if is_sensitive_path(path):
        return ""
    suffix = path.suffix.lower()
    try:
        if suffix in KNOWLEDGE_TEXT_EXTENSIONS:
            text = path.read_text(encoding="utf-8", errors="ignore")
        elif suffix == ".docx":
            text = xml_archive_text(path, ("word/document.xml", "word/header", "word/footer"))
        elif suffix == ".pptx":
            text = xml_archive_text(path, ("ppt/slides/", "ppt/notesSlides/"))
        elif suffix == ".xlsx":
            text = xml_archive_text(path, ("xl/sharedStrings.xml", "xl/worksheets/"))
        elif suffix == ".pdf" and dependency_available("pypdf"):
            from pypdf import PdfReader  # type: ignore
            text = "\n".join((page.extract_text() or "") for page in PdfReader(str(path)).pages[:80])
        else:
            return ""
    except (OSError, UnicodeError, zipfile.BadZipFile, ValueError):
        return ""
    if any(pattern.search(text) for pattern in SECRET_VALUE_PATTERNS):
        return ""
    clean = redact_secrets(re.sub(r"\x00", "", text))
    return clean[:max_chars].strip()


def knowledge_item_groups(source: Path, rows: list[dict]) -> list[dict]:
    grouped: dict[str, list[dict]] = {}
    for row in rows:
        relative = Path(row["relative"])
        first = relative.parts[0] if len(relative.parts) > 1 else source.name
        if first.lower() in KNOWLEDGE_BROAD_CONTAINERS and len(relative.parts) > 2:
            key = str(Path(first) / relative.parts[1])
        else:
            key = first
        grouped.setdefault(key, []).append(row)
    return [{"title": Path(title).name, "source": source / title if title != source.name else source, "files": files} for title, files in sorted(grouped.items())]


def detect_knowledge_category(title: str, files: list[dict], sample: str) -> str:
    haystack = f"{title} {' '.join(row['relative'] for row in files)} {sample[:3000]}".lower()
    scores = {category: sum(haystack.count(word) for word in words) for category, words in KNOWLEDGE_CATEGORIES.items()}
    if any(row["extension"] in {".py", ".js", ".jsx", ".ts", ".tsx", ".java", ".c", ".cpp", ".cs", ".go", ".rs", ".ml", ".mli"} for row in files):
        scores["Programming"] += 4
    return max(scores, key=scores.get) if max(scores.values(), default=0) else "Academic"


def detect_course(title: str, file_names: str, sample: str) -> str:
    text = f"{title} {file_names} {sample[:2500]}"
    patterns = [
        r"\b(?:CSC|CS|CSE|ISDS|IT|IS|MATH|ENG|BUS|BIO|CHEM|PHYS|HIST|ECON)[-_ ]?\d{3,4}\b",
        r"\b[A-Z][A-Za-z &-]{3,40}\s+(?:Course|Class|Seminar|Lab)\b",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.I)
        if match:
            return match.group(0).strip()
    return "Not detected"


def detect_technologies(files: list[dict], sample: str) -> list[str]:
    haystack = (" ".join(row["relative"].lower() for row in files) + " " + sample[:5000].lower())
    found = [name for name, hints in TECHNOLOGY_HINTS.items() if any(hint in haystack for hint in hints)]
    return found[:12]


def knowledge_related_context(config: RaphaelConfig, title: str, sample: str) -> list[str]:
    terms = {word for word in re.findall(r"[a-z0-9]{4,}", f"{title} {sample[:2000]}".lower())}
    candidates: list[tuple[int, str]] = []
    for folder, label in [(config.vault / "02_Projects", "Project"), (config.vault / "00_Raphael", "Goal")]:
        if not folder.exists():
            continue
        paths = folder.iterdir() if label == "Project" else [folder / "Goals.md"]
        for path in paths:
            name = path.stem if path.is_file() else path.name
            score = len(terms & set(re.findall(r"[a-z0-9]{4,}", name.lower())))
            if score:
                candidates.append((score, f"{label}: {name}"))
    return [label for _score, label in sorted(candidates, reverse=True)[:5]]


def knowledge_item_summary(config: RaphaelConfig, item: dict) -> tuple[str, str, str]:
    files = item["files"]
    samples: list[str] = []
    for row in sorted(files, key=lambda value: (value["size"], value["relative"]))[:20]:
        text = extract_knowledge_text(row["path"], config, max_chars=5000)
        if text:
            samples.append(text)
        if sum(len(part) for part in samples) >= 16000:
            break
    sample = "\n".join(samples)
    category = detect_knowledge_category(item["title"], files, sample)
    technologies = detect_technologies(files, sample)
    names = ", ".join(row["relative"] for row in files[:30])
    course = detect_course(item["title"], names, sample)
    prose = re.sub(r"\s+", " ", sample).strip()
    summary = prose[:900].rsplit(" ", 1)[0] + ("..." if len(prose) > 900 else "") if prose else (
        f"Read-only inventory of {len(files)} supported files. Content extraction was unavailable or intentionally skipped."
    )
    skills = []
    if technologies:
        skills.append("technical implementation")
    if category == "Research":
        skills.extend(["research synthesis", "source analysis"])
    if category == "Academic":
        skills.extend(["requirements interpretation", "academic communication"])
    if any(row["extension"] in {".pptx", ".docx", ".md"} for row in files):
        skills.append("documentation and presentation")
    if any("test" in row["relative"].lower() for row in files):
        skills.append("testing and validation")
    skills = list(dict.fromkeys(skills or ["organization", "problem solving"]))
    portfolio = "High" if technologies and len(files) >= 3 else ("Medium" if len(files) >= 2 else "Low")
    related = knowledge_related_context(config, item["title"], sample)
    tags = sorted({category.lower().replace(" ", "-"), *[tech.lower().replace("/", "-").replace(" ", "-") for tech in technologies]})
    source_ref = str(item["source"].resolve())
    fingerprint = hashlib.sha256(source_ref.encode("utf-8")).hexdigest()[:10]
    knowledge_id = f"KNOW-{fingerprint.upper()}"
    content = f"""# {item['title']}

> Generated from a read-only source. The original files were not copied, modified, moved, renamed, deleted, overwritten, indexed, or uploaded.
> raphael-knowledge-summary: true

## Knowledge ID

{knowledge_id}

## Title

{item['title']}

## Source Path Reference

`{source_ref}`

## Category

{category}

## Course

{course}

## Technologies

{chr(10).join(f"- {value}" for value in technologies) if technologies else "- None confidently detected."}

## Skills Demonstrated

{chr(10).join(f"- {value}" for value in skills)}

## Summary

{summary}

## Files Found

{chr(10).join(f"- `{row['relative']}` ({row['extension'] or 'no extension'}, {row['size']} bytes)" for row in files[:100])}
{f"- ...and {len(files) - 100} more supported files." if len(files) > 100 else ""}

## Portfolio Value

{portfolio} — {"The work shows identifiable tools and enough artifacts to explain an implementation story." if portfolio == "High" else "Useful supporting evidence; review deliverables and outcomes before publishing."}

## Resume Bullet Potential

- Built or completed **{item['title']}** using {", ".join(technologies) if technologies else "documented academic/research methods"}, demonstrating {", ".join(skills[:3])}.
- Add measurable outcomes, scope, grade, users, or performance results after human review.

## Lessons Learned

- Preserve requirements, decisions, tests, and final outcomes together so the project remains explainable later.
- Review this generated summary against the original source before using it in a resume or portfolio.

## Suggested Tags

{chr(10).join(f"- #{tag}" for tag in tags)}

## Related Raphael Projects/Goals

{chr(10).join(f"- {value}" for value in related) if related else "- No confident relationship detected."}

## Safety Record

- Source access: read-only
- Source files copied: no
- Raw source indexed: no
- Credential-bearing files/content: skipped
- External uploads: none
"""
    return category, f"{slugify(item['title'])} - {fingerprint}.md", content


def knowledge_scan_text(config: RaphaelConfig, folder: Path) -> str:
    source = knowledge_source_path(folder, config)
    rows, skipped = scan_knowledge_files(source, config)
    groups = knowledge_item_groups(source, rows)
    size = sum(row["size"] for row in rows)
    return "\n".join([
        "# Knowledge Scan",
        "",
        f"- Source: `{source}`",
        f"- Supported files: {len(rows)}",
        f"- Candidate projects/assignments: {len(groups)}",
        f"- Total supported bytes: {size}",
        f"- Skipped: {sum(skipped.values())}",
        *[f"  - {reason}: {count}" for reason, count in sorted(skipped.items())],
        "",
        "No source files were changed and no content was uploaded or indexed.",
    ])


def knowledge_inventory(config: RaphaelConfig, folder: Path) -> Path:
    root = ensure_knowledge_dirs(config)
    source = knowledge_source_path(folder, config)
    rows, skipped = scan_knowledge_files(source, config)
    groups = knowledge_item_groups(source, rows)
    stamp = dt.datetime.now().strftime("%Y%m%d-%H%M%S")
    source_id = hashlib.sha256(str(source).encode("utf-8")).hexdigest()[:10]
    output = root / "Inventories" / f"{stamp} - {slugify(source.name)} - {source_id}.md"
    content = f"""# Knowledge Inventory

> Read-only inventory. Original files were not copied, modified, moved, renamed, deleted, overwritten, indexed, or uploaded.

## Source

`{source}`

## Generated

{dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Supported files: {len(rows)}
- Candidate projects/assignments: {len(groups)}
- Total supported bytes: {sum(row['size'] for row in rows)}
- Skipped entries: {sum(skipped.values())}

## Skip Report

{chr(10).join(f"- {reason}: {count}" for reason, count in sorted(skipped.items())) if skipped else "- None."}

## Candidate Projects and Assignments

{chr(10).join(f"- `{item['source']}` — {len(item['files'])} supported files" for item in groups) if groups else "- None found."}

## File Inventory

| Relative path | Type | Bytes | Modified |
|---|---:|---:|---|
{chr(10).join(f"| {markdown_table_escape(row['relative'])} | {row['extension'] or 'none'} | {row['size']} | {row['modified']} |" for row in rows)}
"""
    write_file(output, content, config)
    return output


def knowledge_curation_root(config: RaphaelConfig) -> Path:
    return ensure_knowledge_dirs(config) / "Curation"


def knowledge_summary_records(config: RaphaelConfig) -> list[dict]:
    records: list[dict] = []
    for path in knowledge_root(config).rglob("*.md"):
        if "Curation" in path.parts or "Inventories" in path.parts:
            continue
        text = read_text_if_exists(path, config)
        if "raphael-knowledge-summary: true" not in text.lower():
            continue
        def clean_value(heading: str) -> str:
            value = section_value(text, heading).strip()
            return "" if value.startswith("#") else value
        source = clean_value("Source Path Reference").strip("`")
        fingerprint = hashlib.sha256((source or str(path)).encode("utf-8")).hexdigest()[:10].upper()
        knowledge_id = section_value(text, "Knowledge ID") or f"KNOW-{fingerprint}"
        records.append({
            "id": knowledge_id.strip().upper(),
            "path": path,
            "text": text,
            "title": clean_value("Title") or re.sub(r"\s+-\s+[a-f0-9]{10}$", "", path.stem, flags=re.I),
            "source": source,
            "category": clean_value("Category") or path.parent.name,
            "course": clean_value("Course") or "Not detected",
        })
    return sorted(records, key=lambda row: row["id"])


def find_knowledge_record(config: RaphaelConfig, knowledge_id: str) -> dict:
    wanted = knowledge_id.strip().upper()
    for record in knowledge_summary_records(config):
        if record["id"] == wanted:
            return record
    raise FileNotFoundError(f"Knowledge ID not found: {knowledge_id}")


def write_knowledge_record(record: dict, text: str, config: RaphaelConfig) -> Path:
    path = ensure_safe_path(record["path"], config)
    if knowledge_root(config).resolve() not in path.parents:
        raise PermissionError("Knowledge curation updates must stay inside the Raphael knowledge vault.")
    path.write_text(text.rstrip() + "\n", encoding="utf-8")
    return path


def ignored_knowledge_path(config: RaphaelConfig) -> Path:
    return knowledge_curation_root(config) / "Ignored Knowledge Items.md"


def ignored_knowledge_ids(config: RaphaelConfig) -> set[str]:
    text = read_text_if_exists(ignored_knowledge_path(config), config)
    return {match.upper() for match in re.findall(r"\bKNOW-[A-F0-9]{10}\b", text, flags=re.I)}


def knowledge_ignore(config: RaphaelConfig, knowledge_id: str, reason: str = "Ignored by Aaron") -> Path:
    record = find_knowledge_record(config, knowledge_id)
    output = ignored_knowledge_path(config)
    if not output.exists():
        write_file(output, "# Ignored Knowledge Items\n\n| Knowledge ID | Title | Reason | Date |\n|---|---|---|---|\n", config)
    append_unique_line(
        output,
        f"| {record['id']} | {markdown_table_escape(record['title'])} | {markdown_table_escape(reason)} | {today()} |",
        config,
    )
    updated = replace_or_insert_section(record["text"], "Ignored", "Yes")
    write_knowledge_record(record, updated, config)
    return output


def knowledge_corpus(record: dict) -> str:
    return " ".join([
        record["title"],
        record["source"],
        section_value(record["text"], "Summary"),
        section_value(record["text"], "Files Found"),
        section_value(record["text"], "Technologies"),
        section_value(record["text"], "Suggested Tags"),
    ]).lower()


def infer_knowledge_course(record: dict) -> tuple[str, str]:
    corpus = knowledge_corpus(record)
    source_name = Path(record["source"]).name.lower()
    if source_name in KNOWLEDGE_BROAD_CONTAINERS or record["source"].rstrip("\\/").upper() in {"K:", "K"}:
        return "Not detected", "Not detected"
    primary = f"{record['title']} {record['source']}"
    match = re.search(r"\b(CSC|ISDS|CSE|CS)\s*[-_ ]?\s*(\d{4})(?!\d)", primary, flags=re.I)
    if not match:
        if "pintos" in corpus or "userprog" in corpus:
            code = "CSC4103"
            return code, KNOWLEDGE_COURSE_NAMES[code]
        if ("homework3" in corpus or "homework 3" in corpus) and ("ocaml" in corpus or ".ml" in corpus):
            code = "CSC4101"
            return code, KNOWLEDGE_COURSE_NAMES[code]
        if any(term in corpus for term in ["cryptanalysis", "substitution cipher", "substitutionbreaker"]) or record["title"].lower() in {"crypt", "cipher"}:
            code = "CSC2262"
            return code, KNOWLEDGE_COURSE_NAMES[code]
        match = re.search(r"\b(CSC|ISDS|CSE|CS)\s*[-_ ]?\s*(\d{4})(?!\d)", corpus, flags=re.I)
    if not match:
        match = re.search(r"\b(4101|4103|4243|2262|3102|4123)\b", corpus)
        if match:
            number = match.group(1)
            prefix = "ISDS" if number == "4123" and "isds" in corpus else "CSC"
            code = prefix + number
        else:
            if "pintos" in corpus or "userprog" in corpus:
                code = "CSC4103"
            elif ("homework3" in corpus or "homework 3" in corpus) and ("ocaml" in corpus or ".ml" in corpus):
                code = "CSC4101"
            elif any(term in corpus for term in ["cryptanalysis", "substitution cipher", "substitutionbreaker"]):
                code = "CSC2262"
            else:
                return "Not detected", "Not detected"
    else:
        code = f"{match.group(1).upper()}{match.group(2)}"
    return code, KNOWLEDGE_COURSE_NAMES.get(code, "Not confidently detected")


def infer_project_family(record: dict) -> tuple[str, str, list[str]]:
    corpus = knowledge_corpus(record)
    title = record["title"]
    if "$recycle.bin" in corpus or Path(record["source"]).name.lower() in KNOWLEDGE_JUNK_NAMES:
        return "System/Junk Folder", "System artifact", ["Automatically ignore this generated summary; do not index it."]
    if record["source"].rstrip("\\/").upper() in {"K:", "K"} or title.lower() in {"untitled project", "untitled"}:
        return "K Drive Knowledge Root", "Broad Project Container", ["Use child summaries instead of treating the whole drive as one project."]
    if "pintos" in corpus or "userprog" in corpus or ("syscall" in corpus and "pagedir" in corpus):
        return "PintOS User Programs", "Operating Systems Lab", ["Document implemented system calls, process behavior, and test results."]
    if ("homework3" in corpus or "homework 3" in corpus) and ("ocaml" in corpus or ".ml" in corpus):
        return "OCaml Homework 3", "Programming Languages Assignment", ["Clarify the interpreter/compiler features completed and tests passed."]
    if any(term in corpus for term in ["substitutionbreaker", "substitution cipher", "cryptanalysis", "cipher"]):
        return "Substitution Cipher Cryptanalysis", "Cybersecurity/Cryptanalysis Project", ["Add sample ciphertext, accuracy, algorithm explanation, and demo instructions."]
    if "mapreduce" in corpus or "hadoop" in corpus:
        return "MapReduce / Hadoop Project", "Distributed Systems Assignment", ["Record dataset, map/reduce stages, runtime, and output."]
    source_name = Path(record["source"]).name.lower()
    if source_name in KNOWLEDGE_BROAD_CONTAINERS:
        suggested = "NetBeans Java Projects" if source_name == "netbeansprojects" else record["title"]
        return suggested, "Broad Project Container", ["Run a deeper scan so each useful child project receives its own summary."]
    if "n8n" in corpus:
        return "n8n Workflow Automation Collection", "AI/Automation Project", ["Identify authored workflows, use cases, integrations, and measurable automation outcomes."]
    if "react" in corpus or ".jsx" in corpus or "vite" in corpus:
        name = "Tune Trails React Application" if "tune-trails" in corpus or "tunetrail" in corpus else f"{title} React Application"
        return name, "React Web Application", ["Add screenshots, setup steps, feature list, and deployment/demo evidence."]
    technology_lines = {line.strip().lstrip("-").strip().lower() for line in section_value(record["text"], "Technologies").splitlines()}
    if ".java" in corpus or "java" in technology_lines:
        return title, "Java Programming Project", ["Separate starter code from authored implementation and document test results."]
    if "ocaml" in corpus or ".ml" in corpus:
        return title, "OCaml Programming Assignment", ["Document expected behavior, implementation choices, and test evidence."]
    if "python" in corpus or ".py" in corpus or "jupyter" in corpus:
        return title, "Python Project", ["Clarify inputs, outputs, dependencies, and demonstrated result."]
    return title, "Academic Project/Assignment", ["Add a concise outcome, completion evidence, and course context."]


def infer_assignment_status(record: dict) -> str:
    corpus = knowledge_corpus(record)
    if any(term in corpus for term in ["starter code", "initialhandouts", "your name", "todo", "implement this method"]):
        return "Starter/Incomplete"
    if any(term in corpus for term in ["answer", "completed", "final", "submission"]) or len(section_value(record["text"], "Files Found").splitlines()) >= 5:
        return "Likely Completed"
    return "Unknown"


def normalized_technology_stack(record: dict) -> list[str]:
    corpus = knowledge_corpus(record)
    file_text = section_value(record["text"], "Files Found").lower()
    extensions = set(re.findall(r"\((\.[a-z0-9]+)", file_text))
    values = []
    checks = [
        ("Python", ".py" in extensions or "python" in corpus or ".ipynb" in extensions),
        ("Java", ".java" in extensions or bool(re.search(r"\bjava\b", corpus))),
        ("JavaScript", bool(extensions & {".js", ".jsx"}) or bool(re.search(r"\bjavascript\b", corpus))),
        ("TypeScript", bool(extensions & {".ts", ".tsx"}) or "typescript" in corpus),
        ("C", bool(extensions & {".c", ".h"})),
        ("C++", bool(extensions & {".cpp", ".cc", ".hpp"})),
        ("C#/.NET", ".cs" in extensions or bool(re.search(r"\bc#\b|\bdotnet\b|\.net\b", corpus))),
        ("OCaml", bool(extensions & {".ml", ".mli"}) or "ocaml" in corpus),
        ("React", bool(extensions & {".jsx", ".tsx"}) or bool(re.search(r"\breact\b", corpus))),
        ("SQL/MySQL", ".sql" in extensions or bool(re.search(r"\b(sql|mysql|postgres|sqlite)\b", corpus))),
        ("HTML/CSS", bool(extensions & {".html", ".css", ".scss"})),
        ("Docker", "dockerfile" in corpus or "docker-compose" in corpus),
        ("Jupyter", ".ipynb" in extensions or "jupyter" in corpus),
        ("PowerPoint", ".pptx" in extensions),
        ("Excel", ".xlsx" in extensions),
    ]
    values = [name for name, detected in checks if detected]
    return values[:15]


def knowledge_scores(record: dict, project_type: str, technologies: list[str], status: str) -> dict[str, int]:
    corpus = knowledge_corpus(record)
    file_count = len([line for line in section_value(record["text"], "Files Found").splitlines() if line.strip().startswith("-")])
    technical_depth = min(10, 2 + len(technologies) + (2 if any(term in corpus for term in ["kernel", "compiler", "cryptanalysis", "mapreduce", "database"]) else 0))
    completeness = 8 if status == "Likely Completed" else (3 if status == "Starter/Incomplete" else 5)
    uniqueness = 8 if any(term in corpus for term in ["pintos", "compiler", "cryptanalysis", "mapreduce"]) else 5
    career = 8 if any(term in corpus for term in ["react", "python", "java", "sql", "security", "automation", "kernel"]) else 5
    demo = min(10, 3 + (2 if file_count >= 5 else 0) + (2 if any(term in corpus for term in ["react", "web", "cipher", "application"]) else 0))
    resume = min(10, round((technical_depth + completeness + uniqueness + career + demo) / 5))
    business = 8 if any(
        term in corpus
        for term in [
            "shopify", "woocommerce", "commerce", "customer", "agency", "saas",
            "automation", "raphael", "lcintel", "security", "consulting", "api",
        ]
    ) else (6 if any(term in corpus for term in ["react", "web", "database", "software", "product"]) else 3)
    cleanup = 8 if "Broad Project Container" in project_type or status == "Starter/Incomplete" else (5 if "Not detected" in record["course"] else 3)
    total = round((technical_depth * 20 + completeness * 15 + uniqueness * 15 + resume * 15 + demo * 15 + business * 20) / 10)
    if project_type == "Broad Project Container":
        technical_depth, completeness, uniqueness, career, demo, resume, business, cleanup, total = 2, 2, 1, 2, 1, 1, 1, 10, 14
    elif project_type == "System artifact":
        technical_depth, completeness, uniqueness, career, demo, resume, business, cleanup, total = 0, 0, 0, 0, 0, 0, 0, 0, 0
    return {
        "technical_depth": technical_depth,
        "completeness": completeness,
        "uniqueness": uniqueness,
        "career_relevance": career,
        "demo_potential": demo,
        "resume_value": resume,
        "business_relevance": business,
        "cleanup_effort": cleanup,
        "total": total,
    }


def knowledge_duplicate_map(records: list[dict]) -> dict[str, list[str]]:
    groups: dict[str, list[str]] = {}
    for record in records:
        corpus = knowledge_corpus(record)
        if any(term in corpus for term in ["cipher", "cryptanalysis", "substitution"]):
            key = "cryptanalysis"
        elif "homework3" in corpus or "homework 3" in corpus:
            key = "homework3"
        else:
            key = re.sub(r"\b(main|master|answer|starter|code|project|assignment|final|v\d+)\b", "", record["title"].lower())
            key = re.sub(r"[^a-z0-9]+", "", key)
        if key:
            groups.setdefault(key, []).append(record["id"])
    result: dict[str, list[str]] = {}
    for ids in groups.values():
        if len(ids) > 1:
            for knowledge_id in ids:
                result[knowledge_id] = [value for value in ids if value != knowledge_id]
    return result


def knowledge_classify(config: RaphaelConfig) -> str:
    records = knowledge_summary_records(config)
    duplicates = knowledge_duplicate_map(records)
    ignored = ignored_knowledge_ids(config)
    updated_count = 0
    auto_ignored = 0
    for record in records:
        text = record["text"]
        if not section_value(text, "Knowledge ID"):
            text = replace_or_insert_section(text, "Knowledge ID", record["id"])
        inferred_code, inferred_name = infer_knowledge_course(record)
        manual_course = section_value(text, "Course Source") == "Manual"
        course_code = section_value(text, "Course Code") if manual_course else inferred_code
        course_name = section_value(text, "Course Name") if manual_course else inferred_name
        course_label = section_value(text, "Course") if manual_course else (
            f"{course_code} — {course_name}" if course_code != "Not detected" and course_name != "Not confidently detected" else course_code
        )
        suggested_title, project_type, cleanup = infer_project_family(record)
        technologies = normalized_technology_stack(record)
        status = infer_assignment_status(record)
        scores = knowledge_scores(record, project_type, technologies, status)
        curated_skills = []
        if technologies:
            curated_skills.append("Implementation with " + ", ".join(technologies[:6]))
        if "Operating Systems" in project_type:
            curated_skills.extend(["operating systems concepts", "systems programming"])
        if "Cryptanalysis" in project_type:
            curated_skills.extend(["cybersecurity analysis", "cryptanalysis"])
        if "React" in project_type:
            curated_skills.extend(["web application development", "component-based UI development"])
        if "Automation" in project_type:
            curated_skills.extend(["workflow automation", "systems integration"])
        if "Programming Languages" in project_type or "OCaml" in project_type:
            curated_skills.extend(["functional programming", "language implementation"])
        if "test" in knowledge_corpus(record):
            curated_skills.append("testing and validation")
        if not curated_skills:
            curated_skills = ["requirements interpretation", "problem solving", "technical documentation"]
        portfolio_label = "High" if scores["total"] >= 70 else ("Medium" if scores["total"] >= 50 else "Low")
        corpus = knowledge_corpus(record)
        broad = Path(record["source"]).name.lower() in KNOWLEDGE_BROAD_CONTAINERS or project_type == "Broad Project Container"
        outcome = section_value(text, "Outcome") or ("Unclear — human curation needed." if not any(term in corpus for term in ["completed", "built", "implemented", "created"]) else "Likely implementation artifacts are present; verify the final result.")
        flags = []
        if course_code == "Not detected":
            flags.append("course-not-detected")
        if broad:
            flags.append("broad-container")
        if record["title"].lower().startswith("untitled"):
            flags.append("untitled")
        if suggested_title == "System/Junk Folder":
            flags.append("junk-system-folder")
        if status == "Starter/Incomplete":
            flags.append("possibly-incomplete")
        if duplicates.get(record["id"]):
            flags.append("possible-duplicate")
        replacements = {
            "Course": course_label or "Not detected",
            "Course Code": course_code or "Not detected",
            "Course Name": course_name or "Not detected",
            "Suggested Title": suggested_title,
            "Project Type": project_type,
            "Technology Stack": "\n".join(f"- {value}" for value in technologies) if technologies else "- None confidently detected.",
            "Skills Demonstrated": "\n".join(f"- {value}" for value in dict.fromkeys(curated_skills)),
            "Assignment/Project Status": status,
            "Portfolio Value": f"{portfolio_label} — Curated score {scores['total']}/100.",
            "Portfolio Score": f"{scores['total']}/100",
            "Resume Value": f"{scores['resume_value']}/10",
            "Outcome": outcome,
            "Likely Duplicates": "\n".join(f"- {value}" for value in duplicates.get(record["id"], [])) or "- None detected.",
            "Curation Flags": "\n".join(f"- {value}" for value in flags) or "- None.",
            "Cleanup Suggestions": "\n".join(f"- {value}" for value in cleanup),
            "Classification Scores": "\n".join([
                f"- Technical depth: {scores['technical_depth']}/10",
                f"- Completeness: {scores['completeness']}/10",
                f"- Uniqueness: {scores['uniqueness']}/10",
                f"- Career relevance: {scores['career_relevance']}/10",
                f"- Demo potential: {scores['demo_potential']}/10",
                f"- Resume value: {scores['resume_value']}/10",
                f"- Business relevance: {scores['business_relevance']}/10",
                f"- Cleanup effort: {scores['cleanup_effort']}/10",
            ]),
        }
        for heading, value in replacements.items():
            text = replace_or_insert_section(text, heading, value)
        if suggested_title == "System/Junk Folder" and record["id"] not in ignored:
            knowledge_ignore(config, record["id"], "Automatically ignored system/junk folder")
            ignored.add(record["id"])
            auto_ignored += 1
            text = replace_or_insert_section(text, "Ignored", "Yes")
        elif record["id"] in ignored:
            text = replace_or_insert_section(text, "Ignored", "Yes")
        write_knowledge_record(record, text, config)
        updated_count += 1
    return f"Classified {updated_count} knowledge summaries; automatically ignored {auto_ignored} junk/system item(s). Source files changed: no."


def knowledge_rename_suggestions(config: RaphaelConfig) -> Path:
    rows = []
    for record in knowledge_summary_records(config):
        suggested, project_type, _cleanup = infer_project_family(record)
        if suggested != record["title"] or record["title"].lower().startswith("untitled") or project_type == "Broad Project Container":
            rows.append((record, suggested, project_type))
    output = knowledge_curation_root(config) / "Knowledge Rename Suggestions.md"
    content = """# Knowledge Rename Suggestions

> Suggestions apply only to Raphael-generated summary notes. Original source files and folders are never renamed.

| Knowledge ID | Current summary title | Suggested summary title | Reason |
|---|---|---|---|
""" + "\n".join(
        f"| {record['id']} | {markdown_table_escape(record['title'])} | {markdown_table_escape(suggested)} | {markdown_table_escape(project_type)} |"
        for record, suggested, project_type in rows
    ) + "\n"
    output.write_text(content, encoding="utf-8")
    return output


def knowledge_curation_review(config: RaphaelConfig) -> Path:
    records = knowledge_summary_records(config)
    ignored = ignored_knowledge_ids(config)
    missing_course = [row for row in records if section_value(row["text"], "Course Code") in {"", "Not detected"}]
    broad = [row for row in records if "broad-container" in section_value(row["text"], "Curation Flags")]
    unclear = [row for row in records if section_value(row["text"], "Outcome").lower().startswith("unclear")]
    duplicates = [row for row in records if "None detected" not in section_value(row["text"], "Likely Duplicates")]
    output = knowledge_curation_root(config) / "Knowledge Curation Review.md"
    content = f"""# Knowledge Curation Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Knowledge summaries: {len(records)}
- Ignored items: {len(ignored)}
- Course not detected: {len(missing_course)}
- Broad containers needing deeper scan: {len(broad)}
- Unclear outcomes: {len(unclear)}
- Possible duplicates: {len(duplicates)}

## Course Review Queue

{chr(10).join(f"- `{row['id']}` {row['title']}" for row in missing_course) if missing_course else "- None."}

## Broad Containers

{chr(10).join(f"- `{row['id']}` {row['title']} — deeper scan recommended" for row in broad) if broad else "- None."}

## Outcome Review Queue

{chr(10).join(f"- `{row['id']}` {row['title']}" for row in unclear) if unclear else "- None."}

## Possible Duplicates

{chr(10).join(f"- `{row['id']}` {row['title']}: {section_value(row['text'], 'Likely Duplicates')}" for row in duplicates) if duplicates else "- None."}

## Safety

- Source edits/deletes/renames: none
- Raw file indexing: disabled
- External uploads: none
"""
    output.write_text(content, encoding="utf-8")
    return output


def knowledge_set_course(config: RaphaelConfig, knowledge_id: str, course: str) -> Path:
    record = find_knowledge_record(config, knowledge_id)
    normalized = re.sub(r"\s+", "", course.upper())
    code_match = re.search(r"(CSC|ISDS|CSE|CS)\d{4}", normalized)
    code = code_match.group(0) if code_match else course.strip()
    name = KNOWLEDGE_COURSE_NAMES.get(code, "Manually assigned")
    text = replace_or_insert_section(record["text"], "Course", f"{code} — {name}")
    text = replace_or_insert_section(text, "Course Code", code)
    text = replace_or_insert_section(text, "Course Name", name)
    text = replace_or_insert_section(text, "Course Source", "Manual")
    return write_knowledge_record(record, text, config)


def knowledge_set_outcome(config: RaphaelConfig, knowledge_id: str, outcome: str) -> Path:
    record = find_knowledge_record(config, knowledge_id)
    text = replace_or_insert_section(record["text"], "Outcome", outcome.strip())
    text = replace_or_insert_section(text, "Outcome Source", "Manual")
    return write_knowledge_record(record, text, config)


def knowledge_tag(config: RaphaelConfig, knowledge_id: str, tag: str) -> Path:
    record = find_knowledge_record(config, knowledge_id)
    clean = re.sub(r"[^a-zA-Z0-9_+#./-]+", "-", tag.strip()).strip("-")
    existing = [line.strip().lstrip("-").strip().lstrip("#") for line in section_value(record["text"], "Manual Tags").splitlines() if line.strip()]
    if clean.lower() not in {value.lower() for value in existing}:
        existing.append(clean)
    text = replace_or_insert_section(record["text"], "Manual Tags", "\n".join(f"- #{value}" for value in existing))
    return write_knowledge_record(record, text, config)


def knowledge_portfolio_candidates(config: RaphaelConfig) -> Path:
    ignored = ignored_knowledge_ids(config)
    rows = []
    for record in knowledge_summary_records(config):
        if record["id"] in ignored:
            continue
        suggested, project_type, _cleanup = infer_project_family(record)
        if project_type in {"Broad Project Container", "System artifact"}:
            continue
        technologies = normalized_technology_stack(record)
        status = infer_assignment_status(record)
        scores = knowledge_scores(record, project_type, technologies, status)
        rows.append((scores["total"], record, suggested, project_type, scores))
    rows.sort(key=lambda item: (-item[0], item[1]["title"].lower()))
    output = knowledge_curation_root(config) / "Portfolio Candidate Ranking.md"
    content = """# Portfolio Candidate Ranking

| Rank | Knowledge ID | Candidate | Type | Score | Depth | Complete | Unique | Resume | Demo | Business | Cleanup |
|---:|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|
""" + "\n".join(
        f"| {rank} | {record['id']} | {markdown_table_escape(suggested)} | {markdown_table_escape(project_type)} | {score}/100 | {scores['technical_depth']} | {scores['completeness']} | {scores['uniqueness']} | {scores['resume_value']} | {scores['demo_potential']} | {scores['business_relevance']} | {scores['cleanup_effort']} |"
        for rank, (score, record, suggested, project_type, scores) in enumerate(rows, 1)
    ) + "\n"
    output.write_text(content, encoding="utf-8")
    return output


def knowledge_skills_map(config: RaphaelConfig) -> Path:
    ignored = ignored_knowledge_ids(config)
    mappings: dict[str, list[dict]] = {skill: [] for skill in KNOWLEDGE_SKILL_GROUPS}
    for record in knowledge_summary_records(config):
        if record["id"] in ignored:
            continue
        if section_value(record["text"], "Project Type") in {"Broad Project Container", "System artifact"}:
            continue
        corpus = " ".join([
            record["title"],
            section_value(record["text"], "Suggested Title"),
            section_value(record["text"], "Project Type"),
            section_value(record["text"], "Technology Stack"),
            section_value(record["text"], "Course"),
            section_value(record["text"], "Manual Tags"),
        ]).lower()
        for skill, hints in KNOWLEDGE_SKILL_GROUPS.items():
            detected = any(
                bool(re.search(rf"\b{re.escape(hint)}\b", corpus)) if re.fullmatch(r"[a-z0-9 ]+", hint) else hint in corpus
                for hint in hints
            )
            if detected:
                mappings[skill].append(record)
    output = knowledge_curation_root(config) / "Knowledge Skills Map.md"
    sections = []
    for skill, records in mappings.items():
        sections.append(f"## {skill}\n\n" + (
            "\n".join(f"- `{record['id']}` {record['title']}" for record in records) if records else "- No mapped items."
        ))
    output.write_text("# Knowledge Skills Map\n\n" + "\n\n".join(sections) + "\n", encoding="utf-8")
    return output


def knowledge_relationship_root(config: RaphaelConfig) -> Path:
    return ensure_knowledge_dirs(config) / "Relationships"


def knowledge_list_values(text: str, heading: str) -> list[str]:
    values = []
    for line in section_value(text, heading).splitlines():
        value = line.strip().lstrip("-").strip()
        if value and value.lower() not in {"none.", "none detected.", "none confidently detected."}:
            values.append(value.lstrip("#"))
    return values


def knowledge_portfolio_tier(record: dict) -> str:
    match = re.search(r"(\d+)", section_value(record["text"], "Portfolio Score"))
    score = int(match.group(1)) if match else 0
    return "Tier 1" if score >= 70 else ("Tier 2" if score >= 50 else "Tier 3")


def knowledge_track_matches(corpus: str, rules: dict[str, list[str]]) -> list[str]:
    def matches(hint: str) -> bool:
        if re.fullmatch(r"[a-z0-9 ]+", hint):
            return bool(re.search(rf"\b{re.escape(hint)}\b", corpus))
        return hint in corpus
    return [name for name, hints in rules.items() if any(matches(hint) for hint in hints)]


def knowledge_record_features(record: dict) -> dict[str, list[str] | str]:
    text = record["text"]
    corpus = " ".join([
        record["title"],
        section_value(text, "Suggested Title"),
        section_value(text, "Project Type"),
        section_value(text, "Course"),
        section_value(text, "Technology Stack"),
        section_value(text, "Skills Demonstrated"),
        section_value(text, "Manual Tags"),
        section_value(text, "Summary")[:1200],
    ]).lower()
    course = section_value(text, "Course Code")
    technologies = knowledge_list_values(text, "Technology Stack")
    skills = knowledge_list_values(text, "Skills Demonstrated") + knowledge_list_values(text, "Manual Tags")
    family = section_value(text, "Project Type") or "Academic Project/Assignment"
    if family in {"Broad Project Container", "System artifact"}:
        careers, businesses, clusters = [], [], []
    else:
        careers = knowledge_track_matches(corpus, KNOWLEDGE_CAREER_TRACKS)
        businesses = knowledge_track_matches(corpus, KNOWLEDGE_BUSINESS_TRACKS)
        clusters = knowledge_track_matches(corpus, KNOWLEDGE_CLUSTER_RULES)
    return {
        "course": course if course and course != "Not detected" else "",
        "technologies": technologies,
        "skills": list(dict.fromkeys(skills)),
        "family": family,
        "careers": careers,
        "businesses": businesses,
        "portfolio": knowledge_portfolio_tier(record),
        "clusters": clusters,
        "corpus": corpus,
        "goals": [],
    }


def knowledge_goal_names(config: RaphaelConfig) -> list[str]:
    text = read_text_if_exists(config.vault / "00_Raphael" / "Goals.md", config)
    names = []
    for row in meaningful_table_rows(text):
        cells = [cell.strip() for cell in row.strip("|").split("|")]
        if cells and cells[0].startswith("GOAL-") and len(cells) > 1:
            names.append(cells[1])
    return names


def relationship_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")


def build_knowledge_relationship_graph(config: RaphaelConfig) -> dict:
    ignored = ignored_knowledge_ids(config)
    records = [record for record in knowledge_summary_records(config) if record["id"] not in ignored]
    features = {record["id"]: knowledge_record_features(record) for record in records}
    goals = knowledge_goal_names(config)
    nodes: dict[str, dict] = {
        record["id"]: {"id": record["id"], "label": section_value(record["text"], "Suggested Title") or record["title"], "type": "knowledge"}
        for record in records
    }
    edges: list[dict] = []
    edge_keys: set[tuple[str, str, str]] = set()

    def add_node(node_id: str, label: str, node_type: str) -> None:
        nodes.setdefault(node_id, {"id": node_id, "label": label, "type": node_type})

    def add_edge(source: str, target: str, relationship: str, confidence: float, evidence: str) -> None:
        key = (source, target, relationship)
        reverse = (target, source, relationship)
        if key in edge_keys or reverse in edge_keys:
            return
        edge_keys.add(key)
        edges.append({
            "source": source,
            "target": target,
            "relationship": relationship,
            "confidence": round(confidence, 2),
            "evidence": evidence,
        })

    concept_fields = [
        ("course", "Course Relationship", "course", 0.98),
        ("technologies", "Technology Relationship", "technology", 0.92),
        ("skills", "Skill Relationship", "skill", 0.84),
        ("family", "Project Family Relationship", "project-family", 0.90),
        ("careers", "Career Relationship", "career", 0.82),
        ("businesses", "Business Relationship", "business", 0.76),
        ("portfolio", "Portfolio Relationship", "portfolio", 0.72),
        ("clusters", "Project Family Relationship", "cluster", 0.88),
    ]
    for record in records:
        item_id = record["id"]
        feature = features[item_id]
        for field, relationship, node_type, confidence in concept_fields:
            raw_values = feature[field]
            values = raw_values if isinstance(raw_values, list) else [raw_values]
            for value in values:
                if not value:
                    continue
                concept_id = f"{node_type.upper()}:{relationship_key(str(value))}"
                add_node(concept_id, str(value), node_type)
                add_edge(item_id, concept_id, relationship, confidence, str(value))
        corpus = str(feature["corpus"])
        for goal in goals:
            goal_terms = set(re.findall(r"[a-z0-9]{5,}", goal.lower()))
            if goal_terms & set(re.findall(r"[a-z0-9]{5,}", corpus)):
                goal_id = f"GOAL:{relationship_key(goal)}"
                add_node(goal_id, goal, "goal")
                add_edge(item_id, goal_id, "Goal Relationship", 0.70, goal)
        council = "Research Council"
        if feature["businesses"]:
            first_business = str(feature["businesses"][0])
            council = {
                "Agency": "Agency Council", "Commerce": "Commerce Council", "Creator": "Creator Council",
                "AI Products": "Product Council", "Local SaaS": "Product Council", "Raphael OS": "Research Council",
            }.get(first_business, "Research Council")
        elif "Cybersecurity" in feature["careers"]:
            council = "Engineering Council"
        elif "Software Engineering" in feature["careers"] or "Web Development" in feature["careers"]:
            council = "Engineering Council"
        council_id = f"COUNCIL:{relationship_key(council)}"
        add_node(council_id, council, "council")
        add_edge(item_id, council_id, "Council Relationship", 0.68, council)
        employees = []
        if "Software Engineering" in feature["careers"] or "Web Development" in feature["careers"]:
            employees.append("Developer Agent")
        if "Cybersecurity" in feature["careers"]:
            employees.append("Legal Compliance Agent")
        if "AI / Automation" in feature["careers"]:
            employees.extend(["AI Researcher Agent", "Machine Learning AI Engineer Agent"])
        if "Data Engineering" in feature["careers"]:
            employees.append("Data Analyst Agent")
        for employee in employees:
            employee_id = f"EMPLOYEE:{relationship_key(employee)}"
            add_node(employee_id, employee, "employee")
            add_edge(item_id, employee_id, "Employee Skill Relationship", 0.72, employee)

    pair_fields = [
        ("course", "same_course", 0.94),
        ("technologies", "shared_technology", 0.86),
        ("skills", "shared_skill", 0.80),
        ("family", "same_project_family", 0.90),
        ("careers", "shared_career_track", 0.78),
        ("businesses", "shared_business_opportunity", 0.72),
        ("clusters", "same_cluster", 0.88),
    ]
    for index, left in enumerate(records):
        for right in records[index + 1:]:
            left_features = features[left["id"]]
            right_features = features[right["id"]]
            for field, relationship, confidence in pair_fields:
                left_value = left_features[field]
                right_value = right_features[field]
                if isinstance(left_value, list):
                    shared = sorted(set(left_value) & set(right_value))
                else:
                    shared = [left_value] if left_value and left_value == right_value else []
                if shared:
                    adjusted = min(0.99, confidence + min(0.05, 0.01 * (len(shared) - 1)))
                    add_edge(left["id"], right["id"], relationship, adjusted, ", ".join(str(value) for value in shared[:5]))
    return {"nodes": nodes, "edges": edges, "records": records, "features": features}


def knowledge_relationships(config: RaphaelConfig) -> str:
    graph = build_knowledge_relationship_graph(config)
    direct_edges: dict[str, list[dict]] = {}
    concept_edges: dict[str, list[dict]] = {}
    for edge in graph["edges"]:
        if edge["source"].startswith("KNOW-") and edge["target"].startswith("KNOW-"):
            direct_edges.setdefault(edge["source"], []).append(edge)
            direct_edges.setdefault(edge["target"], []).append(edge)
        elif edge["source"].startswith("KNOW-"):
            concept_edges.setdefault(edge["source"], []).append(edge)
    updated = 0
    for record in graph["records"]:
        item_id = record["id"]
        related_lines = []
        for edge in sorted(direct_edges.get(item_id, []), key=lambda row: -row["confidence"])[:20]:
            other = edge["target"] if edge["source"] == item_id else edge["source"]
            other_node = graph["nodes"].get(other, {})
            related_lines.append(f"- `{other}` {other_node.get('label', other)} — {edge['relationship']} ({edge['confidence']:.2f}): {edge['evidence']}")
        concept_lines = []
        for edge in sorted(concept_edges.get(item_id, []), key=lambda row: -row["confidence"]):
            node = graph["nodes"].get(edge["target"], {})
            concept_lines.append(f"- {edge['relationship']}: {node.get('label', edge['target'])} ({edge['confidence']:.2f})")
        text = replace_or_insert_section(record["text"], "Knowledge Relationships", "\n".join(related_lines) or "- No direct item relationships detected.")
        text = replace_or_insert_section(text, "Relationship Concepts", "\n".join(concept_lines) or "- No relationship concepts detected.")
        text = replace_or_insert_section(text, "Relationship Metadata", f"- Generated: {dt.datetime.now().isoformat(timespec='seconds')}\n- Direct relationships: {len(related_lines)}\n- Concept relationships: {len(concept_lines)}")
        write_knowledge_record(record, text, config)
        updated += 1
    return f"Generated relationship metadata for {updated} knowledge items with {len(graph['edges'])} scored relationships."


def knowledge_graph(config: RaphaelConfig) -> Path:
    graph = build_knowledge_relationship_graph(config)
    item_edges = [edge for edge in graph["edges"] if edge["source"].startswith("KNOW-") and edge["target"].startswith("KNOW-")]
    concept_counts = Counter(node["type"] for node in graph["nodes"].values())
    top_edges = sorted(item_edges, key=lambda row: -row["confidence"])[:100]
    output = knowledge_relationship_root(config) / "Knowledge Graph.md"
    content = f"""# Knowledge Graph

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Overview

- Knowledge items: {len(graph['records'])}
- Total nodes: {len(graph['nodes'])}
- Total relationships: {len(graph['edges'])}
- Direct item relationships: {len(item_edges)}

## Node Types

{chr(10).join(f"- {name}: {count}" for name, count in sorted(concept_counts.items()))}

## Strongest Item Relationships

| Source | Target | Relationship | Confidence | Evidence |
|---|---|---|---:|---|
{chr(10).join(f"| {edge['source']} | {edge['target']} | {edge['relationship']} | {edge['confidence']:.2f} | {markdown_table_escape(edge['evidence'])} |" for edge in top_edges)}

## Council Query Contract

Future councils may query `knowledge-related` for local neighborhoods and `knowledge-path` for explainable shortest paths. Relationship generation remains advisory metadata only.
"""
    output.write_text(content, encoding="utf-8")
    return output


def knowledge_cluster_members(graph: dict) -> dict[str, list[dict]]:
    clusters: dict[str, list[dict]] = {name: [] for name in KNOWLEDGE_CLUSTER_RULES}
    for record in graph["records"]:
        for cluster in graph["features"][record["id"]]["clusters"]:
            clusters.setdefault(cluster, []).append(record)
    return clusters


def knowledge_clusters(config: RaphaelConfig) -> Path:
    graph = build_knowledge_relationship_graph(config)
    clusters = knowledge_cluster_members(graph)
    sections = []
    for cluster, records in clusters.items():
        sections.append(f"## {cluster}\n\n" + (
            "\n".join(f"- `{record['id']}` {section_value(record['text'], 'Suggested Title') or record['title']}" for record in records)
            if records else "- No confident members detected."
        ))
    output = knowledge_relationship_root(config) / "Knowledge Clusters.md"
    output.write_text("# Knowledge Clusters\n\n" + "\n\n".join(sections) + "\n", encoding="utf-8")
    return output


def write_knowledge_track_map(config: RaphaelConfig, filename: str, title: str, field: str, rules: dict[str, list[str]]) -> Path:
    graph = build_knowledge_relationship_graph(config)
    sections = []
    for track in rules:
        records = [record for record in graph["records"] if track in graph["features"][record["id"]][field]]
        sections.append(f"## {track}\n\n" + (
            "\n".join(f"- `{record['id']}` {section_value(record['text'], 'Suggested Title') or record['title']}" for record in records)
            if records else "- No confident matches."
        ))
    output = knowledge_relationship_root(config) / filename
    output.write_text(f"# {title}\n\n" + "\n\n".join(sections) + "\n", encoding="utf-8")
    return output


