def knowledge_portfolio_map(config: RaphaelConfig) -> Path:
    graph = build_knowledge_relationship_graph(config)
    sections = []
    for tier in ["Tier 1", "Tier 2", "Tier 3"]:
        records = [record for record in graph["records"] if graph["features"][record["id"]]["portfolio"] == tier]
        records.sort(key=lambda record: -int(re.search(r"\d+", section_value(record["text"], "Portfolio Score") or "0").group()))
        if not records:
            sections.append(f"## {tier}\n\n- No candidates.")
            continue
        rows = []
        for record in records:
            suggested, project_type, _cleanup = infer_project_family(record)
            scores = knowledge_scores(record, project_type, normalized_technology_stack(record), infer_assignment_status(record))
            rows.append(
                f"| `{record['id']}` | {markdown_table_escape(suggested)} | {scores['total']}/100 | "
                f"{scores['technical_depth']} | {scores['uniqueness']} | {scores['resume_value']} | "
                f"{scores['demo_potential']} | {scores['completeness']} | {scores['business_relevance']} |"
            )
        sections.append(
            f"## {tier}\n\n"
            "| Knowledge ID | Project | Score | Technical depth | Uniqueness | Resume value | Demo value | Completeness | Business relevance |\n"
            "|---|---|---:|---:|---:|---:|---:|---:|---:|\n"
            + "\n".join(rows)
        )
    output = knowledge_relationship_root(config) / "Portfolio Map.md"
    output.write_text("# Portfolio Map\n\n" + "\n\n".join(sections) + "\n", encoding="utf-8")
    return output


