def knowledge_related(config: RaphaelConfig, knowledge_id: str) -> str:
    graph = build_knowledge_relationship_graph(config)
    wanted = knowledge_id.strip().upper()
    if wanted not in graph["nodes"]:
        raise FileNotFoundError(f"Knowledge ID not found: {knowledge_id}")
    edges = [edge for edge in graph["edges"] if edge["source"] == wanted or edge["target"] == wanted]
    edges.sort(key=lambda row: -row["confidence"])
    lines = [f"# Related Knowledge: {wanted}", "", f"- Item: {graph['nodes'][wanted]['label']}", ""]
    for edge in edges[:40]:
        other = edge["target"] if edge["source"] == wanted else edge["source"]
        node = graph["nodes"].get(other, {"label": other, "type": "unknown"})
        lines.append(f"- `{other}` {node['label']} [{node['type']}] — {edge['relationship']} ({edge['confidence']:.2f}): {edge['evidence']}")
    return "\n".join(lines) if edges else "\n".join(lines + ["- No relationships found."])


def knowledge_path(config: RaphaelConfig, source_id: str, target_id: str) -> str:
    graph = build_knowledge_relationship_graph(config)
    source = source_id.strip().upper()
    target = target_id.strip().upper()
    if source not in graph["nodes"] or target not in graph["nodes"]:
        raise FileNotFoundError("Both knowledge IDs must exist and must not be ignored.")
    adjacency: dict[str, list[tuple[str, dict]]] = {}
    for edge in graph["edges"]:
        adjacency.setdefault(edge["source"], []).append((edge["target"], edge))
        adjacency.setdefault(edge["target"], []).append((edge["source"], edge))
    queue = [source]
    previous: dict[str, tuple[str, dict] | None] = {source: None}
    while queue:
        current = queue.pop(0)
        if current == target:
            break
        for neighbor, edge in sorted(adjacency.get(current, []), key=lambda value: -value[1]["confidence"]):
            if neighbor not in previous:
                previous[neighbor] = (current, edge)
                queue.append(neighbor)
    if target not in previous:
        return f"No relationship path found between {source} and {target}."
    chain = []
    current = target
    while previous[current] is not None:
        parent, edge = previous[current]
        chain.append((parent, current, edge))
        current = parent
    chain.reverse()
    lines = [f"# Knowledge Path: {source} -> {target}", ""]
    for parent, child, edge in chain:
        lines.append(f"- {graph['nodes'][parent]['label']} (`{parent}`)")
        lines.append(f"  -> {edge['relationship']} ({edge['confidence']:.2f}): {edge['evidence']}")
    lines.append(f"- {graph['nodes'][target]['label']} (`{target}`)")
    return "\n".join(lines)


