def communication_find_request(config: RaphaelConfig, request_id: str) -> dict[str, str]:
    wanted = request_id.strip().upper()
    for record in communication_requests(config):
        if record["id"] == wanted:
            return record
    raise FileNotFoundError(f"Communication request not found: {request_id}")


def communication_request_type(question: str) -> str:
    lowered = question.lower()
    rules = [
        ("Goal Alignment Assessment", ["goal", "alignment", "priority"]),
        ("Resource Assessment", ["financial", "finance", "budget", "capacity", "resource", "time", "staff"]),
        ("Portfolio Assessment", ["portfolio", "focus", "rank"]),
        ("Risk Assessment", ["risk", "safe", "threat", "concern"]),
        ("Opportunity Assessment", ["opportunity", "market", "potential"]),
        ("Technical Assessment", ["technical", "architecture", "software", "technology"]),
        ("Business Assessment", ["business", "agency", "commerce", "revenue", "client"]),
        ("Strategic Assessment", ["strategy", "strategic", "direction"]),
        ("Validation Request", ["validate", "justified", "confirm", "review"]),
    ]
    for request_type, hints in rules:
        if hints and any(hint in lowered for hint in hints):
            return request_type
    return "Information Request"


def communication_topic(question: str) -> str:
    clean = re.sub(r"\s+", " ", question).strip(" .?!")
    for prefix in ["is ", "are ", "should ", "can ", "could ", "what ", "how ", "why "]:
        if clean.lower().startswith(prefix):
            clean = clean[len(prefix):]
            break
    return clean[:100] or "Council Advisory Request"


def communication_update_request(config: RaphaelConfig, request_id: str, **updates: str) -> None:
    path = ensure_communication_system(config) / "Council Requests.md"
    text = read_text_if_exists(path, config)
    pattern = rf"(^## {re.escape(request_id)}\s*\n)(.*?)(?=^## COMM-|\Z)"
    match = re.search(pattern, text, flags=re.M | re.S)
    if not match:
        raise FileNotFoundError(f"Communication request not found: {request_id}")
    body = match.group(2)
    for heading, value in updates.items():
        body = replace_or_insert_subsection(body, heading, value)
    updated = text[:match.start()] + match.group(1) + body.rstrip() + "\n\n" + text[match.end():].lstrip("\n")
    ensure_safe_path(path, config).write_text(updated.rstrip() + "\n", encoding="utf-8")


def communication_history_event(config: RaphaelConfig, event_type: str, record_id: str, detail: str) -> None:
    path = ensure_communication_system(config) / "Communication History.md"
    append_unique_line(
        path,
        f"- {dt.datetime.now().isoformat(timespec='seconds')} | {event_type} | `{record_id}` | {detail}",
        config,
    )


def communication_request(config: RaphaelConfig, from_council: str, to_council: str, question: str) -> str:
    ensure_communication_system(config)
    source = normalize_council_name(from_council)
    target = normalize_council_name(to_council)
    clean_question = redact_secrets(question.strip())
    if not clean_question:
        raise ValueError("Communication question cannot be empty.")
    request_id = communication_id("COMM", f"{source}|{target}|{clean_question}")
    topic = communication_topic(clean_question)
    request_type = communication_request_type(clean_question)
    section = f"""## {request_id}

### From Council

{source}

### To Council

{target}

### Topic

{topic}

### Question

{clean_question}

### Request Type

{request_type}

### Status

Open

### Created

{dt.datetime.now().isoformat(timespec='seconds')}

### Safety Boundary

Internal advisory communication only. No execution, approval, external message, or autonomous decision is authorized.
"""
    append_unique_section(communication_root(config) / "Council Requests.md", request_id, section, config)
    communication_history_event(config, "Request", request_id, f"{source} -> {target}: {topic}")
    return request_id


def communication_keyword_match(topic: str, text: str) -> bool:
    terms = {word for word in re.findall(r"[a-z0-9]{4,}", topic.lower())}
    return bool(terms & set(re.findall(r"[a-z0-9]{4,}", text.lower())))


def communication_evidence(config: RaphaelConfig, topic: str) -> dict[str, list[str]]:
    knowledge = build_knowledge_relationship_graph(config)
    related_knowledge = []
    for record in knowledge["records"]:
        features = knowledge["features"][record["id"]]
        if communication_keyword_match(topic, f"{record['title']} {features['corpus']}"):
            related_knowledge.append(f"{record['id']} {knowledge['nodes'][record['id']]['label']}")
    goals = [
        f"{goal['id']} {goal['title']}"
        for goal in parse_goals(config)
        if goal.get("status") == "Active" or communication_keyword_match(topic, " ".join(goal.values()))
    ]
    kpis = [
        f"{row.get('KPI ID', row.get('id', ''))} {row.get('Name', row.get('name', ''))} ({row.get('Status', row.get('status', 'Unknown'))})"
        for row in read_kpis(config)
        if communication_keyword_match(topic, " ".join(row.values()))
    ]
    initiatives = [
        f"{row.get('Initiative ID', '')} {row.get('Title', '')} ({row.get('Priority', '')})"
        for row in read_initiatives(config)
        if communication_keyword_match(topic, " ".join(row.values()))
    ]
    finance = [
        f"{row.get('Entry ID', '')} {row.get('Business', '')} {row.get('Type', '')} {row.get('Amount', '')}"
        for row in read_finance_entries(config)
        if communication_keyword_match(topic, " ".join(row.values()))
    ]
    portfolio = [
        f"{row.get('Business Name', '')} score {row.get('Current Focus Score', '')}"
        for row in portfolio_context(config)
        if communication_keyword_match(topic, " ".join(str(value) for value in row.values()))
    ]
    return {
        "knowledge": related_knowledge[:8],
        "goals": goals[:6],
        "kpis": kpis[:6],
        "initiatives": initiatives[:6],
        "finance": finance[:6],
        "portfolio": portfolio[:6],
    }


def communication_response_type(council: str, topic: str, evidence: dict[str, list[str]]) -> tuple[str, float]:
    lowered = topic.lower()
    if council == "Governance Council" and any(word in lowered for word in ["execute", "external", "spend", "upload", "autonomous"]):
        return "Concern", 0.94
    if council == "Financial Council":
        return ("Support", 0.86) if evidence["finance"] else ("Needs More Information", 0.64)
    if council == "Portfolio Council":
        return ("Support", 0.88) if evidence["portfolio"] else ("Neutral", 0.66)
    if council == "Research Council":
        return ("Support", 0.82) if evidence["knowledge"] else ("Concern", 0.62)
    if council == "Engineering Council" and any(word in lowered for word in ["technical", "software", "technology", "project"]):
        return "Support", 0.80
    if evidence["goals"] or evidence["knowledge"]:
        return "Support", 0.78
    return "Neutral", 0.60


def communication_respond(config: RaphaelConfig, request_id: str) -> str:
    request = communication_find_request(config, request_id)
    if request.get("Status") in {"Closed", "Escalated"}:
        raise ValueError(f"Request {request['id']} is already {request['Status'].lower()}.")
    council = request["To Council"]
    evidence = communication_evidence(config, request["Topic"])
    response_type, confidence = communication_response_type(council, request["Topic"], evidence)
    evidence_lines = evidence["finance"] + evidence["portfolio"] + evidence["knowledge"]
    if response_type == "Support":
        response = f"{council} supports the advisory direction based on currently available Raphael evidence."
    elif response_type == "Concern":
        response = f"{council} identifies unresolved risk or insufficient evidence and recommends review before any decision."
    elif response_type == "Needs More Information":
        response = f"{council} cannot validate the request confidently until additional financial, KPI, or outcome evidence is recorded."
    else:
        response = f"{council} offers a neutral advisory response; the evidence does not justify a stronger position."
    response_id = communication_id("RESP", request["id"])
    section = f"""## {response_id}

### Request ID

{request['id']}

### From Council

{council}

### To Council

{request['From Council']}

### Topic

{request['Topic']}

### Response Type

{response_type}

### Response

{response}

### Supporting Evidence

{chr(10).join(f"- {item}" for item in evidence_lines) if evidence_lines else "- No directly matching evidence found."}

### Risks

- Recommendations may be incomplete when KPIs, outcomes, or project status are missing.
- This response must not be interpreted as approval to execute.

### Opportunities

- Use related knowledge and portfolio evidence to sharpen the next advisory question.

### Dependencies

- Human review by Aaron for consequential decisions.
- Additional council input when the topic crosses financial, technical, or governance boundaries.

### Related KPIs

{chr(10).join(f"- {item}" for item in evidence['kpis']) if evidence['kpis'] else "- None detected."}

### Related Initiatives

{chr(10).join(f"- {item}" for item in evidence['initiatives']) if evidence['initiatives'] else "- None detected."}

### Related Goals

{chr(10).join(f"- {item}" for item in evidence['goals']) if evidence['goals'] else "- None detected."}

### Related Knowledge Items

{chr(10).join(f"- {item}" for item in evidence['knowledge']) if evidence['knowledge'] else "- None detected."}

### Confidence Score

{confidence:.2f}

### Created

{dt.datetime.now().isoformat(timespec='seconds')}

### Safety Boundary

Advisory response only. No action, approval, external communication, or execution occurred.
"""
    append_unique_section(communication_root(config) / "Council Responses.md", response_id, section, config)
    communication_update_request(config, request["id"], Status="Responded", Updated=dt.datetime.now().isoformat(timespec="seconds"))
    communication_history_event(config, "Response", response_id, f"{council}: {response_type} for {request['id']}")
    return response_id


def communication_recommend(config: RaphaelConfig, topic: str) -> str:
    clean_topic = redact_secrets(topic.strip())
    evidence = communication_evidence(config, clean_topic)
    councils = select_councils(clean_topic)
    opinions = []
    scores = []
    for council in councils:
        response_type, confidence = communication_response_type(council, clean_topic, evidence)
        opinions.append(f"- {council}: {response_type} ({confidence:.2f})")
        scores.append(confidence if response_type in {"Approve", "Support"} else confidence * 0.5)
    confidence = sum(scores) / len(scores) if scores else 0.5
    recommendation = (
        f"Proceed with further internal validation of {clean_topic}; preserve the strongest supporting evidence "
        "and resolve council concerns before Aaron makes a decision."
    )
    recommendation_id = communication_id("REC", clean_topic)
    section = f"""## {recommendation_id}

### Topic

{clean_topic}

### Council Opinions

{chr(10).join(opinions)}

### Supporting Evidence

{chr(10).join(f"- {item}" for item in (evidence['finance'] + evidence['portfolio'] + evidence['knowledge'])[:12]) if any(evidence.values()) else "- No direct evidence found."}

### Risks

- Evidence can be incomplete or stale.
- Council support is advisory and does not authorize action.

### Opportunities

- Convert unresolved questions into targeted council requests.
- Reuse Phase 58.7 relationships to find adjacent projects, skills, and business evidence.

### Dependencies

- Aaron's final judgment.
- Validation of missing KPIs, outcomes, and constraints.

### Related KPIs

{chr(10).join(f"- {item}" for item in evidence['kpis']) if evidence['kpis'] else "- None detected."}

### Related Initiatives

{chr(10).join(f"- {item}" for item in evidence['initiatives']) if evidence['initiatives'] else "- None detected."}

### Related Goals

{chr(10).join(f"- {item}" for item in evidence['goals']) if evidence['goals'] else "- None detected."}

### Related Knowledge Items

{chr(10).join(f"- {item}" for item in evidence['knowledge']) if evidence['knowledge'] else "- None detected."}

### Recommendation

{recommendation}

### Confidence Score

{confidence:.2f}

### Status

Advisory

### Created

{dt.datetime.now().isoformat(timespec='seconds')}

### Safety Boundary

Informational recommendation only. No decision or execution was performed.
"""
    append_unique_section(communication_root(config) / "Council Recommendations.md", recommendation_id, section, config)
    communication_history_event(config, "Recommendation", recommendation_id, clean_topic)
    return recommendation_id


def communication_escalate(config: RaphaelConfig, request_id: str) -> str:
    request = communication_find_request(config, request_id)
    escalation_id = communication_id("ESC", request["id"])
    section = f"""## {escalation_id}

### Request ID

{request['id']}

### From Council

{request['From Council']}

### To Council

Executive Council

### Topic

{request['Topic']}

### Reason

The originating council requested executive visibility because the advisory question crosses council boundaries or remains unresolved.

### Status

Open

### Created

{dt.datetime.now().isoformat(timespec='seconds')}

### Safety Boundary

Escalation requests review only. It does not approve or execute any recommendation.
"""
    append_unique_section(communication_root(config) / "Council Escalations.md", escalation_id, section, config)
    communication_update_request(config, request["id"], Status="Escalated", Updated=dt.datetime.now().isoformat(timespec="seconds"))
    communication_history_event(config, "Escalation", escalation_id, f"{request['id']} -> Executive Council")
    return escalation_id


def communication_synthesize(config: RaphaelConfig, topic: str) -> str:
    clean_topic = topic.strip()
    responses = [row for row in communication_responses(config) if communication_keyword_match(clean_topic, row.get("Topic", ""))]
    recommendations = [row for row in communication_recommendations(config) if communication_keyword_match(clean_topic, row.get("Topic", ""))]
    if not responses and not recommendations:
        communication_recommend(config, clean_topic)
        recommendations = [row for row in communication_recommendations(config) if communication_keyword_match(clean_topic, row.get("Topic", ""))]
    opinion_lines = [
        f"- {row.get('From Council', 'Council')}: {row.get('Response Type', 'Neutral')} — {row.get('Response', '')}"
        for row in responses
    ]
    opinion_lines += [
        f"- Advisory recommendation `{row['id']}`: {row.get('Recommendation', '')}"
        for row in recommendations
    ]
    positive = sum(1 for row in responses if row.get("Response Type") in {"Approve", "Support"})
    concerns = sum(1 for row in responses if row.get("Response Type") in {"Concern", "Reject", "Escalate", "Needs More Information"})
    if positive > concerns:
        executive = f"Maintain {clean_topic} as a supported strategic direction, but require Aaron's decision before any planning or action."
    elif concerns:
        executive = f"Do not advance {clean_topic} beyond advisory review until the recorded concerns and missing evidence are resolved."
    else:
        executive = f"Keep {clean_topic} under review and request targeted council evidence before selecting a direction."
    confidences = []
    for row in responses + recommendations:
        try:
            confidences.append(float(row.get("Confidence Score", "0")))
        except ValueError:
            pass
    confidence = sum(confidences) / len(confidences) if confidences else 0.55
    synthesis_id = communication_id("SYN", clean_topic)
    section = f"""## {synthesis_id}

### Topic

{clean_topic}

### Council Opinions

{chr(10).join(opinion_lines) if opinion_lines else "- No council opinions recorded."}

### Executive Recommendation

{executive}

### Risks

- Synthesis quality depends on the completeness of council evidence.
- Consensus is not authorization.

### Dependencies

- Aaron's final decision.
- Any missing validation identified by responding councils.

### Confidence Score

{confidence:.2f}

### Status

Advisory

### Created

{dt.datetime.now().isoformat(timespec='seconds')}

### Safety Boundary

Executive synthesis combines advice only. No autonomous decision, approval, external communication, or execution occurred.
"""
    append_unique_section(communication_root(config) / "Executive Syntheses.md", synthesis_id, section, config)
    communication_history_event(config, "Synthesis", synthesis_id, clean_topic)
    return synthesis_id


def communication_network(config: RaphaelConfig) -> Path:
    requests = communication_requests(config)
    responses = communication_responses(config)
    recommendations = communication_recommendations(config)
    escalations = communication_escalations(config)
    pairs: dict[tuple[str, str], dict[str, int]] = {}
    for request in requests:
        key = (request["From Council"], request["To Council"])
        pairs.setdefault(key, {"requests": 0, "responses": 0, "recommendations": 0, "escalations": 0})["requests"] += 1
    request_map = {row["id"]: row for row in requests}
    for response in responses:
        request = request_map.get(response.get("Request ID", ""))
        if request:
            key = (request["From Council"], request["To Council"])
            pairs.setdefault(key, {"requests": 0, "responses": 0, "recommendations": 0, "escalations": 0})["responses"] += 1
    for escalation in escalations:
        request = request_map.get(escalation.get("Request ID", ""))
        if request:
            key = (request["From Council"], request["To Council"])
            pairs.setdefault(key, {"requests": 0, "responses": 0, "recommendations": 0, "escalations": 0})["escalations"] += 1
    for recommendation in recommendations:
        mentioned = [council for council in COUNCILS if council in recommendation.get("Council Opinions", "")]
        for council in mentioned:
            if council == "Executive Council":
                continue
            key = ("Executive Council", council)
            pairs.setdefault(key, {"requests": 0, "responses": 0, "recommendations": 0, "escalations": 0})["recommendations"] += 1
    rows = [
        f"| {source} | {target} | {counts['requests']} | {counts['responses']} | {counts['recommendations']} | {counts['escalations']} |"
        for (source, target), counts in sorted(pairs.items())
    ]
    output = communication_root(config) / "Communication Network Overview.md"
    content = f"""# Communication Network Overview

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Council Graph

| Council A | Council B | Request Count | Response Count | Recommendation Count | Escalation Count |
|---|---|---:|---:|---:|---:|
{chr(10).join(rows) if rows else "| No communications | No communications | 0 | 0 | 0 | 0 |"}

## Totals

- Councils: {len(COUNCILS)}
- Requests: {len(requests)}
- Responses: {len(responses)}
- Recommendations: {len(recommendations)}
- Escalations: {len(escalations)}
- Executive syntheses: {len(communication_syntheses(config))}

## Boundary

The communication graph represents internal advisory traffic only. It does not trigger actions or approvals.
"""
    write_generated_note(output, content, config)
    return output


def communication_status_text(config: RaphaelConfig) -> str:
    requests = communication_requests(config)
    return "\n".join([
        "# Inter-Council Communication Status",
        "",
        f"- Councils: {len(COUNCILS)}",
        f"- Requests: {len(requests)}",
        f"- Open requests: {sum(1 for row in requests if row.get('Status') == 'Open')}",
        f"- Responses: {len(communication_responses(config))}",
        f"- Recommendations: {len(communication_recommendations(config))}",
        f"- Escalations: {len(communication_escalations(config))}",
        f"- Executive syntheses: {len(communication_syntheses(config))}",
        "- Execution authority: none",
        "- External communication: disabled",
    ])


def communication_review(config: RaphaelConfig) -> Path:
    requests = communication_requests(config)
    responses = communication_responses(config)
    escalations = communication_escalations(config)
    open_requests = [row for row in requests if row.get("Status") == "Open"]
    stale = []
    now = dt.datetime.now()
    for row in open_requests:
        try:
            if now - dt.datetime.fromisoformat(row.get("Created", "")) > dt.timedelta(days=7):
                stale.append(row)
        except ValueError:
            pass
    output = communication_root(config) / "Communication Review.md"
    content = f"""# Communication Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Total requests: {len(requests)}
- Open requests: {len(open_requests)}
- Responses: {len(responses)}
- Escalations: {len(escalations)}
- Stale open requests: {len(stale)}

## Open Requests

{chr(10).join(f"- `{row['id']}` {row['From Council']} -> {row['To Council']}: {row['Topic']}" for row in open_requests) if open_requests else "- None."}

## Stale Requests

{chr(10).join(f"- `{row['id']}` created {row.get('Created', 'unknown')}" for row in stale) if stale else "- None."}

## Recommendations

- Respond to open requests with evidence before synthesizing.
- Escalate unresolved cross-council conflicts to Executive Council for advisory review.
- Keep all outputs informational and confirmation-free because they cannot execute.

## Safety

- Autonomous decisions: disabled
- External messages: disabled
- Execution: disabled
- Approval bypass: disabled
"""
    write_generated_note(output, content, config)
    return output


