def replace_goal_generated_section(path: Path, goal_id: str, section: str, config: RaphaelConfig) -> None:
    safe = ensure_safe_path(path, config)
    text = safe.read_text(encoding="utf-8") if safe.exists() else f"# {safe.stem}\n\n"
    marker = f"## {goal_id}"
    pattern = rf"^## {re.escape(goal_id)}\s*\n.*?(?=^## GOAL-|\Z)"
    block = f"## {goal_id}\n\n{section.strip()}\n"
    if re.search(pattern, text, flags=re.M | re.S):
        text = re.sub(pattern, block.rstrip() + "\n", text, count=1, flags=re.M | re.S)
    else:
        text = text.rstrip() + "\n\n" + block
    safe.parent.mkdir(parents=True, exist_ok=True)
    safe.write_text(text.rstrip() + "\n", encoding="utf-8")


def propagate_goal(config: RaphaelConfig, goal_ref: str) -> Path:
    root = ensure_goal_propagation(config)
    goal = resolve_goal(config, goal_ref)
    data = goal_cascade_data(config, goal)
    plan = root / "Goal Cascade Plans" / f"{goal['id']} - Cascade Plan.md"
    write_generated_note(plan, goal_cascade_plan_content(config, data), config)
    council_text = "\n".join(f"- **{row['council']}**: {row['objective']} Output: {row['output']}" for row in data["councils"])
    department_text = "\n".join(f"- **{row['department']}** ({row['council']}): {row['objective']} → {row['output']}" for row in data["departments"])
    employee_text = "\n".join(f"- **{row['employee']}** ({row['council']}): {row['responsibility']}" for row in data["employees"])
    kpi_text = "\n".join(f"- {row['name']} — {row['status']} — {row['id'] or 'Not created'}" for row in data["kpis"])
    initiative_text = "\n".join(f"- {row['name']} — {row['status']} — {row['id'] or 'Not created'}" for row in data["initiatives"])
    replace_goal_generated_section(root / "Council Objectives.md", goal["id"], council_text, config)
    replace_goal_generated_section(root / "Department Objectives.md", goal["id"], department_text, config)
    replace_goal_generated_section(root / "Employee Objectives.md", goal["id"], employee_text, config)
    replace_goal_generated_section(root / "Goal KPI Map.md", goal["id"], kpi_text, config)
    replace_goal_generated_section(root / "Goal Initiative Map.md", goal["id"], initiative_text, config)
    replace_goal_generated_section(root / "Goal Review Cycles.md", goal["id"], goal_review_cycle_text(goal), config)
    replace_goal_generated_section(root / "Goal Cascade Plans.md", goal["id"], f"- [[Goal Cascade Plans/{plan.stem}|{plan.stem}]]", config)
    registry = root / "Goal Propagation Registry.md"
    registry_text = read_text_if_exists(registry, config)
    registry_lines = [line for line in registry_text.splitlines() if not line.startswith(f"| {goal['id']} |")]
    registry_lines.append(
        f"| {goal['id']} | {markdown_table_escape(goal['title'])} | Propagated | {len(data['councils'])} | "
        f"{len(data['employees'])} | {len(data['kpis'])} | {len(data['initiatives'])} | {len(data['tasks'])} | "
        f"{dt.datetime.now().isoformat(timespec='seconds')} |"
    )
    ensure_safe_path(registry, config).write_text("\n".join(registry_lines).rstrip() + "\n", encoding="utf-8")
    goal_log(config, goal["id"], f"Generated advisory cascade plan: {plan.name}. No tasks, KPIs, initiatives, delegations, or execution created.")
    return plan


def goal_cascade(config: RaphaelConfig, goal_ref: str) -> Path:
    goal = resolve_goal(config, goal_ref) if goal_ref.strip() else default_goal(config)
    path = ensure_goal_propagation(config) / "Goal Cascade Plans" / f"{goal['id']} - Cascade Plan.md"
    if not path.exists():
        return propagate_goal(config, goal["id"])
    return path


def goal_objectives(config: RaphaelConfig, goal_ref: str) -> str:
    goal = resolve_goal(config, goal_ref)
    data = goal_cascade_data(config, goal)
    lines = [f"# Goal Objectives: {goal['id']}", "", f"## {goal['title']}", "", "### Councils"]
    lines += [f"- {row['council']}: {row['objective']} Output: {row['output']}" for row in data["councils"]]
    lines += ["", "### Departments"]
    lines += [f"- {row['department']} ({row['council']}): {row['objective']}" for row in data["departments"]]
    lines += ["", "### Employees"]
    lines += [f"- {row['employee']}: {row['responsibility']}" for row in data["employees"]]
    return "\n".join(lines)


def goal_kpi_map_text(config: RaphaelConfig, goal_ref: str) -> str:
    goal = resolve_goal(config, goal_ref)
    rows = goal_cascade_data(config, goal)["kpis"]
    return "\n".join([f"# Goal KPI Map: {goal['id']}", ""] + [
        f"- {row['name']} [{row['status']}] {row['id'] or 'Not created'} — {row['target']}" for row in rows
    ])


def goal_initiative_map_text(config: RaphaelConfig, goal_ref: str) -> str:
    goal = resolve_goal(config, goal_ref)
    rows = goal_cascade_data(config, goal)["initiatives"]
    return "\n".join([f"# Goal Initiative Map: {goal['id']}", ""] + [
        f"- {row['name']} [{row['status']}] {row['id'] or 'Not created'} — {row['council']}" for row in rows
    ])


def goal_review_cycle(config: RaphaelConfig, goal_ref: str) -> str:
    goal = resolve_goal(config, goal_ref)
    ensure_goal_propagation(config)
    replace_goal_generated_section(goal_propagation_root(config) / "Goal Review Cycles.md", goal["id"], goal_review_cycle_text(goal), config)
    return f"# Goal Review Cycle: {goal['id']}\n\n{goal_review_cycle_text(goal)}"


def goal_propagation_status_text(config: RaphaelConfig) -> str:
    root = ensure_goal_propagation(config)
    plans = list((root / "Goal Cascade Plans").glob("GOAL-* - Cascade Plan.md"))
    return "\n".join([
        "# Goal Propagation Status",
        "",
        f"- Enabled: {config.goal_propagation_enabled}",
        f"- Goals: {len(parse_goals(config))}",
        f"- Cascade plans: {len(plans)}",
        f"- Task creation requires confirmation: {config.goal_propagation_requires_confirmation_for_task_creation}",
        f"- KPI creation requires confirmation: {config.goal_propagation_requires_confirmation_for_kpi_creation}",
        f"- Initiative creation requires confirmation: {config.goal_propagation_requires_confirmation_for_initiatives}",
        "- Autonomous execution: disabled",
        "- Source project edits: disabled",
    ])


def goal_propagation_review(config: RaphaelConfig) -> Path:
    root = ensure_goal_propagation(config)
    goals = parse_goals(config)
    plans = {path.name.split(" - ", 1)[0]: path for path in (root / "Goal Cascade Plans").glob("GOAL-* - Cascade Plan.md")}
    missing = [goal for goal in goals if goal["id"] not in plans]
    content = f"""# Goal Propagation Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Goals: {len(goals)}
- Propagated goals: {len(plans)}
- Goals without cascade plans: {len(missing)}

## Missing Cascade Plans

{chr(10).join(f"- `{goal['id']}` {goal['title']}" for goal in missing) if missing else "- None."}

## Review Guidance

- Confirm success definitions, KPI targets, deadlines, and portfolio tradeoffs.
- Convert suggested tasks, KPIs, initiatives, and communication requests only through existing confirmation gates.
- Review daily blockers, weekly progress, and monthly portfolio/financial alignment.

## Safety

- Tasks auto-created: no
- KPIs auto-created: no
- Initiatives auto-created: no
- Delegations auto-created: no
- Execution added: no
"""
    output = root / "Goal Propagation Review.md"
    write_generated_note(output, content, config)
    return output


def goal_propagation_brief(config: RaphaelConfig) -> Path:
    root = ensure_goal_propagation(config)
    goals = parse_goals(config)
    plans = list((root / "Goal Cascade Plans").glob("GOAL-* - Cascade Plan.md"))
    active = [goal for goal in goals if goal["status"] == "Active"]
