def n8n_root(config: RaphaelConfig) -> Path:
    root = ensure_safe_path(config.vault / "00_Raphael" / "n8n Workflow Studio", config)
    root.mkdir(parents=True, exist_ok=True)
    for child in ["Workflow Plans", "Workflow Drafts", "Workflow Summaries", "Exports"]:
        (root / child).mkdir(parents=True, exist_ok=True)
    return root


def ensure_n8n_studio(config: RaphaelConfig) -> Path:
    if not config.n8n_workflow_studio_enabled:
        raise RuntimeError("n8n Workflow Studio is disabled in config/settings.json.")
    if config.n8n_allow_activation or config.n8n_store_credentials or config.n8n_allow_external_calls:
        raise RuntimeError("Unsafe n8n settings detected. Activation, credential storage, and external calls must remain disabled.")
    root = n8n_root(config)
    for filename, content in N8N_STUDIO_FILES.items():
        if not (root / filename).exists():
            write_file(root / filename, content, config)
    return root


def n8n_workflow_id(seed: str, prefix: str = "N8N") -> str:
    digest = hashlib.sha1(seed.encode("utf-8", errors="ignore")).hexdigest()[:10].upper()
    return f"{prefix}-{digest}"


def n8n_category(text: str, node_types: list[str] | None = None) -> str:
    corpus = f"{text} {' '.join(node_types or [])}".lower()
    rules = [
        ("POD", ["print on demand", "pod", "printify", "printful", "etsy"]),
        ("Creator", ["creator", "youtube", "video", "content", "podcast", "ebook"]),
        ("Agency", ["agency", "client", "proposal", "crm", "lead", "hubspot"]),
        ("Research", ["research", "scrape", "search", "rss", "analysis"]),
        ("Knowledge", ["knowledge", "notion", "obsidian", "vector", "qdrant", "document"]),
        ("Finance", ["finance", "invoice", "stripe", "payment", "accounting", "expense"]),
        ("Notifications", ["notification", "telegram", "slack", "discord", "alert"]),
        ("Executive Briefs", ["executive brief", "morning brief", "weekly brief", "summary report"]),
        ("Marketing", ["marketing", "campaign", "mailchimp", "social", "twitter", "linkedin"]),
    ]
    for category, terms in rules:
        if any(term in corpus for term in terms):
            return category
    return "Automation"


def n8n_plan_nodes(idea: str) -> list[dict[str, str]]:
    text = idea.lower()
    trigger_type = "n8n-nodes-base.scheduleTrigger" if any(word in text for word in ["daily", "weekly", "schedule", "export"]) else "n8n-nodes-base.manualTrigger"
    nodes = [
        {"name": "Start", "type": trigger_type, "purpose": "Start only when an operator later imports and explicitly configures the draft."},
        {"name": "Load Input", "type": "n8n-nodes-base.set", "purpose": "Define or normalize workflow inputs without embedding secrets."},
    ]
    if any(word in text for word in ["research", "api", "fetch", "webhook"]):
        nodes.append({"name": "Prepare API Request", "type": "n8n-nodes-base.httpRequest", "purpose": "Placeholder external integration; URL and authentication remain unconfigured."})
    if any(word in text for word in ["pod", "export", "file", "csv"]):
        nodes.append({"name": "Transform Export Records", "type": "n8n-nodes-base.code", "purpose": "Transform records into an export-ready structure."})
    else:
        nodes.append({"name": "Transform Data", "type": "n8n-nodes-base.code", "purpose": "Apply deterministic data transformation logic."})
    nodes += [
        {"name": "Validate Output", "type": "n8n-nodes-base.if", "purpose": "Check required fields before any downstream handoff."},
        {"name": "Draft Result", "type": "n8n-nodes-base.set", "purpose": "Produce an internal draft result only."},
    ]
    return nodes


def n8n_required_credentials(nodes: list[dict[str, str]]) -> list[str]:
    credentials = []
    for node in nodes:
        node_type = node["type"].lower()
        if "httprequest" in node_type:
            credentials.append("API credential for the selected service (configure manually in n8n)")
        if "google" in node_type:
            credentials.append("Google OAuth2 credential (configure manually in n8n)")
        if "slack" in node_type:
            credentials.append("Slack credential (configure manually in n8n)")
    return list(dict.fromkeys(credentials))


def n8n_diagram(nodes: list[dict[str, str]]) -> str:
    labels = [re.sub(r"[^A-Za-z0-9 _-]", "", node["name"]) or f"Node {index}" for index, node in enumerate(nodes, 1)]
    lines = ["flowchart LR"]
    for index, label in enumerate(labels):
        lines.append(f'    N{index}["{label}"]')
        if index:
            lines.append(f"    N{index - 1} --> N{index}")
    return "\n".join(lines)


def n8n_draft_json(workflow_id: str, idea: str, nodes: list[dict[str, str]]) -> dict:
    draft_nodes = []
    x = 0
    for index, node in enumerate(nodes):
        parameters: dict[str, object] = {}
        if node["type"].endswith(".set"):
            parameters = {"assignments": {"assignments": []}, "options": {}}
        elif node["type"].endswith(".code"):
            parameters = {"jsCode": "// Draft only. Add reviewed transformation logic before manual import.\\nreturn $input.all();"}
        elif node["type"].endswith(".if"):
            parameters = {"conditions": {"options": {}, "conditions": [], "combinator": "and"}, "options": {}}
        elif node["type"].endswith(".httpRequest"):
            parameters = {"url": "https://example.invalid/configure-manually", "authentication": "none", "options": {}}
        draft_nodes.append({
            "id": f"{workflow_id}-NODE-{index + 1}",
            "name": node["name"],
            "type": node["type"],
            "typeVersion": 1,
            "position": [x, 0],
            "parameters": parameters,
            "disabled": True,
        })
        x += 260
    connections = {}
    for index in range(len(draft_nodes) - 1):
        connections[draft_nodes[index]["name"]] = {
            "main": [[{"node": draft_nodes[index + 1]["name"], "type": "main", "index": 0}]]
        }
    return {
        "name": f"Draft - {idea}",
        "active": False,
        "nodes": draft_nodes,
        "connections": connections,
        "settings": {"executionOrder": "v1"},
        "meta": {
            "raphaelWorkflowId": workflow_id,
            "draftOnly": True,
            "credentialsStored": False,
            "activationAuthorized": False,
        },
        "pinData": {},
    }


def n8n_workflow_plan(config: RaphaelConfig, idea: str, generate_json: bool = False) -> Path:
    root = ensure_n8n_studio(config)
    clean = redact_secrets(idea.strip())
    if not clean:
        raise ValueError("Workflow idea cannot be empty.")
    workflow_id = n8n_workflow_id(f"{clean}|{dt.datetime.now().isoformat()}", "WF")
    nodes = n8n_plan_nodes(clean)
    credentials = n8n_required_credentials(nodes)
    category = n8n_category(clean, [node["type"] for node in nodes])
    purpose = f"Create an inactive n8n workflow draft that supports: {clean}."
    inputs = ["Operator-supplied records or trigger data", "Manually configured non-secret workflow settings"]
    outputs = ["Validated internal workflow result", "Draft export data for operator review"]
    risks = [
        "External service schemas may differ from the placeholders.",
        "A future operator could activate the workflow without completing review.",
        "Rate limits, privacy rules, and platform terms require manual validation.",
        "Generated transformation logic is a draft and requires testing in a safe n8n environment.",
    ]
    json_structure = n8n_draft_json(workflow_id, clean, nodes)
    draft_path = root / "Workflow Drafts" / f"{workflow_id} - {slugify(clean)[:70]}.json"
    if generate_json:
        ensure_safe_path(draft_path, config).write_text(json.dumps(json_structure, indent=2), encoding="utf-8")
    content = f"""# n8n Workflow {workflow_id}

## Workflow ID

{workflow_id}

## Name

{clean}

## Category

{category}

## Status

{"JSON Draft Generated" if generate_json else "Plan Only"}

## Purpose

{purpose}

## Inputs

{chr(10).join(f"- {item}" for item in inputs)}

## Outputs

{chr(10).join(f"- {item}" for item in outputs)}

## Nodes

| Node | Type | Purpose |
|---|---|---|
{chr(10).join(f"| {node['name']} | `{node['type']}` | {markdown_table_escape(node['purpose'])} |" for node in nodes)}

## Required Credentials

{chr(10).join(f"- {item}" for item in credentials) if credentials else "- None required by the current draft."}

## Risks

{chr(10).join(f"- {item}" for item in risks)}

## Business Use

- Category: {category}
- Use the draft as an architecture starting point and review it before manual import.
- Keep platform actions, outreach, publishing, financial actions, and external calls unconfigured.

## Suggested JSON Structure

```json
{json.dumps(json_structure, indent=2)}
```

## Workflow Diagram

```mermaid
{n8n_diagram(nodes)}
```

## JSON Draft

{str(draft_path) if generate_json else "Not generated. Run `n8n-workflow-generate` to create an inactive JSON draft."}

## Safety

- Executed: no
- Activated: no
- Credentials stored: no
- External calls made: no
- Source workflows modified: no
"""
    folder = "Workflow Drafts" if generate_json else "Workflow Plans"
    note_path = root / folder / f"{workflow_id} - {slugify(clean)[:70]}.md"
    write_generated_note(note_path, content, config)
    n8n_workflow_catalog(config)
    return note_path


def n8n_sanitize_json(value):
    if isinstance(value, dict):
        clean = {}
        for key, item in value.items():
            lower = str(key).lower()
            if lower in {"credentials", "credential", "shared", "staticdata"}:
                continue
            if lower == "active":
                clean[key] = False
            elif lower in {"apikey", "api_key", "token", "password", "secret", "authorization"}:
                clean[key] = "[CONFIGURE_MANUALLY]"
            else:
                clean[key] = n8n_sanitize_json(item)
        if "active" not in clean and ("nodes" in clean or "connections" in clean):
            clean["active"] = False
        return clean
    if isinstance(value, list):
        return [n8n_sanitize_json(item) for item in value]
    return value


def n8n_node_service(node_type: str) -> str:
    tail = node_type.split(".")[-1]
    return re.sub(r"(?<!^)(?=[A-Z])", " ", tail).replace("_", " ").strip().title() or node_type


def n8n_archive_record(data: dict, source_label: str, relative_name: str) -> dict[str, object]:
    schema_valid = isinstance(data.get("nodes"), list)
    nodes = data.get("nodes", []) if schema_valid else []
    node_types = [str(node.get("type", "Unknown")) for node in nodes if isinstance(node, dict)]
    credential_types: list[str] = []
    services: list[str] = []
    for node in nodes:
        if not isinstance(node, dict):
            continue
        services.append(n8n_node_service(str(node.get("type", "Unknown"))))
        credentials = node.get("credentials", {})
        if isinstance(credentials, dict):
            credential_types.extend(str(key) for key in credentials)
    name = str(data.get("name") or Path(relative_name).stem)
    category = n8n_category(f"{name} {relative_name}", node_types)
    connection_count = 0
    connections = data.get("connections", {})
    if isinstance(connections, dict):
        for outputs in connections.values():
            if isinstance(outputs, dict):
                connection_count += sum(
                    len(group) for channel in outputs.values() if isinstance(channel, list)
                    for group in channel if isinstance(group, list)
                )
    workflow_id = n8n_workflow_id(f"{source_label}|{relative_name}", "WFARCH")
    return {
        "id": workflow_id,
        "name": redact_secrets(name),
        "category": category,
        "node_types": sorted(set(node_types)),
        "services": sorted(set(services)),
        "credentials": sorted(set(credential_types)),
        "nodes": len(nodes),
        "connections": connection_count,
        "source": source_label,
        "relative": relative_name,
        "source_active": bool(data.get("active", False)),
        "schema_valid": schema_valid,
    }


def n8n_archive_items(source: Path, config: RaphaelConfig) -> tuple[str, list[tuple[str, dict]]]:
    safe_source = ensure_safe_read_path(source, config)
    items: list[tuple[str, dict]] = []
    if safe_source.is_dir():
        label = str(safe_source)
        for path in sorted(safe_source.rglob("*.json")):
            try:
                data = json.loads(path.read_text(encoding="utf-8-sig"))
            except (OSError, UnicodeError, json.JSONDecodeError):
                continue
            if isinstance(data, dict):
                items.append((path.relative_to(safe_source).as_posix(), data))
        return label, items
    if safe_source.is_file() and safe_source.suffix.lower() == ".zip":
        label = str(safe_source)
        with zipfile.ZipFile(safe_source) as archive:
            for name in sorted(member for member in archive.namelist() if member.lower().endswith(".json") and not member.endswith("/")):
                try:
                    data = json.loads(archive.read(name).decode("utf-8-sig"))
                except (KeyError, UnicodeError, json.JSONDecodeError):
                    continue
                if isinstance(data, dict):
                    items.append((name, data))
        return label, items
    raise ValueError("n8n-workflow-import-archive accepts a ZIP file or folder path.")


