def pod_find_concept(config: RaphaelConfig, concept_ref: str) -> tuple[Path, str]:
    path = pod_find_note(config, "Concepts", concept_ref, "PODCON-")
    return path, read_text_if_exists(path, config, 50000)


POD_NO_TYPOGRAPHY_DIRECTIVE = """NO TEXT
NO LETTERS
NO WORDS
NO TYPOGRAPHY
NO WRITING
NO LOGOS"""


def pod_enforce_no_typography_prompt(prompt: str) -> str:
    clean = prompt.strip()
    missing = [
        directive
        for directive in POD_NO_TYPOGRAPHY_DIRECTIVE.splitlines()
        if directive.lower() not in clean.lower()
    ]
    return clean if not missing else clean + "\n\n" + "\n".join(missing)


def pod_prompt_specs(concept_text: str) -> list[dict[str, object]]:
    idea = section_value(concept_text, "Product Idea")
    style = section_value(concept_text, "Visual Style")
    palette = ", ".join(line[2:].strip() for line in section_value(concept_text, "Color Palette").splitlines() if line.startswith("- "))
    base = pod_enforce_no_typography_prompt(
        f"{idea}, {style}, {palette}, original artwork, centered t-shirt graphic, crisp silhouette, print-ready composition"
    )
    negative = "text, letters, words, typography, writing, numbers, logo, mockup, garment, person, watermark, copyrighted character, trademark, brand name, blurry, low contrast, tiny details, photo background, illegible text, extra text, artifacts"
    specs = [
        {"name": "SDXL", "model": "sdxl", "positive": base + ", professional vector-inspired illustration", "negative": negative, "size": "1024x1024", "steps": 30, "use": "Primary high-quality design exploration"},
        {"name": "Flux", "model": "flux", "positive": base + ", highly coherent graphic design, clean shapes", "negative": negative, "size": "1024x1024", "steps": 4, "use": "Fast local concept variants"},
        {"name": "Transparent Isolated", "model": "sdxl", "positive": base + ", isolated design only, transparent-background intent, no scene, no garment", "negative": negative + ", background, shadow box", "size": "1024x1024", "steps": 30, "use": "Background-removal candidate"},
        {"name": "Black and White Screen Print", "model": "sdxl", "positive": base + ", pure black and white, two-tone screen print, thick lines, high contrast", "negative": negative + ", gradients, gray shading, color", "size": "1024x1024", "steps": 28, "use": "One-color screen-print version"},
        {"name": "Vintage Distressed", "model": "sdxl", "positive": base + ", authentic vintage distressed ink texture, retro outdoor badge", "negative": negative + ", glossy 3d render", "size": "1024x1024", "steps": 32, "use": "Vintage apparel treatment"},
        {"name": "No Text", "model": "flux", "positive": base + ", symbolic illustration only, absolutely no text, no letters, no words", "negative": negative + ", text, typography, letters", "size": "1024x1024", "steps": 4, "use": "IP-safer visual version"},
        {"name": "Mockup Background", "model": "sdxl", "positive": f"neutral studio lifestyle background suitable for presenting {idea}, no product artwork, warm natural light, uncluttered", "negative": "text, logo, watermark, clutter, busy background, distorted clothing", "size": "1344x768", "steps": 28, "use": "Manual mockup planning background"},
    ]
    for spec in specs:
        if spec["model"] in {"sdxl", "flux"}:
            spec["positive"] = pod_enforce_no_typography_prompt(str(spec["positive"]))
    return specs


def pod_prompt(config: RaphaelConfig, concept_ref: str) -> Path:
    root, _ = ensure_pod_studio(config)
    _, concept_text = pod_find_concept(config, concept_ref)
    concept_id = section_value(concept_text, "Concept ID")
    specs = pod_prompt_specs(concept_text)
    sections = []
    for spec in specs:
        sections.append(f"""## {spec['name']} Prompt

- Positive prompt: {spec['positive']}
- Negative prompt: {spec['negative']}
- Recommended dimensions: {spec['size']}
- Recommended steps: {spec['steps']}
- Model: {spec['model']}
- Intended use: {spec['use']}
""")
    content = f"""# POD Design Prompts {concept_id}

## Concept ID

{concept_id}

## Product Idea

{section_value(concept_text, 'Product Idea')}

{chr(10).join(sections)}
## Safety

- Prompts require manual IP review.
- No image generation occurred.
- No external API was called.
- No platform action was performed.

## Suggested Next Command

`python raphael.py pod-generation-request "{concept_id}" "{config.pod_default_generation_model}"`

## Brand Library

Use `python raphael.py asset-import "{root / 'Design Prompts' / f'{concept_id} - Design Prompts.md'}"` after review to catalog this prompt history for reuse. Import requires confirmation.
"""
    output = root / "Design Prompts" / f"{concept_id} - Design Prompts.md"
    write_generated_note(output, content, config)
    pod_pipeline(config)
    return output


def pod_prompt_spec_for_model(concept_text: str, model: str) -> dict[str, object]:
    normalized = model.lower()
    specs = pod_prompt_specs(concept_text)
    for spec in specs:
        if spec["model"] == normalized and spec["name"] in {"SDXL", "Flux"}:
            return spec
    if normalized not in {"sdxl", "flux"}:
        raise ValueError("Supported POD generation models: sdxl, flux.")
    return next(spec for spec in specs if spec["model"] == normalized)


def pod_comfy_workflow(request_id: str, spec: dict[str, object], model: str, variants: int) -> dict[str, object]:
    is_flux = model == "flux"
    checkpoint = "flux1-schnell.safetensors" if is_flux else "sd_xl_base_1.0.safetensors"
    sampler = "euler" if is_flux else "dpmpp_2m"
    scheduler = "simple" if is_flux else "karras"
    cfg = 1.0 if is_flux else 7.0
    width, height = (int(value) for value in str(spec["size"]).split("x"))
    return {
        "1": {"class_type": "CheckpointLoaderSimple", "inputs": {"ckpt_name": checkpoint}},
        "2": {"class_type": "CLIPTextEncode", "inputs": {"text": str(spec["positive"]), "clip": ["1", 1]}},
        "3": {"class_type": "CLIPTextEncode", "inputs": {"text": str(spec["negative"]), "clip": ["1", 1]}},
        "4": {"class_type": "EmptyLatentImage", "inputs": {"width": width, "height": height, "batch_size": variants}},
        "5": {"class_type": "KSampler", "inputs": {
            "seed": int(hashlib.sha1(request_id.encode()).hexdigest()[:8], 16),
            "steps": int(spec["steps"]), "cfg": cfg, "sampler_name": sampler, "scheduler": scheduler,
            "denoise": 1.0, "model": ["1", 0], "positive": ["2", 0], "negative": ["3", 0], "latent_image": ["4", 0],
        }},
        "6": {"class_type": "VAEDecode", "inputs": {"samples": ["5", 0], "vae": ["1", 2]}},
        "7": {"class_type": "SaveImage", "inputs": {"filename_prefix": f"RaphaelPOD_{request_id}", "images": ["6", 0]}},
    }


POD_UI_WIDGET_INPUTS = {
    "CheckpointLoaderSimple": ["ckpt_name"],
    "CLIPTextEncode": ["text"],
    "EmptyLatentImage": ["width", "height", "batch_size"],
    "EmptySD3LatentImage": ["width", "height", "batch_size"],
    "KSampler": ["seed", "_control_after_generate", "steps", "cfg", "sampler_name", "scheduler", "denoise"],
    "SaveImage": ["filename_prefix"],
}


def pod_ui_workflow_to_api(data: dict[str, object]) -> dict[str, dict[str, object]]:
    nodes = data.get("nodes")
    links = data.get("links")
    if not isinstance(nodes, list) or not isinstance(links, list):
        raise ValueError("UI workflow conversion requires `nodes` and `links` arrays.")
    api: dict[str, dict[str, object]] = {}
    node_map: dict[int, dict[str, object]] = {}
    for raw_node in nodes:
        if not isinstance(raw_node, dict) or not isinstance(raw_node.get("id"), int):
            raise ValueError("UI workflow contains a node without an integer id.")
        node_id = int(raw_node["id"])
        node_map[node_id] = raw_node
        node_type = str(raw_node.get("type", ""))
        if node_type in {"Note", "MarkdownNote"}:
            continue
        if not node_type:
            raise ValueError(f"UI workflow node {node_id} has no type.")
        inputs: dict[str, object] = {}
        widget_names = POD_UI_WIDGET_INPUTS.get(node_type, [])
        widget_values = raw_node.get("widgets_values", [])
        if isinstance(widget_values, list):
            for name, value in zip(widget_names, widget_values):
                if not name.startswith("_"):
                    inputs[name] = value
        api[str(node_id)] = {"class_type": node_type, "inputs": inputs}
    for link in links:
        if not isinstance(link, list) or len(link) < 6:
            raise ValueError("UI workflow contains an invalid link record.")
        _link_id, source_id, source_slot, target_id, target_slot, _link_type = link[:6]
        target = node_map.get(int(target_id))
        if target is None or str(target_id) not in api:
            continue
        target_inputs = target.get("inputs", [])
        if not isinstance(target_inputs, list) or not 0 <= int(target_slot) < len(target_inputs):
            raise ValueError(f"UI workflow link targets an invalid input slot on node {target_id}.")
        input_name = str(target_inputs[int(target_slot)].get("name", ""))
        if not input_name:
            raise ValueError(f"UI workflow node {target_id} has an unnamed linked input.")
        api[str(target_id)]["inputs"][input_name] = [str(source_id), int(source_slot)]
    save_ids = [node_id for node_id, node in api.items() if node.get("class_type") == "SaveImage"]
    if not save_ids:
        return api
    required = set(save_ids)
    pending = list(save_ids)
    while pending:
        node_id = pending.pop()
        inputs = api.get(node_id, {}).get("inputs", {})
        if not isinstance(inputs, dict):
            continue
        for value in inputs.values():
            if isinstance(value, list) and len(value) == 2 and str(value[0]) in api:
                source_id = str(value[0])
                if source_id not in required:
                    required.add(source_id)
                    pending.append(source_id)
    return {node_id: node for node_id, node in api.items() if node_id in required}


def pod_normalize_comfy_payload(raw: object) -> tuple[dict[str, object], str]:
    if not isinstance(raw, dict):
        raise ValueError("Workflow JSON root must be an object.")
    if isinstance(raw.get("nodes"), list) and isinstance(raw.get("links"), list):
        prompt = pod_ui_workflow_to_api(raw)
        return {"prompt": prompt}, "ui_workflow_converted"
    if "prompt" in raw:
        prompt = raw.get("prompt")
        if not isinstance(prompt, dict):
            raise ValueError("Existing `prompt` value must be an object.")
        return {"prompt": prompt}, "api_payload"
    if raw and all(isinstance(value, dict) for value in raw.values()):
        return {"prompt": raw}, "api_prompt"
    raise ValueError("Workflow is neither ComfyUI UI format nor API prompt format.")


def pod_api_prompt_roles(prompt: dict[str, object]) -> dict[str, str]:
    samplers = [
        (node_id, node) for node_id, node in prompt.items()
        if isinstance(node, dict) and node.get("class_type") in {"KSampler", "KSamplerAdvanced"}
    ]
    if len(samplers) != 1:
        raise ValueError(f"Expected exactly one sampler node; found {len(samplers)}.")
    sampler_id, sampler = samplers[0]
    inputs = sampler.get("inputs")
    if not isinstance(inputs, dict):
        raise ValueError(f"Sampler node {sampler_id} has no inputs object.")
    def source(name: str) -> str:
        ref = inputs.get(name)
        if not isinstance(ref, list) or len(ref) < 2:
            raise ValueError(f"Sampler node {sampler_id} has no valid `{name}` connection.")
        return str(ref[0])
    dimensions = [
        node_id for node_id, node in prompt.items()
        if isinstance(node, dict) and node.get("class_type") in {"EmptyLatentImage", "EmptySD3LatentImage"}
    ]
    if len(dimensions) != 1:
        raise ValueError(f"Expected exactly one width/height node; found {len(dimensions)}.")
    saves = [
        node_id for node_id, node in prompt.items()
        if isinstance(node, dict) and node.get("class_type") == "SaveImage"
    ]
    if not saves:
        raise ValueError("SaveImage node is missing.")
    return {
        "sampler": sampler_id,
        "positive": source("positive"),
        "negative": source("negative"),
        "dimensions": dimensions[0],
        "save": saves[0],
    }


def pod_inject_comfy_request(
    payload: dict[str, object],
    *,
    request_id: str,
    positive: str,
    negative: str,
    width: int,
    height: int,
    seed: int,
    variants: int,
) -> dict[str, str]:
    positive = pod_enforce_no_typography_prompt(positive)
    prompt = payload.get("prompt")
    if not isinstance(prompt, dict):
        raise ValueError("Payload `prompt` must be an object before injection.")
    roles = pod_api_prompt_roles(prompt)
    for role, text in [("positive", positive), ("negative", negative)]:
        node = prompt.get(roles[role])
        if not isinstance(node, dict) or node.get("class_type") != "CLIPTextEncode":
            raise ValueError(f"Detected {role} prompt node {roles[role]} is not CLIPTextEncode.")
        inputs = node.setdefault("inputs", {})
        if not isinstance(inputs, dict):
            raise ValueError(f"Prompt node {roles[role]} inputs must be an object.")
        inputs["text"] = text
    dimension_node = prompt[roles["dimensions"]]
    dimension_inputs = dimension_node.setdefault("inputs", {})
    if not isinstance(dimension_inputs, dict):
        raise ValueError("Width/height node inputs must be an object.")
    dimension_inputs.update({"width": width, "height": height, "batch_size": variants})
    sampler = prompt[roles["sampler"]]
    sampler_inputs = sampler.setdefault("inputs", {})
    if not isinstance(sampler_inputs, dict):
        raise ValueError("Sampler inputs must be an object.")
    sampler_inputs["seed"] = seed
    save = prompt[roles["save"]]
    save_inputs = save.setdefault("inputs", {})
    if not isinstance(save_inputs, dict):
        raise ValueError("SaveImage inputs must be an object.")
    save_inputs["filename_prefix"] = f"RaphaelPOD_{request_id}"
    return roles


def pod_validate_comfy_payload(payload: object) -> list[str]:
    errors: list[str] = []
    if not isinstance(payload, dict):
        return ["Payload must be an object."]
    prompt = payload.get("prompt")
    if not isinstance(prompt, dict):
        return ["Payload must contain a `prompt` object."]
    if not prompt:
        return ["Payload `prompt` object is empty."]
    save_found = False
    prompt_nodes = 0
    sampler_found = False
    for node_id, node in prompt.items():
        if not isinstance(node, dict):
            errors.append(f"Node {node_id} must be an object.")
            continue
        class_type = node.get("class_type")
        inputs = node.get("inputs")
        if not class_type:
            errors.append(f"Node {node_id} is missing `class_type`.")
        if not isinstance(inputs, dict):
            errors.append(f"Node {node_id} is missing an `inputs` object.")
            continue
        if class_type == "SaveImage":
            save_found = True
            if "images" not in inputs:
                errors.append(f"SaveImage node {node_id} is missing `images`.")
        if class_type == "CLIPTextEncode":
            prompt_nodes += 1
            if not isinstance(inputs.get("text"), str):
                errors.append(f"Prompt node {node_id} is missing text input.")
            if "clip" not in inputs:
                errors.append(f"Prompt node {node_id} is missing CLIP input.")
        if class_type in {"KSampler", "KSamplerAdvanced"}:
            sampler_found = True
            required = {"model", "positive", "negative", "latent_image", "seed", "steps", "cfg", "sampler_name", "scheduler", "denoise"}
            missing = sorted(required - set(inputs))
            if missing:
                errors.append(f"Sampler node {node_id} is missing inputs: {', '.join(missing)}.")
    if not save_found:
        errors.append("SaveImage node is missing.")
    if prompt_nodes < 1:
        errors.append("No CLIPTextEncode prompt nodes were found.")
    if not sampler_found:
        errors.append("Sampler node is missing.")
    return errors


def pod_generation_request(config: RaphaelConfig, concept_ref: str, model: str) -> Path:
    root, runtime = ensure_pod_studio(config)
    _, concept_text = pod_find_concept(config, concept_ref)
    concept_id = section_value(concept_text, "Concept ID")
    normalized_model = model.lower().strip()
    if normalized_model == "flux" and not config.pod_flux_enabled:
        raise RuntimeError("Flux generation is disabled.")
    if normalized_model == "sdxl" and not config.pod_sdxl_enabled:
        raise RuntimeError("SDXL generation is disabled.")
    spec = pod_prompt_spec_for_model(concept_text, normalized_model)
    request_id = pod_make_id("PODGEN", f"{concept_id}|{normalized_model}")
    variants = min(4, config.pod_max_variants_per_request)
    output_folder = runtime / "generated" / request_id
    output_folder.mkdir(parents=True, exist_ok=True)
    template_name = "flux_schnell_workflow.json" if normalized_model == "flux" else "SDXL_workflow.json"
    template_path = runtime / "templates" / template_name
    if template_path.exists():
        workflow_path = template_path
    else:
        workflow = pod_comfy_workflow(request_id, spec, normalized_model, variants)
        workflow_path = runtime / "templates" / f"{request_id} - ComfyUI API Workflow.json"
        workflow_path.write_text(json.dumps(workflow, indent=2), encoding="utf-8")
    content = f"""# POD Generation Request {request_id}

## Request ID

{request_id}

## Concept ID

{concept_id}

## Model

{normalized_model}

## Prompt

{spec['positive']}

## Negative Prompt

{spec['negative']}

## Width

{str(spec['size']).split('x')[0]}

## Height

{str(spec['size']).split('x')[1]}

## Steps

{spec['steps']}

## CFG / Guidance

{1.0 if normalized_model == 'flux' else 7.0}

## Number of Variants

{variants}

## Output Folder

{output_folder}

## ComfyUI Workflow JSON

{workflow_path}

## Workflow Template Path

{workflow_path}

## Safety Notes

- Pending requests do not generate images.
- Local ComfyUI is the only permitted generation target.
- No Etsy, Printify, credential, publishing, upload, spending, or external API action is authorized.
- The workflow remains inactive until Aaron confirms local generation.

## Status

Pending

## Suggested Next Command

`python raphael.py pod-generate "{request_id}"`
"""
    output = root / "Generation Requests" / f"{request_id} - {concept_id} - {normalized_model}.md"
    write_generated_note(output, content, config)
    pod_pipeline(config)
    return output


def pod_confirmation_granted(prompt: str) -> None:
    if os.environ.get("RAPHAEL_CONFIRMED", "").upper() == "YES":
        return
    if not sys.stdin.isatty():
        raise PermissionError(f"Confirmation required: {prompt}")
    try:
        approved = confirm(prompt)
    except EOFError as exc:
        raise PermissionError(f"Confirmation required: {prompt}") from exc
    if not approved:
        raise PermissionError("POD operation cancelled.")


def pod_comfyui_status(config: RaphaelConfig) -> tuple[bool, str, list[str]]:
    if not config.pod_comfyui_enabled:
        return False, "Disabled in config.", []
    try:
        with urllib.request.urlopen(config.pod_comfyui_url.rstrip("/") + "/object_info/CheckpointLoaderSimple", timeout=4) as response:
            data = json.loads(response.read().decode("utf-8"))
        names = data.get("CheckpointLoaderSimple", {}).get("input", {}).get("required", {}).get("ckpt_name", [[]])[0]
        return True, "Reachable", [str(item) for item in names]
    except Exception as exc:
        return False, f"Unavailable: {exc}", []


def pod_comfyui_json(config: RaphaelConfig, route: str, *, payload: dict[str, object] | None = None, timeout: float = 10) -> dict[str, object]:
    url = config.pod_comfyui_url.rstrip("/") + route
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    request = urllib.request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json"} if data is not None else {},
        method="POST" if data is not None else "GET",
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        parsed = json.loads(response.read().decode("utf-8"))
    if not isinstance(parsed, dict):
        raise RuntimeError(f"Unexpected ComfyUI response from {route}.")
    return parsed


def pod_generation_log_path(config: RaphaelConfig, request_id: str) -> Path:
    _, runtime = ensure_pod_studio(config)
    return runtime / "logs" / f"{request_id} - Generation Log.md"


def pod_generation_diagnostic_paths(config: RaphaelConfig, request_id: str) -> tuple[Path, Path]:
    _, runtime = ensure_pod_studio(config)
    return (
        runtime / "logs" / f"{request_id}-submitted-payload.json",
        runtime / "logs" / f"{request_id}-comfyui-error.json",
    )


def pod_write_generation_log(
    config: RaphaelConfig,
    request_id: str,
    *,
    status: str,
    prompt_id: str = "",
    workflow_path: Path | None = None,
    comfy_files: list[str] | None = None,
    pod_files: list[Path] | None = None,
    error: str = "",
    payload_path: Path | None = None,
    http_status: int | str = "",
    response_body: str = "",
    validation_errors: list[str] | None = None,
    output_folder: Path | None = None,
) -> Path:
    path = pod_generation_log_path(config, request_id)
    content = f"""# POD Generation Log {request_id}

## Request ID

{request_id}

## Status

{status}

## Prompt ID

{prompt_id or "Not assigned"}

## Workflow Path

{workflow_path or "Unknown"}

## Submitted Payload

{payload_path or "Not written"}

## HTTP Status

{http_status or "Not submitted"}

## Response Body

{response_body or "None"}

## Validation Errors

{chr(10).join(f"- {item}" for item in (validation_errors or [])) or "- None"}

## Generated Output Folder

{output_folder or "Unknown"}

## ComfyUI Output Files

{chr(10).join(f"- {item}" for item in (comfy_files or [])) or "- None"}

## PODStudio Output Files

{chr(10).join(f"- {item}" for item in (pod_files or [])) or "- None"}

## Errors

{error or "None"}

## Updated

{dt.datetime.now().isoformat(timespec="seconds")}

## Safety

Local ComfyUI only. No publishing, upload, credentials, spending, or external platform action occurred.
"""
    safe_path = ensure_safe_path(path, config)
    safe_path.parent.mkdir(parents=True, exist_ok=True)
    safe_path.write_text(content, encoding="utf-8")
    return path


def pod_generation_debug(config: RaphaelConfig, request_ref: str) -> dict[str, object]:
    request_path = pod_find_note(config, "Generation Requests", request_ref, "PODGEN-")
    text = read_text_if_exists(request_path, config, 100000)
    request_id = section_value(text, "Request ID")
    payload_path, error_path = pod_generation_diagnostic_paths(config, request_id)
    log_path = pod_generation_log_path(config, request_id)
    log_text = read_text_if_exists(log_path, config, 200000) if log_path.exists() else ""
    response_body = section_value(log_text, "Response Body")
    if error_path.exists():
        response_body = error_path.read_text(encoding="utf-8", errors="replace")
    validation = [
        line[2:].strip()
        for line in section_value(log_text, "Validation Errors").splitlines()
        if line.startswith("- ") and line[2:].strip().lower() != "none"
    ]
    return {
        "request_id": request_id,
        "model": section_value(text, "Model"),
        "workflow_template_path": section_value(text, "Workflow Template Path") or section_value(text, "ComfyUI Workflow JSON"),
        "payload_file_path": str(payload_path),
        "payload_file_exists": payload_path.exists(),
        "comfyui_prompt_id": section_value(text, "ComfyUI Prompt ID") or section_value(log_text, "Prompt ID"),
        "http_status": section_value(log_text, "HTTP Status"),
        "response_body": response_body,
        "validation_errors": validation,
        "generated_output_folder": section_value(text, "Output Folder"),
        "generation_status": section_value(text, "Status"),
        "generation_error": section_value(text, "Generation Error"),
        "error_file_path": str(error_path),
        "error_file_exists": error_path.exists(),
        "generation_log": str(log_path),
    }


def pod_history_images(history: dict[str, object], prompt_id: str) -> tuple[list[dict[str, str]], str]:
    record = history.get(prompt_id, history)
    if not isinstance(record, dict):
        return [], "ComfyUI returned an invalid history record."
    outputs = record.get("outputs", {})
    images: list[dict[str, str]] = []
    if isinstance(outputs, dict):
        for node_output in outputs.values():
            if not isinstance(node_output, dict):
                continue
            for image in node_output.get("images", []):
                if isinstance(image, dict) and image.get("filename"):
                    images.append({
                        "filename": str(image.get("filename", "")),
                        "subfolder": str(image.get("subfolder", "")),
                        "type": str(image.get("type", "output")),
                    })
    status = record.get("status", {})
    error = ""
    if isinstance(status, dict):
        messages = status.get("messages", [])
        error_messages = [
            str(item)
            for item in messages
            if "error" in str(item).lower() or "failed" in str(item).lower()
        ]
        error = "; ".join(error_messages)
    return images, error


def pod_download_comfy_image(config: RaphaelConfig, image: dict[str, str], output_folder: Path) -> Path:
    query = urllib.parse.urlencode({
        "filename": image["filename"],
        "subfolder": image.get("subfolder", ""),
        "type": image.get("type", "output"),
    })
    url = config.pod_comfyui_url.rstrip("/") + "/view?" + query
    with urllib.request.urlopen(url, timeout=30) as response:
        content = response.read()
    if not content:
        raise RuntimeError(f"ComfyUI returned an empty image for {image['filename']}.")
    target = output_folder / Path(image["filename"]).name
    if target.exists():
        target = unique_path(target)
    target.write_bytes(content)
    return target


def pod_checkpoint_available(model: str, checkpoints: list[str]) -> tuple[bool, str]:
    aliases = {
        "sdxl": ("sd_xl_base", "sdxl", "sd-xl-base"),
        "flux": ("flux1-schnell", "flux.1-schnell", "flux_schnell", "flux-schnell"),
    }
    candidates = aliases.get(model.lower(), (model.lower(),))
    for checkpoint in checkpoints:
        lowered = checkpoint.lower()
        if any(candidate in lowered for candidate in candidates):
            return True, checkpoint
    return False, ""


class TypographyContaminationError(RuntimeError):
    pass


class TypographyEnforcementUnavailableError(RuntimeError):
    pass


def pod_tesseract_executable(config: RaphaelConfig) -> tuple[Path | None, str]:
    configured = config.tesseract_path
    if configured and configured.is_file():
        return configured, "configured path"
    detected = shutil.which("tesseract")
    if detected:
        return Path(detected), "PATH"
    return None, "not found"


def pod_ocr_typography_scan(config: RaphaelConfig, image_path: Path) -> dict[str, object]:
    result: dict[str, object] = {
        "available": False,
        "detected": False,
        "rejected": False,
        "max_confidence": 0.0,
        "tokens": [],
        "penalty": 0,
        "status": "OCR unavailable",
    }
    if not config.allow_ocr:
        result["status"] = "OCR disabled"
        return result
    executable, executable_source = pod_tesseract_executable(config)
    if not executable:
        result["status"] = "Tesseract OCR not found"
        return result
    try:
        completed = subprocess.run(
            [str(executable), str(image_path), "stdout", "--psm", "11", "tsv"],
            capture_output=True,
            text=True,
            timeout=60,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        result["status"] = f"OCR failed: {exc}"
        return result
    if completed.returncode != 0:
        result["status"] = f"OCR failed: {completed.stderr.strip() or 'unknown Tesseract error'}"
        return result
    detections: list[dict[str, object]] = []
    lines = completed.stdout.splitlines()
    for line in lines[1:]:
        fields = line.split("\t")
        if len(fields) < 12:
            continue
        token = fields[11].strip()
        if not token or not re.search(r"[A-Za-z0-9]", token):
            continue
        try:
            confidence = float(fields[10])
        except ValueError:
            continue
        if confidence < 0:
            continue
        detections.append({"text": token, "confidence": round(confidence, 2)})
    maximum = max((float(item["confidence"]) for item in detections), default=0.0)
    rejected = maximum >= config.pod_ocr_text_confidence_threshold
    result.update({
        "available": True,
        "detected": bool(detections),
        "rejected": rejected,
        "max_confidence": round(maximum, 2),
        "tokens": detections,
        "penalty": config.pod_ocr_typography_penalty if detections else 0,
        "status": "Typography contamination detected." if detections else "No typography detected.",
        "executable": str(executable),
        "executable_source": executable_source,
    })
    return result


def pod_typography_scan_summary(image: Path, scan: dict[str, object]) -> str:
    tokens = scan.get("tokens", [])
    token_text = ", ".join(
        f"{item.get('text')} ({item.get('confidence')}%)"
        for item in tokens
        if isinstance(item, dict)
    ) or "None"
    return (
        f"- `{image}`: {scan.get('status')} "
        f"Max confidence: {scan.get('max_confidence', 0)}%. "
        f"Penalty: {scan.get('penalty', 0)}. Tokens: {token_text}"
    )


def pod_generate(config: RaphaelConfig, request_ref: str) -> Path:
    _, _ = ensure_pod_studio(config)
    request_path = pod_find_note(config, "Generation Requests", request_ref, "PODGEN-")
    text = read_text_if_exists(request_path, config, 80000)
    request_id = section_value(text, "Request ID")
    status = section_value(text, "Status")
    available_model = section_value(text, "Model")
    configured_workflow_path = Path(section_value(text, "ComfyUI Workflow JSON"))
    base_template = config.os_root / "PODStudio" / "templates" / (
        "flux_schnell_workflow.json" if available_model == "flux" else "SDXL_workflow.json"
    )
    workflow_path = base_template if base_template.exists() else configured_workflow_path
    output_folder = ensure_safe_path(Path(section_value(text, "Output Folder")), config)
    output_folder.mkdir(parents=True, exist_ok=True)
    reachable, detail, checkpoints = pod_comfyui_status(config)
    if status == "Generated":
        raise RuntimeError(f"Generation request {request_id} is already Generated.")
    if config.pod_requires_confirmation_for_generation:
        pod_confirmation_granted(f"Generate local POD images for {request_id}?")
    expected = "Flux Schnell" if available_model == "flux" else "SDXL Base"
    checkpoint_ok, checkpoint_name = pod_checkpoint_available(available_model, checkpoints)
    if not reachable or not checkpoint_ok:
        updated = replace_or_insert_section(text, "Status", "Blocked")
        error = f"ComfyUI readiness check failed: {detail}. Expected checkpoint: {expected}."
        updated = replace_or_insert_section(updated, "Generation Result", error)
        updated = replace_or_insert_section(updated, "Generation Error", error)
        write_generated_note(request_path, updated, config)
        pod_write_generation_log(config, request_id, status="Blocked", workflow_path=workflow_path, error=error)
        raise RuntimeError(error)
    if not workflow_path.exists():
        error = f"ComfyUI workflow file not found: {workflow_path}"
        updated = replace_or_insert_section(text, "Status", "Failed")
        updated = replace_or_insert_section(updated, "Generation Error", error)
        write_generated_note(request_path, updated, config)
        pod_write_generation_log(config, request_id, status="Failed", workflow_path=workflow_path, error=error)
        raise FileNotFoundError(error)

    prompt_id = ""
    comfy_files: list[str] = []
    pod_files: list[Path] = []
    payload_path, error_path = pod_generation_diagnostic_paths(config, request_id)
    http_status: int | str = ""
    response_body = ""
    validation_errors: list[str] = []
    typography_scans: list[tuple[Path, dict[str, object]]] = []
    text = replace_or_insert_section(text, "Workflow Template Path", str(workflow_path))
    text = replace_or_insert_section(text, "Submitted Payload", str(payload_path))
    text = replace_or_insert_section(text, "ComfyUI Error Response", str(error_path))
    write_generated_note(request_path, text, config)
    try:
        raw_workflow = json.loads(workflow_path.read_text(encoding="utf-8"))
        payload, payload_format = pod_normalize_comfy_payload(raw_workflow)
        pod_inject_comfy_request(
            payload,
            request_id=request_id,
            positive=section_value(text, "Prompt"),
            negative=section_value(text, "Negative Prompt"),
            width=int(section_value(text, "Width")),
            height=int(section_value(text, "Height")),
            seed=int(hashlib.sha1(request_id.encode()).hexdigest()[:8], 16),
            variants=int(section_value(text, "Number of Variants") or "1"),
        )
        payload["client_id"] = f"raphael-{request_id.lower()}"
        validation_errors = pod_validate_comfy_payload(payload)
        payload_path.parent.mkdir(parents=True, exist_ok=True)
        payload_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
        if validation_errors:
            raise ValueError("ComfyUI payload validation failed: " + "; ".join(validation_errors))
        try:
            queued = pod_comfyui_json(config, "/prompt", payload=payload, timeout=20)
            http_status = 200
            response_body = json.dumps(queued, indent=2)
        except urllib.error.HTTPError as exc:
            http_status = exc.code
            raw_body = exc.read().decode("utf-8", errors="replace")
            exc.close()
            response_body = raw_body or str(exc)
            if raw_body:
                error_path.write_text(raw_body, encoding="utf-8")
            else:
                error_document = {
                    "http_status": exc.code,
                    "reason": str(exc.reason),
                    "response_body": raw_body,
                }
                error_path.write_text(json.dumps(error_document, indent=2), encoding="utf-8")
            raise RuntimeError(
                f"ComfyUI HTTP {exc.code}: {raw_body or exc.reason}. "
                f"Debug: python raphael.py pod-generation-debug \"{request_id}\""
            ) from exc
        prompt_id = str(queued.get("prompt_id", "")).strip()
        if not prompt_id:
            raise RuntimeError(f"ComfyUI did not return prompt_id: {queued}")

        deadline = time.monotonic() + 600
        images: list[dict[str, str]] = []
        history_error = ""
        while time.monotonic() < deadline:
            history = pod_comfyui_json(config, f"/history/{urllib.parse.quote(prompt_id)}", timeout=20)
            images, history_error = pod_history_images(history, prompt_id)
            if images or history_error:
                break
            time.sleep(1.5)
        if not images:
            raise RuntimeError(history_error or f"ComfyUI completed or timed out without reporting image outputs for prompt {prompt_id}.")

        for image in images:
            comfy_ref = "/".join(
                part for part in [image.get("subfolder", ""), image["filename"]] if part
            )
            comfy_files.append(comfy_ref)
            pod_files.append(pod_download_comfy_image(config, image, output_folder))
        if not pod_files or not any(path.exists() and path.stat().st_size > 0 for path in pod_files):
            raise RuntimeError("ComfyUI reported outputs, but no non-empty images were copied into the PODStudio request folder.")
        typography_scans = [(path, pod_ocr_typography_scan(config, path)) for path in pod_files]
        unavailable = [(path, scan) for path, scan in typography_scans if not scan.get("available")]
        if unavailable:
            details = "; ".join(f"{path.name}: {scan.get('status')}" for path, scan in unavailable)
            raise TypographyEnforcementUnavailableError(
                f"Typography enforcement unavailable. Generated images cannot be finalized: {details}"
            )
        contaminated = [(path, scan) for path, scan in typography_scans if scan.get("rejected")]
        if contaminated:
            details = "; ".join(
                f"{path.name} ({scan.get('max_confidence', 0)}%)"
                for path, scan in contaminated
            )
            raise TypographyContaminationError(
                f"Typography contamination detected. Rejected image(s): {details}. Regeneration required."
            )
    except Exception as exc:
        error = str(exc)
        rejected = isinstance(exc, TypographyContaminationError)
        blocked = isinstance(exc, TypographyEnforcementUnavailableError)
        final_status = "Rejected" if rejected else "Blocked" if blocked else "Failed"
        updated = replace_or_insert_section(text, "Status", final_status)
        updated = replace_or_insert_section(updated, "ComfyUI Prompt ID", prompt_id or "Not assigned")
        updated = replace_or_insert_section(updated, "ComfyUI Output Files", "\n".join(f"- {item}" for item in comfy_files) or "- None")
        updated = replace_or_insert_section(updated, "PODStudio Output Files", "\n".join(f"- {item}" for item in pod_files) or "- None")
        updated = replace_or_insert_section(
            updated,
            "Typography Enforcement",
            "\n".join(pod_typography_scan_summary(path, scan) for path, scan in typography_scans) or "OCR scoring did not complete.",
        )
        updated = replace_or_insert_section(updated, "Generation Error", error)
        updated = replace_or_insert_section(updated, "Generation Result", f"{final_status}: {error}")
        if rejected:
            updated = replace_or_insert_section(
                updated,
                "Suggested Next Command",
                f'`python raphael.py pod-generate "{request_id}"`',
            )
        write_generated_note(request_path, updated, config)
        pod_write_generation_log(
            config, request_id, status=final_status, prompt_id=prompt_id, workflow_path=workflow_path,
            comfy_files=comfy_files, pod_files=pod_files, error=error,
            payload_path=payload_path, http_status=http_status, response_body=response_body,
            validation_errors=validation_errors, output_folder=output_folder,
        )
        raise RuntimeError(error) from exc

    updated = replace_or_insert_section(text, "Status", "Generated")
    updated = replace_or_insert_section(updated, "ComfyUI Prompt ID", prompt_id)
    updated = replace_or_insert_section(updated, "ComfyUI Output Files", "\n".join(f"- {item}" for item in comfy_files))
    updated = replace_or_insert_section(updated, "PODStudio Output Files", "\n".join(f"- {item}" for item in pod_files))
    updated = replace_or_insert_section(
        updated,
        "Typography Enforcement",
        "\n".join(pod_typography_scan_summary(path, scan) for path, scan in typography_scans),
    )
    updated = replace_or_insert_section(updated, "Generation Error", "None")
    updated = replace_or_insert_section(
        updated,
        "Generation Result",
        f"""Generated {len(pod_files)} local image(s) with checkpoint `{checkpoint_name}`.

Output folder: `{output_folder}`

Next command: `python raphael.py pod-review-batch "{output_folder}"`""",
    )
    updated = replace_or_insert_section(
        updated,
        "Suggested Next Command",
        f'`python raphael.py pod-review-batch "{output_folder}"`',
    )
    write_generated_note(request_path, updated, config)
    pod_write_generation_log(
        config, request_id, status="Generated", prompt_id=prompt_id, workflow_path=workflow_path,
        comfy_files=comfy_files, pod_files=pod_files, payload_path=payload_path,
        http_status=http_status, response_body=response_body,
        validation_errors=validation_errors, output_folder=output_folder,
    )
    pod_pipeline(config)
    return request_path


def pod_generation_log(config: RaphaelConfig, request_ref: str) -> Path:
    request_path = pod_find_note(config, "Generation Requests", request_ref, "PODGEN-")
    request_text = read_text_if_exists(request_path, config, 80000)
    request_id = section_value(request_text, "Request ID")
    path = pod_generation_log_path(config, request_id)
    if not path.exists():
        raise FileNotFoundError(f"No generation log exists for {request_id}.")
    return path


def pod_comfyui_test(config: RaphaelConfig) -> Path:
    _, runtime = ensure_pod_studio(config)
    output_test = runtime / "generated" / ".raphael-write-test"
    checks: list[str] = []
    errors: list[str] = []
    reachable, detail, checkpoints = pod_comfyui_status(config)
    checks.append(f"- ComfyUI API reachable: {'Yes' if reachable else 'No'} - {detail}")
    stats_ok = False
    if reachable:
        try:
            pod_comfyui_json(config, "/system_stats", timeout=8)
            stats_ok = True
        except Exception as exc:
            errors.append(f"System stats unavailable: {exc}")
    checks.append(f"- System stats reachable: {'Yes' if stats_ok else 'No'}")
    checks.append(f"- Checkpoint models visible: {'Yes' if checkpoints else 'No'} ({len(checkpoints)} found)")
    model = config.pod_default_generation_model
    model_ok, checkpoint = pod_checkpoint_available(model, checkpoints)
    checks.append(f"- Configured default model `{model}` available: {'Yes' if model_ok else 'No'}{f' - {checkpoint}' if checkpoint else ''}")
    writable = False
    try:
        output_test.write_text("Raphael POD output write test.", encoding="utf-8")
        writable = output_test.exists()
        output_test.unlink(missing_ok=True)
    except OSError as exc:
        errors.append(f"PODStudio output folder is not writable: {exc}")
    checks.append(f"- PODStudio output folder writable: {'Yes' if writable else 'No'}")
    workflow_ok = False
    try:
        sample = pod_comfy_workflow("PODGEN-DIAGNOSTIC", {
            "positive": "diagnostic image", "negative": "", "size": "512x512", "steps": 1,
        }, model, 1)
        workflow_ok = all(isinstance(node, dict) and node.get("class_type") for node in sample.values())
    except Exception as exc:
        errors.append(f"Workflow validation failed: {exc}")
    checks.append(f"- Simple workflow structure valid: {'Yes' if workflow_ok else 'No'}")
    status = "Ready" if reachable and model_ok and writable and workflow_ok else "Needs Attention"
    content = f"""# POD ComfyUI Diagnostic

## Status

{status}

## Checks

{chr(10).join(checks)}

## Models

{chr(10).join(f"- {item}" for item in checkpoints) or "- None reported"}

## Errors

{chr(10).join(f"- {item}" for item in errors) or "- None"}

## Safety

Diagnostic only. No generation, publishing, upload, credentials, spending, or external platform action occurred.
"""
    path = runtime / "logs" / "ComfyUI Diagnostic.md"
    safe_path = ensure_safe_path(path, config)
    safe_path.parent.mkdir(parents=True, exist_ok=True)
    safe_path.write_text(content, encoding="utf-8")
    return path


def pod_vision_model(config: RaphaelConfig) -> tuple[str, bool, str]:
    models, status = ollama_local_models()
    if status != "ok":
        return config.vision_model, False, status
    configured_ok, configured_status = model_available("ollama", config.vision_model)
    if configured_ok:
        return config.vision_model, True, configured_status
    for candidate in models:
        if candidate.lower().startswith(("qwen2.5vl", "qwen2.5-vl")):
            return candidate, True, f"local POD fallback selected; configured model unavailable: {configured_status}"
    return config.vision_model, False, configured_status


def pod_validate_image(config: RaphaelConfig, image_path: Path) -> Path:
    path = ensure_safe_read_path(image_path, config)
    if not path.exists() or not path.is_file():
        raise FileNotFoundError(f"Image not found: {path}")
    if path.suffix.lower() not in POD_IMAGE_EXTENSIONS:
        raise ValueError(f"Unsupported image type: {path.suffix}")
    return path


def pod_image_context(config: RaphaelConfig, image: Path) -> tuple[str, str]:
    request_id = next((part for part in image.parts if part.upper().startswith("PODGEN-")), "")
    if not request_id:
        return "", ""
    try:
        request_note = pod_find_note(config, "Generation Requests", request_id, "PODGEN-")
    except FileNotFoundError:
        return request_id, ""
    request_text = read_text_if_exists(request_note, config, 80000)
    return request_id, section_value(request_text, "Concept ID")


def pod_review_prompt() -> str:
    return """Review this image as a print-on-demand apparel design. Be concise and evidence-based.
Score each criterion from 0-10: POD suitability, print readability, contrast, composition, niche clarity,
originality, text quality, artifact risk, IP/trademark risk, background cleanliness, Etsy listing potential.
Then provide Overall Score out of 100, issues, strengths, and recommended next action.
Do not identify private people. Do not claim trademark clearance."""


def pod_review_design(config: RaphaelConfig, image_path: Path) -> Path:
    root, _ = ensure_pod_studio(config)
    image = pod_validate_image(config, image_path)
    review_id = pod_make_id("PODREV", str(image))
    request_id, concept_id = pod_image_context(config, image)
    vision_model = "Disabled"
    vision_status = "Vision review disabled by POD configuration."
    if config.pod_review_with_vision_model:
        vision_model, available, vision_status = pod_vision_model(config)
        if available:
            result = call_ollama_vision_model(config, vision_model, image, pod_review_prompt())
        else:
            result = f"Local vision review unavailable: {vision_status}"
    else:
        result = "Vision review disabled. Manual review required."
    score_match = re.search(r"(?:Overall Score|overall score)\D{0,8}(\d{1,3})", result)
    base_score = min(100, int(score_match.group(1))) if score_match else 50
    typography_scan = pod_ocr_typography_scan(config, image)
    penalty = int(typography_scan.get("penalty", 0))
    score = max(0, base_score - penalty)
    typography_status = str(typography_scan.get("status", "OCR unavailable"))
    regeneration = "Required" if typography_scan.get("rejected") else "Not required"
    recommended_command = f'`python raphael.py pod-refactor-plan "{review_id}"`'
    if typography_scan.get("rejected") and request_id:
        recommended_command = f'`python raphael.py pod-generate "{request_id}"`'
    content = f"""<!-- raphael-memory: skip -->
# POD Design Review {review_id}

## Design Review ID

{review_id}

## Image Path

{image}

## Request ID

{request_id or 'Unknown'}

## Concept ID

{concept_id or 'Unknown'}

## Vision Model

{vision_model}

## Vision Model Status

{vision_status}

## Overall Score

{score}/100

## Base Score

{base_score}/100

## Typography Penalty

-{penalty}

## Typography Enforcement

{typography_status}

- Maximum OCR confidence: {typography_scan.get('max_confidence', 0)}%
- Rejected: {'Yes' if typography_scan.get('rejected') else 'No'}
- Regeneration: {regeneration}
- OCR tokens: {', '.join(str(item.get('text')) for item in typography_scan.get('tokens', []) if isinstance(item, dict)) or 'None'}

## Review Criteria

{result}

## IP/Trademark Note

This review is not legal clearance. Perform manual trademark, copyright, personality-rights, and marketplace-policy review before commercial use.

## Recommended Next Command

{recommended_command}

## Safety

- Raw image indexed into memory: no
- Image modified: no
- External API called: no
- Platform action performed: no
"""
    output = root / "Design Reviews" / f"{review_id} - {slugify(image.stem)[:60]}.md"
    write_generated_note(output, content, config)
    return output


def pod_sync_generated_variants(config: RaphaelConfig) -> list[Path]:
    root, runtime = ensure_pod_studio(config)
    notes: list[Path] = []
    for image in sorted((runtime / "generated").rglob("*")):
        if not image.is_file() or image.suffix.lower() not in POD_IMAGE_EXTENSIONS:
            continue
        request_id, concept_id = pod_image_context(config, image)
        request_status = ""
        if request_id:
            try:
                request_note = pod_find_note(config, "Generation Requests", request_id, "PODGEN-")
                request_text = read_text_if_exists(request_note, config, 80000)
                request_status = section_value(request_text, "Status")
            except FileNotFoundError:
                pass
        variant_id = "PODVAR-" + hashlib.sha1(str(image).encode("utf-8")).hexdigest()[:10].upper()
        output = root / "Generated Variants" / f"{variant_id} - {slugify(image.stem)[:60]}.md"
        content = f"""<!-- raphael-memory: skip -->
# POD Generated Variant {variant_id}

## Variant ID

{variant_id}

## Request ID

{request_id or 'Unknown'}

## Concept ID

{concept_id or 'Unknown'}

## Image Path

{image}

## File Size

{image.stat().st_size} bytes

## Request Status

{request_status or 'Unknown'}

## Storage

The raw image remains in `C:/RaphaelOS/PODStudio/generated/`. This vault note stores metadata and a local reference only.

## Safety

- Raw image copied to vault: no
- Raw image indexed into memory: no
- External upload: no
- Source image modified: no
"""
        write_generated_note(output, content, config)
        notes.append(output)
    return notes


def pod_review_batch(config: RaphaelConfig, folder_path: Path) -> Path:
    root, _ = ensure_pod_studio(config)
    folder = ensure_safe_read_path(folder_path, config)
    if not folder.exists() or not folder.is_dir():
        raise FileNotFoundError(f"Image folder not found: {folder}")
    images = [path for path in sorted(folder.rglob("*")) if path.is_file() and path.suffix.lower() in POD_IMAGE_EXTENSIONS]
    images = images[:config.pod_max_variants_per_request]
    rows = []
    for image in images:
        review = pod_review_design(config, image)
        text = read_text_if_exists(review, config)
        score = section_value(text, "Overall Score")
        rows.append((image, review, int(re.search(r"\d+", score).group()) if re.search(r"\d+", score) else 0))
    rows.sort(key=lambda row: row[2], reverse=True)
    batch_id = pod_make_id("PODBATCH", str(folder))
    content = f"""# POD Batch Review {batch_id}

## Folder

{folder}

## Images Reviewed

{len(rows)}

## Ranking

| Rank | Image | Score | Review |
|---:|---|---:|---|
{chr(10).join(f"| {index} | `{image}` | {score}/100 | `{review}` |" for index, (image, review, score) in enumerate(rows, 1)) if rows else "| - | No supported images | - | - |"}

## Safety

- Batch capped at {config.pod_max_variants_per_request} images.
- Unsupported files skipped.
- Raw images indexed into memory: no.
- Images modified: no.
"""
    output = root / "POD Studio Reviews" / f"{batch_id} - Batch Review.md"
    write_generated_note(output, content, config)
    pod_sync_generated_variants(config)
    pod_pipeline(config)
    return output


def pod_refactor_plan(config: RaphaelConfig, review_ref: str) -> Path:
    root, _ = ensure_pod_studio(config)
