def prompt_library(config: RaphaelConfig) -> Path:
    root, runtime = ensure_brand_library(config)
    sources = []
    scan_roots = [
        config.vault / "05_Business" / "Commerce" / "POD Design Studio" / "Design Prompts",
        root / "Prompt Libraries",
    ]
    for scan_root in scan_roots:
        if scan_root.exists():
            sources.extend(path for path in scan_root.glob("*.md") if path.name != "Prompt Library.md")
    rows = []
    seen = set()
    for path in sources:
        text = read_text_if_exists(path, config, 160000)
        for match in re.finditer(r"## ([^\n]+Prompt)\s+(.*?)(?=\n## |\Z)", text, flags=re.S):
            title, block = match.group(1).strip(), match.group(2)
            positive = re.search(r"(?:Positive prompt:|## Prompt\s*)([^\n]+)", block, flags=re.I)
            model = re.search(r"(?:Model:)\s*([^\n]+)", block, flags=re.I)
            prompt_text = positive.group(1).strip() if positive else summarize_text(block, 500)
            identifier = "PROMPT-" + hashlib.sha1(f"{title}|{prompt_text}".encode("utf-8")).hexdigest()[:10].upper()
            if identifier in seen:
                continue
            seen.add(identifier)
            category = "POD" if "pod design studio" in str(path).lower() else (
                "Logo" if "logo" in title.lower() else "Content"
            )
            rows.append((identifier, title, category, model.group(1).strip() if model else "Unspecified", prompt_text, path))
    content = "# Prompt Library\n\n| Prompt ID | Purpose | Category | Model | Results Used In | Performance Notes | Related Assets | Related Brands |\n|---|---|---|---|---|---|---|---|\n"
    content += "\n".join(
        f"| {identifier} | {markdown_table_escape(title)} | {category} | {markdown_table_escape(model)} | `{path.name}` | Not scored yet | Link through asset relationships | Unassigned |"
        for identifier, title, category, model, _, path in rows
    ) or "| None | No reusable prompts found | - | - | - | - | - | - |"
    content += "\n\n## Prompt Categories\n\n- Flux Prompts\n- SDXL Prompts\n- Thumbnail Prompts\n- Logo Prompts\n- POD Prompts\n- Content Prompts\n- Refactor Prompts\n"
    output = root / "Prompt Library.md"
    write_generated_note(output, content, config)
    (runtime / "prompts" / "prompt-index.json").write_text(json.dumps([
        {"prompt_id": row[0], "purpose": row[1], "category": row[2], "model": row[3], "prompt": row[4], "source": str(row[5])}
        for row in rows
    ], indent=2), encoding="utf-8")
    return output


def template_library(config: RaphaelConfig) -> Path:
    root, runtime = ensure_brand_library(config)
    categories = {
        "Listing Templates": [config.vault / "05_Business" / "Commerce" / "Listing Plans", config.vault / "05_Business" / "Commerce" / "POD Design Studio" / "Listing Drafts"],
        "Product Templates": [config.vault / "05_Business" / "Commerce" / "Product Research"],
        "Content Templates": [config.vault / "05_Business" / "Creator" / "Content Calendar", config.vault / "05_Business" / "Creator" / "Scripts"],
        "Offer Templates": [config.vault / "05_Business" / "Creator" / "Offers", config.vault / "05_Business" / "Agency" / "Service Offers"],
        "Proposal Templates": [config.vault / "05_Business" / "Agency" / "Proposals"],
        "Mockup Templates": [config.vault / "05_Business" / "Commerce" / "POD Design Studio" / "Mockup Plans"],
        "Export Templates": [config.vault / "05_Business" / "Commerce" / "POD Design Studio" / "Export Packages"],
    }
    sections = ["# Template Library"]
    index = []
    for category, folders in categories.items():
        records = []
        for folder in folders:
            if folder.exists():
                records.extend(folder.glob("*.md"))
        sections.append(f"## {category}\n\n" + ("\n".join(f"- `{path}`" for path in sorted(records)) if records else "- No templates cataloged yet."))
        index.extend({"category": category, "path": str(path)} for path in records)
    output = root / "Templates" / "Template Library.md"
    write_generated_note(output, "\n\n".join(sections) + "\n", config)
    (runtime / "templates" / "template-index.json").write_text(json.dumps(index, indent=2), encoding="utf-8")
    return output


