def knowledge_registered_sources(config: RaphaelConfig) -> list[Path]:
    inventory_dir = ensure_knowledge_dirs(config) / "Inventories"
    sources: list[Path] = []
    for path in sorted(inventory_dir.glob("*.md")):
        text = read_text_if_exists(path, config)
        value = section_value(text, "Source").strip().strip("`")
        if value:
            candidate = Path(value)
            if candidate not in sources:
                sources.append(candidate)
    return sources


def knowledge_summarize(config: RaphaelConfig, folder: Path | None = None) -> str:
    ensure_knowledge_dirs(config)
    sources = [knowledge_source_path(folder, config)] if folder else knowledge_registered_sources(config)
    if not sources:
        return "No knowledge inventories found. Run `python raphael.py knowledge-inventory \"K:\\\\Folder\"` first."
    created = 0
    existing = 0
    skipped = 0
    for source in sources:
        rows, _skip_counts = scan_knowledge_files(source, config)
        for item in knowledge_item_groups(source, rows):
            category, filename, content = knowledge_item_summary(config, item)
            output = knowledge_root(config) / category / filename
            if output.exists():
                existing += 1
                continue
            if write_file(output, content, config):
                created += 1
            else:
                skipped += 1
    return f"Knowledge summaries created: {created}; already present: {existing}; skipped: {skipped}. Source files changed: no."


def knowledge_import(config: RaphaelConfig, folder: Path) -> str:
    inventory = knowledge_inventory(config, folder)
    summary = knowledge_summarize(config, folder)
    return f"Created inventory: {inventory}\n{summary}\nRaw files copied: no. Raw files indexed: no."


def knowledge_markdown_files(config: RaphaelConfig) -> list[Path]:
    root = ensure_knowledge_dirs(config)
    ignored = ignored_knowledge_ids(config)
    files = []
    for path in root.rglob("*.md"):
        if is_sensitive_path(path):
            continue
        text = safe_markdown_text(path, config)
        knowledge_id = section_value(text or "", "Knowledge ID").strip().upper()
        if text and "raphael-knowledge-summary: true" in text.lower() and knowledge_id not in ignored and section_value(text, "Ignored") != "Yes":
            files.append(path)
    return sorted(files)


def build_knowledge_chunks(config: RaphaelConfig) -> list[dict]:
    chunks: list[dict] = []
    for path in knowledge_markdown_files(config):
        text = safe_markdown_text(path, config)
        if not text:
            continue
        for index, chunk in enumerate(chunk_markdown(text)):
            chunks.append({
                "id": memory_point_id(path, index),
                "text": chunk,
                "payload": {
                    "file_path": str(path.relative_to(config.vault)),
                    "title": markdown_title(path, text),
                    "folder": "09_Knowledge",
                    "chunk_index": index,
                    "text_preview": chunk[:300].replace("\n", " ").strip(),
                    "last_modified": dt.datetime.fromtimestamp(path.stat().st_mtime).isoformat(timespec="seconds"),
                    "knowledge_summary": True,
                    "raw_source_indexed": False,
                },
            })
    return chunks


def knowledge_index(config: RaphaelConfig) -> str:
    if not config.qdrant_enabled:
        return "Qdrant memory is disabled in config/settings.json."
    _embedding_cls, _client_cls, models, error = qdrant_dependencies()
    if error:
        return f"Qdrant memory dependencies are missing: {error}\nInstall later with: pip install qdrant-client fastembed"
    _Distance, PointStruct, _VectorParams = models
    client = qdrant_client(config)
    ensure_qdrant_collection(client, config)
    ignored_ids = ignored_knowledge_ids(config)
    ignored_point_ids: list[str] = []
    for record in knowledge_summary_records(config):
        if record["id"] not in ignored_ids:
            continue
        text = safe_markdown_text(record["path"], config) or ""
        ignored_point_ids.extend(memory_point_id(record["path"], index) for index, _chunk in enumerate(chunk_markdown(text)))
    if ignored_point_ids:
        try:
            from qdrant_client.models import PointIdsList  # type: ignore
            client.delete(collection_name=config.qdrant_collection, points_selector=PointIdsList(points=ignored_point_ids))
        except Exception as exc:
            append_memory_log(config, f"knowledge-index could not remove ignored points: {exc}")
    chunks = build_knowledge_chunks(config)
    if not chunks:
        return "No generated knowledge summaries or inventories found to index."
    embedder = embedding_model(config)
    total = 0
    for start in range(0, len(chunks), 64):
        batch = chunks[start:start + 64]
        vectors = list(embedder.embed([item["text"] for item in batch]))
        points = [PointStruct(id=item["id"], vector=vector.tolist() if hasattr(vector, "tolist") else list(vector), payload=item["payload"]) for item, vector in zip(batch, vectors)]
        client.upsert(collection_name=config.qdrant_collection, points=points)
        total += len(points)
    append_memory_log(config, f"knowledge-index indexed {total} generated summary chunks; raw source indexed=false")
    return f"Indexed {total} generated knowledge summary chunks; excluded {len(ignored_ids)} ignored item(s). Raw source files indexed: no."


def knowledge_search(config: RaphaelConfig, query: str, limit: int = 8) -> str:
    results, status = qdrant_search_results(config, query, limit=limit * 3)
    ignored_paths = {
        str(record["path"].relative_to(config.vault)).replace("\\", "/")
        for record in knowledge_summary_records(config)
        if record["id"] in ignored_knowledge_ids(config)
    }
    filtered = [
        row for row in results
        if str(row.get("file_path", "")).replace("\\", "/").startswith("09_Knowledge/")
        and str(row.get("file_path", "")).replace("\\", "/") not in ignored_paths
    ][:limit]
    lines = [f"# Knowledge Search: {query}", "", f"- Status: {status}", "- Scope: generated knowledge Markdown only", "- Raw source files searched/indexed: no", ""]
    if not filtered:
        lines.append("No generated knowledge summary matches found.")
    for row in filtered:
        lines.extend([f"## {row['title']}", f"- File: {row['file_path']}", f"- Score: {row['score']:.4f}", f"- Preview: {row['text_preview']}", ""])
    return "\n".join(lines).rstrip()


