def chunk_text_for_source(config: RaphaelConfig, source: dict) -> str:
    file_path = source.get("file_path", "")
    if not file_path or is_sensitive_path(file_path):
        return ""
    path = config.vault / file_path
    text = safe_markdown_text(path, config)
    if not text:
        return ""
    chunks = chunk_markdown(text)
    index = int(source.get("chunk_index", 0) or 0)
    if 0 <= index < len(chunks):
        return redact_secrets(chunks[index])
    return redact_secrets(source.get("text_preview", ""))


def format_memory_sources(sources: list[dict]) -> str:
    if not sources:
        return "- No Qdrant memory sources used."
    lines: list[str] = []
    for source in sources:
        lines.append(
            f"- `{source.get('file_path', 'unknown')}` "
            f"(chunk {source.get('chunk_index', 'unknown')}, score {source.get('score', 0):.4f}) "
            f"- {source.get('title', 'Untitled')}"
        )
    return "\n".join(lines)


def rag_memory_context(config: RaphaelConfig, query: str, project_name: str | None = None, limit: int = 8) -> tuple[str, list[dict], str]:
    search_query = f"{project_name} {query}".strip() if project_name else query
    sources, status = qdrant_search_results(config, search_query, limit=limit)
    if project_name:
        project_lower = slugify(project_name).lower()
        sources = sorted(
            sources,
            key=lambda item: (
                project_lower not in str(item.get("file_path", "")).lower()
                and project_lower not in str(item.get("title", "")).lower(),
                -float(item.get("score", 0.0)),
            ),
        )
    sections: list[str] = []
    for source in sources:
        chunk_text = chunk_text_for_source(config, source)
        if not chunk_text:
            chunk_text = source.get("text_preview", "")
        if not chunk_text:
            continue
        sections.append(
            f"## Memory Source: {source.get('title', 'Untitled')}\n"
            f"- File: {source.get('file_path', 'unknown')}\n"
            f"- Chunk: {source.get('chunk_index', 'unknown')}\n"
            f"- Score: {source.get('score', 0):.4f}\n\n"
            f"{chunk_text}"
        )
    context = "\n\n".join(sections)
    return trim_ai_context(context, config), sources, status


def ai_disabled_message(config: RaphaelConfig) -> str | None:
    if config.ai_provider == "none":
        return "AI is disabled because `ai_provider` is set to `none` in config/settings.json."
    if config.ai_provider not in {"openai", "ollama"}:
        return f"Unsupported ai_provider `{config.ai_provider}`. Use one of: none, openai, ollama."
    return None


def generated_project_note_context(config: RaphaelConfig, project_name: str) -> tuple[Path, str]:
    folder = require_project_folder(config, project_name)
    generated_names = [
        "Project Summary.md",
        "Architecture Notes.md",
        "Technical Stack.md",
        "Technical Debt.md",
        "Next Actions.md",
        "Project Health.md",
        "File Inventory.md",
    ]
    sections: list[str] = []
    for name in generated_names:
        text = read_text_if_exists(folder / name, config)
        if text:
            sections.append(f"## {name}\n\n{text}")
    for name in ["Risks.md", "Decisions.md", "Lessons Learned.md"]:
        text = read_text_if_exists(folder / name, config)
        if text:
            sections.append(f"## {name}\n\n{text}")
    if config.allow_ai_file_content_analysis:
        context = project_static_context(config, project_name)
        source_root = context["source_root"]
        inventory = context["inventory"]
        source_sections: list[str] = []
        for item in inventory[:30]:
            rel_path = str(item["path"])
            if is_sensitive_path(rel_path):
                continue
            if Path(rel_path).suffix.lower() not in {".md", ".txt", ".py", ".js", ".jsx", ".ts", ".tsx", ".json", ".yml", ".yaml", ".toml"}:
                continue
            snippet = read_source_file(source_root, rel_path, config)
            if snippet and not is_sensitive_path(rel_path):
                source_sections.append(f"### `{rel_path}`\n\n```text\n{redact_secrets(snippet)}\n```")
        if source_sections:
            sections.append("## Approved Source File Snippets\n\n" + "\n\n".join(source_sections))
    else:
        sections.append(
            "## AI File Content Policy\n\n"
            "Source file content analysis is disabled. Context is limited to generated vault notes and project memory."
        )
    return folder, trim_ai_context("\n\n".join(sections) or "No generated project context available.", config)


def global_ai_context(config: RaphaelConfig) -> str:
    sections: list[str] = []
    for path in [
        config.vault / "00_Raphael" / "Global Brief.md",
        config.vault / "07_Career" / "Portfolio Project Summaries.md",
        config.vault / "07_Career" / "Resume Project Bullets.md",
        config.vault / "01_Memory" / "Decision Log.md",
        config.vault / "01_Memory" / "Risk Register.md",
        config.vault / "01_Memory" / "Lessons Learned Database.md",
        config.vault / "01_Memory" / "Project Registry.md",
    ]:
        text = read_text_if_exists(path, config)
        if text:
            sections.append(f"## {path.name}\n\n{text}")
    return trim_ai_context("\n\n".join(sections) or "No global generated context available.", config)


def call_openai(config: RaphaelConfig, prompt: str, context: str) -> str:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is not set. Set it before using ai_provider `openai`.")
    payload = {
        "model": config.openai_model,
        "messages": [
            {
                "role": "system",
                "content": (
                    "You are Raphael OS, a local executive intelligence assistant. "
                    "Use only the supplied context. Do not invent source-file facts. "
                    "Do not request or expose secrets."
                ),
            },
            {"role": "user", "content": f"{prompt}\n\nCONTEXT:\n{context}"},
        ],
        "temperature": 0.2,
    }
    request = urllib.request.Request(
        "https://api.openai.com/v1/chat/completions",
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=90) as response:
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"OpenAI request failed: {exc.code} {detail}") from exc
    return data["choices"][0]["message"]["content"].strip()


def call_ollama(config: RaphaelConfig, prompt: str, context: str) -> str:
    return call_ollama_model(config, prompt, context, config.ollama_model)


def call_ollama_model(config: RaphaelConfig, prompt: str, context: str, model: str) -> str:
    payload = {
        "model": model,
        "messages": [
            {
                "role": "system",
                "content": (
                    "You are Raphael OS. Use only the provided local context. "
                    "Do not invent facts or expose secrets."
                ),
            },
            {"role": "user", "content": f"{prompt}\n\nCONTEXT:\n{context}"},
        ],
        "stream": False,
    }
    request = urllib.request.Request(
        os.environ.get("OLLAMA_URL", "http://" + os.environ.get("OLLAMA_URL", "http://localhost:11434") + "") + "/api/chat",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=180) as response:
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.URLError as exc:
        raise RuntimeError("Ollama request failed. Confirm Ollama is running on " + os.environ.get("OLLAMA_URL", "http://localhost:11434") + ".") from exc
    return data.get("message", {}).get("content", "").strip()


def call_ollama_vision_model(config: RaphaelConfig, model: str, image_path: Path, question: str) -> str:
    encoded = base64.b64encode(image_path.read_bytes()).decode("ascii")
    payload = {
        "model": model,
        "messages": [
            {
                "role": "system",
                "content": (
                    "You are Raphael OS using a local vision model. Analyze only the supplied image. "
                    "Do not infer private facts beyond visible content. Be clear when uncertain."
                ),
            },
            {
                "role": "user",
                "content": question,
                "images": [encoded],
            },
        ],
        "stream": False,
    }
    request = urllib.request.Request(
        os.environ.get("OLLAMA_URL", "http://" + os.environ.get("OLLAMA_URL", "http://localhost:11434") + "") + "/api/chat",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=240) as response:
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.URLError as exc:
        raise RuntimeError("Ollama vision request failed. Confirm Ollama is running on " + os.environ.get("OLLAMA_URL", "http://localhost:11434") + ".") from exc
    return data.get("message", {}).get("content", "").strip()


def call_openai_model(config: RaphaelConfig, prompt: str, context: str, model: str) -> str:
    original_model = config.openai_model
    try:
        config.openai_model = model
        return call_openai(config, prompt, context)
    finally:
        config.openai_model = original_model


def ollama_local_models() -> tuple[list[str], str]:
    request = urllib.request.Request(os.environ.get("OLLAMA_URL", "http://" + os.environ.get("OLLAMA_URL", "http://localhost:11434") + "") + "/api/tags", method="GET")
    try:
        with urllib.request.urlopen(request, timeout=10) as response:
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.URLError as exc:
        return [], f"Ollama unavailable: {exc}"
    models = sorted({item.get("name", "") for item in data.get("models", []) if item.get("name")})
    return models, "ok"


def model_available(provider: str, model: str) -> tuple[bool, str]:
    provider = provider.lower()
    if provider == "ollama":
        models, status = ollama_local_models()
        if status != "ok":
            return False, status
        if model in models:
            return True, "available"
        bare_model = model.split(":")[0]
        if any(candidate == bare_model or candidate.startswith(f"{bare_model}:") for candidate in models):
            return True, "available by base name"
        return False, f"not found in Ollama models: {', '.join(models) if models else 'none'}"
    if provider == "openai":
        return bool(os.environ.get("OPENAI_API_KEY")), "OPENAI_API_KEY is set" if os.environ.get("OPENAI_API_KEY") else "OPENAI_API_KEY is not set"
    if provider == "none":
        return False, "AI provider is none"
    return False, f"Unsupported provider `{provider}`"


def configured_agent_model(config: RaphaelConfig, agent_name: str) -> str:
    normalized = normalize_agent_name(agent_name)
    normalized_models = {normalize_agent_name(agent): model for agent, model in config.agent_models.items()}
    return str(normalized_models.get(normalized, config.default_model))


def route_model_for_agent(config: RaphaelConfig, agent_name: str) -> tuple[str, str, str]:
    provider = config.default_ai_provider if config.model_routing_enabled else config.ai_provider
    model = configured_agent_model(config, agent_name) if config.model_routing_enabled else (
        config.ollama_model if provider == "ollama" else config.openai_model
    )
    available, status = model_available(provider, model)
    if available:
        return provider, model, status
    fallback = config.default_model
    fallback_available, fallback_status = model_available(provider, fallback)
    if fallback_available:
        return provider, fallback, f"{model} unavailable ({status}); fell back to {fallback}"
    return provider, fallback, f"{model} unavailable ({status}); fallback {fallback} unavailable ({fallback_status})"


def call_ai_with_route(config: RaphaelConfig, provider: str, model: str, prompt: str, context: str) -> str:
    if config.ai_provider == "none":
        raise RuntimeError(ai_disabled_message(config) or "AI is disabled.")
    safe_context = trim_ai_context(context, config)
    active_provider = provider.lower()
    if config.ai_provider != "none":
        active_provider = config.ai_provider
    if active_provider == "ollama":
        routed_model = model if provider == "ollama" else config.ollama_model
        return call_ollama_model(config, prompt, safe_context, routed_model)
    if active_provider == "openai":
        openai_model = model if provider == "openai" and model else config.openai_model
        return call_openai_model(config, prompt, safe_context, openai_model)
    raise RuntimeError(f"Unsupported ai_provider `{active_provider}`.")


def call_ai(config: RaphaelConfig, prompt: str, context: str) -> str:
    disabled = ai_disabled_message(config)
    if disabled:
        raise RuntimeError(disabled)
    safe_context = trim_ai_context(context, config)
    if config.ai_provider == "openai":
        return call_openai(config, prompt, safe_context)
    if config.ai_provider == "ollama":
        return call_ollama(config, prompt, safe_context)
    raise RuntimeError(f"Unsupported ai_provider `{config.ai_provider}`.")


def ai_generated_header(config: RaphaelConfig, title: str) -> str:
    model = config.openai_model if config.ai_provider == "openai" else config.ollama_model
    return f"""# {title}

> AI-assisted output generated by Raphael OS on {today()} using provider `{config.ai_provider}` and model `{model}`.
> Review before making decisions. Source-file content analysis: {"enabled" if config.allow_ai_file_content_analysis else "disabled"}.
> Qdrant memory retrieval: {"enabled" if config.qdrant_enabled else "disabled"}.

"""


def combine_ai_context(*sections: str, config: RaphaelConfig) -> str:
    joined = "\n\n".join(section for section in sections if section.strip())
    return trim_ai_context(joined or "No context available.", config)


def disabled_ai_response(
    prompt: str,
    memory_context: str,
    memory_sources: list[dict],
    memory_status: str,
    fallback_context: str = "",
) -> str:
    previews = "\n\n".join(
        f"### {source.get('title', 'Untitled')}\n"
        f"- File: `{source.get('file_path', 'unknown')}`\n"
        f"- Score: {source.get('score', 0):.4f}\n"
        f"- Preview: {source.get('text_preview', '')}"
        for source in memory_sources
    )
    if not previews:
        previews = "- No relevant Qdrant memory chunks were available."
    fallback_preview = ""
    if not memory_sources and fallback_context:
        fallback_preview = (
            "\n\n## Fallback Vault Context Preview\n\n"
            + summarize_text(redact_secrets(fallback_context), max_chars=1600)
        )
    return f"""AI is disabled because `ai_provider` is set to `none` in config/settings.json.

## Requested Reasoning

{prompt}

## Memory Retrieval Status

{memory_status}

## Relevant Memory Results

{previews}
{fallback_preview}
"""


def ai_project_output(config: RaphaelConfig, project_name: str, output_name: str, title: str, prompt: str) -> Path:
    clean_project = slugify(project_name)
    folder, fallback_context = generated_project_note_context(config, clean_project)
    memory_context, memory_sources, memory_status = rag_memory_context(config, prompt, clean_project)
    context = combine_ai_context(
        f"# Retrieved Qdrant Memory\n\n{memory_context}" if memory_context else "",
        f"# Generated Vault Notes\n\n{fallback_context}",
        config=config,
    )
    disabled = ai_disabled_message(config)
    if disabled:
        response = disabled_ai_response(prompt, memory_context, memory_sources, memory_status, fallback_context)
    else:
        response = call_ai(
            config,
            f"{prompt}\n\nUse the retrieved memory first. Include uncertainty when context is incomplete.",
            context,
        )
    output = folder / output_name
    content = (
        ai_generated_header(config, title)
        + response.strip()
        + "\n\n## Memory Sources Used\n\n"
        + format_memory_sources(memory_sources)
        + "\n"
    )
    write_generated_note(output, content, config)
    return output


