def ai_brief(config: RaphaelConfig) -> Path:
    prompt = "Create an executive briefing across all Raphael OS projects. Include priorities, risks, lessons, portfolio leverage, and recommended focus."
    fallback_context = global_ai_context(config)
    memory_context, memory_sources, memory_status = rag_memory_context(config, prompt)
    context = combine_ai_context(
        f"# Retrieved Qdrant Memory\n\n{memory_context}" if memory_context else "",
        f"# Generated Global Vault Notes\n\n{fallback_context}",
        config=config,
    )
    disabled = ai_disabled_message(config)
    if disabled:
        response = disabled_ai_response(prompt, memory_context, memory_sources, memory_status, fallback_context)
    else:
        response = call_ai(
            config,
            f"{prompt}\n\nUse the retrieved memory first. Include uncertainty when context is incomplete.",
            context,
        )
    output = config.vault / "00_Raphael" / "AI Executive Brief.md"
    content = (
        ai_generated_header(config, "AI Executive Brief")
        + response.strip()
        + "\n\n## Memory Sources Used\n\n"
        + format_memory_sources(memory_sources)
        + "\n"
    )
    write_generated_note(output, content, config)
    return output


def infer_confidence(memory_sources: list[dict], ai_enabled: bool) -> str:
    if not memory_sources:
        return "Low"
    top_score = max(float(source.get("score", 0.0)) for source in memory_sources)
    if ai_enabled and top_score >= 0.78 and len(memory_sources) >= 3:
        return "High"
    if top_score >= 0.70:
        return "Medium"
    return "Low"


def append_ai_answer(config: RaphaelConfig, question: str, answer: str, memory_sources: list[dict], confidence: str) -> Path:
    output = ensure_safe_path(config.vault / "00_Raphael" / "AI Answers.md", config)
    output.parent.mkdir(parents=True, exist_ok=True)
    if not output.exists():
        output.write_text("# AI Answers\n\n", encoding="utf-8")
    entry = f"""## {dt.datetime.now().isoformat(timespec='seconds')}

### Question

{question}

### Answer

{answer.strip()}

### Memory Sources Used

{format_memory_sources(memory_sources)}

### Confidence

{confidence}

### Follow-up Recommendations

- Review cited notes before acting on the answer.
- Run `memory-search` with a narrower query if the sources look too broad.
- Capture a decision, risk, or lesson if this answer changes project direction.

"""
    with output.open("a", encoding="utf-8") as handle:
        handle.write(entry)
    return output


def ask_memory(config: RaphaelConfig, question: str, project_name: str | None = None) -> Path:
    prompt = (
        f"Answer this question for project `{slugify(project_name)}`: {question}"
        if project_name
        else f"Answer this question across Raphael OS memory: {question}"
    )
    fallback_context = generated_project_note_context(config, project_name)[1] if project_name else global_ai_context(config)
    memory_context, memory_sources, memory_status = rag_memory_context(config, question, project_name)
    context = combine_ai_context(
        f"# Retrieved Qdrant Memory\n\n{memory_context}" if memory_context else "",
        f"# Fallback Vault Context\n\n{fallback_context}",
        config=config,
    )
    disabled = ai_disabled_message(config)
    if disabled:
        answer = disabled_ai_response(prompt, memory_context, memory_sources, memory_status, fallback_context)
        ai_enabled = False
    else:
        answer = call_ai(
            config,
            (
                f"{prompt}\n\n"
                "Answer with practical recommendations. Include uncertainty, cite memory sources by file path, "
                "and do not use information outside the supplied context."
            ),
            context,
        )
        ai_enabled = True
    confidence = infer_confidence(memory_sources, ai_enabled)
    return append_ai_answer(config, question if not project_name else f"{slugify(project_name)}: {question}", answer, memory_sources, confidence)


def model_status_text(config: RaphaelConfig) -> str:
    provider = config.default_ai_provider
    lines = [
        "# Model Routing Status",
        "",
        f"- Model routing enabled: {config.model_routing_enabled}",
        f"- Active ai_provider: {config.ai_provider}",
        f"- Default routing provider: {config.default_ai_provider}",
        f"- Default routed model: {config.default_model}",
        "",
        "## Provider Status",
    ]
    if provider == "ollama":
        models, status = ollama_local_models()
        lines.append(f"- Ollama: {status}")
        lines.append(f"- Local models: {', '.join(models) if models else 'none detected'}")
    elif provider == "openai":
        available, status = model_available("openai", config.openai_model)
        lines.append(f"- OpenAI: {'available' if available else 'unavailable'} ({status})")
        lines.append(f"- OpenAI model: {config.openai_model}")
    else:
        lines.append(f"- Provider `{provider}` is not configured for route checks.")
    lines.extend(["", "## Agent Model Routes"])
    for agent in AGENTS:
        model = configured_agent_model(config, agent)
        available, status = model_available(provider, model)
        lines.append(f"- {agent}: `{model}` - {'available' if available else 'unavailable'} ({status})")
    lines.extend(
        [
            "",
            "## Boundary",
            "",
            "Model routing is advisory. Raphael did not execute actions or modify source project folders.",
        ]
    )
    return "\n".join(lines)


def write_model_routing_note(config: RaphaelConfig, content: str) -> Path:
    output = config.vault / "00_Raphael" / "Model Routing.md"
    write_generated_note(output, content, config)
    return output


def model_status(config: RaphaelConfig) -> Path:
    content = model_status_text(config)
    return write_model_routing_note(config, content)


def model_route_text(config: RaphaelConfig, task_description: str) -> str:
    agent, ranked = route_task_choice(task_description)
    provider, model, status = route_model_for_agent(config, agent)
    related_project = detect_related_project(config, task_description)
    ranked_lines = "\n".join(f"- {name}: {score}" for name, score in ranked if score > 0)
    if not ranked_lines:
        ranked_lines = "- No strong keyword match; defaulting to Chief of Staff Agent for triage."
    return f"""# Model Routing

Generated: {today()}

## Task

{task_description}

## Recommended Route

- Agent: {agent}
- Related project: {related_project}
- Provider: {provider}
- Model: {model}
- Model status: {status}
- Priority: {infer_task_priority(task_description)}

## Agent Routing Scores

{ranked_lines}

## Boundary

This is a routing recommendation only. Raphael did not execute actions or modify source project folders.
"""


def model_route(config: RaphaelConfig, task_description: str) -> Path:
    return write_model_routing_note(config, model_route_text(config, task_description))


def search_root(config: RaphaelConfig) -> Path:
    return config.vault / config.search_result_folder


def search_requests_dir(config: RaphaelConfig) -> Path:
    folder = search_root(config) / "Search Requests"
    ensure_safe_path(folder, config).mkdir(parents=True, exist_ok=True)
    return folder


def current_info_reason(config: RaphaelConfig, question: str) -> str:
    lowered = question.lower()
    matched = [trigger for trigger in config.current_info_triggers if trigger.lower() in lowered]
    if matched:
        return f"Question contains current-information trigger(s): {', '.join(matched)}."
    return "Question may require current web verification."


def search_file_name(question: str) -> str:
    short = slugify(question)[:70].strip()
    short = re.sub(r"\s+", "-", short).strip("-") or "search-request"
    return f"{today()}-{short}.md"


def create_search_request(config: RaphaelConfig, question: str) -> Path:
    request_id = make_search_request_id(question)
    folder = search_requests_dir(config)
    output = unique_path(folder / search_file_name(question))
    content = f"""# Search Request {request_id}

## Search Request ID

{request_id}

## Question

{question}

## Reason Current Info Is Needed

{current_info_reason(config, question)}

## Status

Pending

## Created Date

{dt.datetime.now().isoformat(timespec='seconds')}

## Source Requirement

Needs web verification

## Search Provider

{config.search_provider}

## Boundary

Raphael did not browse, search the internet, or perform external actions. This request is pending manual or approved web verification.
"""
    write_file(output, content, config)
    return output


def read_search_requests(config: RaphaelConfig) -> list[dict]:
    requests: list[dict] = []
    folder = search_requests_dir(config)
    for path in sorted(folder.glob("*.md")):
        text = read_text_if_exists(path, config)
        request_id = section_value(text, "Search Request ID") or path.stem
        requests.append(
            {
                "id": request_id,
                "question": section_value(text, "Question") or "Unknown question",
                "status": section_value(text, "Status") or "Unknown",
                "created": section_value(text, "Created Date") or "",
                "path": path,
            }
        )
    return requests


def search_review(config: RaphaelConfig) -> Path:
    requests = read_search_requests(config)
    pending = [item for item in requests if item["status"].lower() == "pending"]
    completed = [item for item in requests if item["status"].lower() == "completed"]
    content = f"""# Search Review

Generated: {today()}

## Settings

- Internet search enabled: {config.internet_search_enabled}
- Search provider: {config.search_provider}
- Search requires confirmation: {config.search_requires_confirmation}

## Pending Requests

{chr(10).join(f"- `{item['id']}` - {item['question']} ({item['created']})" for item in pending) if pending else "- No pending search requests."}

## Completed Requests

{chr(10).join(f"- `{item['id']}` - {item['question']}" for item in completed[-20:]) if completed else "- No completed search requests."}

## Boundary

Search review does not browse the internet. It only summarizes saved search request notes.
"""
    output = search_root(config) / "Search Review.md"
    write_generated_note(output, content, config)
    return output


def find_search_request(config: RaphaelConfig, request_id: str) -> Path:
    target = request_id.strip().lower()
    for item in read_search_requests(config):
        if item["id"].lower() == target:
            return item["path"]
    raise FileNotFoundError(f"Search request not found: {request_id}")


def save_search_result(config: RaphaelConfig, request_id: str, summary: str) -> Path:
    path = find_search_request(config, request_id)
    text = read_text_if_exists(path, config)
    updated = replace_or_insert_subsection(text, "Status", "Completed")
    updated = replace_or_insert_subsection(updated, "Result Summary", summary)
    updated = replace_or_insert_subsection(updated, "Result Recorded Date", dt.datetime.now().isoformat(timespec="seconds"))
    updated += "\n## Result Boundary\n\nThis result was manually supplied or filled by an approved future search tool. Raphael did not independently browse in this command.\n"
    write_generated_note(path, updated, config)
    if config.save_search_results:
        result_file = unique_path(search_root(config) / f"{request_id} Result.md")
        result_content = f"""# Search Result {request_id}

## Search Request

[[Search Requests/{path.stem}|{request_id}]]

## Summary

{summary}

## Recorded Date

{dt.datetime.now().isoformat(timespec='seconds')}

## Boundary

Raphael did not browse automatically. This note stores a supplied summary.
"""
        write_file(result_file, result_content, config)
    return path


