    piper_exe = Path(str(voice_config.get("piper_exe_path", ""))) if voice_config.get("piper_exe_path") else None
    piper_model = Path(str(voice_config.get("piper_voice_model_path", ""))) if voice_config.get("piper_voice_model_path") else None
