def generate_build_files(config: RaphaelConfig, build_id: str) -> Path:
    if not config.builder_mode_enabled:
        raise RuntimeError("Builder Mode is disabled.")
    path, text = build_request_text(config, build_id)
    complexity = section_value(text, "Complexity Level")
    # if config.builder_high_complexity_requires_plan and complexity.startswith("3"):
    #     if not section_value(text, "Related Deliberation") or not section_value(text, "Related Execution Plan"):
    #         raise PermissionError("High-complexity build generation requires council deliberation and an execution plan.")
    #     if section_value(text, "Status") != "Approved":
    #         raise PermissionError("High-complexity build plan must be explicitly approved before generation.")
    description = section_value(text, "Description")
    plan = build_plan_data(description)
    workspace = builder_safe_write_path(config, config.builder_workspace / build_id)
    workspace.mkdir(parents=True, exist_ok=True)
    # Phase 70.3: LLM Builder Engine with CLI Scaffolding
    from .builder_engine import BuilderEngine
    engine = BuilderEngine()
    
    framework = "react" if "react" in description.lower() or plan["kind"] == "web" else "vanilla"
    print("Initializing comprehensive project scaffolding...")
    
    if framework == "react":
        # Scaffold a Vite React app
        subprocess.run(["npx", "-y", "create-vite@latest", ".", "--template", "react"], cwd=str(workspace), check=True, shell=True)
        # Install dependencies
        subprocess.run(["npm", "install"], cwd=str(workspace), check=True, shell=True)
    
    print("Requesting comprehensive architectural blueprint from LLM...")
    files = engine.request_build_blueprint(description, str(plan["name"]), framework)
    
    created: list[str] = []
    for filename, content in files.items():
        target = builder_safe_write_path(config, workspace / filename)
        if target.suffix.lower() not in SAFE_BUILDER_EXTENSIONS:
            print(f"Skipping unsupported file extension: {target.suffix}")
            continue
            
        target.parent.mkdir(parents=True, exist_ok=True)
        # We allow overwriting because scaffolding creates default files
        target.write_text(content, encoding="utf-8")
        created.append(str(target))
    updated = replace_or_insert_section(text, "Status", "Generated")
    updated = replace_or_insert_section(updated, "Generated Workspace", str(workspace))
    updated = replace_or_insert_section(updated, "Generated Files", "\n".join(f"- `{item}`" for item in created))
    updated = replace_or_insert_section(updated, "Generated Date", dt.datetime.now().isoformat(timespec="seconds"))
    updated = replace_or_insert_section(updated, "Next Command", f'`python raphael.py build-complete "{build_id}"`')
    write_build_request_text(config, path, updated)
    log_path = builder_logs_dir(config) / "Builder Log.md"
    append_unique_section(log_path, f"Generated {build_id}", f"## Generated {build_id}\n\n- Date: {dt.datetime.now().isoformat(timespec='seconds')}\n- Workspace: `{workspace}`\n", config)
    generated_status = normalize_task_status(config.builder_mark_generated_as)
    sync_build_task_status(
        config,
        build_id,
        generated_status,
        f"Builder generated files for {build_id}.",
    )
    return workspace


def build_review_text(config: RaphaelConfig) -> str:
    rows = read_build_requests(config)
    pending = [row for row in rows if row["status"] in {"Requested", "Planned", "Technical Review Complete", "Council Review Not Required"}]
    awaiting_plan = [row for row in rows if row["status"] == "Awaiting Plan Approval"]
    generated = [row for row in rows if row["status"] == "Generated"]
    approved = [row for row in rows if row["status"] == "Approved"]
    return f"""# Builder Review

## Pending Builds

{chr(10).join(f"- `{row['id']}` [{row['status']}] {row['description']}" for row in pending) if pending else "- No pending builds."}

## Generated Builds

{chr(10).join(f"- `{row['id']}` {row['description']} - `{row['workspace']}`" for row in generated) if generated else "- No generated builds."}

## Awaiting Council Plan Approval

{chr(10).join(f"- `{row['id']}` [{row['complexity']}] {row['description']} - Deliberation `{row['deliberation_id'] or 'None'}` - Plan `{row['execution_plan_id'] or 'None'}`" for row in awaiting_plan) if awaiting_plan else "- No builds awaiting council plan approval."}

## Approved Builds

{chr(10).join(f"- `{row['id']}` {row['description']}" for row in approved) if approved else "- No approved builds."}
"""


