def build_approve(config: RaphaelConfig, build_id: str) -> Path:
    path, text = build_request_text(config, build_id)
    updated = replace_or_insert_section(text, "Status", "Approved")
    updated = replace_or_insert_section(updated, "Next Command", f'`python raphael.py build-generate "{build_id}"`')
    updated = replace_or_insert_section(updated, "Safety Status", "Plan approved for sandbox generation only.")
    updated = append_section_note(updated, "Approval Log", f"- {dt.datetime.now().isoformat(timespec='seconds')} - Approved for review/apply workflow by Aaron.")
    write_build_request_text(config, path, updated)
    sync_build_governance_to_task(config, build_id)
    return path


def build_apply(config: RaphaelConfig, build_id: str) -> Path:
    path, text = build_request_text(config, build_id)
    status = section_value(text, "Status")
    if status != "Approved":
        raise RuntimeError(f"Build request must be Approved before apply. Current status: {status or 'Unknown'}")
    if not config.builder_can_modify_existing_projects:
        raise PermissionError("Builder apply is disabled for real project folders because builder_can_modify_existing_projects is false.")
    raise PermissionError("Project apply is not implemented in Phase 31. Generate a diff/proposal first before real project edits.")


def self_improvement_root(config: RaphaelConfig) -> Path:
    root = config.vault / "00_Raphael" / "Self Improvement"
    ensure_safe_path(root, config).mkdir(parents=True, exist_ok=True)
    return root


def improvement_requests_dir(config: RaphaelConfig) -> Path:
    folder = self_improvement_root(config) / "Improvement Requests"
    ensure_safe_path(folder, config).mkdir(parents=True, exist_ok=True)
    return folder


def system_reviews_dir(config: RaphaelConfig) -> Path:
    folder = self_improvement_root(config) / "System Reviews"
    ensure_safe_path(folder, config).mkdir(parents=True, exist_ok=True)
    return folder


def feedback_dir(config: RaphaelConfig) -> Path:
    folder = self_improvement_root(config) / "Feedback"
    ensure_safe_path(folder, config).mkdir(parents=True, exist_ok=True)
    return folder


def ensure_self_improvement_dirs(config: RaphaelConfig) -> None:
    for folder in [self_improvement_root(config), improvement_requests_dir(config), system_reviews_dir(config), feedback_dir(config)]:
        ensure_safe_path(folder, config).mkdir(parents=True, exist_ok=True)


def make_improvement_id(description: str) -> str:
    digest = hashlib.sha1(f"{description}|{dt.datetime.now().isoformat()}".encode("utf-8")).hexdigest()[:8].upper()
    return f"IMPROVE-{today().replace('-', '')}-{digest}"


def improvement_file_name(description: str) -> str:
    short = re.sub(r"\s+", "-", slugify(description)[:70]).strip("-") or "improvement"
    return f"{today()}-{short}.md"


def create_improvement_request(
    config: RaphaelConfig,
    description: str,
    *,
    problem: str | None = None,
    evidence: str | None = None,
    proposed_fix: str | None = None,
    risk: str = "Medium",
    affected_files: str = "To be determined.",
    codex_should_implement: str = "Yes, after Aaron approves.",
) -> Path:
    if not config.self_improvement_enabled:
        raise RuntimeError("Self-improvement is disabled in config/settings.json.")
    ensure_self_improvement_dirs(config)
    improvement_id = make_improvement_id(description)
    path = unique_path(improvement_requests_dir(config) / improvement_file_name(description))
    content = f"""# Improvement Request {improvement_id}

## Improvement ID

{improvement_id}

## Description

{description}

## Problem

{problem or description}

## Evidence

{evidence or 'Captured from Aaron feedback or Raphael self-review.'}

## Proposed Fix

{proposed_fix or 'Create a scoped implementation plan, then wait for Aaron approval before code changes.'}

## Risk Level

{risk}

## Affected Files

{affected_files}

## Codex Should Implement

{codex_should_implement}

## Approval Required

Yes

## Status

Proposed

## Created Date

{dt.datetime.now().isoformat(timespec='seconds')}

## Tests Or Smoke Checks Required

- Run relevant CLI command smoke tests.
- Verify dashboard/voice behavior if UI or routing changed.
- Confirm no destructive actions or source-folder edits occur without approval.

## Boundary

Raphael created this request as an advisory proposal. Raphael did not edit core code, execute workflows, approve actions, or modify source project folders.
"""
    write_generated_note(path, content, config)
    return path


def read_improvement_requests(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_self_improvement_dirs(config)
    rows: list[dict[str, str]] = []
    for path in sorted(improvement_requests_dir(config).glob("*.md"), key=lambda item: item.stat().st_mtime, reverse=True):
        text = read_text_if_exists(path, config)
        rows.append({
            "id": section_value(text, "Improvement ID") or path.stem,
            "description": section_value(text, "Description"),
            "status": section_value(text, "Status") or "Unknown",
            "risk": section_value(text, "Risk Level") or "Unknown",
            "created": section_value(text, "Created Date"),
            "path": str(path),
        })
    return rows


def find_improvement_request(config: RaphaelConfig, improvement_id: str) -> Path:
    target = improvement_id.strip().lower()
    for row in read_improvement_requests(config):
        if row["id"].lower() == target:
            return Path(row["path"])
    raise FileNotFoundError(f"Improvement ID not found: {improvement_id}")


def improvement_plan(config: RaphaelConfig, improvement_id: str) -> Path:
    path = find_improvement_request(config, improvement_id)
    text = read_text_if_exists(path, config)
    plan = f"""## Implementation Plan

1. Confirm Aaron approves the improvement request.
2. Identify the smallest safe code or documentation change.
3. Implement in a focused patch.
4. Run smoke tests listed below.
5. Capture lessons learned after verification.

## Smoke Tests

- `python -m py_compile raphael.py C:/RaphaelOS/voice_gateway.py C:/RaphaelOS/dashboard/app.py`
- Run the affected Raphael CLI command.
- If dashboard-related, verify `http://localhost:8787`.
- If voice-related, run `python C:/RaphaelOS/voice_gateway.py test-intent "..."`

## Approval Gate

Code changes require Aaron approval before implementation.
"""
    updated = replace_or_insert_section(text, "Improvement Plan", plan)
    updated = replace_or_insert_section(updated, "Status", "Planned")
    write_generated_note(path, updated, config)
    return path


def improvement_review_text(config: RaphaelConfig) -> str:
    rows = read_improvement_requests(config)
    proposed = [row for row in rows if row["status"] in {"Proposed", "Planned"}]
    approved = [row for row in rows if row["status"] == "Approved"]
    done = [row for row in rows if row["status"] in {"Done", "Implemented"}]
    return f"""# Improvement Review

## Proposed / Planned

{chr(10).join(f"- `{row['id']}` [{row['risk']}] {row['description']} ({row['status']})" for row in proposed) if proposed else "- No proposed improvements."}

## Approved

{chr(10).join(f"- `{row['id']}` {row['description']}" for row in approved) if approved else "- No approved improvements."}

## Implemented

{chr(10).join(f"- `{row['id']}` {row['description']}" for row in done) if done else "- No implemented improvements recorded yet."}

## Boundary

Improvement review is advisory. Raphael does not rewrite itself from this command.
"""


def improvement_status_text(config: RaphaelConfig, improvement_id: str) -> str:
    path = find_improvement_request(config, improvement_id)
