def count_occurrences(text: str, needles: list[str]) -> int:
    lowered = text.lower()
    return sum(lowered.count(needle.lower()) for needle in needles)


def self_review_recommendations(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_identity_files(config)
    dashboard_log = read_text_if_exists(config.os_root / "dashboard" / "logs" / "Dashboard Chat Log.md", config)
    voice_log = read_text_if_exists(config.os_root / "voice" / "logs" / "Voice Interaction Log.md", config)
    action_log = read_text_if_exists(config.vault / "00_Raphael" / "Action Execution Log.md", config)
    workflow_log = read_text_if_exists(config.vault / "00_Raphael" / "Workflow Execution Log.md", config)
    task_review_text = read_text_if_exists(config.vault / "00_Raphael" / "Task Review.md", config)
    goal_review_text = read_text_if_exists(config.vault / "00_Raphael" / "Goal Review.md", config)
    identity_review_text = read_text_if_exists(identity_dir(config) / "Identity Review.md", config)
    combined = "\n\n".join([dashboard_log, voice_log, action_log, workflow_log, task_review_text, goal_review_text])
    recommendations: list[dict[str, str]] = []

    failures = count_occurrences(combined, ["Status: Refused", "Result status: Refused", "Status: Failed", "Raphael command failed", "Internal Server Error"])
    if failures:
        recommendations.append({
            "problem": "Some dashboard/voice/command interactions are refused or failing.",
            "evidence": f"Found {failures} refused/failed markers across logs.",
            "proposed_fix": "Group failures by command/intent, add clearer routing or safer fallback messages, and add smoke tests for the most common failed path.",
            "risk": "Low-Medium",
            "affected_files": "raphael.py, C:/RaphaelOS/voice_gateway.py, C:/RaphaelOS/dashboard/app.py",
        })

    if "```python" in dashboard_log or "pasted code" in dashboard_log.lower() or "Here's a simple Python app" in dashboard_log:
        recommendations.append({
            "problem": "Build requests previously produced code in chat instead of files.",
            "evidence": "Dashboard Chat Log contains code-block style app generation responses.",
            "proposed_fix": "Continue improving Builder Mode so code-like responses become sandboxed build requests with generated files and review status.",
            "risk": "Medium",
            "affected_files": "raphael.py, C:/RaphaelOS/voice_gateway.py, C:/RaphaelOS/dashboard/app.py",
        })

    uncertainty_markers = count_occurrences(combined, ["uncertain", "not enough context", "i may need", "i do not know", "requires current internet"])
    unsafe_markers = count_occurrences(combined, ["delete", "rename", "upload", "install", "approve-action", "execute-action"])
    refusal_markers = count_occurrences(combined, ["cannot do that safely", "refused", "approval required", "requires confirmation"])
    if config.identity_layer_enabled and uncertainty_markers == 0:
        recommendations.append({
            "problem": "Recent responses may not be disclosing uncertainty clearly enough.",
            "evidence": "Recent dashboard, voice, action, workflow, task, and goal logs did not include uncertainty markers.",
            "proposed_fix": "Tighten dashboard and voice response summaries so uncertain/current/sensitive requests use identity templates and escalation language.",
            "risk": "Low",
            "affected_files": "C:/RaphaelOS/voice_gateway.py, C:/RaphaelOS/dashboard/app.py",
        })

    if config.identity_layer_enabled and unsafe_markers and refusal_markers == 0:
        recommendations.append({
            "problem": "Potentially sensitive action language appeared without matching refusal or confirmation language.",
            "evidence": f"Found {unsafe_markers} sensitive-action marker(s), but no obvious refusal/approval-gate marker in reviewed logs.",
            "proposed_fix": "Route sensitive action requests through response templates and explicit approval gates before any planning or execution path.",
            "risk": "Medium",
            "affected_files": "raphael.py, C:/RaphaelOS/voice_gateway.py, C:/RaphaelOS/dashboard/app.py",
        })

    if config.identity_layer_enabled and "Older responses pasted code into chat" in identity_review_text:
        recommendations.append({
            "problem": "Identity review still flags older chat behavior that violated Builder Mode expectations.",
            "evidence": "Identity Review notes older code-in-chat responses.",
            "proposed_fix": "Keep Builder Mode interception active and add regression checks for app/file creation requests in dashboard chat and voice.",
            "risk": "Low-Medium",
            "affected_files": "C:/RaphaelOS/voice_gateway.py, C:/RaphaelOS/dashboard/app.py",
        })

    build_rows = read_build_requests(config)
    if len(build_rows) >= 3:
        recommendations.append({
            "problem": "Aaron is repeatedly asking Raphael to build small apps/files.",
            "evidence": f"Found {len(build_rows)} build requests in Builder Mode.",
            "proposed_fix": "Add richer Builder templates, preview links, and diff proposal support before project apply.",
            "risk": "Medium",
            "affected_files": "raphael.py, C:/RaphaelOS/dashboard/app.py",
        })

    pending_search = [item for item in read_search_requests(config) if item["status"].lower() == "pending"]
    if pending_search:
        recommendations.append({
            "problem": "Current-information questions still require manual search handling.",
            "evidence": f"{len(pending_search)} pending search request(s).",
            "proposed_fix": "Add an approved internet/search provider integration with explicit confirmation and source capture.",
            "risk": "Low-Medium",
            "affected_files": "raphael.py, C:/RaphaelOS/voice_gateway.py, C:/RaphaelOS/dashboard/app.py",
        })

    pending_vision = [item for item in read_vision_requests(config) if item["status"].lower() == "pending"]
    if pending_vision:
        recommendations.append({
            "problem": "Some vision analysis requests remain pending.",
            "evidence": f"{len(pending_vision)} pending vision request(s).",
            "proposed_fix": "Improve vision dashboard controls for running approved local analysis and surfacing model availability.",
            "risk": "Low",
            "affected_files": "raphael.py, C:/RaphaelOS/dashboard/app.py",
        })

    blocked_tasks = [task for task in all_agent_tasks(config) if task["status"] in {"Blocked", "Waiting on Aaron"}]
    if blocked_tasks:
        recommendations.append({
            "problem": "Some agent tasks are blocked or waiting on Aaron.",
            "evidence": f"{len(blocked_tasks)} blocked/waiting task(s).",
            "proposed_fix": "Add a focused waiting-on-Aaron digest and dashboard banner for blocked tasks.",
            "risk": "Low",
            "affected_files": "raphael.py, C:/RaphaelOS/dashboard/app.py",
        })

    confirmations = count_occurrences(combined, ["Confirmation Required", "awaiting confirmation", "Say confirm"])
    if confirmations >= 5:
        recommendations.append({
            "problem": "Repeated confirmation gates may need better pending-action UX.",
            "evidence": f"Found {confirmations} confirmation-related markers.",
            "proposed_fix": "Improve pending action summaries with exact command, risk, and confirm/cancel buttons while preserving approval requirements.",
            "risk": "Low",
            "affected_files": "C:/RaphaelOS/dashboard/app.py, C:/RaphaelOS/voice_gateway.py",
        })

    if not recommendations:
        recommendations.append({
            "problem": "No major recurring issue detected in current logs.",
            "evidence": "Logs and reviews did not cross simple heuristic thresholds.",
            "proposed_fix": "Continue collecting feedback and run self-review after more dashboard/voice/build usage.",
            "risk": "Low",
            "affected_files": "None",
        })
    return recommendations


def self_review(config: RaphaelConfig) -> Path:
    if not config.self_improvement_enabled:
        raise RuntimeError("Self-improvement is disabled in config/settings.json.")
    ensure_self_improvement_dirs(config)
    recommendations = self_review_recommendations(config)
    created_requests: list[Path] = []
    for rec in recommendations:
        if rec["affected_files"] != "None":
            created_requests.append(
                create_improvement_request(
                    config,
                    rec["problem"],
                    problem=rec["problem"],
                    evidence=rec["evidence"],
                    proposed_fix=rec["proposed_fix"],
                    risk=rec["risk"],
                    affected_files=rec["affected_files"],
                )
            )
    content = f"""# Raphael Self Review - {today()}

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Reviewed Sources

- `C:/RaphaelOS/dashboard/logs/Dashboard Chat Log.md`
- `C:/RaphaelOS/voice/logs/Voice Interaction Log.md`
- `00_Raphael/Action Execution Log.md`
- `00_Raphael/Workflow Execution Log.md`
- `00_Raphael/Task Review.md`
- `00_Raphael/Goal Review.md`
- Search requests
- Vision requests
- Build requests
- Identity Review

## Recommendations

{chr(10).join(f"### Recommendation {idx + 1}\n\n- Problem: {rec['problem']}\n- Evidence: {rec['evidence']}\n- Proposed fix: {rec['proposed_fix']}\n- Risk level: {rec['risk']}\n- Affected files: {rec['affected_files']}\n- Codex should implement: {'Yes, after Aaron approval.' if rec['affected_files'] != 'None' else 'No immediate implementation.'}\n- Approval required: Yes\n" for idx, rec in enumerate(recommendations))}

## Improvement Requests Created

{chr(10).join(f"- `{section_value(read_text_if_exists(path, config), 'Improvement ID')}` - {path}" for path in created_requests) if created_requests else "- No new improvement requests created."}

## Boundary

Raphael observed, measured, diagnosed, and proposed improvements only. Raphael did not rewrite core code or execute upgrades.
"""
    output = unique_path(system_reviews_dir(config) / f"{today()}-System-Review.md")
    write_generated_note(output, content, config)
    return output


