def identity_dir(config: RaphaelConfig) -> Path:
    folder = config.vault / "00_Raphael" / "Identity"
    ensure_safe_path(folder, config).mkdir(parents=True, exist_ok=True)
    return folder


def ensure_identity_files(config: RaphaelConfig) -> None:
    folder = identity_dir(config)
    for filename, content in IDENTITY_FILES.items():
        path = folder / filename
        if not path.exists():
            write_generated_note(path, content, config)


def identity_context(config: RaphaelConfig) -> str:
    ensure_identity_files(config)
    parts: list[str] = []
    for filename in [
        "Raphael Identity.md",
        "Personality Profile.md",
        "Communication Style.md",
        "Decision Principles.md",
        "Escalation Rules.md",
        "Behavior Boundaries.md",
    ]:
        text = read_text_if_exists(identity_dir(config) / filename, config)
        if text:
            parts.append(text)
    return "\n\n".join(parts)


