def identity_review(config: RaphaelConfig) -> Path:
    ensure_identity_files(config)
    dashboard_log = read_text_if_exists(config.os_root / "dashboard" / "logs" / "Dashboard Chat Log.md", config)
    voice_log = read_text_if_exists(config.os_root / "voice" / "logs" / "Voice Interaction Log.md", config)
    combined = f"{dashboard_log}\n\n{voice_log}"
    findings: list[str] = []
    if "I don't know" not in combined and "uncertain" not in combined.lower() and config.always_disclose_uncertainty:
        findings.append("- Watch for uncertainty disclosure. Recent logs have few explicit uncertainty markers.")
    if "delete" in combined.lower() and "Refused" in combined:
        findings.append("- Unsafe requests appear to be refused according to recent logs.")
    if "confirm" in combined.lower():
        findings.append("- Confirmation language is being used for gated actions.")
    if "Here's a simple Python app" in combined:
        findings.append("- Older responses pasted code into chat. Builder Mode should continue intercepting build requests.")
    if not findings:
        findings.append("- No obvious identity drift detected from recent dashboard/voice logs.")
    content = f"""# Identity Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Configuration

- Communication style: {config.communication_style}
- Response length default: {config.response_length_default}
- Always disclose uncertainty: {config.always_disclose_uncertainty}
- Prefer actionable recommendations: {config.prefer_actionable_recommendations}
- Escalate when uncertain: {config.escalate_when_uncertain}

## Findings

{chr(10).join(findings)}

## Recommendations

- Keep responses concise and action-oriented.
- Escalate uncertain, sensitive, current, destructive, financial, legal, or external-action requests.
- Use Builder Mode for app/file creation instead of large code dumps.
- Use search requests for current information unless an approved search tool is configured.

## Boundary

Identity review evaluates behavior only. It does not change permissions or execute actions.
"""
    output = identity_dir(config) / "Identity Review.md"
    write_generated_note(output, content, config)
    return output


def update_identity(config: RaphaelConfig, section: str, content: str) -> Path:
    ensure_identity_files(config)
    section_key = section.strip().lower()
    mapping = {
        "identity": "Raphael Identity.md",
        "raphael identity": "Raphael Identity.md",
        "personality": "Personality Profile.md",
        "communication": "Communication Style.md",
        "communication style": "Communication Style.md",
        "decision": "Decision Principles.md",
        "decision principles": "Decision Principles.md",
        "escalation": "Escalation Rules.md",
        "escalation rules": "Escalation Rules.md",
        "boundaries": "Behavior Boundaries.md",
        "behavior boundaries": "Behavior Boundaries.md",
        "templates": "Response Templates.md",
        "response templates": "Response Templates.md",
    }
    filename = mapping.get(section_key)
    if not filename:
        raise ValueError(f"Unknown identity section `{section}`. Use identity, personality, communication, decision, escalation, boundaries, or templates.")
    path = identity_dir(config) / filename
    if path.resolve().parent != identity_dir(config).resolve():
        raise PermissionError("update-identity can only edit identity files.")
    existing = read_text_if_exists(path, config)
    updated = append_section_note(existing, f"Update - {today()}", content)
    write_generated_note(path, updated, config)
    return path


def response_template_text(config: RaphaelConfig, template_name: str) -> str:
    ensure_identity_files(config)
    text = read_text_if_exists(identity_dir(config) / "Response Templates.md", config)
    value = section_value(text, template_name)
    if not value:
        normalized = template_name.lower().strip()
        for heading in re.findall(r"^## (.+)$", text, flags=re.M):
            if heading.lower().strip() == normalized:
                value = section_value(text, heading)
                break
    if not value:
        available = ", ".join(re.findall(r"^## (.+)$", text, flags=re.M))
        raise FileNotFoundError(f"Response template not found: {template_name}. Available: {available}")
    return value


