def world_record_id(prefix: str, name: str) -> str:
    digest = hashlib.sha1(f"{prefix}|{name}|{dt.datetime.now().isoformat()}".encode("utf-8")).hexdigest()[:8].upper()
    return f"{prefix}-{today().replace('-', '')}-{digest}"


def infer_business_category(name: str, description: str) -> str:
    text = f"{name} {description}".lower()
    for category, terms in BUSINESS_CATEGORIES.items():
        if any(term in text for term in terms):
            return category
    return "Unclassified"


def infer_world_council(record_type: str, name: str, description: str) -> str:
    category = infer_business_category(name, description)
    if category == "Software Products":
        return "Product Council, Engineering Council"
    if category == "Career/Portfolio":
        return "Career Council"
    if category in {"Agency", "Commerce", "Creator Business"}:
        return "Business Council, Product Council"
    if record_type in {"platform", "asset"}:
        return "Operations Council"
    if record_type == "relationship":
        return "Executive Council"
    return "Executive Council"


def infer_world_agents(record_type: str, name: str, description: str) -> str:
    council = infer_world_council(record_type, name, description)
    if "Engineering" in council:
        return "Developer Agent, Business Strategy Agent"
    if "Career" in council:
        return "Career Agent"
    if "Business" in council:
        return "Business Strategy Agent, Marketing Agent, Finance Agent"
    if record_type == "relationship":
        return "Chief of Staff Agent"
    return "Chief of Staff Agent"


def world_append_record(
    config: RaphaelConfig,
    record_type: str,
    name: str,
    description: str,
    *,
    parent_business: str = "",
    subtype: str = "",
) -> str:
    ensure_world_model_files(config)
    filename, prefix = WORLD_MODEL_TYPES[record_type]
    record_id = world_record_id(prefix, name)
    category = subtype or record_type.replace("_", " ").title()
    if record_type == "business":
        category = infer_business_category(name, description)
    council = infer_world_council(record_type, name, description)
    agents = infer_world_agents(record_type, name, description)
    parent_line = f"\n### Business Name\n\n{parent_business}\n" if parent_business else ""
    record = f"""
## {record_id} {name}

### ID

{record_id}

### Name

{name}

### Type

{category}

### Status

Active

### Description

{description}
{parent_line}
### Related Projects

Unlinked

### Related Goals

Unlinked

### Related Council

{council}

### Related Agents

{agents}

### Notes

- Created through Raphael World Model. Advisory record only; no business action executed.

### Created Date

{dt.datetime.now().isoformat(timespec='seconds')}
"""
    path = world_model_dir(config) / filename
    existing = read_text_if_exists(path, config)
    write_generated_note(path, existing.rstrip() + "\n\n" + record.strip() + "\n", config)
    return record_id


def read_world_records(config: RaphaelConfig, record_type: str) -> list[dict[str, str]]:
    ensure_world_model_files(config)
    filename, _ = WORLD_MODEL_TYPES[record_type]
    text = read_text_if_exists(world_model_dir(config) / filename, config)
    records: list[dict[str, str]] = []
    pattern = r"^## ([A-Z]+-\d{8}-[A-F0-9]+)\s+(.+?)(?=^## [A-Z]+-\d{8}-[A-F0-9]+|\Z)"
    for match in re.finditer(pattern, text, flags=re.M | re.S):
        body = match.group(2)
        records.append({
            "id": match.group(1),
            "name": subsection_value(body, "Name") or body.splitlines()[0].strip(),
            "type": subsection_value(body, "Type") or record_type.replace("_", " ").title(),
            "status": subsection_value(body, "Status") or "Unknown",
            "description": subsection_value(body, "Description"),
            "business": subsection_value(body, "Business Name"),
            "projects": subsection_value(body, "Related Projects") or "Unlinked",
            "goals": subsection_value(body, "Related Goals") or "Unlinked",
            "council": subsection_value(body, "Related Council"),
            "agents": subsection_value(body, "Related Agents"),
            "notes": subsection_value(body, "Notes"),
            "created": subsection_value(body, "Created Date"),
        })
    return records


def world_model_records(config: RaphaelConfig) -> dict[str, list[dict[str, str]]]:
    return {record_type: read_world_records(config, record_type) for record_type in WORLD_MODEL_TYPES}


