def world_review(config: RaphaelConfig) -> Path:
    ensure_world_model_files(config)
    records = world_model_records(config)
    businesses = records["business"]
    products = records["product"]
    revenue = records["revenue_stream"]
    platforms = records["platform"]
    project_names = list_projects(config)
    goal_rows = parse_goals(config)
    product_businesses = {item["business"].lower() for item in products if item["business"]}
    revenue_businesses = {item["business"].lower() for item in revenue if item["business"]}
    platform_names = {item["name"].lower() for item in platforms}
    review_lines: list[str] = []

    no_products = [item for item in businesses if item["name"].lower() not in product_businesses]
    review_lines.append("## Businesses With No Products\n\n" + ("\n".join(f"- {item['name']}" for item in no_products) if no_products else "- None detected."))

    products_without_revenue = [item for item in products if item["business"].lower() not in revenue_businesses]
    review_lines.append("## Products With No Revenue Stream\n\n" + ("\n".join(f"- {item['name']} ({item['business'] or 'No business linked'})" for item in products_without_revenue) if products_without_revenue else "- None detected."))

    revenue_without_platform = [item for item in revenue if not platform_names]
    review_lines.append("## Revenue Streams With No Platform\n\n" + ("\n".join(f"- {item['name']} ({item['business'] or 'No business linked'})" for item in revenue_without_platform) if revenue_without_platform else "- None detected."))

    linked_projects_text = "\n".join(item["projects"] for group in records.values() for item in group).lower()
    unlinked_projects = [project for project in project_names if project.lower() not in linked_projects_text]
    review_lines.append("## Projects Not Linked To A Business\n\n" + ("\n".join(f"- {project}" for project in unlinked_projects[:50]) if unlinked_projects else "- None detected."))

    linked_goals_text = "\n".join(item["goals"] for group in records.values() for item in group).lower()
    unlinked_goals = [goal for goal in goal_rows if goal["id"].lower() not in linked_goals_text and goal["title"].lower() not in linked_goals_text]
    review_lines.append("## Goals Not Linked To Business Or Project\n\n" + ("\n".join(f"- {goal['id']} {goal['title']}" for goal in unlinked_goals[:50]) if unlinked_goals else "- None detected."))

    missing_kpis = [item for item in businesses + products if "kpi" not in item["notes"].lower()]
    review_lines.append("## Missing KPIs\n\n" + ("\n".join(f"- {item['name']}" for item in missing_kpis) if missing_kpis else "- None detected."))

    missing_owners = [item for group in records.values() for item in group if not item["council"] or not item["agents"]]
    review_lines.append("## Missing Owners / Councils\n\n" + ("\n".join(f"- {item['name']}" for item in missing_owners) if missing_owners else "- None detected."))

    content = f"""# World Model Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

{chr(10).join(review_lines)}

## Opportunities For Structure Improvement

- Link priority projects to businesses, products, or career assets.
- Add KPIs to active businesses and products.
- Add revenue streams for products intended to become leverage.
- Assign councils/agents as advisory owners for every active business object.

## Boundary

This review identifies structure gaps only. It does not execute business actions.
"""
    output = world_model_dir(config) / "World Model Review.md"
    write_generated_note(output, content, config)
    return output


