SIMULATION_WEIGHTS = {
    "startup_cost": 1.0,
    "time_required": 1.0,
    "difficulty": 1.0,
    "revenue_potential": 1.5,
    "skill_fit": 1.3,
    "strategic_value": 1.5,
    "risk": 1.2,
    "speed_to_launch": 1.1,
    "portfolio_value": 1.2,
    "automation_potential": 1.4,
}

SIMULATION_LABELS = {
    "startup_cost": "Startup Cost",
    "time_required": "Time Required",
    "difficulty": "Difficulty",
    "revenue_potential": "Revenue Potential",
    "skill_fit": "Skill Fit",
    "strategic_value": "Strategic Value",
    "risk": "Risk",
    "speed_to_launch": "Speed To Launch",
    "portfolio_value": "Portfolio Value",
    "automation_potential": "Automation Potential",
}


def simulations_dir(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "00_Raphael" / "Simulations", config)


def ensure_simulation_files(config: RaphaelConfig) -> None:
    if not config.simulation_engine_enabled:
        raise RuntimeError("Simulation engine is disabled in config/settings.json.")
    folder = simulations_dir(config)
    folder.mkdir(parents=True, exist_ok=True)
    for filename, content in SIMULATION_FILES.items():
        path = folder / filename
        if not path.exists():
            write_generated_note(path, content, config)


def simulation_id(options: list[str]) -> str:
    digest = hashlib.sha1(("|".join(options) + dt.datetime.now().isoformat()).encode("utf-8")).hexdigest()[:8].upper()
    return f"SIM-{today().replace('-', '')}-{digest}"


def clamp_score(value: int) -> int:
    return max(1, min(10, value))


def score_option(option: str, config: RaphaelConfig) -> dict[str, int]:
    text = option.lower()
    scores = {
        "startup_cost": 6,
        "time_required": 5,
        "difficulty": 5,
        "revenue_potential": 5,
        "skill_fit": 6,
        "strategic_value": 6,
        "risk": 6,
        "speed_to_launch": 5,
        "portfolio_value": 5,
        "automation_potential": 6,
    }
    low_cost_terms = ["digital", "ebook", "newsletter", "content", "portfolio", "software", "ai", "automation", "service", "agency"]
    higher_cost_terms = ["inventory", "physical", "manufacturing", "warehouse", "ads", "paid", "hardware"]
    fast_terms = ["ebook", "template", "newsletter", "service", "agency", "portfolio", "landing page", "digital"]
    hard_terms = ["secure", "erp", "integration", "platform", "marketplace", "dashboard", "ai influencer", "machine learning"]
    revenue_terms = ["agency", "shopify", "woocommerce", "client", "service", "saas", "store", "commerce", "etsy", "integration"]
    portfolio_terms = ["secure email", "dashboard", "raphael", "mentormap", "portfolio", "github", "developer", "software"]
    automation_terms = ["ai", "automation", "dashboard", "workflow", "software", "raphael", "agent", "template"]
    risk_terms = ["legal", "compliance", "financial", "inventory", "ads", "client dependency", "security", "health"]

    if any(term in text for term in low_cost_terms):
        scores["startup_cost"] += 2
    if any(term in text for term in higher_cost_terms):
        scores["startup_cost"] -= 3
        scores["risk"] -= 2
    if any(term in text for term in fast_terms):
        scores["time_required"] += 2
        scores["speed_to_launch"] += 2
    if any(term in text for term in hard_terms):
        scores["difficulty"] -= 2
        scores["time_required"] -= 1
        scores["portfolio_value"] += 2
    if any(term in text for term in revenue_terms):
        scores["revenue_potential"] += 3
        scores["strategic_value"] += 1
    if any(term in text for term in portfolio_terms):
        scores["portfolio_value"] += 3
        scores["skill_fit"] += 2
        scores["strategic_value"] += 2
    if any(term in text for term in automation_terms):
        scores["automation_potential"] += 3
        scores["strategic_value"] += 1
    if any(term in text for term in risk_terms):
        scores["risk"] -= 2
        scores["difficulty"] -= 1
    if "print on demand" in text or "pod" in text:
        scores["startup_cost"] += 1
        scores["speed_to_launch"] += 1
        scores["revenue_potential"] += 1
        scores["risk"] -= 1
    if "kdp" in text or "amazon" in text:
        scores["startup_cost"] += 1
        scores["speed_to_launch"] += 1
        scores["revenue_potential"] += 1
    if "client" in text or "agency" in text:
        scores["skill_fit"] += 2
        scores["revenue_potential"] += 2
        scores["speed_to_launch"] += 1
        scores["risk"] -= 1
    if "career" in text or "portfolio" in text:
        scores["portfolio_value"] += 3
        scores["strategic_value"] += 2
        scores["revenue_potential"] -= 1
    return {key: clamp_score(value) for key, value in scores.items()}


def weighted_total(scores: dict[str, int]) -> float:
    return round(sum(scores[key] * SIMULATION_WEIGHTS[key] for key in SIMULATION_WEIGHTS), 2)


def option_strengths(option: str, scores: dict[str, int]) -> list[str]:
    top = sorted(scores.items(), key=lambda item: item[1], reverse=True)[:3]
    return [f"{SIMULATION_LABELS[key]} ({value}/10)" for key, value in top]


def option_weaknesses(option: str, scores: dict[str, int]) -> list[str]:
    low = sorted(scores.items(), key=lambda item: item[1])[:3]
    return [f"{SIMULATION_LABELS[key]} ({value}/10)" for key, value in low]


def option_risks(option: str, scores: dict[str, int]) -> list[str]:
    risks: list[str] = []
    if scores["risk"] <= 5:
        risks.append("Risk score is moderate or low; validate assumptions before committing resources.")
    if scores["difficulty"] <= 4:
        risks.append("Implementation difficulty may slow launch.")
    if scores["time_required"] <= 4:
        risks.append("Time required may compete with active goals and projects.")
    if scores["revenue_potential"] <= 4:
        risks.append("Revenue path may need clearer offer, customer, or pricing validation.")
    return risks or ["No major rule-based risk flagged; still validate with real-world research."]


def simulation_world_context(config: RaphaelConfig) -> str:
    try:
        records = world_model_records(config)
    except Exception:
        return "World model unavailable."
    lines: list[str] = []
    for label, key in [("Businesses", "business"), ("Products", "product"), ("Revenue Streams", "revenue_stream"), ("Platforms", "platform"), ("Assets", "asset")]:
        rows = records.get(key, [])
        if rows:
            lines.append(f"## {label}\n" + "\n".join(f"- {row['name']} [{row['type']}] {row['description']}" for row in rows[:12]))
    return "\n\n".join(lines) or "No world model records found."


def optional_simulation_ai_reasoning(config: RaphaelConfig, prompt: str, options: list[str]) -> str:
    if config.ai_provider != "ollama":
        return "AI reasoning disabled or not configured for Ollama. Rule-based simulation used."
    try:
        memory_sources, memory_status = qdrant_search_results(config, " ".join(options), limit=5)
        memory_context = "\n".join(f"- {item.get('title')}: {item.get('text_preview')}" for item in memory_sources)
        context = trim_ai_context(
            f"# World Model Context\n{simulation_world_context(config)}\n\n# Memory Context\n{memory_context}\n\nMemory status: {memory_status}",
            config,
        )
        return call_ollama(config, prompt, context)
    except Exception as exc:
        return f"AI reasoning unavailable; rule-based simulation used. Reason: {exc}"


def simulate_options(config: RaphaelConfig, options: list[str], *, mode: str = "comparison") -> Path:
    ensure_simulation_files(config)
    clean_options = [option.strip() for option in options if option.strip()]
    if len(clean_options) < 1:
        raise ValueError("At least one option is required.")
    sim_id = simulation_id(clean_options)
    scored = []
    for option in clean_options:
        scores = score_option(option, config)
        scored.append({"option": option, "scores": scores, "total": weighted_total(scores)})
    ranked = sorted(scored, key=lambda item: item["total"], reverse=True)
    winner = ranked[0]
    if mode == "business":
        score = winner["total"]
        if score >= 82:
            verdict = "Pursue now"
        elif score >= 68:
            verdict = "Research more"
        elif score >= 54:
            verdict = "Park for later"
        else:
            verdict = "Reject"
    else:
        verdict = f"Recommended winner: {winner['option']}"
    headers = "| Option | " + " | ".join(SIMULATION_LABELS[key] for key in SIMULATION_WEIGHTS) + " | Weighted Total |"
    divider = "|---" * (len(SIMULATION_WEIGHTS) + 2) + "|"
    rows = []
    for item in ranked:
        rows.append("| " + markdown_table_escape(item["option"]) + " | " + " | ".join(str(item["scores"][key]) for key in SIMULATION_WEIGHTS) + f" | {item['total']} |")
    ai_reasoning = optional_simulation_ai_reasoning(
        config,
        f"Evaluate these options for Aaron using the scoring table and provide concise strategic reasoning. Options: {', '.join(clean_options)}",
        clean_options,
    )
    content = f"""# Simulation {sim_id}

## Simulation ID

{sim_id}

## Type

{mode}

## Created Date

{dt.datetime.now().isoformat(timespec='seconds')}

## Options

{chr(10).join(f"- {option}" for option in clean_options)}

## Scoring Table

{headers}
{divider}
{chr(10).join(rows)}

## Strengths

{chr(10).join(f"### {item['option']}\n\n" + chr(10).join(f"- {strength}" for strength in option_strengths(item['option'], item['scores'])) for item in ranked)}

## Weaknesses

{chr(10).join(f"### {item['option']}\n\n" + chr(10).join(f"- {weakness}" for weakness in option_weaknesses(item['option'], item['scores'])) for item in ranked)}

## Risks

{chr(10).join(f"### {item['option']}\n\n" + chr(10).join(f"- {risk}" for risk in option_risks(item['option'], item['scores'])) for item in ranked)}

## Recommendation

{verdict}

## AI / Memory Reasoning

{ai_reasoning}

## Boundary

This simulation is advisory analysis only. Raphael did not execute business actions, spend money, access external platforms, perform external search, or edit source project folders.
"""
    result_path = simulations_dir(config) / f"{sim_id}.md"
    write_generated_note(result_path, content, config)
    results_index = simulations_dir(config) / "Simulation Results.md"
    existing = read_text_if_exists(results_index, config)
    summary = f"| {sim_id} | {today()} | {markdown_table_escape(mode)} | {markdown_table_escape(', '.join(clean_options))} | {markdown_table_escape(verdict)} | {winner['total']} |"
    if "| Simulation ID | Date | Type | Options | Recommendation | Top Score |" not in existing:
        existing = existing.rstrip() + "\n\n| Simulation ID | Date | Type | Options | Recommendation | Top Score |\n|---|---|---|---|---|---|\n"
        write_generated_note(results_index, existing, config)
    append_unique_line(results_index, summary, config)
    return result_path


def simulation_status_text(config: RaphaelConfig) -> str:
    ensure_simulation_files(config)
    result_files = [path for path in simulations_dir(config).glob("SIM-*.md")]
    return f"""# Simulation Status

- Enabled: {config.simulation_engine_enabled}
- Saved results require confirmation: {config.simulation_requires_confirmation_for_saved_results}
- Folder: `{simulations_dir(config)}`
- Results: {len(result_files)}
- AI provider: {config.ai_provider}

## Criteria

{chr(10).join(f"- {SIMULATION_LABELS[key]} (weight {SIMULATION_WEIGHTS[key]})" for key in SIMULATION_WEIGHTS)}

## Boundary

The simulation engine analyzes and recommends only. It does not execute business actions.
"""


def collect_opportunity_options(config: RaphaelConfig) -> list[str]:
    options: list[str] = []
    try:
        records = world_model_records(config)
        for key in ["business", "product", "business_idea"]:
            options.extend(row["name"] for row in records.get(key, []))
    except Exception:
        pass
    memory_business_ideas = read_text_if_exists(config.vault / "01_Memory" / "Business Ideas.md", config)
    for line in memory_business_ideas.splitlines():
        clean = line.strip(" -\t")
        if clean and not clean.startswith("#") and len(clean) <= 90:
            options.append(clean)
    goals = [goal["title"] for goal in parse_goals(config) if goal["status"] == "Active"]
    options.extend(goals[:8])
    options.extend(list_projects(config)[:20])
    for root in [config.vault / "05_Business", config.vault / "08_Notes", config.vault / "04_Research"]:
        if root.exists():
            for path in sorted(root.rglob("*Opportunity*.md"))[:12]:
                options.append(path.stem)
    deduped: list[str] = []
    seen: set[str] = set()
    for option in options:
        key = option.lower()
        if key not in seen:
            seen.add(key)
            deduped.append(option)
    return deduped[:12]


def compare_opportunities(config: RaphaelConfig) -> Path:
    options = collect_opportunity_options(config)
    if not options:
        options = ["Agency services", "Etsy store", "Software product"]
    return simulate_options(config, options, mode="opportunity comparison")


def simulation_review(config: RaphaelConfig) -> Path:
    ensure_simulation_files(config)
    result_files = sorted(simulations_dir(config).glob("SIM-*.md"), key=lambda path: path.stat().st_mtime, reverse=True)
    entries: list[str] = []
    for path in result_files[:20]:
        text = read_text_if_exists(path, config)
        entries.append(
            f"- `{section_value(text, 'Simulation ID') or path.stem}` "
            f"{section_value(text, 'Type') or 'simulation'}: {section_value(text, 'Recommendation') or 'No recommendation'}"
        )
    content = f"""# Simulation Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Total saved simulations: {len(result_files)}
- AI provider: {config.ai_provider}
- World model enabled: {config.world_model_enabled}

## Recent Simulations

{chr(10).join(entries) if entries else "- No simulations saved yet."}

## Recommended Simulation Maintenance

- Run `compare-opportunities` after adding new businesses, products, goals, or projects.
- Treat scores as prioritization aids, not proof.
- Create search requests for market-size, pricing, competitor, or current trend assumptions.
- Re-score after real customer evidence appears.

## Boundary

Simulation review is advisory only. No business action was executed.
"""
    output = simulations_dir(config) / "Simulation Review.md"
    write_generated_note(output, content, config)
    return output


