def make_opportunity_id(title: str) -> str:
    digest = hashlib.sha1(f"{title}|{dt.datetime.now().isoformat()}".encode("utf-8")).hexdigest()[:8].upper()
    return f"OPP-{today().replace('-', '')}-{digest}"


def infer_opportunity_type(title: str, description: str) -> str:
    text = f"{title} {description}".lower()
    if any(term in text for term in ["client", "agency", "service", "lead"]):
        return "Client Opportunity"
    if any(term in text for term in ["revenue", "sales", "sell", "pricing", "stream"]):
        return "Revenue Opportunity"
    if any(term in text for term in ["ebook", "product", "template", "course", "store", "kdp", "etsy"]):
        return "Product Opportunity"
    if any(term in text for term in ["content", "influencer", "newsletter", "social", "youtube"]):
        return "Content Opportunity"
    if any(term in text for term in ["portfolio", "resume", "career", "interview", "github"]):
        return "Portfolio Opportunity"
    if any(term in text for term in ["automation", "workflow", "repeated", "dashboard", "script"]):
        return "Automation Opportunity"
    if any(term in text for term in ["learn", "study", "course", "skill"]):
        return "Learning Opportunity"
    if any(term in text for term in ["business", "offer", "market"]):
        return "Business Opportunity"
    return "Business Opportunity"


def opportunity_scores(title: str, description: str) -> dict[str, int]:
    text = f"{title} {description}".lower()
    scores = {
        "revenue_potential": 5,
        "speed_to_launch": 5,
        "skill_fit": 6,
        "strategic_value": 6,
        "automation_potential": 5,
        "portfolio_value": 5,
        "risk": 6,
        "effort_required": 5,
        "confidence": 5,
    }
    if any(term in text for term in ["agency", "client", "shopify", "woocommerce", "integration", "service"]):
        scores.update({"revenue_potential": 9, "skill_fit": 8, "speed_to_launch": 7, "risk": 5, "confidence": 7})
    if any(term in text for term in ["ebook", "template", "digital", "etsy", "kdp"]):
        scores.update({"speed_to_launch": 8, "automation_potential": 8, "revenue_potential": max(scores["revenue_potential"], 7), "risk": 7})
    if any(term in text for term in ["portfolio", "secure email", "dashboard", "github", "resume"]):
        scores["portfolio_value"] = 9
        scores["strategic_value"] = 8
        scores["skill_fit"] = 8
    if any(term in text for term in ["automation", "repeated", "workflow", "self-review", "builder"]):
        scores["automation_potential"] = 9
        scores["strategic_value"] = 8
    if any(term in text for term in ["legal", "compliance", "inventory", "paid ads", "security"]):
        scores["risk"] = max(2, scores["risk"] - 2)
        scores["effort_required"] = max(2, scores["effort_required"] - 2)
    return {key: clamp_score(value) for key, value in scores.items()}


def opportunity_total(scores: dict[str, int]) -> int:
    weights = {
        "revenue_potential": 1.4,
        "speed_to_launch": 1.1,
        "skill_fit": 1.2,
        "strategic_value": 1.4,
        "automation_potential": 1.2,
        "portfolio_value": 1.1,
        "risk": 1.1,
        "effort_required": 1.0,
        "confidence": 1.0,
    }
    total = sum(scores[key] * weights[key] for key in weights)
    return int(round((total / (10 * sum(weights.values()))) * 100))


def opportunity_risk_level(score: int, scores: dict[str, int]) -> str:
    if scores["risk"] <= 4 or score < 50:
        return "High"
    if scores["risk"] <= 6 or score < 70:
        return "Medium"
    return "Low"


def opportunity_council(title: str, description: str) -> str:
    text = f"{title} {description}".lower()
    if any(term in text for term in ["portfolio", "resume", "career", "interview"]):
        return "Career Council"
    if any(term in text for term in ["automation", "software", "build", "dashboard"]) or re.search(r"\bapp\b", text):
        return "Engineering Council"
    if any(term in text for term in ["research", "market", "competitor"]):
        return "Research Council"
    return "Business Council"


def opportunity_agents(title: str, description: str) -> str:
    council = opportunity_council(title, description)
    if council == "Career Council":
        return "Career Agent, Portfolio Agent"
    if council == "Engineering Council":
        return "Developer Agent, Tech Lead Agent"
    if council == "Research Council":
        return "Research Agent, Market Analyst Agent"
    return "Business Strategy Agent, Marketing Agent, Finance Agent"


def append_opportunity(
    config: RaphaelConfig,
    title: str,
    description: str,
    *,
    source: str = "Manual entry",
    related: str = "Unlinked",
) -> str:
    ensure_opportunity_files(config)
    opp_id = make_opportunity_id(title)
    opp_type = infer_opportunity_type(title, description)
    scores = opportunity_scores(title, description)
    score = opportunity_total(scores)
    council = opportunity_council(title, description)
    agents = opportunity_agents(title, description)
    risk = opportunity_risk_level(score, scores)
    record = f"""
## {opp_id} {title}

### Opportunity ID

{opp_id}

### Title

{title}

### Type

{opp_type}

### Description

{description}

### Source Evidence

{source}

### Related Business/Project/Goal

{related}

### Suggested Council

{council}

### Suggested Agents

{agents}

### Score

{score}

### Risk Level

{risk}

### Effort Estimate

{scores['effort_required']}/10, where higher means lower effort.

### Revenue Potential

{scores['revenue_potential']}/10

### Next Recommended Action

Review the opportunity, validate assumptions, and delegate a planning task only if Aaron approves.

### Status

New

### Created Date

{dt.datetime.now().isoformat(timespec='seconds')}

### Scoring Detail

{chr(10).join(f"- {key}: {value}/10" for key, value in scores.items())}
"""
    path = opportunities_dir(config) / "Opportunity Inbox.md"
    existing = read_text_if_exists(path, config)
    if title.lower() not in existing.lower():
        write_generated_note(path, existing.rstrip() + "\n\n" + record.strip() + "\n", config)
    return opp_id


def read_opportunities(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_opportunity_files(config)
    text = read_text_if_exists(opportunities_dir(config) / "Opportunity Inbox.md", config)
    rows: list[dict[str, str]] = []
    pattern = r"^## (OPP-\d{8}-[A-F0-9]+)\s+(.+?)(?=^## OPP-\d{8}-[A-F0-9]+|\Z)"
    for match in re.finditer(pattern, text, flags=re.M | re.S):
        body = match.group(2)
        rows.append({
            "id": match.group(1),
            "title": subsection_value(body, "Title"),
            "type": subsection_value(body, "Type"),
            "description": subsection_value(body, "Description"),
            "source": subsection_value(body, "Source Evidence"),
            "related": subsection_value(body, "Related Business/Project/Goal"),
            "council": subsection_value(body, "Suggested Council"),
            "agents": subsection_value(body, "Suggested Agents"),
            "score": subsection_value(body, "Score") or "0",
            "risk": subsection_value(body, "Risk Level"),
            "effort": subsection_value(body, "Effort Estimate"),
            "revenue": subsection_value(body, "Revenue Potential"),
            "next": subsection_value(body, "Next Recommended Action"),
            "status": subsection_value(body, "Status") or "New",
            "created": subsection_value(body, "Created Date"),
        })
    return rows


def detect_opportunities(config: RaphaelConfig) -> Path:
    ensure_opportunity_files(config)
    created = 0
    records = world_model_records(config)
    businesses = records.get("business", [])
    products = records.get("product", [])
    revenues = records.get("revenue_stream", [])
    platforms = records.get("platform", [])
    product_businesses = {item["business"].lower() for item in products if item["business"]}
    revenue_businesses = {item["business"].lower() for item in revenues if item["business"]}
    for business in businesses:
        if business["name"].lower() not in product_businesses:
            append_opportunity(config, f"Create product ladder for {business['name']}", f"{business['name']} exists in the world model but has no linked products.", source="World Model: business with no products", related=business["name"])
            created += 1
    for product in products:
        if product["business"].lower() not in revenue_businesses:
            append_opportunity(config, f"Define revenue stream for {product['name']}", f"{product['name']} has no linked revenue stream.", source="World Model: product with no revenue stream", related=product["business"] or product["name"])
            created += 1
        if not platforms:
            append_opportunity(config, f"Choose sales channel for {product['name']}", f"{product['name']} needs a platform or sales channel.", source="World Model: product with no platform context", related=product["name"])
            created += 1
        append_opportunity(config, f"Create content plan for {product['name']}", f"{product['name']} needs awareness, proof, and launch content.", source="World Model: product content gap", related=product["name"])
        created += 1
    for project in list_projects(config):
        health = read_text_if_exists(project_dir(config, project) / "Project Health.md", config)
        if "70/100" in health or "80/100" in health or "90/100" in health or "Project Summary.md" in health:
            append_opportunity(config, f"Package {project} for portfolio", f"{project} appears close enough to review for portfolio leverage.", source="Project health/project registry", related=project)
            created += 1
    for sim_path in simulations_dir(config).glob("SIM-*.md") if simulations_dir(config).exists() else []:
        text = read_text_if_exists(sim_path, config)
        rec = section_value(text, "Recommendation")
        score_match = re.search(r"\|\s*([^|]+)\s*\|(?:[^|]*\|){10}\s*(\d+(?:\.\d+)?)\s*\|", text)
        if rec and score_match and float(score_match.group(2)) >= config.opportunity_score_threshold:
            append_opportunity(config, f"Advance simulation winner: {rec.replace('Recommended winner:', '').strip()}", f"Simulation {sim_path.stem} produced a high-scoring recommendation.", source=f"Simulation: {sim_path.name}", related=rec)
            created += 1
    for build in read_build_requests(config):
        if build["description"]:
            append_opportunity(config, f"Turn repeated build request into reusable template", f"Builder request `{build['id']}` suggests reusable automation or app scaffolding.", source="Build requests", related=build["id"])
            created += 1
    for rec in self_review_recommendations(config):
        if config.opportunity_auto_create_from_self_review or "automation" in rec["proposed_fix"].lower() or "builder" in rec["proposed_fix"].lower():
            append_opportunity(config, f"Improve Raphael: {rec['problem']}", rec["proposed_fix"], source=f"Self-review evidence: {rec['evidence']}", related="Self Improvement")
            created += 1
    for item in read_search_requests(config):
        if item.get("status", "").lower() == "pending":
            append_opportunity(config, f"Research pending search: {item.get('question', 'Unknown')}", "Pending search request may reveal a market, content, or decision opportunity.", source="Search requests", related=item.get("id", "Search request"))
            created += 1
    for item in read_vision_requests(config):
        if item.get("status", "").lower() == "pending":
            append_opportunity(config, f"Analyze visual input: {item.get('question', 'Unknown')}", "Pending vision request may reveal design, document, or workflow opportunity.", source="Vision requests", related=item.get("id", "Vision request"))
            created += 1
    output = opportunity_review(config)
    return output


