def opportunity_delegate(config: RaphaelConfig, opportunity_id: str, council_name: str) -> tuple[Path, Path]:
    rows = read_opportunities(config)
    target = next((row for row in rows if row["id"].lower() == opportunity_id.lower()), None)
    if not target:
        raise FileNotFoundError(f"Opportunity ID not found: {opportunity_id}")
    task = f"Evaluate opportunity `{target['id']}`: {target['title']}. Expected output: validation questions, risks, next action, and recommendation for Aaron."
    council_path, agent_path = delegate_task(config, task, council_name)
    inbox = opportunities_dir(config) / "Opportunity Inbox.md"
    text = read_text_if_exists(inbox, config)
    pattern = rf"(## {re.escape(target['id'])}\s+.*?)(?=\n## OPP-|\Z)"
    match = re.search(pattern, text, flags=re.S)
    if match:
        section = replace_or_insert_subsection(match.group(1), "Status", "Delegated")
        section = append_subsection_note(section, "Delegation Log", f"- {dt.datetime.now().isoformat(timespec='seconds')} - Delegated to {council_name}. Council task: `{council_path}` Agent task: `{agent_path}`")
        updated = text[: match.start(1)] + section.rstrip() + "\n" + text[match.end(1):]
        write_generated_note(inbox, updated, config)
    return council_path, agent_path


