def blueprints_dir(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "00_Raphael" / "Business Blueprints", config)


def ensure_blueprint_files(config: RaphaelConfig) -> None:
    if not config.business_blueprint_enabled:
        raise RuntimeError("Business blueprint generator is disabled in config/settings.json.")
    folder = blueprints_dir(config)
    folder.mkdir(parents=True, exist_ok=True)
    for filename, content in BLUEPRINT_FILES.items():
        path = folder / filename
        if not path.exists():
            write_generated_note(path, content, config)


def make_blueprint_id(idea: str) -> str:
    digest = hashlib.sha1(f"{idea}|{dt.datetime.now().isoformat()}".encode("utf-8")).hexdigest()[:8].upper()
    return f"BLUEPRINT-{today().replace('-', '')}-{digest}"


def infer_business_type(idea: str) -> str:
    text = idea.lower()
    if "print on demand" in text or "pod" in text or "etsy" in text and ("shirt" in text or "apparel" in text):
        return "Print-on-demand Etsy store"
    if "shopify" in text and "agency" not in text:
        return "Shopify store"
    if any(term in text for term in ["ebook", "kdp", "book"]):
        return "Ebook/KDP business"
    if any(term in text for term in ["influencer", "content brand", "youtube", "newsletter"]):
        return "AI influencer/content brand"
    if "automation agency" in text or "ai automation" in text:
        return "AI automation agency"
    if "web development" in text or "website agency" in text:
        return "Web development agency"
    if "agency" in text or "client service" in text:
        return "Client service agency"
    if any(term in text for term in ["saas", "software", "app", "platform"]):
        return "SaaS/software product"
    if any(term in text for term in ["civic", "permit", "economic", "local"]):
        return "Local civic-tech product"
    if any(term in text for term in ["template", "digital product", "course"]):
        return "Digital product business"
    return "Digital product business"


def blueprint_name(idea: str) -> str:
    cleaned = re.sub(r"^(create|make|blueprint|business blueprint for|a|an|the)\s+", "", idea.strip(), flags=re.I)
    return slugify(cleaned).title()


def blueprint_council_and_agents(business_type: str) -> tuple[str, str]:
    if business_type in {"SaaS/software product", "Local civic-tech product"}:
        return "Product Council, Engineering Council", "Product Manager Agent, Developer Agent, Business Strategy Agent"
    if "agency" in business_type.lower():
        return "Business Council, Operations Council", "Business Strategy Agent, Marketing Agent, Operations Agent"
    if business_type == "AI influencer/content brand":
        return "Business Council, Marketing Agent", "Marketing Agent, Business Strategy Agent, Research Agent"
    if "Ebook" in business_type or "Digital product" in business_type or "Print-on-demand" in business_type or "Shopify" in business_type:
        return "Business Council, Product Council", "Business Strategy Agent, Marketing Agent, Finance Agent"
    return "Business Council", "Business Strategy Agent, Marketing Agent"


def blueprint_estimates(business_type: str) -> tuple[str, str]:
    if "agency" in business_type.lower():
        return "$0-$200 for portfolio/site/tools; no spend authorized.", "7-21 days for MVP offer and outreach assets."
    if "Print-on-demand" in business_type:
        return "$0-$100 for samples/tools; no spend authorized.", "7-14 days for concept, designs, mockups, and validation plan."
    if "Ebook" in business_type or "Digital product" in business_type:
        return "$0-$50 for tooling; no spend authorized.", "3-10 days for outline, draft, landing page, and validation."
    if "SaaS" in business_type or "software" in business_type:
        return "$0-$50 local prototype; hosting later requires approval.", "14-45 days for prototype depending on scope."
    return "$0-$100 estimate; spending requires Aaron approval.", "7-30 days depending on validation and scope."


def blueprint_context(config: RaphaelConfig, idea: str) -> str:
    snippets = [
        "# World Model\n" + simulation_world_context(config),
        "# Active Goals\n" + "\n".join(f"- {goal['title']} [{goal['priority']}]" for goal in parse_goals(config) if goal["status"] == "Active"),
        "# Opportunities\n" + "\n".join(f"- {row['id']} [{row['score']}] {row['title']}" for row in read_opportunities(config)[:10]),
        "# Resource Profile\n" + str(resource_profile(config)),
    ]
    memory_context, _sources, status = rag_memory_context(config, idea, limit=5)
    if memory_context:
        snippets.append("# Retrieved Memory\n" + memory_context + f"\n\nMemory status: {status}")
    return trim_ai_context("\n\n".join(snippets), config)


def blueprint_ai_reasoning(config: RaphaelConfig, idea: str, business_type: str) -> str:
    if config.ai_provider != "ollama":
        return "AI reasoning disabled or not configured for Ollama. Structured rule-based blueprint generated."
    try:
        prompt = f"Improve this business blueprint reasoning for `{idea}` ({business_type}). Keep it practical, concise, and planning-only. No execution."
        return call_ollama(config, prompt, blueprint_context(config, idea))
    except Exception as exc:
        return f"AI reasoning unavailable; rule-based blueprint generated. Reason: {exc}"


def blueprint_business(config: RaphaelConfig, idea: str) -> Path:
    ensure_blueprint_files(config)
    blueprint_id = make_blueprint_id(idea)
    name = blueprint_name(idea)
    business_type = infer_business_type(idea)
    council, agents = blueprint_council_and_agents(business_type)
    startup_cost, launch_time = blueprint_estimates(business_type)
    concept = f"{name} is a {business_type.lower()} designed to turn Aaron's skills and systems into a validated offer."
    target_customer = "People or businesses with a clear need matching the idea; refine with research before spending."
    if "Etsy" in business_type or "Print-on-demand" in business_type:
        target_customer = "Niche buyers searching for identity, belief, hobby, or gift-driven products."
    elif "agency" in business_type.lower():
        target_customer = "Small businesses that need websites, integrations, AI automation, or operational support."
    elif "SaaS" in business_type or "software" in business_type:
        target_customer = "Users with a repeatable workflow pain that can be solved with software."
    ai_reasoning = blueprint_ai_reasoning(config, idea, business_type)
    content = f"""# Business Blueprint - {name}

## Blueprint ID

{blueprint_id}

## Business Name

{name}

## Business Type

{business_type}

## One-Sentence Concept

{concept}

## Target Customer

{target_customer}

## Problem Solved

The customer needs a faster, clearer, cheaper, or more reliable way to get the outcome implied by `{idea}`.

## Offer/Product

Start with one narrow MVP offer/product that can be explained in one sentence and validated before spending money.

## Revenue Model

- Direct sale, client service fee, digital product sale, subscription, or project-based pricing depending on validation.
- Do not spend or launch paid channels without Aaron approval.

## Startup Cost Estimate

{startup_cost}

## Time-To-Launch Estimate

{launch_time}

## Required Skills

- Offer definition
- Customer research
- Basic branding/content
- Writing and documentation
- Lightweight technical or automation support where useful

## Required Tools/Platforms

- Raphael OS for planning, memory, tasks, councils, and automation planning
- Obsidian vault for blueprint and decision tracking
- Potential platform/tool access later only after explicit approval

## Suggested Council Ownership

{council}

## Suggested Agents

{agents}

## MVP Scope

- Define one customer segment.
- Define one offer/product.
- Create validation questions.
- Create a simple landing/portfolio/spec artifact in Builder Mode if needed.
- Do not create stores, upload products, send outreach, or spend money in this phase.

## First 7-Day Plan

1. Clarify customer, problem, and promised outcome.
2. Draft offer/product page copy in the vault.
3. List assumptions and validation questions.
4. Run a simulation and resource allocation plan.
5. Create a research request for current market/platform facts if needed.

## First 30-Day Plan

1. Validate demand with research and non-spammy manual discovery.
2. Build the smallest proof asset.
3. Create a repeatable content or sales process on paper.
4. Capture risks, decisions, and lessons.
5. Decide whether to pursue, park, or reject.

## KPIs

- Validation responses collected
- Clear customer segment defined
- Offer/product page drafted
- Cost kept at or below approved budget
- First proof asset completed

## Risks

- Building before validating demand
- Spending money too early
- Platform policy or compliance constraints
- Too many ideas competing for focus
- Current market assumptions requiring verified research

## Assumptions

- Aaron has limited weekly time and budget.
- Raphael may plan and organize, but Aaron approves business actions.
- Current market/platform facts require search requests or approved tools.

## Open Questions

- Who is the first specific customer?
- What result are they buying?
- What would prove demand without spending money?
- What should be deliberately ignored for now?

## Automation Opportunities

- Content calendar generation
- Product/offer template generation
- Research request creation
- Task and council routing
- KPI tracking inside the vault

## Suggested Next Action

Run `python raphael.py blueprint-next-actions "{blueprint_id}"`, then decide whether to delegate validation planning to {council.split(',')[0]}.

## AI / Memory Reasoning

{ai_reasoning}

## Boundary

This blueprint is planning-only. Raphael did not create stores, spend money, upload products, send outreach, access platforms, browse externally, or execute business actions.
"""
    output = unique_path(blueprints_dir(config) / f"{blueprint_id} - {slugify(name)[:70]}.md")
    write_generated_note(output, content, config)
    index = blueprints_dir(config) / "Business Blueprint Index.md"
    row = f"| {blueprint_id} | {today()} | {markdown_table_escape(name)} | {markdown_table_escape(business_type)} | {markdown_table_escape(council)} | Run blueprint-next-actions |"
    append_unique_line(index, row, config)
    return output


def read_blueprints(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_blueprint_files(config)
    rows: list[dict[str, str]] = []
    for path in sorted(blueprints_dir(config).glob("BLUEPRINT-*.md"), key=lambda item: item.stat().st_mtime, reverse=True):
        text = read_text_if_exists(path, config)
        rows.append({
            "id": section_value(text, "Blueprint ID") or path.stem.split(" ")[0],
            "name": section_value(text, "Business Name"),
            "type": section_value(text, "Business Type"),
            "concept": section_value(text, "One-Sentence Concept"),
            "council": section_value(text, "Suggested Council Ownership") or section_value(text, "Suggested Council"),
            "agents": section_value(text, "Suggested Agents"),
            "next": section_value(text, "Suggested Next Action"),
            "path": str(path),
        })
    return rows


def find_blueprint(config: RaphaelConfig, blueprint_id: str) -> tuple[Path, str]:
    target = blueprint_id.strip().lower()
    for row in read_blueprints(config):
        if row["id"].lower() == target:
            path = Path(row["path"])
            return path, read_text_if_exists(path, config)
    raise FileNotFoundError(f"Blueprint ID not found: {blueprint_id}")


def blueprint_status_text(config: RaphaelConfig) -> str:
    ensure_blueprint_files(config)
    rows = read_blueprints(config)
    return f"""# Business Blueprint Status

- Enabled: {config.business_blueprint_enabled}
- Delegation requires confirmation: {config.business_blueprint_requires_confirmation_for_delegation}
- Default depth: {config.business_blueprint_default_depth}
- Folder: `{blueprints_dir(config)}`
- Blueprints: {len(rows)}

## Boundary

Blueprints are planning only. No business actions are executed.
"""


