def blueprint_delegate(config: RaphaelConfig, blueprint_id: str, council_name: str) -> tuple[Path, Path]:
    _path, text = find_blueprint(config, blueprint_id)
    name = section_value(text, "Business Name")
    task = f"Evaluate business blueprint `{blueprint_id}`: {name}. Expected output: validation plan, risks, first 7-day recommendation, and Aaron decision points. Do not execute business actions."
    return delegate_task(config, task, council_name)


