def commerce_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "05_Business" / "Commerce", config)


def ensure_commerce_system(config: RaphaelConfig) -> None:
    if not config.commerce_council_enabled:
        raise RuntimeError("Commerce Council is disabled in config/settings.json.")
    root = commerce_root(config)
    for rel in ["Product Research", "Listing Plans", "Store Plans", "Digital Products", "POD Ideas", "Commerce Reviews"]:
        ensure_safe_path(root / rel, config).mkdir(parents=True, exist_ok=True)
    for filename, content in COMMERCE_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)
    for agent in COMMERCE_AGENTS:
        create_agent(config, agent)
        ensure_safe_path(agent_dir(config, agent) / "Tasks", config).mkdir(parents=True, exist_ok=True)


def commerce_platforms(config: RaphaelConfig) -> str:
    return ", ".join(config.commerce_default_platforms) or "Etsy, Shopify, Amazon KDP, Gumroad, Payhip"


def commerce_note_name(title: str, prefix: str = "") -> str:
    clean = slugify(title).title()
    stem = f"{prefix} - {clean}" if prefix else clean
    return f"{today()} - {stem[:90]}.md"


def commerce_is_digital(idea: str) -> bool:
    return any(term in idea.lower() for term in ["ebook", "template", "prompt", "digital", "pdf", "worksheet", "kdp", "guide", "course"])


def commerce_ip_warning() -> str:
    return (
        "Do not use trademarked brands, copyrighted characters, protected lyrics, celebrity likenesses, "
        "sports/team marks, or copied artwork. Verify platform policies and IP risk through an approved search request before publishing."
    )


