def commerce_pipeline(config: RaphaelConfig) -> Path:
    ensure_commerce_system(config)
    pod = commerce_recent_notes(config, "POD Ideas")
    digital = commerce_recent_notes(config, "Digital Products")
    listings = commerce_recent_notes(config, "Listing Plans")
    stores = commerce_recent_notes(config, "Store Plans")
    listing_names = " ".join(path.stem.lower() for path in listings)
    rows = []
    for path in pod + digital:
        text = read_text_if_exists(path, config, 8000)
        idea = section_value(text, "Product Idea") or section_value(text, "Product Concept") or path.stem
        category = "Digital Product" if "Digital Products" in str(path) else "POD/Product Idea"
        has_listing = "Yes" if slugify(idea).lower() in listing_names or any(word in listing_names for word in slugify(idea).lower().split()[:3]) else "No"
        rows.append(f"| {markdown_table_escape(idea)} | {category} | {has_listing} | Draft/Validation | Create listing plan, verify IP/platform rules |")
    if not rows:
        rows.append("| No product ideas yet | n/a | No | Empty | Create first commerce product idea |")
    content = f"""# Commerce Product Pipeline

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

| Product / Idea | Type | Listing Plan | Stage | Next Action |
|---|---|---|---|---|
{chr(10).join(rows)}

## Store Plans

{chr(10).join(f"- {path.stem}" for path in stores[:20]) if stores else "- No store plans yet."}

## Boundary

Pipeline is planning-only. No store, upload, listing, spend, login, or external platform action was performed.
"""
    output = commerce_root(config) / "Commerce Product Pipeline.md"
    write_generated_note(output, content, config)
    return output


def commerce_review(config: RaphaelConfig) -> Path:
    ensure_commerce_system(config)
    opportunities = [row for row in read_opportunities(config) if any(term in (row.get("title", "") + row.get("description", "")).lower() for term in ["etsy", "shopify", "pod", "print", "digital", "ebook", "kdp", "commerce", "store"])]
    blueprints = [row for row in read_blueprints(config) if any(term in (row.get("name", "") + row.get("type", "") + row.get("concept", "")).lower() for term in ["etsy", "shopify", "pod", "print", "digital", "ebook", "kdp", "store"])]
    simulations = [row for row in latest_simulation_rows(config) if any(term in (row.get("options", "") + row.get("recommendation", "")).lower() for term in ["etsy", "shopify", "pod", "print", "digital", "ebook", "kdp", "store"])]
    world = world_model_records(config)
    commerce_products = [row for row in world.get("product", []) if any(term in (row.get("name", "") + row.get("description", "")).lower() for term in ["etsy", "shopify", "pod", "print", "digital", "ebook", "kdp", "store"])]
    pod = commerce_recent_notes(config, "POD Ideas")
    digital = commerce_recent_notes(config, "Digital Products")
    listings = commerce_recent_notes(config, "Listing Plans")
    stores = commerce_recent_notes(config, "Store Plans")
    findings = []
    if pod and not listings:
        findings.append("- Product/POD ideas exist with no listing plans.")
    if stores and not (pod or digital):
        findings.append("- Store plans exist with no product pipeline items.")
    if digital:
        for path in digital[:8]:
            text = read_text_if_exists(path, config, 8000)
            if not section_value(text, "Outline"):
                findings.append(f"- Digital product note may need an outline: `{path.name}`")
    if not read_text_if_exists(commerce_root(config) / "Commerce KPI Draft.md", config):
        findings.append("- Commerce KPI draft is missing.")
    if not findings:
        findings.append("- No major commerce documentation gaps detected yet.")
    content = f"""# Commerce Opportunity Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Commerce opportunities detected: {len(opportunities)}
- Commerce blueprints detected: {len(blueprints)}
- Commerce simulations detected: {len(simulations)}
- Commerce world-model products detected: {len(commerce_products)}
- Product/POD ideas: {len(pod)}
- Digital product notes: {len(digital)}
- Listing plans: {len(listings)}
- Store plans: {len(stores)}

## Findings

{chr(10).join(findings)}

## Relevant Opportunities

{chr(10).join(f"- `{row.get('id', '')}` {row.get('title', '')} [{row.get('score', '0')}]" for row in opportunities[:10]) if opportunities else "- No commerce-specific opportunities found yet."}

## Relevant Blueprints

{chr(10).join(f"- `{row.get('id', '')}` {row.get('name', '')} ({row.get('type', '')})" for row in blueprints[:10]) if blueprints else "- No commerce-specific blueprints found yet."}

## Relevant Simulations

{chr(10).join(f"- {row.get('options', '')} -> {row.get('recommendation', '')}" for row in simulations[:10]) if simulations else "- No commerce-specific simulations found yet."}

## Recommended Next Actions

- Create listing plans for the strongest product ideas.
- Create search requests for current platform rules, keywords, demand, and pricing.
- Run `python raphael.py commerce-pipeline`.
- Capture IP/compliance risks before platform work.
- Use resource allocation before starting design or build work.

## Boundary

Review is advisory only. Raphael did not create stores, upload products, spend money, log in, publish, or browse externally.
"""
    output = commerce_root(config) / "Commerce Opportunity Review.md"
    write_generated_note(output, content, config)
    dated = unique_path(commerce_root(config) / "Commerce Reviews" / commerce_note_name("Commerce Review"))
    write_generated_note(dated, content, config)
    return output


