def commerce_delegate(config: RaphaelConfig, task: str, agent_name: str) -> tuple[Path, Path]:
    ensure_commerce_system(config)
    normalized = normalize_agent_name(agent_name)
    if normalized not in COMMERCE_AGENTS:
        raise ValueError(f"Commerce delegation must target a commerce specialist agent: {', '.join(COMMERCE_AGENTS)}")
    task_path = create_agent_task(config, normalized, f"Commerce Council task: {task}. Do not perform platform actions, spending, uploads, store creation, or external execution.")
    task_text = read_text_if_exists(task_path, config)
    task_id = section_value(task_text, "Task ID")
    board = commerce_root(config) / "Commerce Task Board.md"
    row = f"| {today()} | {task_id} | {markdown_table_escape(task)} | {normalized} | Open | Planning only; no platform action |"
    append_unique_line(board, row, config)
    return board, task_path


