def agency_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "05_Business" / "Agency", config)


def ensure_agency_system(config: RaphaelConfig) -> None:
    if not config.agency_council_enabled:
        raise RuntimeError("Agency Council is disabled in config/settings.json.")
    root = agency_root(config)
    for rel in ["Lead Research", "Service Offers", "Proposals", "Client Delivery", "Agency Reviews"]:
        ensure_safe_path(root / rel, config).mkdir(parents=True, exist_ok=True)
    for filename, content in AGENCY_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)
    for agent in AGENCY_AGENTS:
        create_agent(config, agent)
        ensure_safe_path(agent_dir(config, agent) / "Tasks", config).mkdir(parents=True, exist_ok=True)


def agency_note_name(title: str, prefix: str = "") -> str:
    clean = slugify(title).title()
    stem = f"{prefix} - {clean}" if prefix else clean
    return f"{today()} - {stem[:90]}.md"


def agency_boundary_note() -> str:
    return (
        "No emails, outreach, CRM access, contract signing, invoicing, payment processing, spending, "
        "external API use, or external system action is authorized by this note."
    )


def agency_status_text(config: RaphaelConfig) -> str:
    ensure_agency_system(config)
    root = agency_root(config)
    counts = {
        "lead_research": len(list((root / "Lead Research").glob("*.md"))),
        "offers": len(list((root / "Service Offers").glob("*.md"))),
        "proposals": len(list((root / "Proposals").glob("*.md"))),
        "delivery": len(list((root / "Client Delivery").glob("*.md"))),
        "reviews": len(list((root / "Agency Reviews").glob("*.md"))),
    }
    agent_lines = "\n".join(f"- {agent}" for agent in AGENCY_AGENTS)
    return f"""# Agency Council Status

- Enabled: {config.agency_council_enabled}
- Delegation requires confirmation: {config.agency_requires_confirmation_for_delegation}
- External outreach blocked: {config.agency_no_external_outreach}
- Folder: `{root}`
- Lead/client profiles: {counts['lead_research']}
- Service offers: {counts['offers']}
- Proposal plans: {counts['proposals']}
- Delivery plans: {counts['delivery']}
- Agency reviews: {counts['reviews']}

## Specialist Agents

{agent_lines}

## Boundary

Planning only. {agency_boundary_note()}
"""


