def agency_pipeline(config: RaphaelConfig) -> Path:
    ensure_agency_system(config)
    offers = agency_recent_notes(config, "Service Offers")
    proposals = agency_recent_notes(config, "Proposals")
    delivery = agency_recent_notes(config, "Client Delivery")
    profiles = agency_recent_notes(config, "Lead Research")
    proposal_names = " ".join(path.stem.lower() for path in proposals)
    delivery_names = " ".join(path.stem.lower() for path in delivery)
    rows = []
    for path in offers:
        text = read_text_if_exists(path, config, 8000)
        service = section_value(text, "Service Name") or path.stem
        key_words = slugify(service).lower().split()[:3]
        has_proposal = "Yes" if any(word in proposal_names for word in key_words) else "No"
        has_delivery = "Yes" if any(word in delivery_names for word in key_words) else "No"
        rows.append(f"| {markdown_table_escape(service)} | Service Offer | {has_proposal} | {has_delivery} | Draft/Validation | Create client profile and proposal plan |")
    if not rows:
        rows.append("| No service offers yet | n/a | No | No | Empty | Create first agency service offer |")
    content = f"""# Agency Pipeline

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

| Service / Offer | Type | Proposal Plan | Delivery Plan | Stage | Next Action |
|---|---|---|---|---|---|
{chr(10).join(rows)}

## Client Profiles

{chr(10).join(f"- {path.stem}" for path in profiles[:20]) if profiles else "- No client profiles yet."}

## Boundary

Pipeline is planning-only. {agency_boundary_note()}
"""
    output = agency_root(config) / "Agency Pipeline.md"
    write_generated_note(output, content, config)
    return output


def agency_review(config: RaphaelConfig) -> Path:
    ensure_agency_system(config)
    offers = agency_recent_notes(config, "Service Offers")
    profiles = agency_recent_notes(config, "Lead Research")
    proposals = agency_recent_notes(config, "Proposals")
    delivery = agency_recent_notes(config, "Client Delivery")
    blueprints = [row for row in read_blueprints(config) if any(term in (row.get("name", "") + row.get("type", "") + row.get("concept", "")).lower() for term in ["agency", "service", "consulting", "shopify", "woocommerce", "automation", "integration"])]
    simulations = [row for row in latest_simulation_rows(config) if any(term in (row.get("options", "") + row.get("recommendation", "")).lower() for term in ["agency", "service", "consulting", "shopify", "woocommerce", "automation", "integration"])]
    opportunities = [row for row in read_opportunities(config) if any(term in (row.get("title", "") + row.get("description", "")).lower() for term in ["agency", "client", "service", "shopify", "woocommerce", "automation", "integration"])]
    world = world_model_records(config)
    world_agency = [row for row in world.get("business", []) + world.get("product", []) if any(term in (row.get("name", "") + row.get("description", "")).lower() for term in ["agency", "service", "client", "consulting", "shopify", "woocommerce", "automation", "integration"])]
    proposal_names = " ".join(path.stem.lower() for path in proposals)
    delivery_names = " ".join(path.stem.lower() for path in delivery)
    findings = []
    if offers and not delivery:
        findings.append("- Service offers exist with no delivery plans.")
    if offers and not proposals:
        findings.append("- Service offers exist with no proposal plans.")
    if offers and not profiles:
        findings.append("- Service offers exist with no client profiles.")
    for path in offers[:10]:
        text = read_text_if_exists(path, config, 8000)
        service = section_value(text, "Service Name") or path.stem
        if not section_value(text, "Pricing Assumptions"):
            findings.append(f"- Service offer missing pricing assumptions: `{path.name}`")
        words = slugify(service).lower().split()[:3]
        if not any(word in delivery_names for word in words):
            findings.append(f"- Service may need delivery plan: {service}")
        if not any(word in proposal_names for word in words):
            findings.append(f"- Service may need proposal plan: {service}")
    if not findings:
        findings.append("- No major agency documentation gaps detected yet.")
    content = f"""# Agency Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Service offers: {len(offers)}
- Client profiles: {len(profiles)}
- Proposal plans: {len(proposals)}
- Delivery plans: {len(delivery)}
- Agency-related opportunities: {len(opportunities)}
- Agency-related blueprints: {len(blueprints)}
- Agency-related simulations: {len(simulations)}
- Agency-related world model records: {len(world_agency)}

## Findings

{chr(10).join(findings)}

## Relevant Opportunities

{chr(10).join(f"- `{row.get('id', '')}` {row.get('title', '')} [{row.get('score', '0')}]" for row in opportunities[:10]) if opportunities else "- No agency-specific opportunities found yet."}

## Relevant Blueprints

{chr(10).join(f"- `{row.get('id', '')}` {row.get('name', '')} ({row.get('type', '')})" for row in blueprints[:10]) if blueprints else "- No agency-specific blueprints found yet."}

## Relevant Simulations

{chr(10).join(f"- {row.get('options', '')} -> {row.get('recommendation', '')}" for row in simulations[:10]) if simulations else "- No agency-specific simulations found yet."}

## Recommended Next Actions

- Create delivery plans for active service offers.
- Create proposal plans for services Aaron might sell later.
- Create client profiles before outreach is considered.
- Use search requests for current market/pricing/platform facts.
- Keep outreach, email, contracts, CRM, invoicing, and payment actions approval-gated and outside this phase.

## Boundary

Review is advisory only. {agency_boundary_note()}
"""
    output = agency_root(config) / "Agency Review.md"
    write_generated_note(output, content, config)
    dated = unique_path(agency_root(config) / "Agency Reviews" / agency_note_name("Agency Review"))
    write_generated_note(dated, content, config)
    return output


