def agency_delegate(config: RaphaelConfig, task: str, agent_name: str) -> tuple[Path, Path]:
    ensure_agency_system(config)
    normalized = normalize_agent_name(agent_name)
    if normalized not in AGENCY_AGENTS:
        raise ValueError(f"Agency delegation must target an agency specialist agent: {', '.join(AGENCY_AGENTS)}")
    task_path = create_agent_task(config, normalized, f"Agency Council task: {task}. Do not send outreach, emails, contracts, invoices, payments, CRM updates, or external actions.")
    task_text = read_text_if_exists(task_path, config)
    task_id = section_value(task_text, "Task ID")
    board = agency_root(config) / "Agency Task Board.md"
    row = f"| {today()} | {task_id} | {markdown_table_escape(task)} | {normalized} | Open | Planning only; no outreach/external action |"
