def creator_recent_notes(config: RaphaelConfig, subfolder: str) -> list[Path]:
    folder = creator_root(config) / subfolder
    if not folder.exists():
        return []
    return sorted(folder.glob("*.md"), key=lambda item: item.stat().st_mtime, reverse=True)


def creator_pipeline(config: RaphaelConfig) -> Path:
    ensure_creator_system(config)
    ideas = creator_recent_notes(config, "Content Ideas")
    plans = creator_recent_notes(config, "Content Calendar")
    scripts = creator_recent_notes(config, "Scripts")
    ebooks = creator_recent_notes(config, "Ebooks")
    offers = creator_recent_notes(config, "Offers")
    plan_names = " ".join(path.stem.lower() for path in plans)
    script_names = " ".join(path.stem.lower() for path in scripts)
    rows = []
    for path in ideas + ebooks + offers:
        text = read_text_if_exists(path, config, 8000)
        topic = section_value(text, "Topic") or section_value(text, "Offer") or path.stem
        item_type = "Ebook" if "Ebooks" in str(path) else "Offer" if "Offers" in str(path) else "Content Idea"
        words = slugify(topic).lower().split()[:3]
        has_plan = "Yes" if any(word in plan_names for word in words) else "No"
        has_script = "Yes" if any(word in script_names for word in words) else "No"
        rows.append(f"| {markdown_table_escape(topic)} | {item_type} | {has_plan} | {has_script} | Draft/Planning | Create plan/script/funnel link |")
    if not rows:
        rows.append("| No creator items yet | n/a | No | No | Empty | Create first content idea |")
    content = f"""# Creator Pipeline

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

| Topic / Asset | Type | Content Plan | Script | Stage | Next Action |
|---|---|---|---|---|---|
{chr(10).join(rows)}

## Boundary

Pipeline is planning-only. {creator_boundary_note()}
"""
    output = creator_root(config) / "Creator Pipeline.md"
    write_generated_note(output, content, config)
    return output


def creator_review(config: RaphaelConfig) -> Path:
    ensure_creator_system(config)
    ideas = creator_recent_notes(config, "Content Ideas")
    plans = creator_recent_notes(config, "Content Calendar")
    scripts = creator_recent_notes(config, "Scripts")
    ebooks = creator_recent_notes(config, "Ebooks")
    offers = creator_recent_notes(config, "Offers")
    blueprints = [row for row in read_blueprints(config) if any(term in (row.get("name", "") + row.get("type", "") + row.get("concept", "")).lower() for term in ["creator", "influencer", "content", "ebook", "newsletter", "digital"])]
    opportunities = [row for row in read_opportunities(config) if any(term in (row.get("title", "") + row.get("description", "")).lower() for term in ["creator", "content", "ebook", "newsletter", "influencer", "audience", "funnel"])]
    findings = []
    if ideas and not plans:
        findings.append("- Content ideas exist with no content plans.")
    if plans and not scripts:
        findings.append("- Content plans exist with no scripts.")
    if ebooks and not offers:
        findings.append("- Ebook plans exist with no related offer/funnel plan.")
    if offers and not plans:
        findings.append("- Offer plans exist with no supporting content plan.")
    if not findings:
        findings.append("- No major creator documentation gaps detected yet.")
    content = f"""# Creator Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Content ideas: {len(ideas)}
- Content plans/calendar notes: {len(plans)}
- Scripts: {len(scripts)}
- Ebook plans: {len(ebooks)}
- Offer plans: {len(offers)}
- Creator-related opportunities: {len(opportunities)}
- Creator-related business blueprints: {len(blueprints)}

## Findings

{chr(10).join(findings)}

## Relevant Opportunities

{chr(10).join(f"- `{row.get('id', '')}` {row.get('title', '')} [{row.get('score', '0')}]" for row in opportunities[:10]) if opportunities else "- No creator-specific opportunities found yet."}

## Business Blueprints Connected To Content

{chr(10).join(f"- `{row.get('id', '')}` {row.get('name', '')} ({row.get('type', '')})" for row in blueprints[:10]) if blueprints else "- No creator-specific blueprints found yet."}

## Recommended Next Actions

- Convert strong content ideas into content plans.
- Create scripts for near-term short-form content.
- Connect ebooks and offers into a funnel map.
- Use search requests for current platform/trend facts.
- Do not publish, upload, email, or access external platforms in this phase.

## Boundary

Review is advisory only. {creator_boundary_note()}
"""
    output = creator_root(config) / "Creator Review.md"
    write_generated_note(output, content, config)
    dated = unique_path(creator_root(config) / "Creator Reviews" / creator_note_name("Creator Review"))
    write_generated_note(dated, content, config)
    return output


