def make_kpi_id(name: str) -> str:
    digest = hashlib.sha1(f"{name}|{dt.datetime.now().isoformat()}".encode("utf-8")).hexdigest()[:8].upper()
    return f"KPI-{today().replace('-', '')}-{digest}"


def kpi_record_block(kpi: dict[str, str]) -> str:
    return f"""## {kpi['id']}

### Name

{kpi['name']}

### Category

{kpi['category']}

### Owner Council

{kpi.get('owner_council', 'Unassigned')}

### Related Business

{kpi.get('related_business', 'Unassigned')}

### Related Project

{kpi.get('related_project', 'Unassigned')}

### Target

{kpi.get('target', '')}

### Current Value

{kpi.get('current_value', '0')}

### Previous Value

{kpi.get('previous_value', '0')}

### Status

{kpi.get('status', 'Unknown')}

### Last Updated

{kpi.get('last_updated', today())}

### Notes

{kpi.get('notes', 'Seeded KPI.')}

### History

{kpi.get('history', f'- {today()}: Created KPI with target {kpi.get("target", "")}.')}
"""


def read_kpis(config: RaphaelConfig) -> list[dict[str, str]]:
    registry = kpi_root(config) / "KPI Registry.md"
    if not registry.exists():
        return []
    text = read_text_if_exists(registry, config)
    pattern = r"^## (KPI-\d{8}-[A-F0-9]+)\s+(.+?)(?=^## KPI-\d{8}-[A-F0-9]+|\Z)"
    rows: list[dict[str, str]] = []
    for match in re.finditer(pattern, text, flags=re.M | re.S):
        body = match.group(2)
        rows.append({
            "id": match.group(1),
            "name": subsection_value(body, "Name"),
            "category": subsection_value(body, "Category"),
            "owner_council": subsection_value(body, "Owner Council"),
            "related_business": subsection_value(body, "Related Business"),
            "related_project": subsection_value(body, "Related Project"),
            "target": subsection_value(body, "Target"),
            "current_value": subsection_value(body, "Current Value"),
            "previous_value": subsection_value(body, "Previous Value"),
            "status": subsection_value(body, "Status") or "Unknown",
            "last_updated": subsection_value(body, "Last Updated"),
            "notes": subsection_value(body, "Notes"),
            "history": subsection_value(body, "History"),
        })
    return rows


def write_kpis(config: RaphaelConfig, rows: list[dict[str, str]]) -> None:
    registry = kpi_root(config) / "KPI Registry.md"
    content = "# KPI Registry\n\n" + "\n".join(kpi_record_block(row).strip() for row in rows) + "\n"
    write_generated_note(registry, content, config)
    targets = kpi_root(config) / "KPI Targets.md"
    target_rows = [
        f"| {row['id']} | {markdown_table_escape(row['name'])} | {markdown_table_escape(row['category'])} | {markdown_table_escape(row.get('target', ''))} | {markdown_table_escape(row.get('owner_council', 'Unassigned'))} | {markdown_table_escape(row.get('status', 'Unknown'))} |"
        for row in rows
    ]
    write_generated_note(targets, "# KPI Targets\n\n| KPI ID | Name | Category | Target | Owner Council | Status |\n|---|---|---|---|---|---|\n" + "\n".join(target_rows) + "\n", config)


def infer_kpi_status(value: str, target: str) -> str:
    try:
        current = float(re.sub(r"[^0-9.\-]", "", value) or "0")
        target_number = float(re.sub(r"[^0-9.\-]", "", target) or "0")
    except ValueError:
        return "Unknown"
    if target_number <= 0:
        return "Unknown"
    ratio = current / target_number
    if ratio >= 1:
        return "On Track"
    if ratio >= 0.7:
        return "At Risk"
    return "Behind"


