def kpi_dashboard(config: RaphaelConfig) -> Path:
    ensure_kpi_system(config)
    rows = read_kpis(config)
    grouped: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        grouped.setdefault(row["category"], []).append(row)
    sections = []
    for category in sorted(grouped):
        table_rows = "\n".join(
            f"| {row['id']} | {markdown_table_escape(row['name'])} | {markdown_table_escape(row.get('current_value', ''))} | {markdown_table_escape(row.get('target', ''))} | {markdown_table_escape(row.get('status', 'Unknown'))} | {markdown_table_escape(row.get('last_updated', ''))} |"
            for row in grouped[category]
        )
        sections.append(f"## {category}\n\n| KPI ID | Name | Current | Target | Status | Updated |\n|---|---|---|---|---|---|\n{table_rows}")
    content = f"""# KPI Dashboard

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

{chr(10).join(sections) if sections else "No KPIs found."}

## Boundary

Dashboard is reporting-only. No external metric collection or business action was performed.
"""
    output = kpi_root(config) / "KPI Dashboard.md"
    write_generated_note(output, content, config)
    return output


def kpi_review(config: RaphaelConfig) -> Path:
    ensure_kpi_system(config)
    rows = read_kpis(config)
    stale = []
    no_targets = []
    cutoff = dt.date.today() - dt.timedelta(days=14)
    for row in rows:
        if not row.get("target") or row.get("target") in {"0", "To be defined"}:
            no_targets.append(row)
        try:
            updated = dt.date.fromisoformat(row.get("last_updated", "1900-01-01")[:10])
            if updated < cutoff:
                stale.append(row)
        except ValueError:
            stale.append(row)
    world = world_model_records(config)
    businesses_without_kpis = [item for item in world.get("business", []) if not any(item.get("name", "").lower() in (row.get("related_business", "") + row.get("name", "")).lower() for row in rows)]
    councils = ["Executive Council", "Business Council", "Agency Council", "Commerce Council", "Creator Council", "Engineering Council", "Career Council", "Operations Council"]
    councils_without = [council for council in councils if not any(row.get("owner_council") == council for row in rows)]
    opportunities_without = [row for row in read_opportunities(config) if not any(row.get("title", "").lower() in kpi.get("name", "").lower() for kpi in rows)]
    projects_without = [project for project in list_projects(config) if not any(project.lower() in (row.get("related_project", "") + row.get("name", "")).lower() for row in rows)]
    content = f"""# KPI Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## KPIs Without Targets

{chr(10).join(f"- `{row['id']}` {row['name']}" for row in no_targets[:30]) if no_targets else "- None detected."}

## KPIs Not Updated Recently

{chr(10).join(f"- `{row['id']}` {row['name']} last updated {row.get('last_updated', 'Unknown')}" for row in stale[:30]) if stale else "- None detected."}

## Businesses Without KPIs

{chr(10).join(f"- {item.get('name', '')}" for item in businesses_without_kpis[:30]) if businesses_without_kpis else "- None detected or no businesses recorded."}

## Councils Without KPIs

{chr(10).join(f"- {council}" for council in councils_without) if councils_without else "- None detected."}

## Opportunities Without Measurable Success Criteria

{chr(10).join(f"- `{row.get('id', '')}` {row.get('title', '')}" for row in opportunities_without[:30]) if opportunities_without else "- None detected."}

## Projects Without Portfolio/Completion Metrics

{chr(10).join(f"- {project}" for project in projects_without[:30]) if projects_without else "- None detected."}

## Boundary

Review is advisory only. No external metric collection or business execution occurred.
"""
    output = kpi_root(config) / "KPI Review.md"
    write_generated_note(output, content, config)
    return output


