def portfolio_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "00_Raphael" / "Business Portfolio", config)


def ensure_portfolio_system(config: RaphaelConfig) -> None:
    if not config.business_portfolio_enabled:
        raise RuntimeError("Business Portfolio Manager is disabled in config/settings.json.")
    root = portfolio_root(config)
    root.mkdir(parents=True, exist_ok=True)
    for filename, content in PORTFOLIO_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)


def portfolio_line_for_name(name: str) -> dict[str, object]:
    wanted = normalize_finance_business(name).lower()
    aliases = {"career portfolio": "career/portfolio", "software": "software products", "raphael": "raphael os"}
    wanted = aliases.get(wanted, wanted)
    for line in PORTFOLIO_BUSINESS_LINES:
        if str(line["name"]).lower() == wanted:
            return line
    raise ValueError(f"Unknown portfolio business line: {name}")


def portfolio_recommendation_id(business: str) -> str:
    cleaned = re.sub(r"[^A-Z0-9]+", "-", business.upper()).strip("-")
    return f"PORTREC-{cleaned}"


def portfolio_contains(row: dict[str, str], keywords: list[str]) -> bool:
    blob = " ".join(str(value) for value in row.values()).lower()
    return any(keyword.lower() in blob for keyword in keywords)


def portfolio_score(base: int, bonus: int = 0) -> int:
    return max(1, min(10, base + bonus))


def portfolio_context(config: RaphaelConfig) -> list[dict[str, object]]:
    ensure_portfolio_system(config)
    finance = finance_totals(config)
    financials: dict[str, dict[str, float]] = finance["by_business"]  # type: ignore[assignment]
    kpis = read_kpis(config)
    opportunities = read_opportunities(config)
    initiatives = read_initiatives(config)
    blueprints = read_blueprints(config)
    tasks = all_agent_tasks(config)
    goals = parse_goals(config)
    projects = list_projects(config)
    risks_text = read_text_if_exists(config.vault / "01_Memory" / "Risk Register.md", config, 60000)
    world = world_model_records(config)
    rows: list[dict[str, object]] = []
    for line in PORTFOLIO_BUSINESS_LINES:
        name = str(line["name"])
        council = str(line["council"])
        keywords = list(line["keywords"])  # type: ignore[arg-type]
        values = financials.get(name, {"revenue": 0.0, "expense": 0.0, "budget": 0.0})
        revenue = values["revenue"]
        expenses = values["expense"]
        profit = revenue - expenses
        line_kpis = [row for row in kpis if portfolio_contains(row, keywords + [name, council])]
        line_opps = [row for row in opportunities if portfolio_contains(row, keywords + [name, council])]
        line_inits = [row for row in initiatives if portfolio_contains(row, keywords + [name, council])]
        line_blueprints = [row for row in blueprints if portfolio_contains(row, keywords + [name, council])]
        line_tasks = [row for row in tasks if portfolio_contains(row, keywords + [name, council])]
        line_goals = [row for row in goals if portfolio_contains(row, keywords + [name])]
        line_projects = [project for project in projects if any(keyword in project.lower() for keyword in keywords)]
        products = [item for item in world.get("product", []) if portfolio_contains(item, keywords + [name])]
        offers = [item for item in world.get("business", []) + world.get("business_idea", []) if portfolio_contains(item, keywords + [name])]
        risk_count = sum(1 for keyword in keywords if keyword in risks_text.lower())
        bonus = min(2, len(line_opps) // 2 + len(line_inits) // 3)
        current_revenue = portfolio_score(1 + int(min(9, revenue / 100)))
        profitability = 8 if profit > 0 else 5 if profit == 0 and revenue > 0 else 3 if expenses > 0 else 4
        revenue_potential_base = {"Agency": 8, "Commerce": 7, "Creator": 7, "Software Products": 9, "Career/Portfolio": 5, "Raphael OS": 6}[name]
        speed_base = {"Agency": 8, "Commerce": 6, "Creator": 5, "Software Products": 4, "Career/Portfolio": 4, "Raphael OS": 3}[name]
        startup_cost_base = {"Agency": 9, "Commerce": 6, "Creator": 8, "Software Products": 7, "Career/Portfolio": 9, "Raphael OS": 8}[name]
        skill_base = {"Agency": 8, "Commerce": 6, "Creator": 7, "Software Products": 9, "Career/Portfolio": 8, "Raphael OS": 9}[name]
        portfolio_base = {"Agency": 7, "Commerce": 5, "Creator": 6, "Software Products": 10, "Career/Portfolio": 10, "Raphael OS": 9}[name]
        automation_base = {"Agency": 8, "Commerce": 8, "Creator": 7, "Software Products": 9, "Career/Portfolio": 6, "Raphael OS": 10}[name]
        strategic_base = {"Agency": 8, "Commerce": 7, "Creator": 7, "Software Products": 9, "Career/Portfolio": 8, "Raphael OS": 10}[name]
        risk_score = portfolio_score(8 - risk_count - (1 if expenses > revenue and expenses > 0 else 0))
        resource_score = portfolio_score({"Agency": 6, "Commerce": 7, "Creator": 6, "Software Products": 4, "Career/Portfolio": 7, "Raphael OS": 5}[name] + (1 if line_tasks else 0))
        momentum = portfolio_score(3 + min(4, len(line_tasks)) + min(2, len(line_opps)) + (1 if revenue > 0 else 0))
        scores = {
            "Revenue Potential": portfolio_score(revenue_potential_base, bonus),
            "Current Revenue": current_revenue,
            "Profitability": profitability,
            "Speed To Cash": speed_base,
            "Startup Cost": startup_cost_base,
            "Skill Fit": skill_base,
            "Portfolio Value": portfolio_base,
            "Automation Potential": automation_base,
            "Strategic Value": strategic_base,
            "Risk": risk_score,
            "Resource Demand": resource_score,
            "Momentum": momentum,
        }
        weights = {
            "Revenue Potential": 1.4,
            "Current Revenue": 1.3,
            "Profitability": 1.4,
            "Speed To Cash": 1.2,
            "Startup Cost": 1.0,
            "Skill Fit": 1.2,
            "Portfolio Value": 1.1,
            "Automation Potential": 1.1,
            "Strategic Value": 1.5,
            "Risk": 1.0,
            "Resource Demand": 1.0,
            "Momentum": 1.2,
        }
        weighted = sum(scores[key] * weights[key] for key in scores)
        max_weighted = sum(10 * weight for weight in weights.values())
        focus = round((weighted / max_weighted) * 100)
        if revenue > 0 and profit > 0:
            status = "Active / Earning"
        elif line_opps or line_inits or line_blueprints:
            status = "Developing"
        elif line_tasks:
            status = "Planned"
        else:
            status = "Unvalidated"
        rows.append({
            "Recommendation ID": portfolio_recommendation_id(name),
            "Business Name": name,
            "Business Type": line["type"],
            "Status": status,
            "Owner Council": council,
            "Related Products/Offers": ", ".join((item.get("name") or item.get("title") or item.get("id", "")) for item in (products + offers + line_blueprints)[:8]) or "None recorded",
            "Related Projects": ", ".join(line_projects[:8]) or "None linked",
            "Related KPIs": ", ".join(row.get("id", "") for row in line_kpis[:8]) or "None linked",
            "Revenue": revenue,
            "Expenses": expenses,
            "Profit": profit,
            "Active Opportunities": line_opps,
            "Active Initiatives": line_inits,
            "Active Tasks": line_tasks,
            "Risks": risk_count,
            "Resource Allocation": f"{len(line_tasks)} active tasks; {len(line_goals)} related goals.",
            "Scores": scores,
            "Current Focus Score": focus,
            "Recommended Action": portfolio_recommended_action(name, status, revenue, profit, len(line_opps), len(line_inits), len(line_tasks)),
        })
    return sorted(rows, key=lambda row: int(row["Current Focus Score"]), reverse=True)


def portfolio_recommended_action(name: str, status: str, revenue: float, profit: float, opps: int, inits: int, tasks: int) -> str:
    if revenue > 0 and profit > 0:
        return f"Protect and systematize {name}; document repeatable process and KPI targets."
    if name == "Agency":
        return "Prioritize a low-cost service offer, client profile, proposal plan, and delivery checklist."
    if name == "Commerce":
        return "Pick one product idea, create listing/store plan, and validate demand before spending."
    if name == "Creator":
        return "Choose one content pillar and connect it to an offer, ebook, or lead magnet plan."
    if name == "Software Products":
        return "Select one portfolio-ready product and close README, setup, tests, screenshots, and case study gaps."
    if name == "Career/Portfolio":
        return "Convert strongest projects into resume bullets, interview talking points, and a portfolio narrative."
    if name == "Raphael OS":
        return "Use Raphael OS to support higher-value business lines while preserving safety and documentation."
    if opps or inits or tasks or status != "Unvalidated":
        return f"Review {name} opportunities and decide whether to delegate planning."
    return f"Research whether {name} deserves active focus."


def portfolio_scorecard(config: RaphaelConfig) -> Path:
    rows = portfolio_context(config)
    table_rows = []
    for row in rows:
        scores: dict[str, int] = row["Scores"]  # type: ignore[assignment]
        table_rows.append(
            f"| {row['Recommendation ID']} | {markdown_table_escape(str(row['Business Name']))} | {markdown_table_escape(str(row['Owner Council']))} | {row['Current Focus Score']} | {money(float(row['Revenue']), config)} | {money(float(row['Expenses']), config)} | {money(float(row['Profit']), config)} | {scores['Revenue Potential']} | {scores['Speed To Cash']} | {scores['Strategic Value']} | {scores['Momentum']} | {markdown_table_escape(str(row['Recommended Action']))} |"
        )
    content = f"""# Portfolio Scorecard

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

| Recommendation ID | Business | Owner Council | Focus Score | Revenue | Expenses | Profit | Revenue Potential | Speed To Cash | Strategic Value | Momentum | Recommended Action |
|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---|
{chr(10).join(table_rows)}

## Scoring Criteria

- Revenue potential
- Current revenue
- Profitability
- Speed to cash
- Startup cost
- Skill fit
- Portfolio value
- Automation potential
- Strategic value
- Risk
- Resource demand
- Momentum

## Boundary

Scorecard is advisory only. No business action, spending, outreach, publishing, uploads, external APIs, or platform access occurred.
"""
    output = portfolio_root(config) / "Portfolio Scorecard.md"
    write_generated_note(output, content, config)
    return output


