def portfolio_compare(config: RaphaelConfig, business_a: str, business_b: str) -> str:
    rows = {str(row["Business Name"]).lower(): row for row in portfolio_context(config)}
    a = rows.get(str(portfolio_line_for_name(business_a)["name"]).lower())
    b = rows.get(str(portfolio_line_for_name(business_b)["name"]).lower())
    if not a or not b:
        raise ValueError("Could not compare those business lines.")
    winner = a if int(a["Current Focus Score"]) >= int(b["Current Focus Score"]) else b
    return f"""# Portfolio Compare - {a['Business Name']} vs {b['Business Name']}

| Business | Focus Score | Revenue | Expenses | Profit | Recommended Action |
|---|---:|---:|---:|---:|---|
| {a['Business Name']} | {a['Current Focus Score']} | {money(float(a['Revenue']), config)} | {money(float(a['Expenses']), config)} | {money(float(a['Profit']), config)} | {markdown_table_escape(str(a['Recommended Action']))} |
| {b['Business Name']} | {b['Current Focus Score']} | {money(float(b['Revenue']), config)} | {money(float(b['Expenses']), config)} | {money(float(b['Profit']), config)} | {markdown_table_escape(str(b['Recommended Action']))} |

## Recommendation

Focus on **{winner['Business Name']}** first based on the current portfolio score. This is advisory only.
"""


