def portfolio_delegate(config: RaphaelConfig, recommendation_id: str, council_name: str) -> tuple[Path, Path]:
    rows = portfolio_context(config)
    wanted = recommendation_id.strip().upper()
    for row in rows:
        if str(row["Recommendation ID"]).upper() == wanted:
            task = f"Business Portfolio recommendation for {row['Business Name']}: {row['Recommended Action']}. Planning only; no spending, outreach, publishing, uploads, platform access, or external APIs."
            council_path, agent_path = delegate_task(config, task, council_name)
            decisions = portfolio_root(config) / "Portfolio Decisions.md"
            append_unique_line(decisions, f"- {dt.datetime.now().isoformat(timespec='seconds')}: Delegated `{wanted}` to {normalize_council_name(council_name)} for planning only.", config)
            return council_path, agent_path
    raise FileNotFoundError(f"Portfolio recommendation not found: {recommendation_id}")


def load_command_bus_module():
    path = Path("C:/RaphaelOS/command_bus.py")
    spec = importlib.util.spec_from_file_location("raphael_command_bus_cli", path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Unable to load Command Bus from {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def command_bus_status_text() -> str:
    return load_command_bus_module().command_bus_status()


def command_bus_test_text(input_text: str) -> str:
    module = load_command_bus_module()
    bus = module.RaphaelCommandBus()
    return json.dumps(bus.route(input_text, "cli", {}), indent=2)


def command_bus_review_note() -> Path:
    return load_command_bus_module().command_bus_review()


def command_bus_list_text() -> str:
    module = load_command_bus_module()
    bus = module.RaphaelCommandBus()
    return json.dumps(bus.list_commands(), indent=2)


def command_bus_help_text(command_type: str | None) -> str:
    module = load_command_bus_module()
    bus = module.RaphaelCommandBus()
    return json.dumps(bus.command_help(command_type), indent=2)


NOTIFICATION_TYPES = {
    "KPI Alert", "Initiative Alert", "Opportunity Alert", "Risk Alert", "Task Alert",
    "Execution Alert", "Builder Alert", "Financial Alert", "Portfolio Alert",
    "Council Alert", "System Alert", "Search/Vision Alert", "Self-Improvement Alert",
}

NOTIFICATION_SEVERITIES = {"Critical", "High", "Medium", "Low", "Info"}
NOTIFICATION_STATUSES = {"New", "Read", "Dismissed", "Escalated"}

NOTIFICATION_FILES = {
    "Notification Center Overview.md": """# Notification Center Overview

Raphael's Notification Center surfaces important alerts, reminders, risks, opportunities, KPI issues, initiatives, blocked tasks, pending approvals, execution results, build results, and system warnings in one place.

## Boundary

Notifications are advisory only. Raphael does not execute actions automatically.
""",
    "Notification Inbox.md": "# Notification Inbox\n\n",
    "Notification Rules.md": """# Notification Rules

Raphael detects notifications from generated vault/runtime systems.

## Detection Sources

- KPI Review and KPI Registry
- Executive Initiatives
- Opportunity Review and Opportunity Inbox
- Risk Register
- Task Review and agent task files
- Controlled Execution Log and requests
- Builder Requests
- Financial Review
- Business Portfolio Brief
- Council Reviews
- Search Requests
- Vision Requests
- Self-Improvement Reviews
- System Health notes

## Boundary

Detection creates notification records only. No execution happens automatically.
""",
    "Notification Review.md": "# Notification Review\n\nNo notification review generated yet.\n",
    "Notification Brief.md": "# Notification Brief\n\nNo notification brief generated yet.\n",
    "Notification History.md": "# Notification History\n\n",
}


def notification_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "00_Raphael" / "Notifications", config)


def ensure_notification_system(config: RaphaelConfig) -> None:
    if not config.notification_center_enabled:
        raise RuntimeError("Notification Center is disabled in config/settings.json.")
    root = notification_root(config)
    root.mkdir(parents=True, exist_ok=True)
    for filename, content in NOTIFICATION_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)


def make_notification_id(title: str, source: str) -> str:
    digest = hashlib.sha1(f"{title}|{source}|{today()}".encode("utf-8")).hexdigest()[:8].upper()
    return f"NOTIF-{today().replace('-', '')}-{digest}"


def notification_block(row: dict[str, str]) -> str:
    fields = [
        "Notification ID", "Title", "Type", "Severity", "Description", "Source System",
        "Related Project", "Related Business", "Related Council", "Related Employee",
        "Related KPI", "Related Initiative", "Recommended Action", "Status",
        "Created Date", "Last Updated",
    ]
    lines = [f"## {row['Notification ID']} {row['Title']}"]
    for field in fields:
        lines.append(f"\n### {field}\n\n{row.get(field, '')}")
    return "\n".join(lines).strip() + "\n"


def read_notifications(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_notification_system(config)
    text = read_text_if_exists(notification_root(config) / "Notification Inbox.md", config)
    rows: list[dict[str, str]] = []
    pattern = r"^## (NOTIF-\d{8}-[A-F0-9]+)\s+(.+?)(?=^## NOTIF-\d{8}-[A-F0-9]+|\Z)"
    fields = [
        "Notification ID", "Title", "Type", "Severity", "Description", "Source System",
        "Related Project", "Related Business", "Related Council", "Related Employee",
        "Related KPI", "Related Initiative", "Recommended Action", "Status",
        "Created Date", "Last Updated",
    ]
    for match in re.finditer(pattern, text, flags=re.M | re.S):
        body = match.group(2)
        row = {"Notification ID": match.group(1)}
        for field in fields:
            row[field] = subsection_value(body, field)
        if not row.get("Title"):
            row["Title"] = match.group(2).splitlines()[0].strip() or match.group(1)
        rows.append(row)
    return rows


def write_notifications(config: RaphaelConfig, rows: list[dict[str, str]]) -> None:
    ensure_notification_system(config)
    content = "# Notification Inbox\n\n" + "\n".join(notification_block(row) for row in rows) + "\n"
    write_generated_note(notification_root(config) / "Notification Inbox.md", content, config)


def notification_add_candidate(config: RaphaelConfig, rows: list[dict[str, str]], *, title: str, ntype: str, severity: str, description: str, source: str, recommended_action: str, project: str = "Unassigned", business: str = "Unassigned", council: str = "Unassigned", employee: str = "Unassigned", kpi: str = "Unassigned", initiative: str = "Unassigned") -> bool:
    clean_type = ntype if ntype in NOTIFICATION_TYPES else "System Alert"
    clean_severity = severity if severity in NOTIFICATION_SEVERITIES else "Info"
    for row in rows:
        if row.get("Title", "").lower() == title.lower() and row.get("Source System", "").lower() == source.lower() and row.get("Status") not in {"Dismissed"}:
            return False
    now = dt.datetime.now().isoformat(timespec="seconds")
    rows.append({
        "Notification ID": make_notification_id(title, source),
        "Title": title,
        "Type": clean_type,
        "Severity": clean_severity,
        "Description": description,
        "Source System": source,
        "Related Project": project,
        "Related Business": business,
        "Related Council": council,
        "Related Employee": employee,
        "Related KPI": kpi,
        "Related Initiative": initiative,
        "Recommended Action": recommended_action,
        "Status": "New",
        "Created Date": now,
        "Last Updated": now,
    })
    return True


def notification_pending_searches(config: RaphaelConfig) -> list[dict[str, str]]:
    rows = []
    folder = search_requests_dir(config)
    for path in sorted(folder.glob("*.md")):
        text = read_text_if_exists(path, config)
        status = section_value(text, "Status") or "Pending"
        if status.lower() == "pending":
            rows.append({"id": section_value(text, "Search Request ID") or path.stem, "question": section_value(text, "Question") or path.stem})
    return rows


def notification_pending_vision(config: RaphaelConfig) -> list[dict[str, str]]:
    rows = []
    folder = vision_requests_dir(config)
    for path in sorted(folder.glob("*.md")):
        text = read_text_if_exists(path, config)
        status = section_value(text, "Status") or "Pending"
        if status.lower() == "pending":
            rows.append({"id": section_value(text, "Vision Request ID") or path.stem, "file": section_value(text, "File Path") or section_value(text, "File name") or path.stem})
    return rows


def notification_detect(config: RaphaelConfig) -> Path:
    ensure_notification_system(config)
    if not config.notification_auto_detect_enabled:
        raise RuntimeError("Notification auto detection is disabled in config/settings.json.")
    rows = read_notifications(config)
    created = 0

    for kpi in read_kpis(config):
        status = kpi.get("status", "Unknown")
        if status in {"Behind", "At Risk"}:
            created += notification_add_candidate(
                config, rows,
                title=f"KPI {kpi.get('name', kpi.get('id', 'Unknown'))} is {status}",
                ntype="KPI Alert",
                severity="High" if status == "Behind" else "Medium",
                description=f"KPI `{kpi.get('id', '')}` is marked {status}. Current: {kpi.get('current_value', '')}. Target: {kpi.get('target', '')}.",
                source="KPI System",
                recommended_action="Review KPI target, update value if stale, or create a task to recover performance.",
                council=kpi.get("owner_council", "Unassigned"),
                kpi=kpi.get("id", "Unassigned"),
            )
        try:
            updated = dt.date.fromisoformat(kpi.get("last_updated", "1900-01-01")[:10])
            if updated < dt.date.today() - dt.timedelta(days=14):
                created += notification_add_candidate(
                    config, rows,
                    title=f"KPI {kpi.get('name', kpi.get('id', 'Unknown'))} has stale data",
                    ntype="KPI Alert",
                    severity="Medium",
                    description=f"KPI `{kpi.get('id', '')}` was last updated {kpi.get('last_updated', 'Unknown')}.",
                    source="KPI System",
                    recommended_action="Update the KPI manually or decide whether the KPI should be retired.",
                    council=kpi.get("owner_council", "Unassigned"),
                    kpi=kpi.get("id", "Unassigned"),
                )
        except ValueError:
            pass

    for initiative in read_initiatives(config):
        if initiative.get("Priority") in {"Critical", "High"} and initiative.get("Status") not in {"Delegated", "Completed", "Rejected"}:
            created += notification_add_candidate(
                config, rows,
                title=f"{initiative.get('Priority')} initiative: {initiative.get('Title')}",
                ntype="Initiative Alert",
                severity="Critical" if initiative.get("Priority") == "Critical" else "High",
                description=initiative.get("Description", "High-priority initiative needs review."),
                source="Executive Initiative Engine",
                recommended_action=initiative.get("Recommended Action", "Review and decide whether to delegate."),
                council=initiative.get("Suggested Council", "Unassigned"),
                initiative=initiative.get("Initiative ID", "Unassigned"),
            )

    for opp in read_opportunities(config):
        try:
            score = int(re.sub(r"[^0-9]", "", opp.get("score", "0")) or "0")
        except ValueError:
            score = 0
        if score >= int(config.opportunity_score_threshold) and opp.get("status") not in {"Delegated", "Completed", "Rejected"}:
            created += notification_add_candidate(
                config, rows,
                title=f"High-scoring opportunity: {opp.get('title')}",
                ntype="Opportunity Alert",
                severity="High",
                description=opp.get("description", "High-scoring opportunity detected."),
                source="Opportunity Engine",
                recommended_action=opp.get("next", "Review and decide whether to delegate or blueprint."),
                council=opp.get("council", "Unassigned"),
            )

    for task in all_agent_tasks(config):
        if task.get("status") in {"Blocked", "Waiting on Aaron"}:
            created += notification_add_candidate(
                config, rows,
                title=f"{task.get('status')} task: {task.get('id')}",
                ntype="Task Alert",
                severity="High" if task.get("status") == "Blocked" else "Medium",
                description=task.get("task", "Task needs attention."),
                source="Task System",
                recommended_action="Review blocker, decide next action, or update task status.",
                project=task.get("project", "Unassigned"),
                employee=task.get("agent", "Unassigned"),
            )

    for request in read_execution_requests(config):
        if request.get("Status") == "Pending":
            created += notification_add_candidate(config, rows, title=f"Pending execution request: {request.get('Execution Request ID')}", ntype="Execution Alert", severity="Medium", description=request.get("Action Description", "Execution request pending."), source="Controlled Execution", recommended_action="Dry-run, approve, reject, or leave pending.")
        if request.get("Status") in {"Blocked", "Rejected"}:
            created += notification_add_candidate(config, rows, title=f"Execution {request.get('Status')}: {request.get('Execution Request ID')}", ntype="Execution Alert", severity="High", description=request.get("Safety Notes", "Execution request was blocked or rejected."), source="Controlled Execution", recommended_action="Review safety notes and decide whether a safer request is needed.")

    for build in read_build_requests(config):
        if build.get("status") in {"Requested", "Planned", "Pending", "Generated"}:
            created += notification_add_candidate(config, rows, title=f"Builder request needs review: {build.get('id')}", ntype="Builder Alert", severity="Medium", description=build.get("description", "Builder request needs review."), source="Builder Mode", recommended_action="Run build-status/build-review and approve or park the request.")

    financial_review = read_text_if_exists(finance_root(config) / "Financial Review.md", config, 8000)
    if "Businesses With Expenses But No Revenue" in financial_review and "- None detected." not in section_value(financial_review, "Businesses With Expenses But No Revenue"):
        created += notification_add_candidate(config, rows, title="Financial review found expenses without revenue", ntype="Financial Alert", severity="Medium", description="At least one business has expenses but no recorded revenue.", source="Financial Intelligence", recommended_action="Review finance summary and decide whether to pause spending or add revenue/KPI records.")

    portfolio_brief_text = read_text_if_exists(portfolio_root(config) / "Portfolio Brief.md", config, 8000)
    if "Top Business" in portfolio_brief_text:
        top = section_value(portfolio_brief_text, "Top Business").splitlines()[0].strip("- ").strip()
        if top:
            created += notification_add_candidate(config, rows, title="Portfolio focus recommendation available", ntype="Portfolio Alert", severity="Info", description=top, source="Business Portfolio", recommended_action="Review the portfolio brief and decide this week's primary business focus.")

    for search in notification_pending_searches(config):
        created += notification_add_candidate(config, rows, title=f"Pending search request: {search['id']}", ntype="Search/Vision Alert", severity="Low", description=search["question"], source="Search Requests", recommended_action="Review search request and provide results or approve future search tooling.")
    for vision in notification_pending_vision(config):
        created += notification_add_candidate(config, rows, title=f"Pending vision request: {vision['id']}", ntype="Search/Vision Alert", severity="Low", description=vision["file"], source="Vision Requests", recommended_action="Analyze request manually or run approved local vision analysis.")

    self_review_dir = config.vault / "00_Raphael" / "Self Improvement" / "System Reviews"
    if self_review_dir.exists() and any(self_review_dir.glob("*.md")):
        created += notification_add_candidate(config, rows, title="Self-improvement review available", ntype="Self-Improvement Alert", severity="Info", description="A self-review exists with potential system improvements.", source="Self-Improvement", recommended_action="Review improvement recommendations and decide what Codex should implement.")

    severity_order = {"Critical": 0, "High": 1, "Medium": 2, "Low": 3, "Info": 4}
    rows = sorted(rows, key=lambda row: (row.get("Status") != "New", severity_order.get(row.get("Severity", "Info"), 4), row.get("Created Date", "")))
    active = [row for row in rows if row.get("Status") in {"New", "Read", "Escalated"}]
    if len(active) > config.notification_max_active:
        keep_ids = {row["Notification ID"] for row in active[: config.notification_max_active]}
        for row in rows:
            if row.get("Status") in {"New", "Read"} and row["Notification ID"] not in keep_ids:
                row["Status"] = "Dismissed"
                row["Last Updated"] = dt.datetime.now().isoformat(timespec="seconds")
    write_notifications(config, rows)
    append_unique_line(notification_root(config) / "Notification History.md", f"- {dt.datetime.now().isoformat(timespec='seconds')}: notification-detect created {created} new notification(s).", config)
    return notification_root(config) / "Notification Inbox.md"


def find_notification(config: RaphaelConfig, notification_id: str) -> tuple[list[dict[str, str]], dict[str, str]]:
    rows = read_notifications(config)
    wanted = notification_id.strip().upper()
    for row in rows:
        if row.get("Notification ID", "").upper() == wanted:
            return rows, row
    raise FileNotFoundError(f"Notification ID not found: {notification_id}")


def notification_status_text(config: RaphaelConfig) -> str:
    ensure_notification_system(config)
    rows = read_notifications(config)
    new_high = [row for row in rows if row.get("Status") == "New" and row.get("Severity") in {"Critical", "High"}]
    return f"""# Notification Center Status

- Enabled: {config.notification_center_enabled}
- Auto detect enabled: {config.notification_auto_detect_enabled}
- Delegation requires confirmation: {config.notification_requires_confirmation_for_delegation}
- Max active notifications: {config.notification_max_active}
- Total notifications: {len(rows)}
- New Critical/High notifications: {len(new_high)}
- Folder: `{notification_root(config)}`

## Boundary

Notifications are advisory only. Raphael does not execute actions automatically.
"""


def notification_list_text(config: RaphaelConfig) -> str:
    rows = read_notifications(config)
    visible = [row for row in rows if row.get("Status") != "Dismissed"]
    lines = ["# Notifications", "", "| ID | Severity | Type | Status | Title |", "|---|---|---|---|---|"]
    for row in visible:
        lines.append(f"| {row['Notification ID']} | {row.get('Severity', '')} | {row.get('Type', '')} | {row.get('Status', '')} | {markdown_table_escape(row.get('Title', ''))} |")
    return "\n".join(lines)


def notification_read(config: RaphaelConfig, notification_id: str) -> str:
    rows, row = find_notification(config, notification_id)
    if row.get("Status") == "New":
        row["Status"] = "Read"
        row["Last Updated"] = dt.datetime.now().isoformat(timespec="seconds")
        write_notifications(config, rows)
    return notification_block(row)


def notification_set_status(config: RaphaelConfig, notification_id: str, status: str) -> Path:
    rows, row = find_notification(config, notification_id)
    if status not in NOTIFICATION_STATUSES:
        raise ValueError(f"Unsupported notification status: {status}")
    row["Status"] = status
    row["Last Updated"] = dt.datetime.now().isoformat(timespec="seconds")
    write_notifications(config, rows)
    append_unique_line(notification_root(config) / "Notification History.md", f"- {dt.datetime.now().isoformat(timespec='seconds')}: `{notification_id}` set to {status}.", config)
    return notification_root(config) / "Notification Inbox.md"


def notification_review(config: RaphaelConfig) -> Path:
    rows = read_notifications(config)
    by_status: dict[str, int] = {}
    by_type: dict[str, int] = {}
    for row in rows:
        by_status[row.get("Status", "Unknown")] = by_status.get(row.get("Status", "Unknown"), 0) + 1
        by_type[row.get("Type", "Unknown")] = by_type.get(row.get("Type", "Unknown"), 0) + 1
    new_high = [row for row in rows if row.get("Status") == "New" and row.get("Severity") in {"Critical", "High"}]
    content = f"""# Notification Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Counts By Status

{chr(10).join(f"- {key}: {value}" for key, value in sorted(by_status.items())) if by_status else "- No notifications."}

## Counts By Type

{chr(10).join(f"- {key}: {value}" for key, value in sorted(by_type.items())) if by_type else "- No notifications."}

## New Critical / High Notifications

{chr(10).join(f"- `{row['Notification ID']}` [{row['Severity']}] {row['Title']}" for row in new_high[:20]) if new_high else "- None."}

## Recommended Maintenance

- Run `notification-detect` during command center reviews.
- Dismiss stale low-value notifications.
- Escalate only items that need a task or council review.

## Boundary

Review is advisory only. No actions were executed.
"""
    output = notification_root(config) / "Notification Review.md"
    write_generated_note(output, content, config)
    return output


def notification_brief(config: RaphaelConfig) -> Path:
    rows = read_notifications(config)
    active = [row for row in rows if row.get("Status") in {"New", "Read"}]
    critical = [row for row in active if row.get("Severity") == "Critical"]
    decisions = [row for row in active if "Aaron" in row.get("Recommended Action", "") or row.get("Type") in {"Initiative Alert", "Portfolio Alert", "Execution Alert"}]
    business = [row for row in active if row.get("Type") in {"Financial Alert", "Portfolio Alert", "Opportunity Alert", "KPI Alert"}]
    system = [row for row in active if row.get("Type") in {"System Alert", "Execution Alert", "Builder Alert", "Self-Improvement Alert"}]
    content = f"""# Notification Brief

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Top Critical Notifications

{chr(10).join(f"- `{row['Notification ID']}` {row['Title']}: {row['Recommended Action']}" for row in critical[:10]) if critical else "- No critical notifications."}

## Items Needing Aaron Decision

{chr(10).join(f"- `{row['Notification ID']}` [{row['Severity']}] {row['Title']}" for row in decisions[:15]) if decisions else "- None detected."}

## Pending Confirmations

{chr(10).join(f"- `{row['Notification ID']}` {row['Title']}" for row in active if 'Pending' in row.get('Title', '') or row.get('Type') == 'Execution Alert') or "- None detected."}

## Business Alerts

{chr(10).join(f"- `{row['Notification ID']}` {row['Title']}" for row in business[:15]) if business else "- None detected."}

## System Alerts

{chr(10).join(f"- `{row['Notification ID']}` {row['Title']}" for row in system[:15]) if system else "- None detected."}

## Recommended Next Actions

- Read critical/high notifications first.
- Dismiss low-value duplicates.
- Escalate only notifications that need a task or council review.
- Do not execute external or destructive actions from notifications.
"""
    output = notification_root(config) / "Notification Brief.md"
    write_generated_note(output, content, config)
    return output


def notification_escalate(config: RaphaelConfig, notification_id: str) -> tuple[Path, Path]:
    rows, row = find_notification(config, notification_id)
    council = row.get("Related Council") if row.get("Related Council") not in {"", "Unassigned"} else "Executive Council"
    task = f"Notification escalation: {row.get('Title')}. Description: {row.get('Description')}. Recommended action: {row.get('Recommended Action')}. Planning only; do not execute actions automatically."
    council_path, agent_path = delegate_task(config, task, council)
    row["Status"] = "Escalated"
    row["Last Updated"] = dt.datetime.now().isoformat(timespec="seconds")
    write_notifications(config, rows)
    append_unique_line(notification_root(config) / "Notification History.md", f"- {dt.datetime.now().isoformat(timespec='seconds')}: `{notification_id}` escalated to {council}.", config)
    return council_path, agent_path


def notification_sector_counts(config: RaphaelConfig) -> dict[str, int]:
    rows = [row for row in read_notifications(config) if row.get("Status") == "New"]
    sectors = {"Apex Citadel": 0, "Quantum Labs": 0, "Engine Room": 0, "Neon Forge": 0, "Ledger Grid": 0}
    for row in rows:
        ntype = row.get("Type", "")
        if ntype in {"Initiative Alert", "Portfolio Alert", "Council Alert"}:
            sectors["Apex Citadel"] += 1
        elif ntype in {"Search/Vision Alert", "System Alert", "Self-Improvement Alert"}:
            sectors["Quantum Labs"] += 1
        elif ntype in {"Task Alert", "Execution Alert", "Builder Alert"}:
            sectors["Engine Room"] += 1
        elif ntype in {"Opportunity Alert", "Portfolio Alert"}:
            sectors["Neon Forge"] += 1
        elif ntype in {"KPI Alert", "Financial Alert"}:
            sectors["Ledger Grid"] += 1
    return sectors


