def executive_brief_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "00_Raphael" / "Executive Briefs", config)


def ensure_executive_brief_system(config: RaphaelConfig) -> None:
    if not config.executive_brief_engine_enabled:
        raise RuntimeError("Executive Brief Engine is disabled in config/settings.json.")
    root = executive_brief_root(config)
    root.mkdir(parents=True, exist_ok=True)
    for filename, content in EXECUTIVE_BRIEF_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)


def brief_history_append(config: RaphaelConfig, label: str, output: Path) -> None:
    append_unique_line(executive_brief_root(config) / "Brief History.md", f"- {dt.datetime.now().isoformat(timespec='seconds')}: {label} generated at `{output.name}`.", config)


def brief_context(config: RaphaelConfig) -> dict[str, object]:
    ensure_executive_brief_system(config)
    notifications = read_notifications(config) if config.executive_brief_include_notifications else []
    tasks = all_agent_tasks(config) if config.executive_brief_include_tasks else []
    initiatives = read_initiatives(config) if config.executive_brief_include_initiatives else []
    opportunities = read_opportunities(config) if config.executive_brief_include_opportunities else []
    kpis = read_kpis(config) if config.executive_brief_include_kpis else []
    finance = finance_totals(config) if config.executive_brief_include_finance else {"totals": {"revenue": 0.0, "expense": 0.0, "budget": 0.0}, "month": {"revenue": 0.0, "expense": 0.0, "budget": 0.0}, "by_business": {}}
    portfolio = portfolio_context(config) if config.executive_brief_include_portfolio else []
    resource = resource_profile(config) if config.executive_brief_include_resource_allocation else {}
    active_notifications = [row for row in notifications if row.get("Status") in {"New", "Read"}]
    critical_high = [
        row for row in active_notifications
        if row.get("Severity") in {"Critical", "High"}
        and not (
            row.get("Source System") == "Executive Brief Engine"
            and row.get("Title", "").startswith("Critical/high alerts included in")
        )
    ]
    blocked_tasks = [task for task in tasks if task.get("status") in {"Blocked", "Waiting on Aaron"}]
    open_tasks = [task for task in tasks if task.get("status") in {"Open", "In Progress"}]
    done_tasks = [task for task in tasks if task.get("status") in {"Done", "Archived"}]
    top_initiatives = sorted(
        [row for row in initiatives if row.get("Status") not in {"Completed", "Rejected"}],
        key=lambda row: int(re.sub(r"[^0-9]", "", row.get("Overall Score", "0")) or "0"),
        reverse=True,
    )
    top_opportunities = sorted(
        [row for row in opportunities if row.get("status") not in {"Completed", "Rejected"}],
        key=lambda row: int(re.sub(r"[^0-9]", "", row.get("score", "0")) or "0"),
        reverse=True,
    )
    kpi_warnings = [row for row in kpis if row.get("status") in {"Behind", "At Risk", "Unknown"}]
    top_portfolio = portfolio[0] if portfolio else {}
    finance_totals_data = finance["totals"]  # type: ignore[index]
    return {
        "mode": current_mode_name(config),
        "notifications": active_notifications,
        "critical_high_notifications": critical_high,
        "tasks": tasks,
        "open_tasks": open_tasks,
        "blocked_tasks": blocked_tasks,
        "done_tasks": done_tasks,
        "initiatives": initiatives,
        "top_initiatives": top_initiatives,
        "opportunities": opportunities,
        "top_opportunities": top_opportunities,
        "kpis": kpis,
        "kpi_warnings": kpi_warnings,
        "finance": finance,
        "portfolio": portfolio,
        "top_portfolio": top_portfolio,
        "resource": resource,
        "financial_note": f"Revenue {money(float(finance_totals_data['revenue']), config)}, expenses {money(float(finance_totals_data['expense']), config)}, net {money(float(finance_totals_data['revenue']) - float(finance_totals_data['expense']), config)}.",
    }


def brief_task_lines(tasks: list[dict[str, str]], limit: int = 3) -> str:
    return chr(10).join(f"- `{task['id']}` [{task.get('priority', 'Normal')}] {task.get('task', '')} ({task.get('agent', '')})" for task in tasks[:limit]) or "- None."


def brief_notification_lines(rows: list[dict[str, str]], limit: int = 5) -> str:
    return chr(10).join(f"- `{row['Notification ID']}` [{row.get('Severity', '')}] {row.get('Title', '')}" for row in rows[:limit]) or "- None."


def brief_initiative_line(rows: list[dict[str, str]]) -> str:
    if not rows:
        return "- None."
    row = rows[0]
    return f"- `{row.get('Initiative ID', '')}` {row.get('Title', '')} ({row.get('Priority', 'Unknown')}, score {row.get('Overall Score', '0')})"


def brief_opportunity_line(rows: list[dict[str, str]]) -> str:
    if not rows:
        return "- None."
    row = rows[0]
    return f"- `{row.get('id', '')}` {row.get('title', '')} (score {row.get('score', '0')})"


def brief_kpi_lines(rows: list[dict[str, str]], limit: int = 5) -> str:
    return chr(10).join(f"- `{row.get('id', '')}` {row.get('name', '')}: {row.get('status', '')} ({row.get('current_value', '')}/{row.get('target', '')})" for row in rows[:limit]) or "- None."


def brief_portfolio_focus(ctx: dict[str, object]) -> str:
    top: dict[str, object] = ctx.get("top_portfolio", {})  # type: ignore[assignment]
    if not top:
        return "- None."
    return f"- {top.get('Business Name')} ({top.get('Current Focus Score')}/100): {top.get('Recommended Action')}"


def maybe_create_brief_notification(config: RaphaelConfig, title: str, brief_path: Path, ctx: dict[str, object]) -> None:
    critical: list[dict[str, str]] = ctx.get("critical_high_notifications", [])  # type: ignore[assignment]
    if not critical:
        return
    rows = read_notifications(config)
    changed = notification_add_candidate(
        config,
        rows,
        title=f"Critical/high alerts included in {title}",
        ntype="System Alert",
        severity="High",
        description=f"{len(critical)} critical/high notification(s) were included in `{brief_path.name}`.",
        source="Executive Brief Engine",
        recommended_action="Read the executive brief and decide which alert needs action first.",
    )
    if changed:
        write_notifications(config, rows)


