ACTIVITY_EVENT_TYPES = {
    "Task Event",
    "Goal Event",
    "KPI Event",
    "Initiative Event",
    "Opportunity Event",
    "Notification Event",
    "Execution Event",
    "Workflow Event",
    "Council Event",
    "Employee Event",
    "Finance Event",
    "Portfolio Event",
    "Builder Event",
    "Search Event",
    "Vision Event",
    "Brief Event",
    "System Event",
}

ACTIVITY_SEVERITIES = {"Critical", "High", "Medium", "Low", "Info"}

ACTIVITY_FILES = {
    "Activity Stream Overview.md": """# Activity Stream Overview

Raphael's Activity Stream is the central passive timeline for important system events across tasks, goals, KPIs, initiatives, notifications, councils, employees, finance, portfolio, execution, builder, search, vision, and executive briefs.

## Boundary

The Activity Stream records and visualizes events only. It does not execute actions automatically.
""",
    "Activity Feed.md": "# Activity Feed\n\nNo activity feed generated yet.\n",
    "Activity Timeline.md": "# Activity Timeline\n\nNo activity timeline generated yet.\n",
    "Activity Review.md": "# Activity Review\n\nNo activity review generated yet.\n",
    "Activity Brief.md": "# Activity Brief\n\nNo activity brief generated yet.\n",
    "Activity Statistics.md": "# Activity Statistics\n\nNo activity statistics generated yet.\n",
    "Activity Sources.md": "# Activity Sources\n\n## Event Records\n\n",
}


def activity_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "00_Raphael" / "Activity Stream", config)


def ensure_activity_stream(config: RaphaelConfig) -> None:
    if not config.activity_stream_enabled:
        raise RuntimeError("Activity Stream is disabled in config/settings.json.")
    root = activity_root(config)
    root.mkdir(parents=True, exist_ok=True)
    for filename, content in ACTIVITY_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)


def activity_id_from(*parts: str) -> str:
    seed = "|".join(parts)
    digest = hashlib.sha1(seed.encode("utf-8", errors="ignore")).hexdigest()[:8].upper()
    return f"EVENT-{today()}-{digest}"


def activity_normalize_event(event: dict[str, str]) -> dict[str, str]:
    normalized = {
        "Event ID": event.get("Event ID", activity_id_from(event.get("Timestamp", ""), event.get("Title", ""))),
        "Timestamp": event.get("Timestamp", dt.datetime.now().isoformat(timespec="seconds")),
        "Event Type": event.get("Event Type", "System Event"),
        "Severity": event.get("Severity", "Info"),
        "Title": event.get("Title", "Untitled event"),
        "Details": event.get("Details", ""),
        "Source System": event.get("Source System", "Raphael OS"),
        "Related Business": event.get("Related Business", "Unassigned"),
        "Related Council": event.get("Related Council", "Unassigned"),
        "Related Employee": event.get("Related Employee", "Unassigned"),
        "Related Project": event.get("Related Project", "Unassigned"),
        "Related KPI": event.get("Related KPI", "Unassigned"),
        "Related Initiative": event.get("Related Initiative", "Unassigned"),
        "Related Notification": event.get("Related Notification", "Unassigned"),
        "Status": event.get("Status", "Recorded"),
    }
    if normalized["Event Type"] not in ACTIVITY_EVENT_TYPES:
        normalized["Event Type"] = "System Event"
    if normalized["Severity"] not in ACTIVITY_SEVERITIES:
        normalized["Severity"] = "Info"
    return normalized


def read_activity_events(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_activity_stream(config)
    text = read_text_if_exists(activity_root(config) / "Activity Sources.md", config)
    events: list[dict[str, str]] = []
    for match in re.finditer(r"^###\s+(EVENT-[^\n]+)\n(.*?)(?=^###\s+EVENT-|\Z)", text, flags=re.M | re.S):
        event_id = match.group(1).strip()
        body = match.group(2)
        event = {"Event ID": event_id}
        for line in body.splitlines():
            if not line.startswith("- ") or ":" not in line:
                continue
            key, value = line[2:].split(":", 1)
            event[key.strip()] = value.strip()
        events.append(activity_normalize_event(event))
    return sorted(events, key=lambda row: row.get("Timestamp", ""), reverse=True)


def write_activity_events(config: RaphaelConfig, events: list[dict[str, str]]) -> None:
    ensure_activity_stream(config)
    deduped: dict[str, dict[str, str]] = {}
    for event in events:
        normalized = activity_normalize_event(event)
        deduped[normalized["Event ID"]] = normalized
    ordered = sorted(deduped.values(), key=lambda row: row.get("Timestamp", ""), reverse=True)
    lines = ["# Activity Sources", "", "## Event Records", ""]
    for event in ordered:
        lines.append(f"### {event['Event ID']}")
        for key in [
            "Timestamp",
            "Event Type",
            "Severity",
            "Title",
            "Details",
            "Source System",
            "Related Business",
            "Related Council",
            "Related Employee",
            "Related Project",
            "Related KPI",
            "Related Initiative",
            "Related Notification",
            "Status",
        ]:
            lines.append(f"- {key}: {event.get(key, '')}")
        lines.append("")
    write_generated_note(activity_root(config) / "Activity Sources.md", "\n".join(lines), config)


def activity_add_event(config: RaphaelConfig, event: dict[str, str]) -> dict[str, str]:
    events = read_activity_events(config)
    normalized = activity_normalize_event(event)
    replaced = False
    for index, existing in enumerate(events):
        if existing.get("Event ID") == normalized["Event ID"]:
            events[index] = normalized
            replaced = True
            break
    if not replaced:
        events.append(normalized)
    write_activity_events(config, events)
    return normalized


def activity_auto_capture(config: RaphaelConfig) -> int:
    if not config.activity_auto_capture:
        return 0
    events = read_activity_events(config)
    existing_ids = {event["Event ID"] for event in events}
    created = 0

    def add(event: dict[str, str]) -> None:
        nonlocal created
        normalized = activity_normalize_event(event)
        if normalized["Event ID"] not in existing_ids:
            events.append(normalized)
            existing_ids.add(normalized["Event ID"])
            created += 1

    if config.activity_include_notifications:
        for row in read_notifications(config):
            add({
                "Event ID": activity_id_from("notification", row.get("Notification ID", "")),
                "Timestamp": row.get("Created Date") or row.get("Last Updated") or dt.datetime.now().isoformat(timespec="seconds"),
                "Event Type": "Notification Event",
                "Severity": row.get("Severity", "Info"),
                "Title": f"Notification {row.get('Status', 'Created')}: {row.get('Title', '')}",
                "Details": row.get("Description", ""),
                "Source System": row.get("Source System", "Notification Center"),
                "Related Business": row.get("Related Business", "Unassigned"),
                "Related Council": row.get("Related Council", "Unassigned"),
                "Related Employee": row.get("Related Employee", "Unassigned"),
                "Related Project": row.get("Related Project", "Unassigned"),
                "Related KPI": row.get("Related KPI", "Unassigned"),
                "Related Initiative": row.get("Related Initiative", "Unassigned"),
                "Related Notification": row.get("Notification ID", "Unassigned"),
                "Status": row.get("Status", "Recorded"),
            })

    for row in read_kpis(config):
        severity = "High" if row.get("status") == "Behind" else "Medium" if row.get("status") == "At Risk" else "Info"
        add({
            "Event ID": activity_id_from("kpi", row.get("id", ""), row.get("last_updated", "")),
            "Timestamp": row.get("last_updated") or dt.datetime.now().isoformat(timespec="seconds"),
            "Event Type": "KPI Event",
            "Severity": severity,
            "Title": f"KPI {row.get('status', 'Updated')}: {row.get('name', '')}",
            "Details": f"Current {row.get('current_value', '')}; target {row.get('target', '')}. {row.get('notes', '')}",
            "Source System": "KPI System",
            "Related Business": row.get("related_business", "Unassigned"),
            "Related Council": row.get("owner_council", "Unassigned"),
            "Related Project": row.get("related_project", "Unassigned"),
            "Related KPI": row.get("id", "Unassigned"),
            "Status": row.get("status", "Recorded"),
        })

    for row in read_initiatives(config):
        add({
            "Event ID": activity_id_from("initiative", row.get("Initiative ID", ""), row.get("Status", "")),
            "Timestamp": row.get("Created Date") or dt.datetime.now().isoformat(timespec="seconds"),
            "Event Type": "Initiative Event",
            "Severity": "High" if row.get("Priority") in {"Critical", "High"} else "Medium",
            "Title": f"Initiative {row.get('Status', 'Detected')}: {row.get('Title', '')}",
            "Details": row.get("Recommended Action", row.get("Description", "")),
            "Source System": "Executive Initiative Engine",
            "Related Business": row.get("Related Business", "Unassigned"),
            "Related Council": row.get("Suggested Council", "Unassigned"),
            "Related Project": row.get("Related Project", "Unassigned"),
            "Related KPI": row.get("Related KPI", "Unassigned"),
            "Related Initiative": row.get("Initiative ID", "Unassigned"),
            "Status": row.get("Status", "Recorded"),
        })

    for row in read_opportunities(config):
        add({
            "Event ID": activity_id_from("opportunity", row.get("id", ""), row.get("status", "")),
            "Timestamp": row.get("created") or dt.datetime.now().isoformat(timespec="seconds"),
            "Event Type": "Opportunity Event",
            "Severity": "High" if int(re.sub(r"[^0-9]", "", row.get("score", "0")) or "0") >= config.opportunity_score_threshold else "Info",
            "Title": f"Opportunity {row.get('status', 'Detected')}: {row.get('title', '')}",
            "Details": row.get("description", ""),
            "Source System": "Opportunity Detection Engine",
            "Related Council": row.get("council", "Unassigned"),
            "Status": row.get("status", "Recorded"),
        })

    if config.activity_include_execution_events:
        for row in read_execution_requests(config):
            add({
                "Event ID": activity_id_from("execution", row.get("Execution Request ID", ""), row.get("Status", "")),
                "Timestamp": row.get("Created Date") or dt.datetime.now().isoformat(timespec="seconds"),
                "Event Type": "Execution Event",
                "Severity": "High" if row.get("Status") in {"Blocked", "Rejected"} else "Medium",
                "Title": f"Execution {row.get('Status', 'Requested')}: {row.get('Action Type', row.get('Execution Request ID', ''))}",
                "Details": row.get("Action Description", ""),
                "Source System": "Controlled Execution",
                "Related Council": row.get("Related Council", "Unassigned"),
                "Related Employee": row.get("Related Employee", "Unassigned"),
                "Related Project": row.get("Related Project", "Unassigned"),
                "Related KPI": row.get("Related KPI", "Unassigned"),
                "Related Initiative": row.get("Related Initiative", "Unassigned"),
                "Status": row.get("Status", "Recorded"),
            })

    for row in read_build_requests(config):
        add({
            "Event ID": activity_id_from("builder", row.get("id", ""), row.get("status", "")),
            "Timestamp": row.get("created", dt.datetime.now().isoformat(timespec="seconds")),
            "Event Type": "Builder Event",
            "Severity": "Medium",
            "Title": f"Builder {row.get('status', 'Request')}: {row.get('id', '')}",
            "Details": row.get("description", ""),
            "Source System": "Builder Mode",
            "Status": row.get("status", "Recorded"),
        })

    for row in read_search_requests(config):
        add({
            "Event ID": activity_id_from("search", row.get("id", ""), row.get("status", "")),
            "Timestamp": row.get("created", dt.datetime.now().isoformat(timespec="seconds")),
            "Event Type": "Search Event",
            "Severity": "Low" if row.get("status") == "Pending" else "Info",
            "Title": f"Search {row.get('status', 'Request')}: {row.get('question', '')}",
            "Details": row.get("reason", ""),
            "Source System": "Search Requests",
            "Status": row.get("status", "Recorded"),
        })

    for row in read_vision_requests(config):
        add({
            "Event ID": activity_id_from("vision", row.get("id", ""), row.get("status", "")),
            "Timestamp": row.get("created", dt.datetime.now().isoformat(timespec="seconds")),
            "Event Type": "Vision Event",
            "Severity": "Low" if row.get("status") == "Pending" else "Info",
            "Title": f"Vision {row.get('status', 'Request')}: {row.get('file', '')}",
            "Details": row.get("question", ""),
            "Source System": "Vision Requests",
            "Status": row.get("status", "Recorded"),
        })

    for row in read_finance_entries(config):
        add({
            "Event ID": activity_id_from("finance", row.get("Entry ID", ""), row.get("Date", "")),
            "Timestamp": row.get("Date") or dt.datetime.now().isoformat(timespec="seconds"),
            "Event Type": "Finance Event",
            "Severity": "Info",
            "Title": f"{row.get('Type', 'Finance')} recorded for {row.get('Business', 'Unknown')}",
            "Details": f"{row.get('Amount', '')}: {row.get('Description', '')}",
            "Source System": "Financial Intelligence",
            "Related Business": row.get("Business", "Unassigned"),
            "Related Project": row.get("Related Project", "Unassigned"),
            "Related KPI": row.get("Related KPI", "Unassigned"),
            "Related Initiative": row.get("Related Initiative", "Unassigned"),
            "Status": "Recorded",
        })

    if config.activity_include_system_events:
        brief_root = executive_brief_root(config)
        if brief_root.exists():
            for path in brief_root.glob("*.md"):
                if path.name in {"Brief History.md", "Brief Preferences.md", "Executive Brief System Overview.md"}:
                    continue
                add({
                    "Event ID": activity_id_from("brief", path.name, str(path.stat().st_mtime)),
                    "Timestamp": dt.datetime.fromtimestamp(path.stat().st_mtime).isoformat(timespec="seconds"),
                    "Event Type": "Brief Event",
                    "Severity": "Info",
                    "Title": f"{path.stem} generated",
                    "Details": f"Generated brief file `{path.name}`.",
                    "Source System": "Executive Brief Engine",
                    "Status": "Recorded",
                })

    if config.activity_include_council_events:
        council_root_path = config.vault / "03_Agents" / "Councils"
        if council_root_path.exists():
            for task_file in council_root_path.glob("*/Council Tasks.md"):
                council = task_file.parent.name
                text = (read_text_if_exists(task_file, config) or "")[:20000]
                for line in text.splitlines():
                    if line.strip().startswith("- "):
                        add({
                            "Event ID": activity_id_from("council-task", council, line.strip()),
                            "Timestamp": dt.datetime.fromtimestamp(task_file.stat().st_mtime).isoformat(timespec="seconds"),
                            "Event Type": "Council Event",
                            "Severity": "Info",
                            "Title": f"{council} task recorded",
                            "Details": line.strip().lstrip("- ").strip(),
                            "Source System": "Council System",
                            "Related Council": council,
                            "Status": "Recorded",
                        })

    if created:
        write_activity_events(config, events)
    return created


def activity_events_current(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_activity_stream(config)
    if config.activity_auto_capture:
        activity_auto_capture(config)
    return read_activity_events(config)


def activity_feed(config: RaphaelConfig) -> Path:
    events = activity_events_current(config)[: config.activity_max_feed_items]
    lines = ["# Activity Feed", "", f"Generated: {dt.datetime.now().isoformat(timespec='seconds')}", ""]
    for event in events:
        timestamp = event.get("Timestamp", "").replace("T", " ")[:16]
        lines.extend([
            f"[{timestamp}]",
            f"{event.get('Event Type', '')}",
            event.get("Title", ""),
            "",
        ])
    output = activity_root(config) / "Activity Feed.md"
    write_generated_note(output, "\n".join(lines), config)
    return output


def activity_group_key(timestamp: str) -> str:
    try:
        event_date = dt.datetime.fromisoformat(timestamp.replace("Z", "")).date()
    except ValueError:
        return "Earlier"
    now_date = dt.datetime.now().date()
    if event_date == now_date:
        return "Today"
    if event_date == now_date - dt.timedelta(days=1):
        return "Yesterday"
    if event_date >= now_date - dt.timedelta(days=7):
        return "This Week"
    return "Earlier"


def activity_timeline(config: RaphaelConfig) -> Path:
    events = activity_events_current(config)
    groups = {"Today": [], "Yesterday": [], "This Week": [], "Earlier": []}
    for event in events:
        groups[activity_group_key(event.get("Timestamp", ""))].append(event)
    lines = ["# Activity Timeline", "", f"Generated: {dt.datetime.now().isoformat(timespec='seconds')}", ""]
    for group, rows in groups.items():
        lines.append(f"## {group}")
        lines.append("")
        if rows:
            lines.extend(f"- `{row['Event ID']}` [{row['Severity']}] {row['Title']} ({row['Source System']})" for row in rows[:100])
        else:
            lines.append("- No events.")
        lines.append("")
    output = activity_root(config) / "Activity Timeline.md"
    write_generated_note(output, "\n".join(lines), config)
    return output


def activity_summary_counts(events: list[dict[str, str]]) -> dict[str, object]:
    now = dt.datetime.now()
    today_date = now.date()
    week_start = today_date - dt.timedelta(days=7)
    month_start = today_date.replace(day=1)
    parsed: list[tuple[dict[str, str], dt.date | None]] = []
    for event in events:
        try:
            parsed.append((event, dt.datetime.fromisoformat(event["Timestamp"].replace("Z", "")).date()))
        except (ValueError, KeyError):
            parsed.append((event, None))
    by_type = Counter(event.get("Event Type", "System Event") for event in events)
    empty_markers = {"", "Unassigned", "Unlinked", "Unknown", "None"}
    by_council = Counter(event.get("Related Council", "") for event in events if event.get("Related Council") not in empty_markers)
    by_employee = Counter(event.get("Related Employee", "") for event in events if event.get("Related Employee") not in empty_markers)
    by_business = Counter(event.get("Related Business", "") for event in events if event.get("Related Business") not in empty_markers)
    return {
        "today": sum(1 for _, date_value in parsed if date_value == today_date),
        "week": sum(1 for _, date_value in parsed if date_value and date_value >= week_start),
        "month": sum(1 for _, date_value in parsed if date_value and date_value >= month_start),
        "by_type": by_type,
        "most_active_council": by_council.most_common(1)[0][0] if by_council else "Unassigned",
        "most_active_employee": by_employee.most_common(1)[0][0] if by_employee else "Unassigned",
        "most_active_business": by_business.most_common(1)[0][0] if by_business else "Unassigned",
        "execution_count": by_type.get("Execution Event", 0),
        "notification_count": by_type.get("Notification Event", 0),
        "initiative_count": by_type.get("Initiative Event", 0),
        "critical_events": sum(1 for event in events if event.get("Severity") == "Critical"),
        "high_events": sum(1 for event in events if event.get("Severity") == "High"),
    }


def activity_stats(config: RaphaelConfig) -> Path:
    events = activity_events_current(config)
    summary = activity_summary_counts(events)
    by_type: Counter = summary["by_type"]  # type: ignore[assignment]
    lines = [
        "# Activity Statistics",
        "",
        f"Generated: {dt.datetime.now().isoformat(timespec='seconds')}",
        "",
        f"- Events Today: {summary['today']}",
        f"- Events This Week: {summary['week']}",
        f"- Events This Month: {summary['month']}",
        "",
        "## Events By Type",
        "",
    ]
    lines.extend(f"- {event_type}: {count}" for event_type, count in by_type.most_common())
    lines.extend([
        "",
        "## Most Active",
        "",
        f"- Most Active Council: {summary['most_active_council']}",
        f"- Most Active Employee: {summary['most_active_employee']}",
        f"- Most Active Business: {summary['most_active_business']}",
        "",
        "## Key Counts",
        "",
        f"- Execution Count: {summary['execution_count']}",
        f"- Notification Count: {summary['notification_count']}",
        f"- Initiative Count: {summary['initiative_count']}",
        f"- Critical Events: {summary['critical_events']}",
        f"- High Events: {summary['high_events']}",
    ])
    output = activity_root(config) / "Activity Statistics.md"
    write_generated_note(output, "\n".join(lines), config)
    return output


def activity_review(config: RaphaelConfig) -> Path:
    events = activity_events_current(config)
    summary = activity_summary_counts(events)
    by_type: Counter = summary["by_type"]  # type: ignore[assignment]
    active_systems = Counter(event.get("Source System", "Raphael OS") for event in events)
    repeated = [item for item, count in Counter(event.get("Title", "") for event in events).most_common(10) if count > 1]
    inactive = sorted(ACTIVITY_EVENT_TYPES - set(by_type.keys()))
    content = f"""# Activity Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Most Active Systems

{chr(10).join(f"- {system}: {count}" for system, count in active_systems.most_common(10)) or "- None."}

## Inactive Systems

{chr(10).join(f"- {event_type}" for event_type in inactive[:12]) or "- None."}

## Repeated Events

{chr(10).join(f"- {title}" for title in repeated) or "- No repeated event titles detected."}

## Potential Noise

- Watch for repeated generated brief events and repeated notification events if they crowd out real operational signal.

## Important Trends

- Events today: {summary['today']}
- Events this week: {summary['week']}
- Most active business: {summary['most_active_business']}
- Most active council: {summary['most_active_council']}

## Unusual Spikes

- Critical events: {summary['critical_events']}
- High events: {summary['high_events']}

## Boundary

Activity Review is observational only. No actions were executed.
"""
    output = activity_root(config) / "Activity Review.md"
    write_generated_note(output, content, config)
    return output


