def activity_log(config: RaphaelConfig, event_type: str, title: str, details: str) -> str:
    event = activity_add_event(config, {
        "Event ID": activity_id_from("manual", dt.datetime.now().isoformat(timespec="seconds"), event_type, title),
        "Timestamp": dt.datetime.now().isoformat(timespec="seconds"),
        "Event Type": event_type if event_type in ACTIVITY_EVENT_TYPES else "System Event",
        "Severity": "Info",
        "Title": title,
        "Details": details,
        "Source System": "Manual Activity Log",
        "Status": "Recorded",
    })
    activity_feed(config)
    return event["Event ID"]


def activity_read(config: RaphaelConfig, event_id: str) -> str:
    event_id = event_id.strip().upper()
    for event in activity_events_current(config):
        if event.get("Event ID", "").upper() == event_id:
            return "\n".join([
                f"# {event['Event ID']}",
                "",
                *[f"- {key}: {event.get(key, '')}" for key in [
                    "Timestamp",
                    "Event Type",
                    "Severity",
                    "Title",
                    "Details",
                    "Source System",
                    "Related Business",
                    "Related Council",
                    "Related Employee",
                    "Related Project",
                    "Related KPI",
                    "Related Initiative",
                    "Related Notification",
                    "Status",
                ]],
            ])
    raise ValueError(f"Activity event not found: {event_id}")


