def initiative_history_text(config: RaphaelConfig) -> str:
    ensure_initiative_system(config)
    return read_text_if_exists(initiative_root(config) / "Initiative History.md", config) or "# Initiative History\n\nNo history recorded."


def initiative_delegate(config: RaphaelConfig, initiative_id: str, council_name: str) -> tuple[Path, Path]:
    ensure_initiative_system(config)
    rows, row = find_initiative(config, initiative_id)
    council = normalize_council_name(council_name)
    task = (
        f"Initiative delegation: {row['Title']}. "
        f"Recommended action: {row['Recommended Action']} "
        f"Evidence: {row['Source Evidence']} "
        "Produce a planning recommendation only. Do not execute business actions."
    )
    council_path, agent_path = delegate_task(config, task, council)
    row["Status"] = "Delegated"
    write_initiatives(config, rows)
    append_unique_line(initiative_root(config) / "Initiative History.md", f"- {today()} `{row['Initiative ID']}` delegated to {council}. Council task: {council_path.name}.", config)
    return council_path, agent_path


EMPLOYEE_FILES = {
    "Digital Employee System Overview.md": """# Digital Employee System Overview

Raphael manages agents as digital employees with roles, departments, managers, KPIs, tasks, performance reviews, workload reviews, and operating expectations.

## Boundary

Digital employees organize and evaluate work only. They do not execute tasks, access platforms, send messages, spend money, modify source projects, approve actions, or run external actions.
""",
    "Employee Registry.md": "# Employee Registry\n\n",
    "Employee Org Chart.md": "# Employee Org Chart\n\nNo org chart generated yet.\n",
    "Employee KPI Map.md": "# Employee KPI Map\n\n| Employee ID | Employee Name | KPI ID | KPI Name | Assigned Date |\n|---|---|---|---|---|\n",
    "Employee Performance Reviews.md": "# Employee Performance Reviews\n\n",
    "Employee Workload Review.md": "# Employee Workload Review\n\nNo workload review generated yet.\n",
    "Employee Brief.md": "# Employee Brief\n\nNo employee brief generated yet.\n",
}


def employee_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "03_Agents" / "Digital Employees", config)


def ensure_employee_system(config: RaphaelConfig) -> None:
    if not config.digital_employee_system_enabled:
        raise RuntimeError("Digital Employee System is disabled in config/settings.json.")
    root = employee_root(config)
    root.mkdir(parents=True, exist_ok=True)
    for filename, content in EMPLOYEE_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)


def make_employee_id(employee_name: str) -> str:
    digest = hashlib.sha1(employee_name.lower().encode("utf-8")).hexdigest()[:8].upper()
    return f"EMP-{digest}"


def employee_role(employee_name: str) -> str:
    cleaned = employee_name.replace(" Agent", "").replace("/", " ").strip()
    if "Developer" in cleaned or "Engineer" in cleaned or "Architect" in cleaned or "Tech Lead" in cleaned:
        return "Technical Specialist"
    if any(term in cleaned for term in ["Manager", "Chief", "Operations", "Scrum"]):
        return "Management / Coordination"
    if any(term in cleaned for term in ["Marketing", "Sales", "Business", "Finance", "Legal", "Proposal", "Account", "Client"]):
        return "Business Operations Specialist"
    if any(term in cleaned for term in ["Career", "Resume", "Portfolio", "Interview", "Job"]):
        return "Career Development Specialist"
    if any(term in cleaned for term in ["Research", "Analyst"]):
        return "Research Specialist"
    if any(term in cleaned for term in ["Content", "Script", "Influencer", "Newsletter", "Ebook", "Audience"]):
        return "Creator Operations Specialist"
    if any(term in cleaned for term in ["Store", "Product", "Listing", "SEO", "Digital", "POD", "Customer"]):
        return "Commerce Operations Specialist"
    return f"{cleaned} Specialist"


def employee_department(employee_name: str) -> str:
    for council, meta in COUNCILS.items():
        if employee_name in meta["members"]:
            return council
    return "Executive Council"


def employee_manager_for_department(department: str) -> str:
    managers = {
        "Executive Council": "Raphael",
        "Product Council": "Product Manager Agent",
        "Engineering Council": "Engineering Manager Agent",
        "Operations Council": "Project Manager Agent",
        "Research Council": "Research Agent",
        "Career Council": "Career Agent",
        "Business Council": "Business Strategy Agent",
        "Commerce Council": "Store Manager Agent",
        "Agency Council": "Delivery Manager Agent",
        "Creator Council": "Content Strategist Agent",
    }
    return managers.get(department, "Raphael")


def all_agent_names_from_vault(config: RaphaelConfig) -> list[str]:
    names = set(AGENTS)
    root = config.vault / "03_Agents"
    if root.exists():
        for folder in root.iterdir():
            if folder.is_dir() and folder.name != "Councils" and folder.name != "Digital Employees":
                names.add(folder.name)
    for meta in COUNCILS.values():
        names.update(meta["members"])
    return sorted(names)


def employee_workload(open_count: int) -> str:
    if open_count == 0:
        return "Low"
    if open_count <= 2:
        return "Normal"
    if open_count <= 5:
        return "High"
    return "Overloaded"


def employee_performance_status(open_count: int, blocked_count: int, assigned_kpis: list[dict[str, str]]) -> str:
    if blocked_count > 0 or open_count > 5:
        return "Needs Attention"
    if assigned_kpis and open_count <= 3:
        return "Strong"
    if open_count > 0:
        return "Stable"
    return "Unknown"


def read_employee_registry(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_employee_system(config)
    text = read_text_if_exists(employee_root(config) / "Employee Registry.md", config)
    rows: list[dict[str, str]] = []
    pattern = r"^## (EMP-[A-F0-9]+)\s+(.+?)(?=^## EMP-[A-F0-9]+|\Z)"
    fields = [
        "Employee ID", "Employee Name", "Agent Folder", "Role", "Department/Council", "Manager",
        "Responsibilities", "Current Tasks", "Assigned KPIs", "Related Business Area", "Related Projects",
        "Workload", "Performance Status", "Last Review Date", "Notes",
    ]
    for match in re.finditer(pattern, text, flags=re.M | re.S):
        body = match.group(2)
        row = {"Employee ID": match.group(1)}
        for field in fields:
            row[field] = subsection_value(body, field)
        if not row.get("Employee Name"):
            row["Employee Name"] = match.group(2).splitlines()[0].strip() or match.group(1)
        rows.append(row)
    return rows


def read_employee_kpi_map(config: RaphaelConfig) -> dict[str, list[str]]:
    ensure_employee_system(config)
    text = read_text_if_exists(employee_root(config) / "Employee KPI Map.md", config)
    mapping: dict[str, list[str]] = {}
    for line in text.splitlines():
        if not line.startswith("| EMP-"):
            continue
        parts = [part.strip() for part in line.strip("|").split("|")]
        if len(parts) >= 3:
            mapping.setdefault(parts[0], []).append(parts[2])
    return mapping


def employee_record_block(row: dict[str, str]) -> str:
    fields = [
        "Employee ID", "Employee Name", "Agent Folder", "Role", "Department/Council", "Manager",
        "Responsibilities", "Current Tasks", "Assigned KPIs", "Related Business Area", "Related Projects",
        "Workload", "Performance Status", "Last Review Date", "Notes",
    ]
    body = [f"## {row['Employee ID']} {row['Employee Name']}"]
    for field in fields:
        body.append(f"\n### {field}\n\n{row.get(field, '')}")
    return "\n".join(body).strip() + "\n"


def write_employee_registry(config: RaphaelConfig, rows: list[dict[str, str]]) -> None:
    content = "# Employee Registry\n\n" + "\n".join(employee_record_block(row) for row in sorted(rows, key=lambda item: item["Employee Name"])) + "\n"
    write_generated_note(employee_root(config) / "Employee Registry.md", content, config)


def employee_registry(config: RaphaelConfig) -> Path:
    ensure_employee_system(config)
    prior = {row["Employee ID"]: row for row in read_employee_registry(config)}
    kpi_map = read_employee_kpi_map(config)
    kpis = {row["id"]: row for row in read_kpis(config)}
    tasks = all_agent_tasks(config)
    rows: list[dict[str, str]] = []
    for name in all_agent_names_from_vault(config):
        emp_id = make_employee_id(name)
        old = prior.get(emp_id, {})
        agent_tasks = [task for task in tasks if task["agent"] == name]
        open_tasks = [task for task in agent_tasks if task["status"] not in {"Done", "Archived"}]
        blocked = [task for task in agent_tasks if task["status"] == "Blocked"]
        department = old.get("Department/Council") or employee_department(name)
        manager = old.get("Manager") or employee_manager_for_department(department)
        assigned_ids = sorted(set(kpi_map.get(emp_id, []) + [kpi["id"] for kpi in kpis.values() if kpi.get("owner_council") == department and name.split()[0].lower() in kpi.get("name", "").lower()]))
        assigned_kpi_text = "\n".join(f"- `{kpi_id}` {kpis.get(kpi_id, {}).get('name', '')}".strip() for kpi_id in assigned_ids) or "- None assigned."
        current_task_text = "\n".join(f"- `{task['id']}` [{task['status']}] {task['task']}" for task in open_tasks[:20]) or "- No open tasks."
        projects = sorted({task["project"] for task in agent_tasks if task.get("project") and task["project"] != "Unassigned"})
        workload = employee_workload(len(open_tasks))
        performance = employee_performance_status(len(open_tasks), len(blocked), [kpis[k] for k in assigned_ids if k in kpis])
        rows.append({
            "Employee ID": emp_id,
            "Employee Name": name,
            "Agent Folder": str(agent_dir(config, name)),
            "Role": old.get("Role") or employee_role(name),
            "Department/Council": department,
            "Manager": manager,
            "Responsibilities": read_text_if_exists(agent_dir(config, name) / "Responsibilities.md", config)[:700].strip() or "Maintain context, produce recommendations, document risks, and escalate decisions.",
            "Current Tasks": current_task_text,
            "Assigned KPIs": assigned_kpi_text,
            "Related Business Area": old.get("Related Business Area") or department.replace(" Council", ""),
            "Related Projects": ", ".join(projects) if projects else "Unassigned",
            "Workload": workload,
            "Performance Status": performance,
            "Last Review Date": old.get("Last Review Date") or "Never",
            "Notes": old.get("Notes") or "Generated from agent folders, tasks, councils, and KPI registry.",
        })
    write_employee_registry(config, rows)
    return employee_root(config) / "Employee Registry.md"


def find_employee(config: RaphaelConfig, employee_name: str) -> tuple[list[dict[str, str]], dict[str, str]]:
    rows = read_employee_registry(config)
    if not rows:
        employee_registry(config)
        rows = read_employee_registry(config)
    target = employee_name.strip().lower()
    for row in rows:
        if row["Employee ID"].lower() == target or row["Employee Name"].lower() == target:
            return rows, row
    normalized = normalize_agent_name(employee_name)
    for row in rows:
        if row["Employee Name"].lower() == normalized.lower():
            return rows, row
    raise FileNotFoundError(f"Employee not found: {employee_name}")


def employee_status_text(config: RaphaelConfig) -> str:
    ensure_employee_system(config)
    rows = read_employee_registry(config)
    return f"""# Digital Employee System Status

- Enabled: {config.digital_employee_system_enabled}
- Reviews enabled: {config.digital_employee_reviews_enabled}
- Reassignment requires confirmation: {config.digital_employee_requires_confirmation_for_reassignment}
- Folder: `{employee_root(config)}`
- Employees tracked: {len(rows)}

## Boundary

Digital employees organize and evaluate work only. No task execution, business execution, platform access, external action, source project edit, spending, upload, email, or publishing occurred.
"""


def employee_org_chart(config: RaphaelConfig) -> Path:
    employee_registry(config)
    rows = read_employee_registry(config)
    by_department: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_department.setdefault(row.get("Department/Council") or "Unassigned", []).append(row)
    sections = []
    for council in sorted(by_department):
        sections.append(f"### {council}\n")
        sections.extend(f"- {row['Employee Name']} -> Manager: {row.get('Manager', 'Raphael')}" for row in sorted(by_department[council], key=lambda item: item["Employee Name"]))
    content = f"""# Employee Org Chart

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

Aaron
↓
Raphael
↓
Executive Council
↓
Councils
↓
Digital Employees

## Departments

{chr(10).join(sections)}

## Boundary

Org chart is informational only. No reassignment or execution occurred.
"""
    output = employee_root(config) / "Employee Org Chart.md"
    write_generated_note(output, content, config)
    return output


def employee_workload_review(config: RaphaelConfig) -> Path:
    employee_registry(config)
    rows = read_employee_registry(config)
    kpi_map = read_employee_kpi_map(config)
    overloaded = [row for row in rows if row.get("Workload") == "Overloaded"]
    no_tasks = [row for row in rows if row.get("Workload") == "Low"]
    tasks_no_kpi = [row for row in rows if row.get("Workload") != "Low" and row["Employee ID"] not in kpi_map]
    kpi_no_task = [row for row in rows if row.get("Workload") == "Low" and row["Employee ID"] in kpi_map]
    council_members = {member for meta in COUNCILS.values() for member in meta["members"]}
    duplicates = sorted({name for name in council_members if sum(1 for meta in COUNCILS.values() if name in meta["members"]) > 1})
    content = f"""# Employee Workload Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Overloaded Employees

{chr(10).join(f"- `{row['Employee ID']}` {row['Employee Name']}" for row in overloaded) if overloaded else "- None detected."}

## Employees With No Tasks

{chr(10).join(f"- `{row['Employee ID']}` {row['Employee Name']} ({row['Department/Council']})" for row in no_tasks[:60]) if no_tasks else "- None detected."}

## Employees With Tasks But No KPI

{chr(10).join(f"- `{row['Employee ID']}` {row['Employee Name']}" for row in tasks_no_kpi[:60]) if tasks_no_kpi else "- None detected."}

## Employees With KPI But No Task

{chr(10).join(f"- `{row['Employee ID']}` {row['Employee Name']}" for row in kpi_no_task[:60]) if kpi_no_task else "- None detected."}

## Duplicate / Overlapping Roles

{chr(10).join(f"- {name}" for name in duplicates) if duplicates else "- None detected."}

## Recommended Management Actions

- Assign KPIs to employees carrying recurring work.
- Create or delegate tasks for employees with KPIs but no active work.
- Review duplicate roles before adding new specialist agents.

## Boundary

Workload review is advisory only. No tasks were executed or reassigned.
"""
    output = employee_root(config) / "Employee Workload Review.md"
    write_generated_note(output, content, config)
    return output


