def employee_review(config: RaphaelConfig, employee_name: str) -> Path:
    if not config.digital_employee_reviews_enabled:
        raise RuntimeError("Digital employee reviews are disabled in config/settings.json.")
    rows, employee = find_employee(config, employee_name)
    tasks = [task for task in all_agent_tasks(config) if task["agent"] == employee["Employee Name"]]
    open_tasks = [task for task in tasks if task["status"] not in {"Done", "Archived"}]
    completed = [task for task in tasks if task["status"] == "Done"]
    blocked = [task for task in tasks if task["status"] == "Blocked"]
    related_inits = [row for row in read_initiatives(config) if employee["Employee Name"] in row.get("Suggested Agents", "") or employee["Department/Council"] == row.get("Suggested Council")]
    review = f"""## {dt.datetime.now().isoformat(timespec='seconds')} - {employee['Employee Name']}

### Employee ID

{employee['Employee ID']}

### Performance Status

{employee['Performance Status']}

### Workload

{employee['Workload']}

### Open Tasks

{chr(10).join(f"- `{task['id']}` [{task['status']}] {task['task']}" for task in open_tasks) if open_tasks else "- None."}

### Completed Tasks

{chr(10).join(f"- `{task['id']}` {task['task']}" for task in completed[:20]) if completed else "- None recorded."}

### Blocked Tasks

{chr(10).join(f"- `{task['id']}` {task['task']}" for task in blocked) if blocked else "- None."}

### Assigned KPIs

{employee['Assigned KPIs']}

### Related Initiatives

{chr(10).join(f"- `{row['Initiative ID']}` {row['Title']}" for row in related_inits[:10]) if related_inits else "- None detected."}

### Review Notes

- Strength: {employee['Role']} is available for structured, approval-based work.
- Concern: {'Blocked tasks need escalation.' if blocked else 'No blocking issue detected from task files.'}
- Next management action: assign one measurable KPI or task outcome if missing.
"""
    path = employee_root(config) / "Employee Performance Reviews.md"
    append_unique_section(path, f"{today()} - {employee['Employee ID']}", review, config)
    employee["Last Review Date"] = today()
    write_employee_registry(config, rows)
    return path


def employee_task_brief(config: RaphaelConfig, employee_name: str) -> Path:
    _rows, employee = find_employee(config, employee_name)
    tasks = [task for task in all_agent_tasks(config) if task["agent"] == employee["Employee Name"]]
    status_rank = {"Blocked": 0, "Waiting on Aaron": 1, "In Progress": 2, "Open": 3, "Done": 4, "Archived": 5}
    ordered = sorted(tasks, key=lambda item: (status_rank.get(item["status"], 9), item["priority"], item["id"]))
    content = f"""# Employee Task Brief - {employee['Employee Name']}

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Current Assigned Tasks

{chr(10).join(f"- `{task['id']}` [{task['status']}/{task['priority']}] {task['task']}" for task in ordered if task['status'] not in {'Done', 'Archived'}) if ordered else "- No tasks assigned."}

## Blocked Tasks

{chr(10).join(f"- `{task['id']}` {task['task']}" for task in ordered if task['status'] == 'Blocked') or "- None."}

## Waiting On Aaron

{chr(10).join(f"- `{task['id']}` {task['task']}" for task in ordered if task['status'] == 'Waiting on Aaron') or "- None."}

## Recommended Task Order

{chr(10).join(f"{index}. `{task['id']}` {task['task']}" for index, task in enumerate([task for task in ordered if task['status'] not in {'Done', 'Archived'}][:10], 1)) or "- No active tasks to order."}

## Boundary

Task brief is advisory only. No task execution occurred.
"""
    output = employee_root(config) / f"Employee Task Brief - {slugify(employee['Employee Name'])}.md"
    write_generated_note(output, content, config)
    return output


def employee_assign_kpi(config: RaphaelConfig, employee_name: str, kpi_id: str) -> Path:
    rows, employee = find_employee(config, employee_name)
    _kpi_rows, kpi = find_kpi(config, kpi_id)
    line = f"| {employee['Employee ID']} | {markdown_table_escape(employee['Employee Name'])} | {kpi['id']} | {markdown_table_escape(kpi['name'])} | {today()} |"
    append_unique_line(employee_root(config) / "Employee KPI Map.md", line, config)
    existing = employee.get("Assigned KPIs", "")
    addition = f"- `{kpi['id']}` {kpi['name']}"
    if addition not in existing:
        employee["Assigned KPIs"] = (existing.strip() + "\n" + addition).strip()
    write_employee_registry(config, rows)
    return employee_root(config) / "Employee KPI Map.md"


def employee_reassign(config: RaphaelConfig, employee_name: str, manager_or_council: str) -> Path:
    rows, employee = find_employee(config, employee_name)
    target = manager_or_council.strip()
    if target.lower().endswith("council"):
        employee["Department/Council"] = normalize_council_name(target)
        employee["Manager"] = employee_manager_for_department(employee["Department/Council"])
    else:
        employee["Manager"] = normalize_agent_name(target) if target.lower().endswith("agent") else target
    employee["Notes"] = (employee.get("Notes", "").strip() + f"\n- {today()}: Reassigned/updated manager target to {target}.").strip()
    write_employee_registry(config, rows)
    return employee_root(config) / "Employee Registry.md"


