BLOCKED_EXECUTION_PATTERNS = [
    r"\bdelete\b", r"\bremove\b", r"\bmove\b", r"\brename\b", r"\binstall\b", r"\buninstall\b",
    r"\bupload\b", r"\bemail\b", r"\bsend\b", r"\bpost\b", r"\bpublish\b", r"\bspend\b",
    r"\bpay\b", r"\bcharge\b", r"\bcredential\b", r"\bpassword\b", r"\bsecret\b", r"\btoken\b",
    r"\barbitrary\b", r"\bshell\b", r"\bpowershell\b", r"\bterminal\b", r"\bcmd\b", r"\bapi\b",
    r"\betsy\b.*\b(create|upload|publish|listing)\b", r"\bshopify\b.*\b(create|upload|publish)\b",
]


def controlled_execution_root(config: RaphaelConfig) -> Path:
    return ensure_safe_path(config.vault / "00_Raphael" / "Controlled Execution", config)


def ensure_controlled_execution(config: RaphaelConfig) -> None:
    if not config.controlled_execution_enabled:
        raise RuntimeError("Controlled Execution is disabled in config/settings.json.")
    root = controlled_execution_root(config)
    root.mkdir(parents=True, exist_ok=True)
    for filename, content in CONTROLLED_EXECUTION_FILES.items():
        path = root / filename
        if not path.exists():
            write_file(path, content, config)
    write_execution_allowlist(config)


def write_execution_allowlist(config: RaphaelConfig) -> Path:
    rows = [
        f"| {name} | {meta['level']} | {markdown_table_escape(meta['system'])} | {markdown_table_escape(meta['risk'])} | {markdown_table_escape(meta['writes'])} |"
        for name, meta in CONTROLLED_EXECUTION_ALLOWLIST.items()
    ]
    content = "# Execution Allowlist\n\n| Action Type | Level | Related System | Risk | Expected Writes |\n|---|---:|---|---|---|\n" + "\n".join(rows) + "\n\n## Blocked Examples\n\n- delete files\n- install packages\n- run arbitrary shell commands\n- send email\n- upload products\n- create listings\n- spend money\n- access credentials\n- external business platform actions\n"
    output = controlled_execution_root(config) / "Execution Allowlist.md"
    write_generated_note(output, content, config)
    return output


def make_execution_id(description: str) -> str:
    digest = hashlib.sha1(f"{description}|{dt.datetime.now().isoformat()}".encode("utf-8")).hexdigest()[:8].upper()
    return f"EXEC-{today().replace('-', '')}-{digest}"


def execution_related_id(pattern: str, text: str) -> str:
    match = re.search(pattern, text, flags=re.I)
    return match.group(1).upper() if match else ""


def classify_controlled_execution(config: RaphaelConfig, description: str) -> dict[str, str]:
    lowered = description.lower()
    if any(re.search(pattern, lowered) for pattern in BLOCKED_EXECUTION_PATTERNS):
        action_type = "blocked"
        reason = "Description contains blocked destructive, external, credential, arbitrary shell, or platform-action terms."
    elif "command center" in lowered:
        action_type, reason = "refresh_command_center", "Refresh Daily Command Center."
    elif "priority" in lowered:
        action_type, reason = "refresh_priority_brief", "Refresh Priority Brief."
    elif "kpi" in lowered and ("dashboard" in lowered or "refresh" in lowered):
        action_type, reason = "refresh_kpi_dashboard", "Refresh KPI dashboard, review, and brief."
    elif "initiative" in lowered and ("detect" in lowered or "detection" in lowered):
        action_type, reason = "detect_initiatives", "Run initiative detection."
    elif "initiative" in lowered and ("review" in lowered or "brief" in lowered):
        action_type, reason = "refresh_initiative_review", "Refresh initiative review and brief."
    elif "employee" in lowered and ("registry" in lowered or "workload" in lowered or "org chart" in lowered):
        action_type, reason = "refresh_employee_registry", "Refresh digital employee registry/workload/org chart."
    elif "commerce" in lowered and "review" in lowered:
        action_type, reason = "refresh_commerce_review", "Refresh Commerce Council review/brief/pipeline."
    elif "agency" in lowered and "review" in lowered:
        action_type, reason = "refresh_agency_review", "Refresh Agency Council review/brief/pipeline."
    elif "creator" in lowered and "review" in lowered:
        action_type, reason = "refresh_creator_review", "Refresh Creator Council review/brief/pipeline."
    elif "council" in lowered and "review" in lowered:
        action_type, reason = "refresh_council_review", "Refresh council task review."
    elif "opportunit" in lowered and "detect" in lowered:
        action_type, reason = "detect_opportunities", "Run opportunity detection."
    elif "memory search" in lowered:
        action_type, reason = "run_memory_search", "Run memory search and print results."
    elif "vision" in lowered or "vision-analyze" in lowered:
        action_type, reason = "run_vision_analysis", "Analyze an approved pending vision request."
    elif "simulate" in lowered or "simulation" in lowered:
        action_type, reason = "run_simulation", "Run a structured simulation."
    elif "build-generate" in lowered or "generate builder" in lowered or "builder files" in lowered:
        action_type, reason = "generate_builder_files", "Generate files in builder workspace only."
    elif "build-apply" in lowered or "apply builder" in lowered:
        action_type, reason = "apply_builder_output", "Apply approved builder output if builder apply rules permit it."
    elif "weekly operations" in lowered:
        action_type, reason = "run_weekly_operations_review", "Run weekly operations review internal workflow."
    elif "workflow" in lowered or re.search(r"\bWF-[A-F0-9]+\b", description, flags=re.I):
        action_type, reason = "run_approved_workflow", "Run an existing approved workflow request."
    else:
        action_type, reason = "blocked", "Description does not match a controlled execution allowlist entry."
    meta = CONTROLLED_EXECUTION_ALLOWLIST[action_type]
    project = detect_related_project(config, description)
    council_match = re.search(r"(Executive|Product|Engineering|Operations|Research|Career|Business|Commerce|Agency|Creator) Council", description, flags=re.I)
    employee_match = re.search(r"([A-Za-z /-]+ Agent)", description)
    return {
        "action_type": action_type,
        "level": str(meta["level"]),
        "related_system": meta["system"],
        "risk": "Blocked" if action_type == "blocked" else meta["risk"],
        "allowed": "No" if action_type == "blocked" or meta["level"] > config.max_execution_level else "Yes",
        "reason": reason,
        "expected_outputs": meta["writes"],
        "project": project,
        "council": council_match.group(0).title().replace("Ai", "AI") if council_match else "Unassigned",
        "employee": employee_match.group(1).strip() if employee_match else "Unassigned",
        "kpi": execution_related_id(r"(KPI-\d{8}-[A-Fa-f0-9]+)", description),
        "initiative": execution_related_id(r"(INIT-\d{8}-[A-Fa-f0-9]+)", description),
    }


def execution_record_block(row: dict[str, str]) -> str:
    fields = [
        "Execution Request ID", "Action Description", "Detected Execution Level", "Action Type",
        "Related System", "Related Project", "Related Council", "Related Employee", "Related KPI",
        "Related Initiative", "Risk Level", "Approval Required", "Status", "Dry Run Required",
        "Created Date", "Safety Notes", "Expected Outputs",
    ]
    body = [f"## {row['Execution Request ID']}"]
    for field in fields:
        body.append(f"\n### {field}\n\n{row.get(field, '')}")
    return "\n".join(body).strip() + "\n"


def read_execution_requests(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_controlled_execution(config)
    text = read_text_if_exists(controlled_execution_root(config) / "Execution Requests.md", config)
    rows: list[dict[str, str]] = []
    fields = [
        "Execution Request ID", "Action Description", "Detected Execution Level", "Action Type",
        "Related System", "Related Project", "Related Council", "Related Employee", "Related KPI",
        "Related Initiative", "Risk Level", "Approval Required", "Status", "Dry Run Required",
        "Created Date", "Safety Notes", "Expected Outputs",
    ]
    for match in re.finditer(r"^## (EXEC-\d{8}-[A-F0-9]+)\s+(.+?)(?=^## EXEC-\d{8}-[A-F0-9]+|\Z)", text, flags=re.M | re.S):
        body = match.group(2)
        row = {"Execution Request ID": match.group(1)}
        for field in fields:
            row[field] = subsection_value(body, field)
        rows.append(row)
    return rows


def write_execution_requests(config: RaphaelConfig, rows: list[dict[str, str]]) -> None:
    content = "# Execution Requests\n\n" + "\n".join(execution_record_block(row) for row in rows) + "\n"
    write_generated_note(controlled_execution_root(config) / "Execution Requests.md", content, config)


def find_execution_request(config: RaphaelConfig, request_id: str) -> tuple[list[dict[str, str]], dict[str, str]]:
    rows = read_execution_requests(config)
    target = request_id.strip().upper()
    for row in rows:
        if row["Execution Request ID"].upper() == target:
            return rows, row
    raise FileNotFoundError(f"Execution Request ID not found: {request_id}")


def execution_request(config: RaphaelConfig, description: str) -> str:
    ensure_controlled_execution(config)
    cls = classify_controlled_execution(config, description)
    request_id = make_execution_id(description)
    status = "Blocked" if cls["allowed"] == "No" else "Pending"
    row = {
        "Execution Request ID": request_id,
        "Action Description": description,
        "Detected Execution Level": cls["level"],
        "Action Type": cls["action_type"],
        "Related System": cls["related_system"],
        "Related Project": cls["project"],
        "Related Council": cls["council"],
        "Related Employee": cls["employee"],
        "Related KPI": cls["kpi"] or "Unassigned",
        "Related Initiative": cls["initiative"] or "Unassigned",
        "Risk Level": cls["risk"],
        "Approval Required": "Yes",
        "Status": status,
        "Dry Run Required": "Yes" if config.execution_dry_run_default else "Recommended",
        "Created Date": dt.datetime.now().isoformat(timespec="seconds"),
        "Safety Notes": cls["reason"],
        "Expected Outputs": cls["expected_outputs"],
    }
    rows = read_execution_requests(config)
    rows.append(row)
    write_execution_requests(config, rows)
    append_unique_line(controlled_execution_root(config) / "Execution Log.md", f"| {today()} | {request_id} | {row['Action Type']} | {status} | Request created. |", config)
    return request_id


def execution_status_text(config: RaphaelConfig) -> str:
    ensure_controlled_execution(config)
    rows = read_execution_requests(config)
    return f"""# Controlled Execution Status

- Enabled: {config.controlled_execution_enabled}
- Confirmation required: {config.execution_requires_confirmation}
- Voice execution enabled: {config.voice_execution_enabled}
- Dashboard execution enabled: {config.dashboard_execution_enabled}
- Max execution level: {config.max_execution_level}
- External execution enabled: {config.external_execution_enabled}
- Dry run default: {config.execution_dry_run_default}
- Requests tracked: {len(rows)}

## Boundary

External actions remain blocked. No arbitrary shell commands, emails, uploads, publishing, spending, credential access, or platform actions are allowed.
"""


def execution_policy_text(config: RaphaelConfig) -> str:
    ensure_controlled_execution(config)
    return read_text_if_exists(controlled_execution_root(config) / "Execution Policy.md", config) + "\n\n" + read_text_if_exists(controlled_execution_root(config) / "Execution Allowlist.md", config)


def execution_dry_run(config: RaphaelConfig, request_id: str) -> str:
    _rows, row = find_execution_request(config, request_id)
    allowed = row["Action Type"] in CONTROLLED_EXECUTION_ALLOWLIST and row["Status"] != "Blocked"
    level = int(row.get("Detected Execution Level") or "5")
    if level > config.max_execution_level:
        allowed = False
    result = f"""# Execution Dry Run - {row['Execution Request ID']}

## Would Happen

- Action type: `{row['Action Type']}`
- Level: {row['Detected Execution Level']}
- Related system: {row['Related System']}
- Expected outputs: {row['Expected Outputs']}

## Files / Systems That May Be Written

- {row['Expected Outputs']}
- Controlled execution log and request status notes

## Safety Checks

- Request status: {row['Status']}
- Max level allowed: {config.max_execution_level}
- External execution enabled: {config.external_execution_enabled}
- Allowed: {'Yes' if allowed else 'No'}

## Safety Notes

{row['Safety Notes']}
"""
    append_unique_section(controlled_execution_root(config) / "Execution Safety Report.md", f"Dry Run {row['Execution Request ID']}", result, config)
    return result


def execution_approve(config: RaphaelConfig, request_id: str) -> str:
    rows, row = find_execution_request(config, request_id)
    if row["Status"] == "Blocked":
        raise PermissionError("Blocked execution requests cannot be approved.")
    if int(row.get("Detected Execution Level") or "5") > config.max_execution_level:
        raise PermissionError("Execution request exceeds max_execution_level.")
    row["Status"] = "Approved"
    write_execution_requests(config, rows)
    append_unique_line(controlled_execution_root(config) / "Execution Log.md", f"| {today()} | {row['Execution Request ID']} | {row['Action Type']} | Approved | Approved for controlled execution. |", config)
    return row["Execution Request ID"]


def execute_controlled_action(config: RaphaelConfig, row: dict[str, str]) -> list[Path] | str:
    action_type = row["Action Type"]
    description = row["Action Description"]
    if action_type == "refresh_command_center":
        return [refresh_command_center(config)]
    if action_type == "refresh_priority_brief":
        return [prioritize(config)]
    if action_type == "refresh_kpi_dashboard":
        return [kpi_dashboard(config), kpi_review(config), kpi_brief(config)]
    if action_type == "detect_initiatives":
        return [initiative_detect(config), initiative_review(config), initiative_brief(config)]
    if action_type == "refresh_initiative_review":
        return [initiative_review(config), initiative_brief(config)]
    if action_type == "refresh_employee_registry":
        return [employee_registry(config), employee_workload_review(config), employee_org_chart(config)]
    if action_type == "refresh_council_review":
        return [council_task_review(config)]
    if action_type == "refresh_commerce_review":
        return [commerce_review(config), commerce_brief(config), commerce_pipeline(config)]
    if action_type == "refresh_agency_review":
        return [agency_review(config), agency_brief(config), agency_pipeline(config)]
    if action_type == "refresh_creator_review":
        return [creator_review(config), creator_brief(config), creator_pipeline(config)]
    if action_type == "detect_opportunities":
        return [detect_opportunities(config), opportunity_review(config), opportunity_brief(config)]
    if action_type == "run_memory_search":
        query = re.sub(r".*memory search", "", description, flags=re.I).strip(" :\"'") or description
        return memory_search(config, query)
    if action_type == "run_vision_analysis":
        request_id = execution_related_id(r"(VISION-\d{8}-[A-Fa-f0-9]+)", description)
        if not request_id:
            raise ValueError("run_vision_analysis requires a VISION request ID in the description.")
        return [vision_analyze(config, request_id)]
    if action_type == "run_simulation":
        sim_match = re.search(r"simulate\s+(.+?)\s+(?:versus|vs|and)\s+(.+)$", description, flags=re.I)
        if sim_match:
            return [simulate_options(config, [sim_match.group(1).strip(), sim_match.group(2).strip()])]
        raise ValueError("run_simulation requires a phrase like `simulate A versus B`.")
    if action_type == "generate_builder_files":
        build_id = execution_related_id(r"(BUILD-\d{8}-[A-Fa-f0-9]+)", description)
        if not build_id:
            raise ValueError("generate_builder_files requires a BUILD request ID.")
        return [generate_build_files(config, build_id)]
    if action_type == "apply_builder_output":
        build_id = execution_related_id(r"(BUILD-\d{8}-[A-Fa-f0-9]+)", description)
        if not build_id:
            raise ValueError("apply_builder_output requires a BUILD request ID.")
        return [build_apply(config, build_id)]
    if action_type == "run_approved_workflow":
        workflow_id = execution_related_id(r"(WF-[A-Fa-f0-9]+)", description)
        if not workflow_id:
            raise ValueError("run_approved_workflow requires a WF request ID.")
        return [run_workflow_request(config, workflow_id)]
    if action_type == "run_weekly_operations_review":
        return run_workflow_steps(config, "weekly_operations_review", "Weekly Operations")
    raise PermissionError(f"Action type is not executable: {action_type}")


def execution_run(config: RaphaelConfig, request_id: str) -> str:
    rows, row = find_execution_request(config, request_id)
    if row["Status"] != "Approved":
        raise PermissionError(f"Refused: request status is {row['Status']}; only Approved requests can run.")
    if row["Action Type"] == "blocked":
        raise PermissionError("Refused: blocked action type cannot run.")
    if int(row.get("Detected Execution Level") or "5") > config.max_execution_level:
        raise PermissionError("Refused: request exceeds max_execution_level.")
    try:
        outputs = execute_controlled_action(config, row)
        if isinstance(outputs, str):
            result = outputs[:1000]
        else:
            result = "Generated: " + ", ".join(str(path) for path in outputs)
        row["Status"] = "Executed"
        status = "Executed"
    except Exception as exc:
        result = f"Failed safely: {exc}"
        status = "Failed"
    write_execution_requests(config, rows)
    append_unique_line(controlled_execution_root(config) / "Execution Log.md", f"| {today()} | {row['Execution Request ID']} | {row['Action Type']} | {status} | {markdown_table_escape(result)} |", config)
    if status != "Executed":
        raise RuntimeError(result)
    return result


def execution_review(config: RaphaelConfig) -> Path:
    ensure_controlled_execution(config)
    rows = read_execution_requests(config)
    groups = {status: [row for row in rows if row["Status"] == status] for status in ["Pending", "Approved", "Executed", "Rejected", "Blocked"]}
    content = f"""# Execution Review

Generated: {dt.datetime.now().isoformat(timespec='seconds')}

## Summary

- Total requests: {len(rows)}
- Pending: {len(groups['Pending'])}
- Approved: {len(groups['Approved'])}
- Executed: {len(groups['Executed'])}
- Blocked: {len(groups['Blocked'])}

## Pending Requests

{chr(10).join(f"- `{row['Execution Request ID']}` [{row['Action Type']}] {row['Action Description']}" for row in groups['Pending']) if groups['Pending'] else "- None."}

## Approved Requests

{chr(10).join(f"- `{row['Execution Request ID']}` [{row['Action Type']}]" for row in groups['Approved']) if groups['Approved'] else "- None."}

## Blocked Requests

{chr(10).join(f"- `{row['Execution Request ID']}` {row['Safety Notes']}" for row in groups['Blocked']) if groups['Blocked'] else "- None."}

## Boundary

Review is reporting-only. It did not run any action.
"""
    output = controlled_execution_root(config) / "Execution Review.md"
    write_generated_note(output, content, config)
    return output


