def agent_memory_query(agent_name: str, question: str = "") -> str:
    normalized = normalize_agent_name(agent_name)
    return f"{normalized} responsibilities tasks decisions risks lessons projects {question}".strip()


def agent_context(config: RaphaelConfig, agent_name: str) -> str:
    normalized = normalize_agent_name(agent_name)
    folder = agent_dir(config, normalized)
    sections: list[str] = []
    for name in ["Identity.md", "Responsibilities.md", "Inputs.md", "Outputs.md", "SOPs.md", "Escalation Rules.md", "Memory Links.md"]:
        text = read_text_if_exists(folder / name, config)
        if text:
            sections.append(f"## {name}\n\n{text}")
    open_tasks = [task for task in read_agent_tasks(config, normalized) if task["status"] in {"Open", "In Progress", "Blocked", "Waiting on Aaron"}]
    if open_tasks:
        sections.append(
            "## Open Agent Tasks\n\n"
            + "\n".join(
                f"- `{task['id']}` [{task['status']}/{task['priority']}] {task['task']} ({task['project']})"
                for task in open_tasks
            )
        )
    return trim_ai_context("\n\n".join(sections) or f"No local context found for {normalized}.", config)


def disabled_agent_response(prompt: str, provider: str, model: str, model_status: str, memory_sources: list[dict], memory_status: str, fallback_context: str) -> str:
    return (
        f"## Routed Model\n\n- Provider: {provider}\n- Model: {model}\n- Model status: {model_status}\n\n"
        + disabled_ai_response(prompt, "", memory_sources, memory_status, fallback_context)
    )


def append_agent_ai_answer(config: RaphaelConfig, agent_name: str, question: str, answer: str, provider: str, model: str, model_status: str, memory_sources: list[dict], confidence: str) -> Path:
    normalized = normalize_agent_name(agent_name)
    output = ensure_safe_path(agent_dir(config, normalized) / "AI Answers.md", config)
    if not output.exists():
        output.write_text(f"# {normalized} AI Answers\n\n", encoding="utf-8")
    entry = f"""## {dt.datetime.now().isoformat(timespec='seconds')}

### Question

{question}

### Model Route

- Agent: {normalized}
- Provider: {provider}
- Model: {model}
- Model status: {model_status}

### Answer

{answer.strip()}

### Memory Sources Used

{format_memory_sources(memory_sources)}

### Confidence

{confidence}

### Follow-up Recommendations

- Review cited memory before acting.
- Convert concrete next steps into agent tasks if Aaron approves.
- Capture any important decision, risk, or lesson.

"""
    with output.open("a", encoding="utf-8") as handle:
        handle.write(entry)
    return output


def agent_ask(config: RaphaelConfig, agent_name: str, question: str) -> Path:
    normalized = normalize_agent_name(agent_name)
    provider, model, model_status = route_model_for_agent(config, normalized)
    fallback_context = agent_context(config, normalized)
    memory_context, memory_sources, memory_status = rag_memory_context(config, agent_memory_query(normalized, question))
    context = combine_ai_context(
        f"# Agent Context\n\n{fallback_context}",
        f"# Retrieved Qdrant Memory\n\n{memory_context}" if memory_context else "",
        config=config,
    )
    prompt = (
        f"As {normalized}, answer Aaron's question using only supplied context. "
        f"Question: {question}"
    )
    disabled = ai_disabled_message(config)
    if disabled:
        answer = disabled_agent_response(prompt, provider, model, model_status, memory_sources, memory_status, fallback_context)
        ai_enabled = False
    else:
        answer = call_ai_with_route(
            config,
            provider,
            model,
            prompt + "\n\nDo not execute actions. Recommend next steps and escalate decisions Aaron must make.",
            context,
        )
        ai_enabled = True
    confidence = infer_confidence(memory_sources, ai_enabled)
    return append_agent_ai_answer(config, normalized, question, answer, provider, model, model_status, memory_sources, confidence)


