def ensure_goal_files(config: RaphaelConfig) -> None:
    for rel_path in ["00_Raphael/Goals.md", "00_Raphael/Goal Review.md", "00_Raphael/Priority Brief.md"]:
        write_file(config.vault / rel_path, CORE_FILES[rel_path], config)


def normalize_goal_status(status: str) -> str:
    cleaned = status.strip().lower()
    for valid in SUPPORTED_GOAL_STATUSES:
        if cleaned == valid.lower():
            return valid
    raise ValueError(f"Unsupported goal status `{status}`. Use one of: {', '.join(sorted(SUPPORTED_GOAL_STATUSES))}")


def infer_goal_priority(title: str, description: str) -> str:
    lowered = f"{title} {description}".lower()
    if any(word in lowered for word in ["critical", "urgent", "deadline", "must", "blocked"]):
        return "Critical"
    if any(word in lowered for word in ["career", "portfolio", "revenue", "job", "assignment", "launch", "client"]):
        return "High"
    if any(word in lowered for word in ["important", "improve", "build", "research", "learn"]):
        return "Medium"
    return "Medium"


def goal_related_projects(config: RaphaelConfig, text: str) -> str:
    matches = [project for project in list_projects(config) if project.lower() in text.lower()]
    if matches:
        return ", ".join(matches)
    detected = detect_related_project(config, text)
    return "" if detected == "Unassigned" else detected


def goal_related_agents(text: str) -> str:
    agent, ranked = route_task_choice(text)
    related = [agent]
    related.extend(name for name, score in ranked if score > 0 and name != agent)
    return ", ".join(related[:3])


def add_goal(config: RaphaelConfig, title: str, description: str) -> str:
    ensure_goal_files(config)
    goal_id = make_goal_id(title)
    priority = infer_goal_priority(title, description)
    related_projects = goal_related_projects(config, f"{title} {description}") or "Unassigned"
    related_agents = goal_related_agents(f"{title} {description}")
    goals_path = config.vault / "00_Raphael" / "Goals.md"
    row = (
        f"| {goal_id} | {markdown_table_escape(title)} | {markdown_table_escape(description)} | Active | "
        f"{priority} | {markdown_table_escape(related_projects)} | {markdown_table_escape(related_agents)} | "
        f"{today()} | Define next milestone. |"
    )
    append_unique_line(goals_path, row, config)
    section = f"""
## {goal_id}

### Title

{title}

### Description

{description}

### Status

Active

### Priority

{priority}

### Related Projects

{related_projects}

### Related Agents

{related_agents}

### Created Date

{today()}

### Next Milestone

Define next milestone.

### Progress Log

- {dt.datetime.now().isoformat(timespec='seconds')} - Goal created.
"""
    append_unique_section(goals_path, f"## {goal_id}", section, config)
    return goal_id


def parse_goals(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_goal_files(config)
    text = read_text_if_exists(config.vault / "00_Raphael" / "Goals.md", config)
    goals: list[dict[str, str]] = []
    for row in meaningful_table_rows(text):
        cells = table_cells(row)
        if len(cells) >= 9 and cells[0].startswith("GOAL-"):
            goals.append(
                {
                    "id": cells[0],
                    "title": cells[1],
                    "description": cells[2],
                    "status": cells[3],
                    "priority": cells[4],
                    "projects": cells[5],
                    "agents": cells[6],
                    "created": cells[7],
                    "milestone": cells[8],
                }
            )
    return goals


def rewrite_goal_row(config: RaphaelConfig, goal_id: str, updates: dict[str, str]) -> None:
    goals_path = config.vault / "00_Raphael" / "Goals.md"
    text = read_text_if_exists(goals_path, config)
    lines = text.splitlines()
    new_lines: list[str] = []
    updated = False
    for line in lines:
        if line.startswith(f"| {goal_id} |"):
            cells = table_cells(line)
            while len(cells) < 9:
                cells.append("")
            keys = ["id", "title", "description", "status", "priority", "projects", "agents", "created", "milestone"]
            data = dict(zip(keys, cells))
            data.update(updates)
            line = (
                f"| {data['id']} | {markdown_table_escape(data['title'])} | {markdown_table_escape(data['description'])} | "
                f"{data['status']} | {data['priority']} | {markdown_table_escape(data['projects'])} | "
                f"{markdown_table_escape(data['agents'])} | {data['created']} | {markdown_table_escape(data['milestone'])} |"
            )
            updated = True
        new_lines.append(line)
    if not updated:
        raise FileNotFoundError(f"Goal ID not found: {goal_id}")
    ensure_safe_path(goals_path, config).write_text("\n".join(new_lines).rstrip() + "\n", encoding="utf-8")


def find_goal(config: RaphaelConfig, goal_id: str) -> dict[str, str]:
    wanted = goal_id.strip().upper()
    for goal in parse_goals(config):
        if goal["id"].upper() == wanted:
            return goal
    raise FileNotFoundError(f"Goal ID not found: {goal_id}")


def update_goal_section(config: RaphaelConfig, goal_id: str, heading: str, value: str) -> None:
    goals_path = config.vault / "00_Raphael" / "Goals.md"
    text = read_text_if_exists(goals_path, config)
    section_pattern = rf"(## {re.escape(goal_id)}\s+.*?)(?=\n## GOAL-|\Z)"
    match = re.search(section_pattern, text, flags=re.S)
    if not match:
        raise FileNotFoundError(f"Goal section not found: {goal_id}")
    section = match.group(1)
    updated_section = replace_or_insert_subsection(section, heading, value)
    updated = text[: match.start(1)] + updated_section.rstrip() + "\n" + text[match.end(1) :]
    ensure_safe_path(goals_path, config).write_text(updated.rstrip() + "\n", encoding="utf-8")


def goal_status(config: RaphaelConfig, goal_id: str, status: str) -> None:
    valid = normalize_goal_status(status)
    find_goal(config, goal_id)
    rewrite_goal_row(config, goal_id, {"status": valid})
    update_goal_section(config, goal_id, "Status", valid)
    goal_log(config, goal_id, f"Status changed to {valid}.")


def goal_log(config: RaphaelConfig, goal_id: str, note: str) -> None:
    find_goal(config, goal_id)
    goals_path = config.vault / "00_Raphael" / "Goals.md"
    text = read_text_if_exists(goals_path, config)
    section_pattern = rf"(## {re.escape(goal_id)}\s+.*?)(?=\n## GOAL-|\Z)"
    match = re.search(section_pattern, text, flags=re.S)
    if not match:
        raise FileNotFoundError(f"Goal section not found: {goal_id}")
    section = append_subsection_note(match.group(1), "Progress Log", f"- {dt.datetime.now().isoformat(timespec='seconds')} - {note}")
    updated = text[: match.start(1)] + section.rstrip() + "\n" + text[match.end(1) :]
    ensure_safe_path(goals_path, config).write_text(updated.rstrip() + "\n", encoding="utf-8")


