def collect_project_risks(config: RaphaelConfig, limit: int = 10) -> list[str]:
    risks: list[str] = []
    for project in list_projects(config):
        rows = meaningful_table_rows(read_text_if_exists(project_dir(config, project) / "Risks.md", config))
        for row in rows:
            risks.append(f"{project}: {format_risk_row(row)}")
    return risks[:limit]


def collect_deadline_lines(config: RaphaelConfig, limit: int = 10) -> list[str]:
    lines: list[str] = []
    date_like = re.compile(
        r"(?i)(\b\d{1,2}[/-]\d{1,2}([/-]\d{2,4})?\b|\b\d{4}-\d{2}-\d{2}\b|"
        r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\b|"
        r"\btoday\b|\btomorrow\b|\bnext\s+(week|month|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b)"
    )
    for root in [config.vault / "02_Projects", config.vault / "06_Assignments"]:
        if not root.exists():
            continue
        for file in root.rglob("*.md"):
            text = read_text_if_exists(file, config)
            for line in text.splitlines():
                clean_line = line.strip()
                if clean_line.startswith("#"):
                    continue
                if re.search(r"(?i)\b(due date|deadline)\b", clean_line) and date_like.search(clean_line):
                    lines.append(f"{file.parent.name}: {clean_line}")
                    break
            if len(lines) >= limit:
                return lines
    return lines


def priority_score_goal(goal: dict[str, str]) -> int:
    return {"Critical": 100, "High": 75, "Medium": 45, "Low": 20}.get(goal["priority"], 30)


def prioritize(config: RaphaelConfig) -> Path:
    ensure_goal_files(config)
    mode = current_mode_name(config)
    goals = parse_goals(config)
    active_goals = [goal for goal in goals if goal["status"] == "Active"]
    open_tasks = [task for task in all_agent_tasks(config) if task["status"] in {"Open", "In Progress"}]
    blocked = tasks_by_status(all_agent_tasks(config), "Blocked")
    waiting = tasks_by_status(all_agent_tasks(config), "Waiting on Aaron")
    risks = collect_project_risks(config)
    deadlines = collect_deadline_lines(config)
    active_projects = list_projects(config)
    sorted_goals = sorted(active_goals, key=priority_score_goal, reverse=True)
    top_goal_lines = [
        f"- `{goal['id']}` [{goal['priority']}] {goal['title']} - milestone: {goal['milestone']}"
        for goal in sorted_goals[:8]
    ]
    top_task_lines = [
        f"- `{task['id']}` [{task['priority']}/{task['status']}] {task['task']} - {task['agent']}"
        for task in open_tasks[:10]
    ]
    recommendations: list[str] = []
    if waiting:
        recommendations.append("Resolve Waiting on Aaron tasks first; they block system progress.")
    if blocked:
        recommendations.append("Unblock or re-scope blocked tasks before adding new work.")
    if sorted_goals:
        recommendations.append(f"Anchor today's work to top goal `{sorted_goals[0]['id']}`: {sorted_goals[0]['title']}.")
    recommendations.extend(mode_recommendations(config, mode)[:3])
    if risks:
        recommendations.append("Review open risks before executing new workflows.")
    content = f"""# Priority Brief

Generated: {today()}

## Current Operating Mode

{mode}

## Active Goals

{chr(10).join(top_goal_lines) if top_goal_lines else "- No active goals. Add a goal to guide prioritization."}

## Open Tasks

{chr(10).join(top_task_lines) if top_task_lines else "- No open or in-progress tasks."}

## Blocked Tasks

{chr(10).join(f"- `{task['id']}` {task['task']} - {task['agent']}" for task in blocked) if blocked else "- No blocked tasks."}

## Waiting on Aaron

{chr(10).join(f"- `{task['id']}` {task['task']} - {task['agent']}" for task in waiting) if waiting else "- No tasks waiting on Aaron."}

## Active Projects

{chr(10).join(f"- [[{project}/Overview|{project}]]" for project in active_projects[:20]) if active_projects else "- No active projects found."}

## Risks

{chr(10).join(f"- {risk}" for risk in risks) if risks else "- No project risks captured."}

## Deadlines

{chr(10).join(f"- {line}" for line in deadlines) if deadlines else "- No explicit due dates or deadlines found in scanned project/assignment notes."}

## Recommended Priorities

{chr(10).join(f"- {item}" for item in recommendations)}

## Boundary

Prioritization is advisory only. Raphael did not execute actions or edit source folders.
"""
    output = config.vault / "00_Raphael" / "Priority Brief.md"
    write_generated_note(output, content, config)
    return output


