def infer_risk_level(text: str) -> str:
    lowered = text.lower()
    high_terms = ["delete", "remove", "upload", "email", "send", "install", "uninstall", "password", "secret", "token", "credential", "format", "security setting"]
    medium_terms = ["move", "rename", "overwrite", "external", "internet", "api", "shell", "terminal", "command", "financial", "legal"]
    if any(term in lowered for term in high_terms):
        return "High"
    if any(term in lowered for term in medium_terms):
        return "Medium"
    return "Low"


def requires_action_approval(description: str, risk_level: str) -> str:
    lowered = description.lower()
    approval_terms = ["delete", "move", "rename", "overwrite", "install", "uninstall", "upload", "email", "send", "external", "internet", "password", "secret", "financial", "legal", "system"]
    if risk_level in {"Medium", "High"} or any(term in lowered for term in approval_terms):
        return "Yes"
    return "No"


def infer_related_tool(config: RaphaelConfig, description: str) -> str:
    lowered = description.lower()
    for tool in parse_tool_registry(config):
        if tool["name"].lower() in lowered:
            return tool["name"]
    if "python" in lowered:
        return "Python"
    if "powershell" in lowered or "terminal" in lowered or "command" in lowered:
        return "PowerShell"
    if "obsidian" in lowered or "vault" in lowered or "markdown" in lowered:
        return "Obsidian"
    if "ollama" in lowered:
        return "Ollama"
    if "openai" in lowered:
        return "OpenAI"
    return "Unassigned"


def related_agents_for_tool(category: str, tool_name: str) -> str:
    lowered = f"{category} {tool_name}".lower()
    agents: list[str] = []
    if any(term in lowered for term in ["code", "developer", "python", "powershell", "automation", "api"]):
        agents.append("Developer Agent")
    if any(term in lowered for term in ["research", "web", "source"]):
        agents.append("Research Agent")
    if any(term in lowered for term in ["career", "resume", "portfolio"]):
        agents.append("Career Agent")
    if any(term in lowered for term in ["finance", "budget"]):
        agents.append("Finance Agent")
    if any(term in lowered for term in ["legal", "compliance", "policy"]):
        agents.append("Legal Compliance Agent")
    if not agents:
        agents.append("Chief of Staff Agent")
    return ", ".join(dict.fromkeys(agents))


def parse_tool_registry(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_phase9_files(config)
    text = read_text_if_exists(config.vault / "01_Memory" / "Tool Registry.md", config)
    tools: list[dict[str, str]] = []
    for row in meaningful_table_rows(text):
        cells = table_cells(row)
        if len(cells) >= 9:
            if cells[0].lower() == "tool name":
                continue
            tools.append(
                {
                    "name": cells[0],
                    "category": cells[1],
                    "purpose": cells[2],
                    "allowed": cells[3],
                    "restricted": cells[4],
                    "risk": cells[5],
                    "approval": cells[6],
                    "agents": cells[7],
                    "notes": cells[8],
                }
            )
    return tools


def add_tool(config: RaphaelConfig, tool_name: str, category: str, allowed_actions: str, restricted_actions: str) -> None:
    ensure_phase9_files(config)
    risk_level = infer_risk_level(f"{allowed_actions} {restricted_actions}")
    approval = "Yes" if risk_level in {"Medium", "High"} or restricted_actions.strip() else "No"
    purpose = f"{category} tool tracked by Raphael OS."
    related_agents = related_agents_for_tool(category, tool_name)
    line = (
        f"| {markdown_table_escape(tool_name)} | {markdown_table_escape(category)} | "
        f"{markdown_table_escape(purpose)} | {markdown_table_escape(allowed_actions)} | "
        f"{markdown_table_escape(restricted_actions)} | {risk_level} | {approval} | "
        f"{markdown_table_escape(related_agents)} | Added via CLI. |"
    )
    append_unique_line(config.vault / "01_Memory" / "Tool Registry.md", line, config)


def list_tools_text(config: RaphaelConfig) -> str:
    tools = parse_tool_registry(config)
    if not tools:
        return "No tools registered yet."
    return "\n".join(
        f"{tool['name']} [{tool['category']}] risk={tool['risk']} approval={tool['approval']} allowed={tool['allowed']}"
        for tool in tools
    )


