def write_action_request_file(path: Path, content: str, config: RaphaelConfig) -> None:
    safe_path = ensure_safe_path(path, config)
    requests_root = (config.vault / "00_Raphael" / "Action Requests").resolve()
    if not (safe_path == requests_root or requests_root in safe_path.parents):
        raise PermissionError(f"Action request updates are limited to Action Requests: {safe_path}")
    safe_path.write_text(content, encoding="utf-8")


def write_workflow_request_file(path: Path, content: str, config: RaphaelConfig) -> None:
    safe_path = ensure_safe_path(path, config)
    requests_root = (config.vault / "00_Raphael" / "Workflow Requests").resolve()
    if not (safe_path == requests_root or requests_root in safe_path.parents):
        raise PermissionError(f"Workflow request updates are limited to Workflow Requests: {safe_path}")
    safe_path.write_text(content, encoding="utf-8")


def propose_action(config: RaphaelConfig, description: str) -> Path:
    ensure_phase9_files(config)
    requests_dir = config.vault / "00_Raphael" / "Action Requests"
    ensure_safe_path(requests_dir, config).mkdir(parents=True, exist_ok=True)
    path = unique_path(requests_dir / action_file_name(description))
    action_id = make_action_id(path)
    risk_level = infer_risk_level(description)
    related_tool = infer_related_tool(config, description)
    related_project = detect_related_project(config, description)
    approval_required = "Yes"
    content = f"""# Action Request - {action_id}

## Action ID

{action_id}

## Description

{description}

## Risk Level

{risk_level}

## Related Tool

{related_tool}

## Related Project

{related_project}

## Proposed By

Raphael

## Status

Pending

## Approval Required

{approval_required}

## Boundary

This request tracks permission. Phase 10 can execute only allowlisted internal Raphael actions after approval.
"""
    write_action_request_file(path, content, config)
    return path


def read_action_requests(config: RaphaelConfig) -> list[dict[str, str]]:
    ensure_phase9_files(config)
    requests_dir = config.vault / "00_Raphael" / "Action Requests"
    actions: list[dict[str, str]] = []
    for path in sorted(requests_dir.glob("*.md")):
        text = read_text_if_exists(path, config)
        action_id = section_value(text, "Action ID") or make_action_id(path)
        if not section_value(text, "Action ID"):
            text = replace_or_insert_section(text, "Action ID", action_id)
            write_action_request_file(path, text, config)
        actions.append(
            {
                "id": action_id,
                "path": str(path),
                "description": section_value(text, "Description") or path.stem,
                "risk": section_value(text, "Risk Level") or "Unknown",
                "tool": section_value(text, "Related Tool") or "Unassigned",
                "project": section_value(text, "Related Project") or "Unassigned",
                "status": section_value(text, "Status") or "Pending",
                "approval": section_value(text, "Approval Required") or "Yes",
            }
        )
    return actions


def find_action_request(config: RaphaelConfig, action_id: str) -> dict[str, str]:
    wanted = action_id.strip().lower()
    for action in read_action_requests(config):
        if action["id"].lower() == wanted:
            return action
    raise FileNotFoundError(f"Action ID not found: {action_id}")


def update_action_status(config: RaphaelConfig, action_id: str, status: str, reason: str) -> Path:
    ensure_phase9_files(config)
    action = find_action_request(config, action_id)
    path = Path(action["path"])
    text = read_text_if_exists(path, config)
    updated = replace_or_insert_section(text, "Status", status)
    updated = append_section_note(updated, "Decision Log", f"- {dt.datetime.now().isoformat(timespec='seconds')} - {status}: {reason}")
    write_action_request_file(path, updated, config)
    log_line = (
        f"| {today()} | {markdown_table_escape(action['id'])} | "
        f"{markdown_table_escape(action['description'])} | {status} | {markdown_table_escape(reason)} |"
    )
    append_unique_line(config.vault / "00_Raphael" / "Action Approval Log.md", log_line, config)
    return path


def approve_action(config: RaphaelConfig, action_id: str) -> Path:
    if action_id.strip().upper().startswith("WF-"):
        return approve_workflow_request(config, action_id)
    return update_action_status(config, action_id, "Approved", "Approved by Aaron. Only allowlisted internal Phase 10 execution is permitted.")


def reject_action(config: RaphaelConfig, action_id: str, reason: str) -> Path:
    if action_id.strip().upper().startswith("WF-"):
        return reject_workflow_request(config, action_id, reason)
    return update_action_status(config, action_id, "Rejected", reason)


def action_review(config: RaphaelConfig) -> Path:
    ensure_phase9_files(config)
    actions = read_action_requests(config)
    pending = [action for action in actions if action["status"].lower() == "pending"]
    approved = [action for action in actions if action["status"].lower() == "approved"]
    executed = [action for action in actions if action["status"].lower() == "executed"]
    rejected = [action for action in actions if action["status"].lower() == "rejected"]
    high_risk = [action for action in pending if action["risk"].lower() == "high"]
    content = f"""# Action Review

Generated: {today()}

## Summary

- Total action requests: {len(actions)}
- Pending: {len(pending)}
- Approved: {len(approved)}
- Executed: {len(executed)}
- Rejected: {len(rejected)}
- High-risk pending: {len(high_risk)}

## Pending Actions

{chr(10).join(f"- `{action['id']}` [{action['risk']}] {action['description']} (tool: {action['tool']}, project: {action['project']})" for action in pending) if pending else "- No pending actions."}

## High-Risk Pending Actions

{chr(10).join(f"- `{action['id']}` {action['description']}" for action in high_risk) if high_risk else "- No high-risk pending actions."}

## Approved Actions

{chr(10).join(f"- `{action['id']}` {action['description']}" for action in approved[-20:]) if approved else "- No approved actions."}

## Executed Actions

{chr(10).join(f"- `{action['id']}` {action['description']}" for action in executed[-20:]) if executed else "- No executed actions."}

## Rejected Actions

{chr(10).join(f"- `{action['id']}` {action['description']}" for action in rejected[-20:]) if rejected else "- No rejected actions."}

## Boundary

Approved actions are not executed automatically. Phase 10 execution requires an explicit `execute-action` command and an allowlisted internal action type.
"""
    output = config.vault / "00_Raphael" / "Action Review.md"
    write_generated_note(output, content, config)
    return output


def classify_allowlisted_action(action: dict[str, str]) -> tuple[str | None, str]:
    description = action["description"].lower()
    destructive_patterns = [
        r"\bdelete\b",
        r"\bremove\b",
        r"\bmove\b",
        r"\brename\b",
        r"\binstall\b",
        r"\buninstall\b",
        r"\bupload\b",
        r"\bsend\s+email\b",
        r"\bemail\s+(user|customer|client|recipient|contact)\b",
        r"\bpassword\b",
        r"\bsecret\b",
        r"\bcredential\b",
        r"\btoken\b",
        r"\bexternal\s+api\b",
        r"\bbrowser\b",
    ]
    arbitrary_execution_patterns = [r"\bshell\b", r"\bpowershell\b", r"\bterminal\b", r"\bcmd\.exe\b", r"\barbitrary command\b"]
    if any(re.search(pattern, description) for pattern in destructive_patterns):
        return None, "Description contains destructive, external, or credential-related terms."
    if any(re.search(pattern, description) for pattern in arbitrary_execution_patterns):
        return None, "Description appears to request arbitrary command execution, which Phase 10 does not support."
    if "command center" in description or "daily command center" in description:
        return "refresh_command_center", "Refreshes Daily Command Center using internal Raphael function."
    if "global brief" in description or "executive brief" in description:
        return "refresh_global_brief", "Refreshes Global Brief using internal Raphael function."
    if "project health" in description or "health" in description:
        if action["project"] == "Unassigned":
            return None, "refresh_project_health requires a related project."
        return "refresh_project_health", f"Refreshes Project Health for {action['project']}."
    if "vault report" in description or "report" in description:
        return "generate_vault_report", "Generates Task Review, Action Review, Agent Review, and Global Brief."
    if "static analysis" in description or "safe analysis" in description or "analyze project" in description:
        if action["project"] == "Unassigned":
            return None, "safe_static_analysis requires a related project."
        return "safe_static_analysis", f"Runs internal summary, static analysis, next actions, and health for {action['project']}."
    return None, "Action description does not match an allowlisted Phase 10 action type."


def log_action_execution(config: RaphaelConfig, action: dict[str, str], action_type: str, status: str, result: str) -> None:
    ensure_phase9_files(config)
    line = (
        f"| {today()} | {markdown_table_escape(action['id'])} | "
        f"{markdown_table_escape(action_type)} | {markdown_table_escape(status)} | {markdown_table_escape(result)} |"
    )
    append_unique_line(config.vault / "00_Raphael" / "Action Execution Log.md", line, config)


def dry_run_action(config: RaphaelConfig, action_id: str) -> str:
    action = find_action_request(config, action_id)
    action_type, detail = classify_allowlisted_action(action)
    if action["status"] != "Approved":
        return f"Refused: action {action['id']} has status `{action['status']}`. Only Approved actions can execute."
    if action_type is None:
        return f"Refused: {detail}"
    return f"Dry run: {action['id']} would execute `{action_type}`. {detail} No files would be changed in dry-run mode."


def mark_action_executed(config: RaphaelConfig, action: dict[str, str], action_type: str, result: str) -> Path:
    path = Path(action["path"])
    text = read_text_if_exists(path, config)
    updated = replace_or_insert_section(text, "Status", "Executed")
    updated = append_section_note(updated, "Execution Log", f"- {dt.datetime.now().isoformat(timespec='seconds')} - Executed `{action_type}`: {result}")
    write_action_request_file(path, updated, config)
    return path


def run_allowlisted_action(config: RaphaelConfig, action: dict[str, str], action_type: str) -> list[Path]:
    project = action["project"]
    if action_type == "safe_static_analysis":
        return [
            project_summary(config, project),
            *analyze_project(config, project),
            recommend_next_actions(config, project),
            generate_project_health(config, project),
        ]
    if action_type == "generate_vault_report":
        return [
            generate_task_review(config),
            action_review(config),
            agent_review(config),
            global_brief(config),
        ]
    if action_type == "refresh_project_health":
        return [generate_project_health(config, project)]
    if action_type == "refresh_command_center":
        return [refresh_command_center(config)]
    if action_type == "refresh_global_brief":
        return [global_brief(config)]
    raise ValueError(f"Unsupported action type: {action_type}")


def execute_action(config: RaphaelConfig, action_id: str) -> Path:
    action = find_action_request(config, action_id)
    if action["status"] != "Approved":
        result = f"Refused: status is {action['status']}; only Approved actions can execute."
        log_action_execution(config, action, "refused", "Refused", result)
        raise PermissionError(result)
    action_type, detail = classify_allowlisted_action(action)
    if action_type is None:
        result = f"Refused: {detail}"
        log_action_execution(config, action, "refused", "Refused", result)
        raise PermissionError(result)
    outputs = run_allowlisted_action(config, action, action_type)
    result = "Generated: " + ", ".join(str(path) for path in outputs)
    request_path = mark_action_executed(config, action, action_type, result)
    log_action_execution(config, action, action_type, "Executed", result)
    return request_path


def execution_log_text(config: RaphaelConfig, limit: int = 20) -> str:
    ensure_phase9_files(config)
    rows = meaningful_table_rows(read_text_if_exists(config.vault / "00_Raphael" / "Action Execution Log.md", config))
    rows = [row for row in rows if "Action ID" not in row]
    if not rows:
        return "No executed actions logged yet."
    return "\n".join(rows[-limit:])


