def normalize_workflow_name(workflow_name: str) -> str:
    normalized = workflow_name.strip().lower().replace("-", "_").replace(" ", "_")
    if normalized not in WORKFLOWS:
        raise FileNotFoundError(f"Unknown workflow: {workflow_name}. Known workflows: {', '.join(WORKFLOWS)}")
    return normalized


