def maybe_capture_cleanup_risk(config: RaphaelConfig, project_name: str) -> Path | None:
    context = project_static_context(config, project_name)
    risk_parts: list[str] = []
    inventory = context["inventory"]
    if not has_test_files(inventory):
        risk_parts.append("tests are not detected")
    if not find_inventory_names(inventory, README_NAMES):
        risk_parts.append("README/setup notes are missing")
    paths = inventory_paths(inventory)
    if any(Path(path).name.lower() in {".env", "config.json", "settings.json"} for path in paths):
        risk_parts.append("security-sensitive configuration files may need review")
    if not risk_parts:
        return None
    risk = "Project cleanup review found: " + ", ".join(risk_parts)
    mitigation = "Review documentation, testing, and security notes before portfolio or deployment use."
    capture_risk(config, project_name, risk, mitigation)
    return context["folder"] / "Risks.md"


def run_workflow_steps(config: RaphaelConfig, workflow_name: str, project_name: str) -> list[Path]:
    name = normalize_workflow_name(workflow_name)
    project = slugify(project_name)
    if name == "portfolio_review":
        return [
            project_summary(config, project),
            *analyze_project(config, project),
            recommend_next_actions(config, project),
            generate_project_health(config, project),
            *portfolio_export(config),
        ]
    if name == "project_cleanup_review":
        outputs = [
            *analyze_project(config, project),
            recommend_next_actions(config, project),
        ]
        maybe_risk = maybe_capture_cleanup_risk(config, project)
        if maybe_risk:
            outputs.append(maybe_risk)
        outputs.append(generate_project_health(config, project))
        return outputs
    if name == "assignment_review":
        return [
            summarize_assignment(config, project),
            generate_assignment_submission_checklist(config, project),
            identify_assignment_missing_files(config, project),
            recommend_assignment_next_actions(config, project),
        ]
    if name == "weekly_operations_review":
        return [
            generate_task_review(config),
            action_review(config),
            inbox_review(config),
            global_brief(config),
            refresh_command_center(config),
        ]
    raise ValueError(f"Unsupported workflow: {workflow_name}")


def log_workflow_execution(config: RaphaelConfig, request: dict[str, str], status: str, result: str) -> None:
    ensure_phase12_files(config)
    line = (
        f"| {today()} | {markdown_table_escape(request['id'])} | {markdown_table_escape(request['name'])} | "
        f"{markdown_table_escape(request['project'])} | {markdown_table_escape(status)} | {markdown_table_escape(result)} |"
    )
    append_unique_line(config.vault / "00_Raphael" / "Workflow Execution Log.md", line, config)


def run_workflow_request(config: RaphaelConfig, workflow_id: str) -> Path:
    request = find_workflow_request(config, workflow_id)
    if request["status"] != "Approved":
        result = f"Refused: workflow status is {request['status']}; only Approved workflow requests can run."
        log_workflow_execution(config, request, "Refused", result)
        raise PermissionError(result)
    outputs = run_workflow_steps(config, request["name"], request["project"])
    result = "Generated: " + ", ".join(str(path) for path in outputs)
    path = Path(request["path"])
    text = read_text_if_exists(path, config)
    updated = replace_or_insert_section(text, "Status", "Executed")
    updated = append_section_note(updated, "Execution Log", f"- {dt.datetime.now().isoformat(timespec='seconds')} - {result}")
    write_workflow_request_file(path, updated, config)
    log_workflow_execution(config, request, "Executed", result)
    return path


def workflow_review(config: RaphaelConfig) -> Path:
    ensure_phase12_files(config)
    requests = read_workflow_requests(config)
    pending = [item for item in requests if item["status"] == "Pending Approval"]
    approved = [item for item in requests if item["status"] == "Approved"]
    executed = [item for item in requests if item["status"] == "Executed"]
    rejected = [item for item in requests if item["status"] == "Rejected"]
    log_rows = meaningful_table_rows(read_text_if_exists(config.vault / "00_Raphael" / "Workflow Execution Log.md", config))
    content = f"""# Workflow Review

Generated: {today()}

## Summary

- Total workflow requests: {len(requests)}
- Pending approval: {len(pending)}
- Approved: {len(approved)}
- Executed: {len(executed)}
- Rejected: {len(rejected)}

## Pending Approval

{chr(10).join(f"- `{item['id']}` {item['name']} ({item['project']})" for item in pending) if pending else "- No pending workflow requests."}

## Approved

{chr(10).join(f"- `{item['id']}` {item['name']} ({item['project']})" for item in approved) if approved else "- No approved workflow requests waiting to run."}

## Executed

{chr(10).join(f"- `{item['id']}` {item['name']} ({item['project']})" for item in executed[-20:]) if executed else "- No executed workflow requests."}

## Rejected

{chr(10).join(f"- `{item['id']}` {item['name']} ({item['project']})" for item in rejected[-20:]) if rejected else "- No rejected workflow requests."}

## Recent Execution Log

{chr(10).join(f"- {format_memory_row(row)}" for row in log_rows[-10:]) if log_rows else "- No workflow executions logged yet."}

## Boundary

Workflows run allowlisted internal Raphael functions only. No arbitrary shell commands or source folder edits are allowed.
"""
    output = config.vault / "00_Raphael" / "Workflow Review.md"
    write_generated_note(output, content, config)
    return output


def agent_brief(config: RaphaelConfig, agent_name: str) -> Path:
    normalized = normalize_agent_name(agent_name)
    folder = agent_dir(config, normalized)
    identity = read_text_if_exists(folder / "Identity.md", config)
    responsibilities = read_text_if_exists(folder / "Responsibilities.md", config)
    memory_links = read_text_if_exists(folder / "Memory Links.md", config)
    tasks = [task for task in read_agent_tasks(config, normalized) if task["status"].lower() == "open"]
    related_projects = sorted({task["project"] for task in tasks if task["project"] and task["project"] != "Unassigned"})
    focus: list[str] = []
    if len(tasks) >= 5:
        focus.append("Reduce open task load before accepting more work.")
    if any(task["priority"].lower() == "high" for task in tasks):
        focus.append("Address high-priority tasks first.")
    if not tasks:
        focus.append("No open tasks. Stay available for routed work.")
    else:
        focus.append("Clarify expected outputs for any vague tasks before execution.")
    content = f"""# {normalized} Brief

Generated: {today()}

## Agent Identity

{summarize_text(identity, max_chars=700)}

## Responsibilities

{summarize_text(responsibilities, max_chars=900)}

## Open Tasks

{chr(10).join(f"- [{task['priority']}] {task['task']} ({task['project']})" for task in tasks) if tasks else "- No open tasks."}

## Related Projects

{chr(10).join(f"- [[{project}/Overview|{project}]]" for project in related_projects) if related_projects else "- No related projects detected from open tasks."}

## Relevant Memory Links

{memory_links.strip() if memory_links.strip() else "- [[Master Knowledge Base]]\n- [[Project Registry]]"}

## Recommended Focus

{chr(10).join(f"- {item}" for item in focus)}

## Boundary

Agents can receive task files only. No autonomous execution is authorized.
"""
    output = folder / "Agent Brief.md"
    write_generated_note(output, content, config)
    return output


def agent_review(config: RaphaelConfig) -> Path:
    lines_by_agent: list[str] = []
    overloaded: list[str] = []
    unassigned: list[str] = []
    decision_needed: list[str] = []
    routing_changes: list[str] = []
    for agent in AGENTS:
        tasks = [task for task in read_agent_tasks(config, agent) if task["status"].lower() == "open"]
        if len(tasks) >= 5:
            overloaded.append(f"- {agent}: {len(tasks)} open tasks")
        if not tasks:
            lines_by_agent.append(f"## {agent}\n\n- No open tasks.")
            continue
        task_lines: list[str] = []
        for task in tasks:
            task_lines.append(f"- [{task['priority']}] {task['task']} ({task['project']})")
            if task["project"] == "Unassigned":
                unassigned.append(f"- {agent}: {task['task']}")
            if any(word in task["task"].lower() for word in ["approve", "decision", "choose", "confirm", "legal", "finance", "budget"]):
                decision_needed.append(f"- {agent}: {task['task']}")
        lines_by_agent.append(f"## {agent}\n\n" + "\n".join(task_lines))
    if unassigned:
        routing_changes.append("Review unassigned tasks and connect them to a project or explicit outcome.")
    if overloaded:
        routing_changes.append("Move lower-priority tasks away from overloaded agents or pause new assignments.")
    if not routing_changes:
        routing_changes.append("No routing changes recommended from current task load.")
    content = f"""# Agent Review

Generated: {today()}

## Open Tasks By Agent

{chr(10).join(lines_by_agent)}

## Overloaded Agents

{chr(10).join(overloaded) if overloaded else "- No overloaded agents detected."}

## Unassigned Tasks

{chr(10).join(unassigned) if unassigned else "- No unassigned tasks detected."}

## Recommended Routing Changes

{chr(10).join(f"- {item}" for item in routing_changes)}

## Tasks Needing Aaron's Decision

{chr(10).join(decision_needed) if decision_needed else "- No task explicitly appears to need Aaron's decision."}

## Boundary

This review organizes responsibility only. No autonomous execution has been started.
"""
    output = config.vault / "00_Raphael" / "Agent Review.md"
    write_generated_note(output, content, config)
    return output


def add_lesson(config: RaphaelConfig, project: str, lesson: str) -> None:
    capture_lesson(config, project, lesson)


def collect_open_tasks(config: RaphaelConfig) -> list[str]:
    tasks: list[str] = []
    for project in list_projects(config):
        task_file = config.vault / "02_Projects" / project / "Tasks.md"
        if task_file.exists():
            for line in task_file.read_text(encoding="utf-8").splitlines():
                if line.strip().startswith("- [ ]"):
                    tasks.append(f"{project}: {line.strip()}")
    return tasks


def weekly_review(config: RaphaelConfig) -> Path:
    projects = list_projects(config)
    tasks = collect_open_tasks(config)
    decisions: list[str] = []
    for project in projects:
        decision_file = config.vault / "02_Projects" / project / "Decisions.md"
        if decision_file.exists() and "To be defined" not in decision_file.read_text(encoding="utf-8"):
            decisions.append(f"- [[{project}/Decisions|{project} decisions]]")
    date = today()
    content = f"""# Weekly Review - {date}

## Active Projects

{chr(10).join(f"- [[{project}/Overview|{project}]]" for project in projects) or "- None found."}

## Open Tasks

{chr(10).join(f"- {task}" for task in tasks[:50]) or "- No open markdown tasks found."}

## New Ideas

- Review [[Business Ideas]] for new opportunities.

## Open Decisions

{chr(10).join(decisions) or "- No explicit open decisions found yet."}

## Recommended Next Actions

- Pick the top 3 active projects for the week.
- Update each selected project's `Tasks.md`.
- Capture one lesson learned from recent work.
- Process any notes in `{config.os_root / "inbox"}` or `{config.vault / "00_Raphael" / "Inbox"}`.
"""
    vault_review = unique_path(config.vault / "00_Raphael" / "Weekly Reviews" / f"{date} Weekly Review.md")
    export_review = unique_path(config.os_root / "exports" / f"{date} Weekly Review.md")
    write_file(vault_review, content, config)
    write_file(export_review, content, config)
    return vault_review


